[75622] = {id=75622,name="Calling All Competitors!",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="The Artisan's Consortium has struck a deal with the quartermasters of the Gladiator's Refuge! In addition to the usual selection of powerful combat equipment they offer, worthy combatants can now purchase tokens that can be used in Crafting Orders or one's own crafts to certify the equipment for use in battlegrounds and arenas! Present this flier to Calderax to receive two complimentary Trophies of Conquest, on us! - Rabul",ends={{npcID=199599,x=0.444,y=0.368,mapID=2112}},questType="standard"},
