[75712] = {id=75712,name="Warcraft Rumble Minis: New Look!",level=0,requiredLevel=0,faction="alliance",expansion=10,zoneID=13862,mapID=2112,description="This Rumble Foil can be used at a Warcraft Rumble machine . Go and get a new look for one of your minis!",ends={{npcID=384744,x=0.287,y=0.412,mapID=84},{npcID=384744,x=0.506,y=0.822,mapID=85},{npcID=384744,x=0.48,y=0.466,mapID=2112}},questType="standard"},
