[75877] = {id=75877,name="Time to Fly",level=30,requiredLevel=30,faction="alliance",expansion=10,zoneID=8568,mapID=1161,description="Kul Tiras is home to many gryphons. One will accompany you into the skies. Visit Leila Stafford at the Tradewinds Market in Boralus.",ends={{npcID=142073,x=0.696,y=0.13,mapID=1161}},questType="standard"},
