[77788] = {id=77788,name="Ashphodel Research Notes",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description="Q'onzu would definitely be interested in a sample of the pollen and these notes.>",ends={{npcID=210585,x=0.658,y=0.378,mapID=2200}},questType="standard"},
[77795] = {id=77795,name="Scavenged Artifacts",level=30,requiredLevel=30,faction="both",expansion=10,zoneID=8574,mapID=830,starts={{npcID=125246,x=0.568,y=0.686,mapID=830}},ends={{npcID=125246,x=0.568,y=0.686,mapID=830}},coords={x=0.568,y=0.686,source="quest_giver",mapID=830},questType="standard"},
[77815] = {id=77815,name="The Storm Race Tour",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13644,mapID=2022,description="This storm gryphon is intriguing! Whatever land gave rise to such a creature merits further exploration. But since you are here, let us test its training--and your riding skills. My colleagues in the bronze flight have laid out new courses to put the mount through its paces. When a timekeeper sees you upon your gryphon, they will offer you the chance to fly these \"storm races\". Fortune favors the bold, $p. Good luck!",starts={{npcID=193359,x=0.752,y=0.55,mapID=2022}},ends={{npcID=193359,x=0.752,y=0.55,mapID=2022}},coords={x=0.752,y=0.55,source="quest_giver",mapID=2022},questType="standard"},
[77832] = {id=77832,name="Shadows upon shadows",level=10,requiredLevel=10,faction="none",expansion=10,zoneID=14023,description="I need to save him.",questType="standard"},
[77865] = {id=77865,name="A Proper Burial",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,starts={{npcID=206864,x=0.604,y=0.59,mapID=2025},{npcID=206864,x=0.474,y=0.482,mapID=2112}},ends={{npcID=206864,x=0.604,y=0.59,mapID=2025},{npcID=206864,x=0.474,y=0.482,mapID=2112}},coords={x=0.604,y=0.59,source="quest_giver",mapID=2112},questType="standard"},
