[77897] = {id=77897,name="A Special Book",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,starts={{npcID=207696,x=0.478,y=0.47,mapID=2112}},ends={{npcID=207696,x=0.478,y=0.47,mapID=2112}},coords={x=0.478,y=0.47,source="quest_giver",mapID=2112},questType="standard"},
[77937] = {id=77937,name="Forbidden Sugar",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,description="During this very unique time of bloom, a new flower has been discovered in the Dream. These stunning flowers produce a marvelous pollen. Its aroma is a delight, just like fresh baked cookies. To the dismay of chefs, even eating a tiny bit will result in rapid, severe poisoning of the liver. However, it is an incredible all-purpose addition to enchanting. Early tests demonstrate potency as high as quadruple that of Chromatic Dust. Traders from Valdrakken are very interested in its acquisition.",starts={{npcID=210162,x=0.368,y=0.628,mapID=2112}},ends={{npcID=210162,x=0.368,y=0.628,mapID=2112}},coords={x=0.368,y=0.628,source="quest_giver",mapID=2112},questType="standard"},
[77953] = {id=77953,name="A Sphere in Danger",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,starts={{npcID=185562,x=0.474,y=0.466,mapID=2112}},ends={{npcID=185562,x=0.474,y=0.466,mapID=2112}},coords={x=0.474,y=0.466,source="quest_giver",mapID=2112},questType="standard"},
[77957] = {id=77957,name="A Treacherous Race",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13862,mapID=2112,starts={{npcID=206864,x=0.604,y=0.59,mapID=2025},{npcID=206864,x=0.474,y=0.482,mapID=2112}},ends={{npcID=206864,x=0.604,y=0.59,mapID=2025},{npcID=206864,x=0.474,y=0.482,mapID=2112}},coords={x=0.604,y=0.59,source="quest_giver",mapID=2112},questType="standard"},
[78015] = {id=78015,name="Firebrand Fystia",level=10,requiredLevel=10,faction="none",expansion=10,zoneID=14529,mapID=2200,questType="standard"},
[78113] = {id=78113,name="The Challenge Tour",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=13647,mapID=2025,description="Hello again adventurer! Do you like a challenge? I hope so as my bronze colleagues have a new set of challenge courses for you to fly. Make no mistake, these will be more difficult than the previous courses. All the obstacles remain but there none of the boons waiting for you along the route. Are you up to the challenge?",starts={{npcID=193411,x=0.732,y=0.52,mapID=2022},{npcID=199118,x=0.88,y=0.362,mapID=2023},{npcID=199119,x=0.632,y=0.136,mapID=2024},{npcID=199120,x=0.46,y=0.63,mapID=2025}},ends={{npcID=193411,x=0.732,y=0.52,mapID=2022},{npcID=199118,x=0.88,y=0.362,mapID=2023},{npcID=199119,x=0.632,y=0.136,mapID=2024},{npcID=199120,x=0.46,y=0.63,mapID=2025}},coords={x=0.732,y=0.52,source="quest_giver",mapID=2025},questType="standard"},
[78126] = {id=78126,name="Lightbringer's Duty",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=14838,mapID=2215,questType="standard"},
[78131] = {id=78131,name="A Winter Veil Gift",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=1637,mapID=85,starts={{npcID=187236,x=0.335,y=0.66,mapID=87},{npcID=187236,x=0.494,y=0.775,mapID=85}},ends={{npcID=187236,x=0.335,y=0.66,mapID=87},{npcID=187236,x=0.494,y=0.775,mapID=85}},coords={x=0.335,y=0.66,source="quest_giver",mapID=85},questType="standard"},
[78169] = {id=78169,name="LFGDungeons - Timewalking \"Heroic\" Random - 1st",level=0,requiredLevel=0,faction="none",expansion=10,questType="standard"},
[78203] = {id=78203,name="Superbloom",level=10,requiredLevel=10,faction="none",expansion=10,questType="standard"},
[78226] = {id=78226,name="A Most Intriguing Invitation",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14753,description="We've received an invitation. Or rather, you have, . It's a request to meet with the Vizier. That name rattles even the most wealthy and powerful figures in the City of Threads. Gaining this individual as an ally could seal our victory against Ansurek's horrid little shadow for good. You're to meet them in the Burrows. Use the pheromone dispenser here in my lair to mask yourself enough to enter safely.",starts={{npcID=207471,x=0.556,y=0.438,zoneID=14752}},coords={x=0.556,y=0.438,source="quest_giver",zoneID=14752},questType="standard"},
[78228] = {id=78228,name="Into a Skittering City",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14753,mapID=2213,description="I sent these 'invitations' to you and Alleria, both. I'd have bet my father's sword you wouldn't let such a unique opportunity pass you by--it's what sets you apart from us all. Alleria, however... Nevermind. She's as cautious as she is assertive. I suppose I was hoping for the latter, but it's the former that's kept her alive. Perhaps she'll find us later on. For now, it's time you and my new acquaintance properly meet.",questType="standard"},
[78231] = {id=78231,name="Like a Spider on the Wall",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="Inviting Alleria was a risk... but even at this moment, I feel it was worth taking. I know it was. I will speak with her on my own. In the meantime, I'd like you to venture into the city above. The pheromones Nizrek gifted you will allow access into the Umbral Bazaar. Observe the merchants, listen to the conversations, purchase their goods. This city is as vibrant as Stormwind. And its people are as worthy of freeing from abuse as our own. Experience for yourself how similar we all are.",ends={{npcID=217386,x=0.606,y=0.688,zoneID=14752}},questType="standard"},
[78232] = {id=78232,name="Rewriting the Rewritten",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14753,description="We called you here today because it is \"Ascendance Day\". Queen Ansurek has deigned declare it a day to revel in our newfound, void-infused evolution--our \"Ascendance\". Please note my satirical nuance. While the streets are alive with festivity and joyous citizens, the Shadecasters planted through the Bazaar will be drowning the air with Ansurek's vile propaganda. Take this invention of mine. Use it to overwrite them with more... illuminating information for the public.",questType="standard"},
[78233] = {id=78233,name="The Weaver's Gift",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="A little weave-rat tells me that an intriguing series of events are playing out to the north. It seems there has been a remarkably coincidental waterfall of failures marring the military efforts there. I want to know who is responsible. Look into it for me, and see if your curiously binary eyes can pluck out any potential allies. Some of your little friends are among the escapees drawing the ire of one \"Zev'kall.\" Do go catch up. Tell them the Weaver bids them... greetings.",starts={{npcID=207471,x=0.556,y=0.438,zoneID=14752}},ends={{npcID=211409,x=0.592,y=0.194,zoneID=14752}},coords={x=0.556,y=0.438,source="quest_giver",zoneID=14752},questType="standard"},
[78234] = {id=78234,name="Force Your Way",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="Even with the general gone, it's not going to be easy getting out of here. This place is infested. I know I'm hiding it well, but I'm not exactly feeling my best. I'm not sure I'll be much help in this state. You're going to have to clear a path for us.",starts={{npcID=220051,x=0.63,y=0.27,zoneID=14752}},coords={x=0.63,y=0.27,source="quest_giver",zoneID=14752},questType="standard"},
[78236] = {id=78236,name="Scrappy Straggler",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="If someone got left behind, we need to do something about that. I hate to say it, but these people need someone to protect them here. I have to stay. Find this straggler. And while you're at it, take a peek behind enemy lines. See if you can find anything useful.",starts={{npcID=211409,x=0.592,y=0.194,zoneID=14752}},ends={{npcID=220051,x=0.63,y=0.27,zoneID=14752}},coords={x=0.592,y=0.194,source="quest_giver",zoneID=14752},questType="standard"},
[78237] = {id=78237,name="Let Fly!",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="Hm. This Anub'azal gave the orders that led to the prisoners' escape. Zev'kall here didn't seem very pleased with that. So how about this--you sneak into Siegehold, and make best friends with Anub'azal . Easy. I've noticed a lot of cargo being ferried over, I'm sure no one would notice if we just swapped out the contents of a particular crate. In the meantime, I'll share our discoveries with the Weaver. I'd love to come with you, but I'd rather not tempt more Flynn stabbings today.",ends={{npcID=217330,x=0.454,y=0.198,zoneID=14752}},questType="standard"},
[78244] = {id=78244,name="Kaheti Hospitality",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14753,description="That stage in the distance is where Ansurek will give her Ascendance Day speech. You, Alleria, and I shall make our way up one of the nearby towers and observe. If we are to turn her own citizens against her, then we must also gain as much first hand experience with her tactics as we can manage. I've already told Alleria as much, but we cannot make our presence known. If we do run into any trouble, the Vizier has arranged for a set of getaway fliers at the edge of the Burrows where we first met.",starts={{npcID=217386,x=0.606,y=0.688,zoneID=14752},{npcID=217386,x=0.552,y=0.46,zoneID=14753}},ends={{npcID=217386,x=0.606,y=0.688,zoneID=14752},{npcID=217386,x=0.552,y=0.46,zoneID=14753}},coords={x=0.606,y=0.688,source="quest_giver",zoneID=14752},questType="standard"},
[78248] = {id=78248,name="What We Still Have",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="I went into the city prepared--prepared to end this war even if I was ended with it. But I am alive. As are you. As is Anduin. We have new allies and a new way forward. I realize at this moment that my vision may have been obscured by my guilt. Part of me feels those words are Anduin's, not mine. Perhaps he's rubbing off on me. Let us return to your Weaver's Lair. I wish to see yours and Anduin's efforts to save these people as well as our own through.",starts={{npcID=217385,x=0.606,y=0.688,zoneID=14752}},ends={{npcID=207471,x=0.556,y=0.438,zoneID=14752}},coords={x=0.606,y=0.688,source="quest_giver",zoneID=14752},questType="standard"},
[78249] = {id=78249,name="Specific Personages",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="Zev'kall has recently placed his own loyal lackeys in key positions around Siegehold. Killing them will force replacements, which will cause chaos and re-training. All of which will make Zev'kall struggle. Get rid of all three.",starts={{npcID=217330,x=0.454,y=0.198,zoneID=14752}},ends={{npcID=217330,x=0.454,y=0.198,zoneID=14752}},coords={x=0.454,y=0.198,source="quest_giver",zoneID=14752},questType="standard"},
[78250] = {id=78250,name="General Admission",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="It isn't enough to inconvenience Zev'kall. He should be humiliated. I already have some information, but I need more. He stores military logs in a room that is too tiny for me to access. See what information he's hiding. I'm sure there's potential blackmail material in there somewhere.",starts={{npcID=217330,x=0.454,y=0.198,zoneID=14752}},ends={{npcID=217330,x=0.454,y=0.198,zoneID=14752}},coords={x=0.454,y=0.198,source="quest_giver",zoneID=14752},questType="standard"},
[78251] = {id=78251,name="Dalaran's Most Distressed",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="I don't trust this big bug at all. He let me lay there ages without saying anything! But if he wants to give us access to Siegehold, let's use it. I saw some other people dragged away into other parts of the base. I don't think they're eating them. It looks more like they're transporting them somewhere. Let's gather them up, make a prisoner convoy, and roll on out. Find me outside!",starts={{npcID=211399,x=0.452,y=0.2,zoneID=14752}},ends={{npcID=215413,x=0.474,y=0.24,zoneID=14752}},coords={x=0.452,y=0.2,source="quest_giver",zoneID=14752},questType="standard"},
[78254] = {id=78254,name="Stolen Influence",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="These logs of Zev'kall's... he is wasting numerous nerubian lives. Throwing them away like some rabid mantid. We must act. As I said, Zev'kall doesn't produce his own pheromone marks anymore due to this 'Ascension' process. He's been forced to use mine. His alchemist is trying to concoct some for him... but once they do, what of me? Take those false pheromones and sneak them out of Siegehold. Expose Zev'kall, use them... you're creative, aren't you? Just make it messy.",starts={{npcID=217330,x=0.454,y=0.198,zoneID=14752}},ends={{npcID=215413,x=0.474,y=0.24,zoneID=14752}},coords={x=0.454,y=0.198,source="quest_giver",zoneID=14752},questType="standard"},
[78255] = {id=78255,name="Just Act Casual",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="It's time to get outta here with the prisoners and those pheromones. I've found some convincing chains, since we have such a big group. Long as everybody stays in character, our chances look good. We've only got General Anub'azal's marker scent goop for you and I, so we'll be the drones with permission. You do all the talkin', while I mind the cart. I hope this works. Lead us through the gate, !",starts={{npcID=215413,x=0.474,y=0.24,zoneID=14752}},ends={{npcID=215845,x=0.518,y=0.258,zoneID=14752}},coords={x=0.474,y=0.24,source="quest_giver",zoneID=14752},questType="standard"},
[78256] = {id=78256,name="The General's Consensus",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="We got lucky here. That General Anub'azal is so interested in sabotaging Zev'kall that it's an \"enemy of our enemy is our friend\" situation for today. I feel like this is gonna be a theme: spiders tryin' to use us against each other. Ah, well. You're gonna want to take those pheromones somewhere useful, huh? You do that. I'll take these folks safely out of harm's way.",starts={{npcID=215845,x=0.518,y=0.258,zoneID=14752}},ends={{npcID=207471,x=0.556,y=0.438,zoneID=14752}},coords={x=0.518,y=0.258,source="quest_giver",zoneID=14752},questType="standard"},
[78272] = {id=78272,name="Interrupting Duck",level=1,requiredLevel=1,faction="alliance",expansion=10,description="There are so many bunches of baby bunnies bouncing all about! Ducks have been swarming us and we haven't been able to feed the newborns. You look like you could handle the situation--care to help?",questType="standard"},
[78289] = {id=78289,name="To Rambleshire",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="There's word of troubles in the village of Rambleshire, at the base of Thunderhead Peak. Can't abide the place myself. Always wet and rumbling. But Rooktender Lufsela thought it worth a look, however, seeing as how the birds fancy the moss that the village produces. She's still green though, and might just need a hand.",starts={{npcID=214352,x=0.328,y=0.338,zoneID=14771}},ends={{npcID=211740,x=0.614,y=0.316,zoneID=14717}},coords={x=0.328,y=0.338,source="quest_giver",zoneID=14771},questType="standard"},
[78290] = {id=78290,name="Sleepy Sheep",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="The energized moss that these flocks produce is a favorite treat for the storm rooks. But with the storm gone, the rams are lethargic, vulnerable, and no longer producing. We may not be able to conjure a storm, but we could offer the mosswools a motivating zap. See if you can find a lodestone that will hold a charge. Then bring it here to Shraubendre so she can get it loaded up.",starts={{npcID=211740,x=0.614,y=0.316,zoneID=14717}},ends={{npcID=211740,x=0.614,y=0.316,zoneID=14717}},coords={x=0.614,y=0.316,source="quest_giver",zoneID=14717},questType="standard"},
[78291] = {id=78291,name="Power Predators",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="Thunderhead Peak normally boasts a perpetual storm from which the local mosswools draw energy. Without it, the poor dears look to be listless and near dead on their feet. That makes them easy pickings for predators. To get moss production back on track, we'll need to get to the bottom of the missing storm. But first we need to beat back these predators before they turn the mosswools to gravel.",starts={{npcID=211740,x=0.614,y=0.316,zoneID=14717}},ends={{npcID=211740,x=0.614,y=0.316,zoneID=14717}},coords={x=0.614,y=0.316,source="quest_giver",zoneID=14717},questType="standard"},
[78292] = {id=78292,name="Lost Lord of the Storm",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="Listen well, stranger. Once a year, the great ram Durzan , Lord of the Southern Storm, crosses the isle to meet his brother Belzt on Thunderhead Peak. The clash of their horns heralds the storm and brings prosperity for another year. But something is wrong. Durzan has not come and the skies have cleared. The Stormrider may not believe, but I sense you have seen wilder things. Ask around if you still have doubts. Just please help us find Durzan .",starts={{npcID=209918,x=0.596,y=0.29,zoneID=14717}},ends={{npcID=209918,x=0.596,y=0.29,zoneID=14717}},coords={x=0.596,y=0.29,source="quest_giver",zoneID=14717},questType="standard"},
[78293] = {id=78293,name="Their Moss, Our Gain",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="You say nerubians had him? Not sure what they wanted with old Durzan, but he looks weakened by the ordeal. We can't have that if he's to challenge his brother Belzt on the mountain. The moss harvested from our flocks gives the storm rooks a kick, so Durzan might benefit from it as well. Collect a bushel's worth and make an offering. And if the mosswools get ornery, be sure to put them in their place.",starts={{npcID=209918,x=0.596,y=0.29,zoneID=14717}},ends={{npcID=209918,x=0.596,y=0.29,zoneID=14717}},coords={x=0.596,y=0.29,source="quest_giver",zoneID=14717},questType="standard"},
[78294] = {id=78294,name="Thunderhead Butt",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="Durzan looks hale and hearty again. That moss packs a real punch. I have a sense that he's ready to go. I just wish we had more time. I have so many questions. But the greatest of those questions will be answered when he reaches the peak. We shouldn't send him up there alone. But I think he trusts you to take him.",starts={{npcID=211740,x=0.614,y=0.316,zoneID=14717}},ends={{npcID=211740,x=0.614,y=0.316,zoneID=14717}},coords={x=0.614,y=0.316,source="quest_giver",zoneID=14717},questType="standard"},
[78348] = {id=78348,name="Friends in Low Places",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="When we crashed, the nerubians were upon us in an instant. We would have lost nearly everyone we brought with us, had someone not intervened. I do not know who--or what--stepped in on our behalf. But if there is even a shred of hope that we have allies in this place then we must seize upon it and refuse to let go.",starts={{npcID=211699,x=0.294,y=0.422,zoneID=14752}},ends={{npcID=215944,x=0.33,y=0.562,zoneID=14752}},coords={x=0.294,y=0.422,source="quest_giver",zoneID=14752},questType="standard"},
[78350] = {id=78350,name="Heroes Never Die",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="Damn it all! We were too hasty, and now my people are paying the price. We were fools to think the nerubians wouldn't be prepared for an incursion. Arathi soldiers are made of stern stuff, but even they will struggle to walk off an airship crash. I will keep everyone here safe. Please, go into the field and rescue as many people as you can.",starts={{npcID=211699,x=0.294,y=0.422,zoneID=14752}},ends={{npcID=211699,x=0.294,y=0.422,zoneID=14752}},coords={x=0.294,y=0.422,source="quest_giver",zoneID=14752},questType="standard"},
[78352] = {id=78352,name="For Naught, So Vial",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="Truthfully, I don't care what the nerubians are plotting. They are not the first upstart people seeking power, and they certainly won't be the last. The problem is how they're going about it. I fear that tampering with this Black Blood will threaten far more than the delicate ecosystems of Khaz Algar. We must make sure that they never return to this pit again. Their equipment is still strewn throughout the pit. Destroy as much of it as you can manage.",starts={{npcID=215944,x=0.33,y=0.562,zoneID=14752}},ends={{npcID=215113,x=0.358,y=0.582,zoneID=14752}},coords={x=0.33,y=0.562,source="quest_giver",zoneID=14752},questType="standard"},
[78353] = {id=78353,name="Fear the Old Blood",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="This is not exactly the place for a long talk, so I will be brief. These roots you see are part of something much greater than you know, and it is my job to protect them. If it isn't obvious to you already, this place is teeming with writhing Black Blood. If we do not act, it will spread deeper and further still. You want allies? Fine. Help me cleanse this place and protect these roots, and I will at least hear you out.",starts={{npcID=215944,x=0.33,y=0.562,zoneID=14752}},ends={{npcID=215113,x=0.358,y=0.582,zoneID=14752}},coords={x=0.33,y=0.562,source="quest_giver",zoneID=14752},questType="standard"},
[78354] = {id=78354,name="A Guiding Thread",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="Blind and alone, you stumble in the dark. I offer you a thread to cling to. Follow it, should you wish to find your allies.",starts={{npcID=216213,x=0.442,y=0.568,zoneID=14752}},ends={{npcID=207471,x=0.556,y=0.438,zoneID=14752}},coords={x=0.442,y=0.568,source="quest_giver",zoneID=14752},questType="standard"},
[78355] = {id=78355,name="Essence of a Broken Dream",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14643,description="Merithra will know more about it?>",questType="raid"},
[78356] = {id=78356,name="DO NOT USE",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,starts={{npcID=208143,x=0.502,y=0.616,mapID=2200}},ends={{npcID=208143,x=0.502,y=0.616,mapID=2200}},coords={x=0.502,y=0.616,source="quest_giver",mapID=2200},questType="standard"},
[78358] = {id=78358,name="Drake's Crests",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,starts={{npcID=208143,x=0.502,y=0.616,mapID=2200}},ends={{npcID=208143,x=0.502,y=0.616,mapID=2200}},coords={x=0.502,y=0.616,source="quest_giver",mapID=2200},questType="standard"},
[78364] = {id=78364,name="Drake's Crests",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,starts={{npcID=208143,x=0.502,y=0.616,mapID=2200}},ends={{npcID=208143,x=0.502,y=0.616,mapID=2200}},coords={x=0.502,y=0.616,source="quest_giver",mapID=2200},questType="standard"},
[78372] = {id=78372,name="Drake's Crests",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,starts={{npcID=208143,x=0.502,y=0.616,mapID=2200}},ends={{npcID=208143,x=0.502,y=0.616,mapID=2200}},coords={x=0.502,y=0.616,source="quest_giver",mapID=2200},questType="standard"},
[78374] = {id=78374,name="Flightstones",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,starts={{npcID=208143,x=0.502,y=0.616,mapID=2200}},ends={{npcID=208143,x=0.502,y=0.616,mapID=2200}},coords={x=0.502,y=0.616,source="quest_giver",mapID=2200},questType="standard"},
[78383] = {id=78383,name="Strategic Edge",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="To add insult to injury, they disarmed me. I'm not leaving without those blades! While we're looking, keep an eye out for any evidence of what's going on here. Anything that could give us an advantage against the nerubians. Something strange happened that provided us the opening to escape. I have a feeling that could be something we can exploit.",starts={{npcID=220051,x=0.63,y=0.27,zoneID=14752}},coords={x=0.63,y=0.27,source="quest_giver",zoneID=14752},questType="standard"},
[78384] = {id=78384,name="Chasing the Light",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="Anduin survived that swarm. I do not doubt that for a moment. Even so, the nerubians are everywhere and he is just one man. Wherever he goes, wherever he is taken, I will find him. Find me any sign that he yet lives. That is all I need to follow him to Azeroth's end.",starts={{npcID=211752,x=0.324,y=0.47,zoneID=14752}},ends={{npcID=211752,x=0.324,y=0.47,zoneID=14752}},coords={x=0.324,y=0.47,source="quest_giver",zoneID=14752},questType="standard"},
[78385] = {id=78385,name="Small Dreamseeds",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description=", we've noticed an increase of fertile dirt within the Dream. It's the perfect opportunity for new plants! Come talk to me so we can start planting some seeds. -",ends={{npcID=211265,x=0.596,y=0.168,mapID=2200}},questType="standard"},
[78387] = {id=78387,name="Plump Dreamseeds",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description=", we've noticed an increase of fertile dirt within the Dream. It's the perfect opportunity for new plants! Come talk to me so we can start planting some seeds. -",ends={{npcID=211265,x=0.596,y=0.168,mapID=2200}},questType="standard"},
[78388] = {id=78388,name="Gigantic Dreamseeds",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,description=", we've noticed an increase of fertile dirt within the Dream. It's the perfect opportunity for new plants! Come talk to me so we can start planting some seeds. -",ends={{npcID=211265,x=0.596,y=0.168,mapID=2200}},questType="standard"},
[78392] = {id=78392,name="The Tangled Web",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="Make no mistake--I have no intention of sending you off to skitter about in the dark like a freshly-hatched beetle. It wouldn't do to have my little morsel snatched up by a starving cave borer. You must educate yourself, my dear. Your allies have found themselves ensconced in a torrid tapestry. Only by familiarizing yourself with its erstwhile architects can you hope to reclaim them. Luckily for you, I have made some of my personal resources available to you.",starts={{npcID=207471,x=0.556,y=0.438,zoneID=14752}},ends={{npcID=207471,x=0.556,y=0.438,zoneID=14752}},coords={x=0.556,y=0.438,source="quest_giver",zoneID=14752},questType="standard"},
[78393] = {id=78393,name="A Seeming Respite",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="You have endured quite the evening since your ill-fated little ship ride, haven't you? Worry not, little morsel. You will find that my friends here are most accommodating, even to someone with your predilections--as strange as they may be. Please, take a moment to explore. Avail yourself of my many amenities. With luck, you will find some sorely-needed rest. ...Oh, but do take care not to move about too quickly. Sudden movements, I'm sure you understand.",starts={{npcID=207471,x=0.556,y=0.438,zoneID=14752}},ends={{npcID=207471,x=0.556,y=0.438,zoneID=14752}},coords={x=0.556,y=0.438,source="quest_giver",zoneID=14752},questType="standard"},
[78459] = {id=78459,name="State of the Union",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,description="I hate to admit it, but we have been caught unprepared by the nerubians. Our processes focused on sustaining Dornogal and our declining population. Stormward Baelgrim's stalwart pride has kept him and the Stormriders capable fighters, but they are already stretched thin, and they are not builders. The Coreway's damage surpasses our ability to fix it. But... that was not always so. I suppose if you wish to understand, you must learn more about us.",starts={{npcID=217861,x=0.4,y=0.258,zoneID=14771}},ends={{npcID=217861,x=0.4,y=0.258,zoneID=14771}},coords={x=0.4,y=0.258,source="quest_giver",zoneID=14771},questType="standard"},
[78460] = {id=78460,name="Hypocenter",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,description="I have failed my people. The Coreway is impassible. Dornogal's lifeline to the Ringing Deeps has been severed as has the path beyond. The nerubians will get their comeuppance. It is my edict as it is my will. I will ascertain if the Councilward yet functions and bring him to the Archive. Speaker Brinthe should be there, titans willing. But Oathsworn citizens are still in peril. If you wish to ally with us, clear the debris here and help our survivors. I will meet you at the Archive.",starts={{npcID=217852,x=0.362,y=0.644,zoneID=14771}},ends={{npcID=217853,x=0.298,y=0.596,zoneID=14771}},coords={x=0.362,y=0.644,source="quest_giver",zoneID=14771},questType="standard"},
[78461] = {id=78461,name="The Fourth Seat",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="With me da' and Anduin weakened and Alleria nowhere to be found, it's up to us, , to clear the way for Thrall an' Jaina's army if we hope tae strike back at the nerubians an' Xal'atath. But we cannae get to the nerubians without the Coreway. An' we cannae repair the Coreway without the earthen's help. If Merrix thinks this Adelgonn an' her \"Unbound\" are the only ones that can fix the Coreway, then we need tae find her. Time tae sharpen me smile an' put on me diplomat hat. Are ye with me, ?",starts={{npcID=217864,x=0.404,y=0.258,zoneID=14771}},ends={{npcID=217879,x=0.418,y=0.726,zoneID=14717}},coords={x=0.404,y=0.258,source="quest_giver",zoneID=14771},questType="standard"},
[78462] = {id=78462,name="Echoes of Compassion",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="The last thing I expected today was to see Baelgrim--much less receive his help. But I guess since the Coreway was damaged, he has no choice. I... do not know how to compute this. It is only logical to accept it. Adelgonn begins crushing the fungarian flesh roughly in her stone hands. It becomes a masticated pulp disturbingly quickly.> Here. Mix this with mud and apply it to the injured.",starts={{npcID=217879,x=0.418,y=0.726,zoneID=14717}},ends={{npcID=217879,x=0.418,y=0.726,zoneID=14717}},coords={x=0.418,y=0.726,source="quest_giver",zoneID=14717},questType="standard"},
[78463] = {id=78463,name="Building Blocks",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="The quarry is overrun with fungarians, all of the mining tunnels are collapsed, and we do not have time to clear them out and rebuild! However, I did spy a good amount of ore on the ground on the way here. It would be a start at repairing the Coreway but... Baelgrim sighs and grimly looks at the injured Unbound earthen.> I am needed here. With Adelgonn's people. My people. Will you gather the ore in my stead?",starts={{npcID=217881,x=0.418,y=0.728,zoneID=14717}},ends={{npcID=217881,x=0.418,y=0.728,zoneID=14717}},coords={x=0.418,y=0.728,source="quest_giver",zoneID=14717},questType="standard"},
[78464] = {id=78464,name="Delve into the Earth",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14999,description="The nerubian attack, your meteoric fall... And now Baelgrim is here? Baelgrim needs more hands for his Coreway, but I couldn't help even if I wanted to. My people are dying as we speak. Some were abducted by the nerubians during the attack. You're not the first outlander I've met. A small fellow, like Moira, arrived here earlier and wasted no time following the nerubians. He took the path west to a nearby cave. I would be in your debt if you found my people.",starts={{npcID=217879,x=0.418,y=0.726,zoneID=14717}},ends={{npcID=217879,x=0.418,y=0.726,zoneID=14717}},coords={x=0.418,y=0.726,source="quest_giver",zoneID=14717},questType="standard"},
[78465] = {id=78465,name="Golgrin's Reach",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="Now that we have the opals, we can meet Brinthe in Golgrin's Reach. She said there's a project she's workin' on there she wants me tae help with. I wonder what it is?",starts={{npcID=225451,x=0.448,y=0.644,zoneID=14717}},ends={{npcID=225453,x=0.616,y=0.702,zoneID=14717}},coords={x=0.448,y=0.644,source="quest_giver",zoneID=14717},questType="standard"},
[78467] = {id=78467,name="Charge for a Charge",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="I am pleased Dagran has brought you here. I need help with a dangerous task. I used Dagran's opals to repair the titan console we recently recovered from this site. The Oathsworn have long wanted to learn more about the titans and restore records unreachable in the Archive--or from before its construction. This console may hold some answers if we can bring it back online. Take this device I have made. It will lead you to titan power cells we can use to power it on now that it is restored.",starts={{npcID=225478,x=0.616,y=0.702,zoneID=14717}},ends={{npcID=225478,x=0.616,y=0.702,zoneID=14717}},coords={x=0.616,y=0.702,source="quest_giver",zoneID=14717},questType="standard"},
[78468] = {id=78468,name="The Archive",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,description="The memory gem you recovered is what its name suggests. It contains an earthen's memories, directives, and a hard coding of our Edicts. This building, the Archive, is the nexus of our civilization. Here, memories are cycled, catalogued, and stored at the end of an earthen's scheduled rotation. With the codex I have invented, we can access one or two memories from a memory gem. Take it, and read the memory gem you found.",starts={{npcID=217857,x=0.294,y=0.598,zoneID=14771}},ends={{npcID=217857,x=0.294,y=0.598,zoneID=14771}},coords={x=0.294,y=0.598,source="quest_giver",zoneID=14771},questType="standard"},
[78469] = {id=78469,name="Prairie Fever",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="I was supposed to see Kodun earlier, but I'm as petrified as unliving stone. The attack on the village was... paralyzing. Hreka takes a deep breath and focuses on the shape of another jar.> Could you do me a favor and deliver those jars to Kodun ? He's a stone's throw away in the village pottery shop. I must finish this piece before the clay dries.",starts={{npcID=217961,x=0.418,y=0.708,zoneID=14717}},ends={{npcID=216094,x=0.422,y=0.732,zoneID=14717}},coords={x=0.418,y=0.708,source="quest_giver",zoneID=14717},questType="standard"},
[78470] = {id=78470,name="The Proscenium",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="The nerubians are attackin' the earthen again. We must follow that swarm! I fear we are outnumbered, but if the earthen can come together and stand with us... We may just have a chance.",starts={{npcID=217878,x=0.418,y=0.726,zoneID=14717}},ends={{npcID=217898,x=0.564,y=0.48,zoneID=14717}},coords={x=0.418,y=0.726,source="quest_giver",zoneID=14717},questType="standard"},
[78471] = {id=78471,name="Convergence",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,description="We know the nerubians are in league with Xal'atath. An' we have a fair idea why they attacked us--and Dalaran. They seem bent on destroying the earthen--even kickin' 'em when they're down. But why? Is it because the Coreway is the key an' destroyin' it was nae enough? Maybe what we're doin' here, repairin' the Coreway, is just what they dunnae want us to do. We should go back to Dornogal an try to piece this together.",starts={{npcID=217898,x=0.564,y=0.48,zoneID=14717}},ends={{npcID=217905,x=0.402,y=0.26,zoneID=14771}},coords={x=0.564,y=0.48,source="quest_giver",zoneID=14717},questType="standard"},
[78504] = {id=78504,name="A Gently Shaken Gift",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=1637,mapID=85,starts={{npcID=180746,x=0.334,y=0.659,mapID=87},{npcID=180746,x=0.491,y=0.782,mapID=85}},ends={{npcID=180746,x=0.334,y=0.659,mapID=87},{npcID=180746,x=0.491,y=0.782,mapID=85}},coords={x=0.334,y=0.659,source="quest_giver",mapID=85},questType="standard"},
[78529] = {id=78529,name="Violent Impact",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,ends={{npcID=211993,x=0.294,y=0.55,zoneID=14717},{npcID=211994,x=0.294,y=0.55,zoneID=14717}},questType="standard"},
[78530] = {id=78530,name="Slay the Saboteurs",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="The nerubians are everywhere, . There are too many for all of them to be solely crash survivors. I've seen others burrowing up from the ground. This Queensguard Zirix was laying in wait here to overwhelm us. Let them know we are not easy prey. Cut them down!",starts={{npcID=211994,x=0.294,y=0.55,zoneID=14717}},ends={{npcID=211994,x=0.294,y=0.55,zoneID=14717}},coords={x=0.294,y=0.55,source="quest_giver",zoneID=14717},questType="standard"},
[78531] = {id=78531,name="Urgent Recovery",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="We survived mostly unharmed. Not everyone was so lucky. Many who were in Dalaran when it went down are unaccounted for. They will need our help. Search the battlefield for survivors. Help them in any way you can. We need everyone up and fighting!",starts={{npcID=211993,x=0.294,y=0.55,zoneID=14717}},ends={{npcID=211993,x=0.294,y=0.55,zoneID=14717}},coords={x=0.294,y=0.55,source="quest_giver",zoneID=14717},questType="standard"},
[78532] = {id=78532,name="Erratic Artifacts",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="Dalaran housed many precious and powerful relics. Many of them were damaged in the crash and are now malfunctioning. They must be destroyed! Take this scroll. I have stored a shattering spell within it. Read the words aloud and its magic will be unleashed. Report what you have done to Jaina when you are through. She will understand.",starts={{npcID=223166,x=0.308,y=0.55,zoneID=14717}},ends={{npcID=211994,x=0.294,y=0.55,zoneID=14717}},coords={x=0.308,y=0.55,source="quest_giver",zoneID=14717},questType="standard"},
[78533] = {id=78533,name="Secure the Beach",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="Queensguard Zirix emerged from the ground and surprised Magni. He's near the farthest edge of the wreckage fighting off his swarm. Moira and I were trying to help, but we couldn't draw them away. Come with me. Magni needs our help!",starts={{npcID=212450,x=0.294,y=0.55,zoneID=14717}},ends={{npcID=211859,x=0.304,y=0.558,zoneID=14717}},coords={x=0.294,y=0.55,source="quest_giver",zoneID=14717},questType="standard"},
[78534] = {id=78534,name="To Dornogal",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,description="You have brought death and destruction to our shores the likes of which has not been seen in millennia. But you have nerubian blood on your hands and a thraegar at your side. This is enough to earn my trust--for now. My Stormriders and I must return to our capital, Dornogal, and investigate what is likely an ongoing attack there. Fly with us. Our slipstream will allow you to soar through the skies with ease. I will send other Stormriders to collect your allies once it is safe for them to land.",starts={{npcID=211859,x=0.304,y=0.558,zoneID=14717}},ends={{npcID=216628,x=0.336,y=0.754,zoneID=14771}},coords={x=0.304,y=0.558,source="quest_giver",zoneID=14717},questType="standard"},
[78535] = {id=78535,name="They Come from Below",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,description="I do not yet know why you have come here, outlander. But you seem... efficient in killing nerubians. As are we, the Stormriders, vanguards of this isle. The nerubians are an ancient enemy. I would not be surprised if this Zirix knows and fears me, the Stormward. Even so, we could use your skill to help us protect Dornogal. I have a stormrook for you to ride. Mount up and help us rid our city of these insects!",starts={{npcID=216628,x=0.336,y=0.754,zoneID=14771}},ends={{npcID=217852,x=0.362,y=0.644,zoneID=14771}},coords={x=0.336,y=0.754,source="quest_giver",zoneID=14771},questType="standard"},
[78536] = {id=78536,name="Impossible Odds",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,description="By the titans... The Coreway appears completely destroyed! It will take years, perhaps centuries, to remove the rubble and repair the damage the nerubians did to its inner structure, much less traverse to the world's core. More than that with the Stonebound gone... I must take a moment to decide what to do. Your friends have safely arrived. Speak to them, and stay out of my way. If we need you, I will let you know.",starts={{npcID=217852,x=0.362,y=0.644,zoneID=14771}},ends={{npcID=217852,x=0.362,y=0.644,zoneID=14771}},coords={x=0.362,y=0.644,source="quest_giver",zoneID=14771},questType="standard"},
[78538] = {id=78538,name="Group Effort",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,description="The Unbound have arrived with the equipment and resources needed to begin repairing the Coreway. This is a momentous occasion. One for the Archive! I would not say this to Adelgonn, but I see the titans' hands in it... And now it is time for me to exercise my directive! I have devised a plan for how to organize our workers most efficiently--and have also allocated supplies to welcome them. Take these orders to Adelgonn's workers so that they can begin in earnest. We will meet you there shortly.",starts={{npcID=217904,x=0.4,y=0.26,zoneID=14771}},ends={{npcID=212746,x=0.36,y=0.526,zoneID=14771}},coords={x=0.4,y=0.26,source="quest_giver",zoneID=14771},questType="standard"},
[78539] = {id=78539,name="Lasting Repairs",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,description="With my Stormriders... inactive, Dornogal is undefended, save a handful of lay peacekeepers. If the nerubians attack us here again, Dornogal will fall--and all of us with it. It is imperative we draw them away from the city and take out their commander. We can and will make our own web and capture Zirix in it. I have a plan.",starts={{npcID=222555,x=0.36,y=0.526,zoneID=14771}},ends={{npcID=222555,x=0.36,y=0.526,zoneID=14771}},coords={x=0.36,y=0.526,source="quest_giver",zoneID=14771},questType="standard"},
[78540] = {id=78540,name="To the Meadery",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="Your archer friend is right. We must eliminate Zirix and his forces if the Coreway is to remain safe. Let us head to the Cinderbrew Meadery at once.",starts={{npcID=222555,x=0.36,y=0.526,zoneID=14771}},ends={{npcID=212749,x=0.752,y=0.432,zoneID=14717}},coords={x=0.36,y=0.526,source="quest_giver",zoneID=14771},questType="standard"},
[78541] = {id=78541,name="Lay the Trap",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="With all these cinderbrew kegs here, this meadery would burn hotter than the Forgegrounds if they were all ignited. I surmise that's why Wenbrandt's kegs are made out of stout and strong ironwood--they do not break or catch fire easily. Luckily, we can start a reaction from the inside if we lead fuses into each of them. Those ropes the workers left around should work in a pinch.",starts={{npcID=212749,x=0.752,y=0.432,zoneID=14717}},ends={{npcID=212749,x=0.752,y=0.432,zoneID=14717}},coords={x=0.752,y=0.432,source="quest_giver",zoneID=14717},questType="standard"},
[78542] = {id=78542,name="Evacuation Area",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="Look, you can blow up my life's work if it is our only choice, but I will not put my workers in danger. This was the path we all chose, but I won't have them sacrifice themselves to fire or nerubians for it. Tell them that I said they need to get out of here immediately. And if a single one of them gets so much as chipped, the Council will have a lot to answer for!",starts={{npcID=212750,x=0.752,y=0.432,zoneID=14717}},ends={{npcID=212750,x=0.752,y=0.432,zoneID=14717}},coords={x=0.752,y=0.432,source="quest_giver",zoneID=14717},questType="standard"},
[78543] = {id=78543,name="Poking the Spider Nest",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="The meadery is evacuated and the explosives are primed. It is time to bait the nerubians into our trap. Your compatriot is by the nerubian burrow north of here. She told me her directive is to keep watch over it in case the nerubians make a move before we are ready. So far they have not made a move and may now need... coaxing. Take a keg of cinderbrew to the burrow. Tossing it in should stir their \"nest.\" Rendezvous with us back at the Meadyard--quickly--after.",starts={{npcID=212749,x=0.752,y=0.432,zoneID=14717}},ends={{npcID=212756,x=0.748,y=0.422,zoneID=14717}},coords={x=0.752,y=0.432,source="quest_giver",zoneID=14717},questType="standard"},
[78544] = {id=78544,name="Bring the Thunder",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="The nerubians will strike out in anger and pride--which is exactly what we want. They will swarm the meadery soon, seeking to punish us for attacking their burrow. We will hold them here on the ground while you take to the skies. When Zirix appears to command his army, we will light the fuses. Wenbrandt scrounged together some supplies we can use to corral the nerubians. Set them up quickly, and then we will get you on a stormrook. Go!",starts={{npcID=212756,x=0.748,y=0.422,zoneID=14717}},ends={{npcID=217849,x=0.75,y=0.438,zoneID=14717}},coords={x=0.748,y=0.422,source="quest_giver",zoneID=14717},questType="standard"},
[78545] = {id=78545,name="Return to the Coreway",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,description="We dealt a heavy blow to the nerubians. But Baelgrim... Adelgonn pauses to compose herself.> He was infuriatingly rigid and we argued ceaselessly, but in the end... he was a defender of our people--all of them. Baelgrim sacrificed himself to vouchsafe the Isle of Dorn from the nerubians. Everyone needs to know that--and we can't let the nerubians force our hand like that again. Go back to Merrix in Dornogal. Tell him we will come soon. We just... need a moment here.",starts={{npcID=217849,x=0.75,y=0.438,zoneID=14717}},ends={{npcID=217880,x=0.32,y=0.596,zoneID=14771}},coords={x=0.75,y=0.438,source="quest_giver",zoneID=14717},questType="standard"},
[78546] = {id=78546,name="Recompense",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,description="We heard the echo of the explosion from here. I presume you have found victory, but your solitary arrival suggests not all is well. What happened?",starts={{npcID=217880,x=0.32,y=0.596,zoneID=14771}},ends={{npcID=217880,x=0.32,y=0.596,zoneID=14771}},coords={x=0.32,y=0.596,source="quest_giver",zoneID=14771},questType="standard"},
[78555] = {id=78555,name="Underground and Overwhelmed",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="I've been away too long. The Machine Speakers are clearly not faring well here. Does the High Speaker know about this? Nerubian sabotage and gross negligence are a devastating combination. We need to get Ironhaul Station up and running as soon as possible. It's a vital link between the Ringing Deeps and the city up above. Please, $p, help our injured workers, collect any salvageable cargo, and restore safety to Ironhaul Station.",starts={{npcID=212592,x=0.42,y=0.284,zoneID=14795}},ends={{npcID=212592,x=0.42,y=0.284,zoneID=14795}},coords={x=0.42,y=0.284,source="quest_giver",zoneID=14795},questType="standard"},
[78557] = {id=78557,name="Getting Off Track",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="Speaker Brinthe acknowledged. Outlanders, there is work to do. One of our larger mine carts has derailed. It's blocking the station's main junction. My workers' productivity is impaired, and their functioning is suboptimal. The titans put us here to work, but my workers aren't all working. Could you go and get us back on track? Be careful. I can see you're made of flesh and bone. I don't want you to be crushed.",starts={{npcID=218290,x=0.42,y=0.282,zoneID=14795}},ends={{npcID=218290,x=0.42,y=0.282,zoneID=14795}},coords={x=0.42,y=0.282,source="quest_giver",zoneID=14795},questType="standard"},
[78562] = {id=78562,name="Discarded and Broken",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="You there! You're here to help, aren't you? The humming melody of the machines is changing, and I... I admit I am not ready. For so many years I served faithfully, and then... Well the important thing is that I'm ready to get to work again. But you see, my tools have all been broken and scattered about. If you could keep an eye out for them and bring them back to me, I would be in your debt.",starts={{npcID=212695,x=0.482,y=0.334,zoneID=14795}},ends={{npcID=212695,x=0.482,y=0.334,zoneID=14795}},coords={x=0.482,y=0.334,source="quest_giver",zoneID=14795},questType="standard"},
[78563] = {id=78563,name="The Weight of a World",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="My tools didn't randomly end up where you found them. They were placed there. By me. I had reached a point so low that I saw no alternative. The machines, the great work of my people, were never going to sing again. So why should I bother to keep them repaired? But now I see, and now, I understand! The last tool I need, I dropped it into the water, and it was eaten by a giant creature. I think that one might need a bit more force to return it to me.",starts={{npcID=212695,x=0.482,y=0.334,zoneID=14795}},ends={{npcID=212695,x=0.482,y=0.334,zoneID=14795}},coords={x=0.482,y=0.334,source="quest_giver",zoneID=14795},questType="standard"},
[78564] = {id=78564,name="Reforged Purpose",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="That's all of them! Now, it's time to do my duty and recast these tools. Reforge them, and myself, into what I was meant to be: a proud machinist of the Ringing Deeps .",starts={{npcID=212695,x=0.482,y=0.334,zoneID=14795}},ends={{npcID=212695,x=0.482,y=0.334,zoneID=14795}},coords={x=0.482,y=0.334,source="quest_giver",zoneID=14795},questType="standard"},
[78570] = {id=78570,name="Frayed Legacy",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="Keep true, t. We of the Woldguard uphold an ancient promise to Freya to tend to these lands. Our edict is older than those wielded by the demagogues in Dornogal. Older than Dornogal itself. However, not all lands have been tended equally. The leader of our order was to care for the basin nearby but we've not heard from them in many cycles. I have sent a novice to investigate. Aid them and my order will be in your favor.",starts={{npcID=212708,x=0.416,y=0.714,zoneID=14717}},ends={{npcID=212700,x=0.536,y=0.698,zoneID=14717}},coords={x=0.416,y=0.714,source="quest_giver",zoneID=14717},questType="standard"},
[78571] = {id=78571,name="Mycomayhem",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="Freydrin was the leader of my order. I was sent here to assist them. I was too late. There is a darkness that haunts these woods, s. These woods were Freydrin's home. It was her charge to tend to them, so given by the Keeper herself. And now she is gone and her woods run amok. Bring me the spores of these mayhemic menaces. Perhaps there is a way to cleanse this land yet.",starts={{npcID=212700,x=0.536,y=0.698,zoneID=14717}},ends={{npcID=212700,x=0.536,y=0.698,zoneID=14717}},coords={x=0.536,y=0.698,source="quest_giver",zoneID=14717},questType="standard"},
[78572] = {id=78572,name="Wold Memories",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="Freydrin must have had some way of fending off the fungarians. Although there are few left in the countryside who still follow the Edicts, Freydrin was long a true believer. She would never have allowed these woods to reach this state while she held faith. We should take a look at her home in the woods. Perhaps there is something that may prove useful inside.",starts={{npcID=212700,x=0.536,y=0.698,zoneID=14717}},ends={{npcID=218333,x=0.542,y=0.652,zoneID=14717}},coords={x=0.536,y=0.698,source="quest_giver",zoneID=14717},questType="standard"},
[78573] = {id=78573,name="Keeper's Aid",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="Magical staff? Wards? What were you doing, Freydrin? I've got it! The life energy in this staff should overcome any mycotic corruptions in the wildlife here. Then you return them to the natural cycle and the land will heal on its own in time. And if you see any wards, take them down. Take her memory gem just in case. It may yield more information yet.",starts={{npcID=218333,x=0.542,y=0.652,zoneID=14717}},ends={{npcID=218333,x=0.542,y=0.652,zoneID=14717}},coords={x=0.542,y=0.652,source="quest_giver",zoneID=14717},questType="standard"},
[78574] = {id=78574,name="Boss of the Bosk",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="There is one final thing I must ask of you. There is a great monster that roams these woods. I am certain you've sensed it. It must be felled. Rotbark was Freydrin's final means to control this basin, but even this was too great for any individual earthen. Ours is not to control, but to tend to its needs. Use the staff once more and bring an end to Rotbark's reign.",starts={{npcID=218333,x=0.542,y=0.652,zoneID=14717}},ends={{npcID=218333,x=0.542,y=0.652,zoneID=14717}},coords={x=0.542,y=0.652,source="quest_giver",zoneID=14717},questType="standard"},
[78579] = {id=78579,name="Dragon Isles Supplies",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,starts={{npcID=208143,x=0.502,y=0.616,mapID=2200}},ends={{npcID=208143,x=0.502,y=0.616,mapID=2200}},coords={x=0.502,y=0.616,source="quest_giver",mapID=2200},questType="standard"},
[78580] = {id=78580,name="Dragon Isles Supplies",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,starts={{npcID=208143,x=0.502,y=0.616,mapID=2200}},ends={{npcID=208143,x=0.502,y=0.616,mapID=2200}},coords={x=0.502,y=0.616,source="quest_giver",mapID=2200},questType="standard"},
[78581] = {id=78581,name="Dragon Isles Supplies",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,starts={{npcID=208143,x=0.502,y=0.616,mapID=2200}},ends={{npcID=208143,x=0.502,y=0.616,mapID=2200}},coords={x=0.502,y=0.616,source="quest_giver",mapID=2200},questType="standard"},
[78582] = {id=78582,name="Dragon Isles Supplies",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,starts={{npcID=208143,x=0.502,y=0.616,mapID=2200}},ends={{npcID=208143,x=0.502,y=0.616,mapID=2200}},coords={x=0.502,y=0.616,source="quest_giver",mapID=2200},questType="standard"},
[78583] = {id=78583,name="Dragon Isles Supplies",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,starts={{npcID=208143,x=0.502,y=0.616,mapID=2200}},ends={{npcID=208143,x=0.502,y=0.616,mapID=2200}},coords={x=0.502,y=0.616,source="quest_giver",mapID=2200},questType="standard"},
[78584] = {id=78584,name="Dragon Isles Supplies",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,starts={{npcID=208143,x=0.502,y=0.616,mapID=2200}},ends={{npcID=208143,x=0.502,y=0.616,mapID=2200}},coords={x=0.502,y=0.616,source="quest_giver",mapID=2200},questType="standard"},
[78585] = {id=78585,name="Dragon Isles Supplies",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,starts={{npcID=208143,x=0.502,y=0.616,mapID=2200}},ends={{npcID=208143,x=0.502,y=0.616,mapID=2200}},coords={x=0.502,y=0.616,source="quest_giver",mapID=2200},questType="standard"},
[78586] = {id=78586,name="Dragon Isles Supplies",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,starts={{npcID=208143,x=0.502,y=0.616,mapID=2200}},ends={{npcID=208143,x=0.502,y=0.616,mapID=2200}},coords={x=0.502,y=0.616,source="quest_giver",mapID=2200},questType="standard"},
[78587] = {id=78587,name="Dragon Isles Supplies",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,starts={{npcID=208143,x=0.502,y=0.616,mapID=2200}},ends={{npcID=208143,x=0.502,y=0.616,mapID=2200}},coords={x=0.502,y=0.616,source="quest_giver",mapID=2200},questType="standard"},
[78588] = {id=78588,name="Dragon Isles Supplies",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,starts={{npcID=208143,x=0.502,y=0.616,mapID=2200}},ends={{npcID=208143,x=0.502,y=0.616,mapID=2200}},coords={x=0.502,y=0.616,source="quest_giver",mapID=2200},questType="standard"},
[78589] = {id=78589,name="Invasive Cuisine",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,description="Chef Dinaire .>",ends={{npcID=206533,x=0.644,y=0.31,zoneID=14838}},questType="standard"},
[78598] = {id=78598,name="Dream Infusion",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14529,mapID=2200,starts={{npcID=211209,x=0.502,y=0.618,mapID=2200}},ends={{npcID=211209,x=0.502,y=0.618,mapID=2200}},coords={x=0.502,y=0.618,source="quest_giver",mapID=2200},questType="standard"},
[78614] = {id=78614,name="Mereldar's Light",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="I still need more time with Alleria to learn about Xal'atath. What I have learned is very worrying. Faerin sent word that she was going to the orphanage, and asked you to meet her there. She often entertains the children while she is in Mereldar, I don't doubt she would appreciate you doing the same.",starts={{npcID=213108,x=0.34,y=0.546,zoneID=14838}},ends={{npcID=220124,x=0.426,y=0.556,zoneID=14838}},coords={x=0.34,y=0.546,source="quest_giver",zoneID=14838},questType="standard"},
[78615] = {id=78615,name="The Bell Tolls",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="Those bells mean Mereldar is under attack! Let's get to the gates and find out what is going on.",starts={{npcID=220124,x=0.426,y=0.556,zoneID=14838}},ends={{npcID=213107,x=0.41,y=0.546,zoneID=14838}},coords={x=0.426,y=0.556,source="quest_giver",zoneID=14838},questType="standard"},
[78621] = {id=78621,name="The Shadow Rising",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="I can sense three beacons of void ahead, all funneling their power into one massive font of darkness. You will need to kill them. With them dead, I can bring down the shield.",starts={{npcID=214402,x=0.41,y=0.546,zoneID=14838}},ends={{npcID=214402,x=0.41,y=0.546,zoneID=14838}},coords={x=0.41,y=0.546,source="quest_giver",zoneID=14838},questType="standard"},
[78626] = {id=78626,name="Spar Day",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="Your skills in combat are impressive, . We are rotating our next round of reserves into active duty, and they need to sharpen their skills. While Alleria fills me in on Xal'atath, I would appreciate it if you could help with their training.",starts={{npcID=213108,x=0.34,y=0.546,zoneID=14838}},ends={{npcID=213108,x=0.34,y=0.546,zoneID=14838}},coords={x=0.34,y=0.546,source="quest_giver",zoneID=14838},questType="standard"},
[78631] = {id=78631,name="Speaking to the Speakers",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="I've heard about a problem nearby, and I think I know what's wrong. We used to have a mining operation northeast of Gundargaz. When we moved out, kobolds moved in. We haven't heard from those kobolds in a long time, but it sounds like they're raiding us now! And the High Speaker is doing nothing about it. Someone has to do something. If we can solve this, more Machine Speakers will listen to us. If the High Speaker doesn't get results, we will.",starts={{npcID=212741,x=0.472,y=0.342,zoneID=14795}},ends={{npcID=212519,x=0.576,y=0.292,zoneID=14795}},coords={x=0.472,y=0.342,source="quest_giver",zoneID=14795},questType="standard"},
[78634] = {id=78634,name="Leave No Stone Behind",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="Many earthen fell when the kobolds took this mine. Worse, those who fell were left to crumble where they dropped. There was no attempt to recover them. We couldn't provide closure or respect their memories. Why? Why did we forsake the fallen? We will not fail them again, . Gather the identification plaques of those we lost, so we may commemorate them properly.",starts={{npcID=212519,x=0.576,y=0.292,zoneID=14795}},ends={{npcID=212519,x=0.576,y=0.292,zoneID=14795}},coords={x=0.576,y=0.292,source="quest_giver",zoneID=14795},questType="standard"},
[78635] = {id=78635,name="Death and Waxes",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="Kobolds take candles seriously. Wax, even more. More important than gold. More important than freedom! We steal candles from Candle King. We make him look weak. Bully that looks weak loses control. Gets dead! Also means we not have to wait out here in dark until get eaten. Hurry!",starts={{npcID=212269,x=0.576,y=0.292,zoneID=14795}},ends={{npcID=212269,x=0.576,y=0.292,zoneID=14795}},coords={x=0.576,y=0.292,source="quest_giver",zoneID=14795},questType="standard"},
[78636] = {id=78636,name="Retaking the Mines",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="Now that we have the keys, it is time to take the fight to the Candle King. Get that gate open. Once we're inside, we'll move on to the next step.",starts={{npcID=212519,x=0.576,y=0.292,zoneID=14795}},ends={{npcID=215671,x=0.594,y=0.218,zoneID=14795}},coords={x=0.576,y=0.292,source="quest_giver",zoneID=14795},questType="standard"},
[78637] = {id=78637,name="Cracking Cogchewer",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="Cogchewer is muscle for Candle King. So mean! Rebuilds earthen gears for wars. Also in charge of mine's defenses. Need his keys to get in the mines... and get me out of this thing!",starts={{npcID=212269,x=0.576,y=0.292,zoneID=14795}},ends={{npcID=212269,x=0.576,y=0.292,zoneID=14795}},coords={x=0.576,y=0.292,source="quest_giver",zoneID=14795},questType="standard"},
[78638] = {id=78638,name="Engineering Destruction",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="Some of the kobolds are retrofitting equipment left behind when the mines fell. Please, destroy the rigs before they're used against us. I'd rather they be scrap than in the hands of an enemy. There was a storage depot on the western edge of the lowest level of the mine. Start there.",starts={{npcID=212519,x=0.576,y=0.292,zoneID=14795}},ends={{npcID=212519,x=0.576,y=0.292,zoneID=14795}},coords={x=0.576,y=0.292,source="quest_giver",zoneID=14795},questType="standard"},
[78639] = {id=78639,name="Ko-boldening",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="Bullies everywhere! Innocent kobolds kept down by Candle King's thugs all across Warrens. Give bullies taste of own medicine! Once bullies beaten, innocent have chance to run. Be free!",starts={{npcID=212991,x=0.614,y=0.32,zoneID=14795}},ends={{npcID=212991,x=0.614,y=0.32,zoneID=14795}},coords={x=0.614,y=0.32,source="quest_giver",zoneID=14795},questType="standard"},
[78640] = {id=78640,name="Manifesto Destiny",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="Before take mines, my people live in great city. Stoneheads call it the Warrens. Candle King's bullies run it now. We need see what we are fighting. Let kobolds know we here to help! Better choices than Candle King. What better way than pamphlets? Everyone love pamphlet! We draw real good! Brinthe say you have some sort of flying dragon-bird-thing? Perfect for scout! Perfect for dropping pamphlets! Skitter looks at you expectantly, making small flapping motions as she waits.>",starts={{npcID=215672,x=0.594,y=0.218,zoneID=14795}},ends={{npcID=212991,x=0.614,y=0.32,zoneID=14795}},coords={x=0.594,y=0.218,source="quest_giver",zoneID=14795},questType="standard"},
[78641] = {id=78641,name="Tackling Torchsnarl",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="Torchsnarl runs Warrens for Candle King. Nothing but big bully! Very, very big bully. We show everyone. Bullies can be beaten!",starts={{npcID=212991,x=0.614,y=0.32,zoneID=14795}},ends={{npcID=212991,x=0.614,y=0.32,zoneID=14795}},coords={x=0.614,y=0.32,source="quest_giver",zoneID=14795},questType="standard"},
[78642] = {id=78642,name="New Candle, New Hope",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="We weaken Candle King's grasp. Still need symbol, rally my people. King has ancient relic: symbol of hope. Called Candle Crown . Heart of my people. Candle King threw away! Found new prize: Darkflame Candle. That crown? Still in hoard. Candle King should come out now. See what we did here! While he looks, we sneak in! Use old tunnels! Take what's ours! We smart.",starts={{npcID=212991,x=0.614,y=0.32,zoneID=14795}},ends={{npcID=212991,x=0.614,y=0.32,zoneID=14795}},coords={x=0.614,y=0.32,source="quest_giver",zoneID=14795},questType="standard"},
[78656] = {id=78656,name="Hose It Down",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,description="With the flame restored, you can see the extent of contamination to the fishing hole. Kobyss and frogs have left heaps of strange goo that pollutes the shoreline. We need your help to clean up this gooey blight! I have a specially modified harvester equipped with a water barrel. Use this device to spray water on the goo piles and clean the shore of this contamination.",starts={{npcID=215956,x=0.658,y=0.244,zoneID=14838}},ends={{npcID=215956,x=0.658,y=0.244,zoneID=14838}},coords={x=0.658,y=0.244,source="quest_giver",zoneID=14838},questType="standard"},
[78658] = {id=78658,name="The Hallowed Path",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="$p, I'm glad our paths have crossed. Adelgonn has been telling me about a cavern called Hallowfall . She's told me the people there are called the Arathi. I cannot imagine that they are related to the ancient human kingdom, but it can't be a coincidence. Adelgonn's people had fruitful contact with them some time ago. Whatever happened, I hope to repair that relationship and gain their aid. Please meet me at the Hallowfall Gate.",starts={{npcID=213983,x=0.47,y=0.322,zoneID=14795}},ends={{npcID=213116,x=0.684,y=0.45,zoneID=14838}},coords={x=0.47,y=0.322,source="quest_giver",zoneID=14795},questType="standard"},
[78659] = {id=78659,name="Where the Light Touches",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="Many in Hallowfall will call you \"outsider\". I would call you friend. I would also ask for your help, if you are no stranger to combat. Desperate times forge strong friendships. General Steelstrike ordered the army to fall back from the nerubian onslaught. In doing so, she abandoned a Lamplighter and many troops to the darkness. I may not be able to save them on my own, but with your help I may succeed. If you're willing, ride with me or meet me there.",starts={{npcID=213116,x=0.684,y=0.45,zoneID=14838}},ends={{npcID=224310,x=0.7,y=0.612,zoneID=14838}},coords={x=0.684,y=0.45,source="quest_giver",zoneID=14838},questType="standard"},
[78665] = {id=78665,name="Tunnel Trouble",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14752,description="It's good to have new allies here. Together, we have much better chances of protecting this tower. The nerubians have overwhelmed us. If we're going to have any chance against them, we need to destroy the burrows they're using to come under the Wall. If you can handle that, we will survey the field from the top of the wall and meet you there.",starts={{npcID=224310,x=0.7,y=0.612,zoneID=14838}},ends={{npcID=224310,x=0.7,y=0.612,zoneID=14838}},coords={x=0.7,y=0.612,source="quest_giver",zoneID=14838},questType="standard"},
[78666] = {id=78666,name="The Only Good Spider",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="$p, if we don't stem the tide of nerubians climbing up to us, nothing else will matter. Their numbers are just too great. We need to delay their onslaught to buy the people of Hallowfall time to prepare. The wall still serves as a very effective chokepoint. Do what you can to thin their numbers.",starts={{npcID=224310,x=0.7,y=0.612,zoneID=14838}},ends={{npcID=224310,x=0.7,y=0.612,zoneID=14838}},coords={x=0.7,y=0.612,source="quest_giver",zoneID=14838},questType="standard"},
[78667] = {id=78667,name="Rekindled Memories",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="Good people died here today, $p--a lot of them. Every Arathi soldier carries a tinderbox. It represents their devotion to the Sacred Flame. Many use it as a focus to bring forth the Flame's light. In the dark places beyond the light of Beledar, the Sacred Flame brings hope. With the nerubian attack, we can't recover their bodies. So we must retrieve these symbols, to venerate their sacrifice. Then use this torch to burn their bodies. It's the best funeral we can offer.",starts={{npcID=213116,x=0.684,y=0.45,zoneID=14838}},ends={{npcID=213116,x=0.684,y=0.45,zoneID=14838}},coords={x=0.684,y=0.45,source="quest_giver",zoneID=14838},questType="standard"},
[78668] = {id=78668,name="Rally on the Dawnbreaker",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="It's critical, with so many nerubians pouring through the Aegis Wall, that we defend our airships docked at Tenir's Ascent. The nerubians have always outnumbered us, but our fleet allows us to concentrate our defenders where they are attacking, as well as allowing us to bombard them from the safety of the skies. If we lose our armada, our hopes fade dramatically. Meet us there when you can.",starts={{npcID=213116,x=0.684,y=0.45,zoneID=14838}},ends={{npcID=224945,x=0.574,y=0.644,zoneID=14838}},coords={x=0.684,y=0.45,source="quest_giver",zoneID=14838},questType="standard"},
[78669] = {id=78669,name="For Their Eyes Only",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="We've fought the nerubians since we arrived, $p. Their attacks have not risen to this level in a long time. These airship docks are clearly a target, but do they have any others? Is there a larger goal? The nerubians carry shadecasters with orders from their queen. We need to learn what we can of their plans and intentions, and recovering a few of those shadecasters is the best way we can do so.",starts={{npcID=224946,x=0.574,y=0.644,zoneID=14838}},ends={{npcID=213120,x=0.568,y=0.682,zoneID=14838}},coords={x=0.574,y=0.644,source="quest_giver",zoneID=14838},questType="standard"},
[78670] = {id=78670,name="Siege Weapon Sabotage",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="$p, if we're going to hold the nerubians back, we have to deal with their siege weapons. Around Tenir's Ascent, there are kegs of black powder to supply our ships for combat. Since the nerubians have caught these ships on the ground, let's put that powder to work. Gather some barrels, and take them down to the nerubian siege weapons.",starts={{npcID=224945,x=0.574,y=0.644,zoneID=14838}},ends={{npcID=213120,x=0.568,y=0.682,zoneID=14838}},coords={x=0.574,y=0.644,source="quest_giver",zoneID=14838},questType="standard"},
[78671] = {id=78671,name="The Light of the Dawntower",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="$p, Faerin went to light the dawntower. She said it keeps the light of the Sacred Flame shining upon Hallowfall . Kyron is there as well. It's hard to imagine that any beacon could outshine their star Beledar, but I am eager to see this new expression of the Light. Meet me by the dawntower and we can see how the Sacred Flame of the Arathi helps to safeguard these long-lost cousins of mine.",starts={{npcID=213120,x=0.568,y=0.682,zoneID=14838}},ends={{npcID=213116,x=0.684,y=0.45,zoneID=14838}},coords={x=0.568,y=0.682,source="quest_giver",zoneID=14838},questType="standard"},
[78672] = {id=78672,name="A Lamplighter's Duty",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="Darkness has fallen. We can't rest yet. Faerin gives you a weary smile, but there is a light in her eyes.> The light from the tower will hold the worst dangers in the darkness at bay. It's my duty, as a Lamplighter, to keep all the towers blazing. My patrol takes me to Lorel's Crossing by air next. I would welcome you and Anduin at my side, for all our sakes.",starts={{npcID=213116,x=0.684,y=0.45,zoneID=14838}},ends={{npcID=214378,x=0.538,y=0.314,zoneID=14838}},coords={x=0.684,y=0.45,source="quest_giver",zoneID=14838},questType="standard"},
[78686] = {id=78686,name="Lights Out",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="Name's Aegor. I try to keep tabs on Lamplighters in the field and assess what areas of Hallowfall may be in need of their aid. The dawntower fell dark at Velhan's Claim a few weeks ago. Based on what's been happening around Hallowfall , it's probably because of the rising tide of kobyss. Lamplighters Taenar and Aemyra are heading there, but this might be more than even two Lamplighters together can handle. Will you meet them there and help them restore the light at Velhan's Claim?",starts={{npcID=214019,x=0.492,y=0.41,zoneID=14838}},ends={{npcID=213614,x=0.458,y=0.13,zoneID=14838}},coords={x=0.492,y=0.41,source="quest_giver",zoneID=14838},questType="standard"},
[78687] = {id=78687,name="Crash Recovery",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="A lot of things went wrong when the Indomitable crashed, $p. But the most upsetting one is that--when the order was finally given to make our way back to Mereldar, we couldn't honor our fallen comrades. It seems the kobyss reanimated our fallen stalwarts, who now wander the Indomitable in a ghastly skeletal form. Take back their tinderboxes. If we can deliver those to the Sacred Flame, they'll finally be free after all these years.",starts={{npcID=213614,x=0.458,y=0.13,zoneID=14838}},ends={{npcID=213614,x=0.458,y=0.13,zoneID=14838}},coords={x=0.458,y=0.13,source="quest_giver",zoneID=14838},questType="standard"},
[78688] = {id=78688,name="Cage, Match",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="When we were scouting before you arrived, we saw a lot of cages set up around Velhan's Claim. Typically, the kobyss use these to hold their victims until they're needed for a ritual sacrifice. Those sacrifices lead to... lots of other dark activities. Not the least of which is eating the victims. Let's get ahead of all that. Take my torch, and destroy the cages, so we don't have to see that happen to anyone from Velhan's Claim.",starts={{npcID=213613,x=0.458,y=0.13,zoneID=14838}},ends={{npcID=213613,x=0.458,y=0.13,zoneID=14838}},coords={x=0.458,y=0.13,source="quest_giver",zoneID=14838},questType="standard"},
[78689] = {id=78689,name="If It Leads, It Bleeds",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="Everything rises and falls on leadership, $p. With a good leader, a unit can achieve almost anything. With a bad leader, chaos ensues and success moves out of reach. I've seen that first-hand. Without leaders, the kobyss siege will break like a wave and everything else we do here becomes easier. I've seen three kobyss who seem to be leading the others--let me mark their locations on your map. Deal with them, and we'll be much more able to help Velhan's Claim.",starts={{npcID=213614,x=0.458,y=0.13,zoneID=14838}},ends={{npcID=213614,x=0.458,y=0.13,zoneID=14838}},coords={x=0.458,y=0.13,source="quest_giver",zoneID=14838},questType="standard"},
[78690] = {id=78690,name="Situational Awareness",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="Regardless of what history Taenar and Velhan have between them, we need to take care of the people here at Velhan's Claim. $p, will you please check in with the families here? Let them know we're here to help. See if they're worried or need anything. And reassure them that the Lamplighters will drive back the kobyss.",starts={{npcID=213613,x=0.458,y=0.13,zoneID=14838}},ends={{npcID=213613,x=0.458,y=0.13,zoneID=14838}},coords={x=0.458,y=0.13,source="quest_giver",zoneID=14838},questType="standard"},
[78691] = {id=78691,name="The One That Got Away",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="$p, my son is out with the kobyss. He convinced the other kids they should sneak out with him to fight. Said they should, \"be brave like my dad\". When they met a kobyss, the others all ran back here, while he ran toward the crashed ship, to lead it away. I have not handled myself bravely, $p. The story of the Indomitable says I was a hero; those lies were my report. If there was ever a time to step up, it's now. But I'm no match for the kobyss alone. Come with me, $p--help me save Maximillian.",starts={{npcID=213787,x=0.458,y=0.13,zoneID=14838}},ends={{npcID=213787,x=0.458,y=0.13,zoneID=14838}},coords={x=0.458,y=0.13,source="quest_giver",zoneID=14838},questType="standard"},
[78692] = {id=78692,name="Teach a Man to Fish",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="$p, the people of Velhan's Claim have been locked up inside, afraid of the dark, for too long. And there's plenty to fear out there, but these are capable, strong people. They should be driving the kobyss away, not hiding behind their walls. Get these spears to the people of Velhan's Claim. They've learned to hide from their problems, but we'll give them the means to take their lives back!",starts={{npcID=213613,x=0.458,y=0.13,zoneID=14838}},ends={{npcID=213613,x=0.458,y=0.13,zoneID=14838}},coords={x=0.458,y=0.13,source="quest_giver",zoneID=14838},questType="standard"},
[78693] = {id=78693,name="Spears for Fears",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="It seems Velhan and his followers hoped they could live in peace here. They were so sure they could, in fact, that they didn't bring any weapons with them. This is a problem, with the kobyss attacking now, but the kobyss can actually solve it for us. They've brought plenty of spears for their siege on Velhan's Claim, and a spear will skewer a kobyss just as well as a human. Head out there and gather some spears for the people, $p, and they won't have to be so afraid.",starts={{npcID=213613,x=0.458,y=0.13,zoneID=14838}},ends={{npcID=213613,x=0.458,y=0.13,zoneID=14838}},coords={x=0.458,y=0.13,source="quest_giver",zoneID=14838},questType="standard"},
[78694] = {id=78694,name="Reclaiming Velhan's Claim",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="The problem I see, $p, is the kobyss. There's just so many of them. Everyone here was serving in the Empire's military when we arrived in Hallowfall . They may be rusty now, but they've all trained before, and know how to be dangerous. But we need to eliminate every disadvantage, including the kobyss numbers. So head out there and even up the numbers. Aemyra and I will keep everyone safe here.",starts={{npcID=213614,x=0.458,y=0.13,zoneID=14838}},ends={{npcID=213614,x=0.458,y=0.13,zoneID=14838}},coords={x=0.458,y=0.13,source="quest_giver",zoneID=14838},questType="standard"},
[78695] = {id=78695,name="Lamp Lit",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="The kobyss normally live deep underwater, $p. When Beledar is at its brightest, they don't bother us. Other sources of bright light will usually keep them away, but definitely weaken them. As Lamplighters, we not only go into the dark to protect those in need, but we provide them the light that will keep them safe. Go set up these torches along the perimeter, then meet us up at the dawntower behind Velhan's Claim.",starts={{npcID=213614,x=0.458,y=0.13,zoneID=14838}},ends={{npcID=213787,x=0.458,y=0.13,zoneID=14838}},coords={x=0.458,y=0.13,source="quest_giver",zoneID=14838},questType="standard"},
[78714] = {id=78714,name="A Poor Reception",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=7502,description="There's strong evidence that the Radiant Song is a warning from Azeroth herself. A cry for help. That's why we're here. If this vision truly is Azeroth's message, Magni will know what she's trying to tell us. He should be in the Chamber of the Heart. Let's go.",starts={{npcID=213620,x=0.418,y=0.45,zoneID=1377}},coords={x=0.418,y=0.45,source="quest_giver",zoneID=1377},questType="standard"},
[78715] = {id=78715,name="Azeroth's Voice",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=1377,description="I haven't spoken with Azeroth for years. At first I just didn't feel the need. Then I realized I had started to resent her. For leaving me like... this. And now I'm not sure if I can. But I know the stakes. This Radiant Song of hers foretells something dire. And we need to know what. First, we need to prepare the Heart Chamber. Can ye start up the consoles nearby?",ends={{npcID=213625,x=0.418,y=0.45,zoneID=1377}},questType="standard"},
[78716] = {id=78716,name="Painful Lessons",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=7502,description="Magni appears stable for now, but he's still not responsive. We need to get him treatment quickly. I'll open a portal to Dalaran . Follow us when you can.",starts={{npcID=213625,x=0.418,y=0.45,zoneID=1377}},coords={x=0.418,y=0.45,source="quest_giver",zoneID=1377},questType="standard"},
[78717] = {id=78717,name="A Mysterious Warning",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=7502,mapID=627,description="Well, that was quite the nap. I wasn't expecting Azeroth to be so... loud. To normal folk, she's gently calling out. But with our connection, it felt like she was screaming. Directly into my crystal noggin. I saw it though. Khaz Algar, an island of earthen, bathed in fire and smoke. That's where Azeroth is trying to lead us. That's what we need to protect.",questType="standard"},
[78718] = {id=78718,name="Strengthen the Wards",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=7502,mapID=627,description="Magni's vision foretells that Khaz Algar may be enduring some... turbulent times. And so it is best to ensure that Dalaran is ready for the worst. Here, take this wand. It's been attuned with Dalaran 's defense magics. Just wave it near strategic parts of the city to strengthen our magical defenses.",questType="standard"},
[78719] = {id=78719,name="Citizens of Dalaran",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=7502,mapID=627,description="Our citizens must be prepared for Dalaran 's departure. Can you ask around the city and see if anyone requires aid? I'd also like for you to speak with Brann and Archmage Drenden. They both had concerns that would be best to address before we depart for Khaz Algar.",questType="standard"},
[78721] = {id=78721,name="Meet the Team",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=7502,mapID=627,description="If we're going tae be exploring new lands in Khaz Algar, then we'll be needing help from the Explorers' League. But they won't be alone in this adventure. The League is teaming up with the Reliquary again, just like on the Dragon Isles. They're calling themselves the Algari Expedition this time around. I'm just a wee bit worried if they're still getting along. Exploring can tear folks apart just as easily as it binds them together. Can you check in on the lot?",questType="standard"},
[78722] = {id=78722,name="To Khaz Algar!",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=15177,mapID=2305,description="From what Magni has seen, Khaz Algar may not be the safest of destinations. We'll be relying on your aid, should a fight break out. Let me know when you're ready to depart.",ends={{npcID=214908,x=0.502,y=0.504,mapID=2305}},questType="standard"},
[78738] = {id=78738,name="Absent Speaker",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="It is a dark day for the Ringing Deeps , $p. I always knew there was something about the High Speaker that wasn't quite right. Now we have proof. And we need justice. If he has plans for the Awakening Machine, then we've got to stop him.",starts={{npcID=212741,x=0.472,y=0.342,zoneID=14795}},ends={{npcID=213569,x=0.47,y=0.206,zoneID=14795}},coords={x=0.472,y=0.342,source="quest_giver",zoneID=14795},questType="standard"},
[78741] = {id=78741,name="Sympathetic Speakers",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="I have to stop the High Speaker from making more skardyn. Machine Speaker protocol dictates that one of the foremen in this area should have a key to the Hall of Awakening. Come with me, and we'll track it down!",starts={{npcID=213569,x=0.47,y=0.206,zoneID=14795}},ends={{npcID=219428,x=0.49,y=0.172,zoneID=14795}},coords={x=0.47,y=0.206,source="quest_giver",zoneID=14795},questType="standard"},
[78742] = {id=78742,name="Battle of the Earthenworks",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="$p! There's a battle afoot! We need to assist Machine Speakers loyal to our cause and move against anyone defending the High Speaker. I'm going to remain and make plans with Adelgonn. I need you to lead our forces while we're containing consequences of the High Speaker's actions in the Earthenworks. This is our first step in deposing him. We're putting a stop to his horrendous crimes once and for all. What do you say, $p? Up for a scrap?",starts={{npcID=213763,x=0.47,y=0.206,zoneID=14795}},ends={{npcID=213763,x=0.47,y=0.206,zoneID=14795}},coords={x=0.47,y=0.206,source="quest_giver",zoneID=14795},questType="standard"},
[78743] = {id=78743,name="Before I Depart",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="I can feel my energy reserves depleting. I will soon not be able to execute my duties. That is why I have Urtago here to take over. Before my systems grind to a halt, I must make sure Mourning Rise is free of kobolds. They have invaded the memorial site I tend and plunder the Unbound shrines and bodies that are there. Maybe it is good you are here. You may have the strength to help us. Please, help Urtago rid the site of kobolds.",starts={{npcID=213184,x=0.574,y=0.43,zoneID=14717}},ends={{npcID=213687,x=0.616,y=0.416,zoneID=14717}},coords={x=0.574,y=0.43,source="quest_giver",zoneID=14717},questType="standard"},
[78744] = {id=78744,name="Honor Their Memories",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="Take these gifts and place them by the past caretakers. Each is a gift honoring their memory. I'd also like us to perform some light groundskeeping to at least maintain the site. Unfortunately, what these kobolds are doing to the memorials will take us weeks to fix. Please do what you can about the kobolds. It would be unwise to leave the gifts unguarded while they are still roaming the area.",starts={{npcID=213687,x=0.616,y=0.416,zoneID=14717}},ends={{npcID=213687,x=0.616,y=0.416,zoneID=14717}},coords={x=0.616,y=0.416,source="quest_giver",zoneID=14717},questType="standard"},
[78745] = {id=78745,name="You No Take Plunder!",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="It looks like the kobolds have taken gems and other... body parts off these shutdown earthen. Abominable. Find where the kobolds are holding their plunder, and bring it back to me so I can return it to its rightful place later. This vandalism will not go unchecked!",starts={{npcID=213687,x=0.616,y=0.416,zoneID=14717}},ends={{npcID=213688,x=0.632,y=0.426,zoneID=14717}},coords={x=0.616,y=0.416,source="quest_giver",zoneID=14717},questType="standard"},
[78746] = {id=78746,name="Laws Apply to All",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="Desecrating a memorial site is one of our greatest taboos in earthen society. This site is a window to our past, into our memories, and a place of self-reflection where we can commune with those who are no longer here. Still, so many of these kobolds infest Mourning Rise. For their crimes, the kobolds deserve the harshest punishment. They must be culled even further.",starts={{npcID=213687,x=0.616,y=0.416,zoneID=14717}},ends={{npcID=213688,x=0.632,y=0.426,zoneID=14717}},coords={x=0.616,y=0.416,source="quest_giver",zoneID=14717},questType="standard"},
[78747] = {id=78747,name="The Great Collapse",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="Now that we landed a mighty blow, it is time to make sure that we block their tunnels so they cannot come back. Remember the stuff that Korgran asked about? Explosive sticks --his recipe. I have brought enough to shake a mountain! More than enough for the kobolds. Help me show these kobolds that we will fight for what is ours so they will never come back!",starts={{npcID=213688,x=0.632,y=0.426,zoneID=14717}},ends={{npcID=213688,x=0.632,y=0.426,zoneID=14717}},coords={x=0.632,y=0.426,source="quest_giver",zoneID=14717},questType="standard"},
[78748] = {id=78748,name="Cutting the Wick",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="Knowing kobolds, they will have several workmasters, or leaders, running this raid. Find and eliminate these so-called \"workmasters.\" The rest of them will get disorganized, forget why they are here, and hopefully leave us alone.",starts={{npcID=213688,x=0.632,y=0.426,zoneID=14717}},ends={{npcID=213688,x=0.632,y=0.426,zoneID=14717}},coords={x=0.632,y=0.426,source="quest_giver",zoneID=14717},questType="standard"},
[78749] = {id=78749,name="Who Runs This Fine Establishment?",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="While you were dealing with the tunnels and the workmasters, I saw a peculiar kobold go into a cave to the northwest. The kobolds seemed to respect him more than the others, calling him Grand-Heister Bokk and offering him the food you call \"cheese.\" This makes me think he is the real mastermind. If that kobold is in fact the real Ward of this operation, then we should take the opportunity to strike him down. I will meet you at this cave.",starts={{npcID=213688,x=0.632,y=0.426,zoneID=14717}},ends={{npcID=213187,x=0.574,y=0.43,zoneID=14717}},coords={x=0.632,y=0.426,source="quest_giver",zoneID=14717},questType="standard"},
[78754] = {id=78754,name="Lost Delivery",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="Gundargaz Courier Express EXPEDITED To: Harvester Farnee Durgaz Cabin OPEN WITH CARE: Contains volatile elemental minerals.",starts={{npcID=423987,x=0.555,y=0.565,zoneID=14717}},ends={{npcID=214640,x=0.67,y=0.438,zoneID=14717}},coords={x=0.555,y=0.565,source="quest_giver",zoneID=14717},questType="standard"},
[78755] = {id=78755,name="Playing in the Mud",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="Remember when we used that clay and the fire honey to patch up Shalehoof? Let's do that again but bigger! Problem is we've run out of clay. But fortunately, with all the recent seismic activity, a whole avalanche of elementals has been roused out of torpor and are clashing on the eastern beach! Bring me wet, elementally charged silt to use as our restorative substrate!",starts={{npcID=214921,x=0.67,y=0.474,zoneID=14717}},ends={{npcID=214921,x=0.67,y=0.474,zoneID=14717}},coords={x=0.67,y=0.474,source="quest_giver",zoneID=14717},questType="standard"},
[78756] = {id=78756,name="Lots and Lots of Fire Honey",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="If Harmot wants to patch this sleeping boulder up and get him out of my pond, I'm all for it. Unfortunately, we used the last of my store of fire honey on Shalehoof's wound. I haven't had time to harvest any from the Cinderwold with all these elementals running amok. Head on down to the wold's edge and bring us some honey. You're going to need a lot.",starts={{npcID=214922,x=0.67,y=0.472,zoneID=14717}},ends={{npcID=214922,x=0.67,y=0.472,zoneID=14717}},coords={x=0.67,y=0.472,source="quest_giver",zoneID=14717},questType="standard"},
[78757] = {id=78757,name="Honey and Clay the Pain Away",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="Ramoliths! Magnificent, aren't they? One of the finest elemental beasts on the isle. The bad news is they're not immune to injury. Poor Shalehoof here was attacked by awakened elementals in Farnee's pond. The good news is that we have all we need to tend to him. We just have to mix that clay you found with some fire honey and slap it up on ol' Shalehoof's hock! Ready?",starts={{npcID=213691,x=0.67,y=0.438,zoneID=14717}},ends={{npcID=213691,x=0.67,y=0.438,zoneID=14717}},coords={x=0.67,y=0.438,source="quest_giver",zoneID=14717},questType="standard"},
[78758] = {id=78758,name="Pulse Within the Earth",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="Before we go and wake up a slumbering mountain giant, it's probably best we get an idea for how deeply asleep he is. Though, if the nerubians burrowing up didn't wake him up, I'm not sure what will. Take these earth shards and plant them on the waterfalls and hills around the lake. Once we've got them set up, I'll be able to get a reading on the giant's health.",starts={{npcID=213691,x=0.67,y=0.438,zoneID=14717}},ends={{npcID=214921,x=0.67,y=0.474,zoneID=14717}},coords={x=0.67,y=0.438,source="quest_giver",zoneID=14717},questType="standard"},
[78759] = {id=78759,name="To Wake a Giant",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="By the Coreway, this stuff packs a punch! Combining healing silt with the molten fusion properties of fire honey has given us a salve that could wake a whole mountain! Which is exactly what you'll do. Take the mixture over to our wounded friend in Farnee's pond, and slap it on his hide! It should be enough to wake him up and alleviate any soreness. Hopefully, anyways.",starts={{npcID=214921,x=0.67,y=0.474,zoneID=14717}},ends={{npcID=214921,x=0.67,y=0.474,zoneID=14717}},coords={x=0.67,y=0.474,source="quest_giver",zoneID=14717},questType="standard"},
[78760] = {id=78760,name="Dark Iron from Above",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="We've done our best to contain the High Speaker's followers. We've hampered their efforts at destroying or looting anything they can take with them into Hall of Awakening. Now, we just need to deal with the leader of their forces before they can coordinate a more unified resistance. Are you ready to do this, ?",starts={{npcID=213763,x=0.47,y=0.206,zoneID=14795}},ends={{npcID=213796,x=0.466,y=0.102,zoneID=14795}},coords={x=0.47,y=0.206,source="quest_giver",zoneID=14795},questType="standard"},
[78761] = {id=78761,name="Into the Machine",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="No time to catch our breath! The High Speaker is fleeing to the earthen's most sacred machine. We need to follow him. Remember, we're doing this for the earthen! For justice! For all the brothers and sisters and comrades who've fallen to the High Speaker's hubris!",starts={{npcID=213796,x=0.466,y=0.102,zoneID=14795}},ends={{npcID=212742,x=0.47,y=0.34,zoneID=14795}},coords={x=0.466,y=0.102,source="quest_giver",zoneID=14795},questType="standard"},
[78763] = {id=78763,name="Dragonflight (70) E",level=70,requiredLevel=70,faction="none",expansion=10,questType="standard"},
[78764] = {id=78764,name="Dragonflight (70) E",level=70,requiredLevel=70,faction="none",expansion=10,questType="standard"},
[78765] = {id=78765,name="Dragonflight (70) E",level=70,requiredLevel=70,faction="none",expansion=10,questType="standard"},
[78766] = {id=78766,name="Dragonflight (70) E",level=70,requiredLevel=70,faction="none",expansion=10,questType="standard"},
[78767] = {id=78767,name="Dragonflight (70) E",level=70,requiredLevel=70,faction="none",expansion=10,questType="standard"},
[78827] = {id=78827,name="Go Take Candle!",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="Ksk, ksk! You there! Yes, you! We, er, I have job for you! You look sharp. Look quick. Fast hands, just like us--me! Quick hands just like me. Bring us, me, bring me candles ! Yes! No ask question, just go get candles . We are, er, I am professional, yes. Professionals do not ask questions. Only get candles .",starts={{npcID=413694,x=0.481,y=0.32,mapID=2214}},ends={{npcID=413694,x=0.481,y=0.32,mapID=2214}},coords={x=0.481,y=0.32,source="quest_giver",mapID=2214},questType="standard"},
[78837] = {id=78837,name="Pomp and Dire Circumstance",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="I'm seeing legitimate concerns. We have to do something about the nerubians... even if the High Speaker won't. If he won't do something, I will. The High Speaker sent me to the surface because I wasn't \"reasonable.\" I think we should have a chance to... reason... with him. We'll need to go to Gundargaz.",starts={{npcID=212592,x=0.42,y=0.284,zoneID=14795}},ends={{npcID=212741,x=0.472,y=0.342,zoneID=14795}},coords={x=0.42,y=0.284,source="quest_giver",zoneID=14795},questType="standard"},
[78838] = {id=78838,name="Cogs in the Machine",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="Gundargaz is my home. Or at least, it was before the High Speaker saw fit to reassign me above ground. I've missed my home, but it's... changed. As the number of Machine Speakers decreases, we're in a race against time. Lately, we've been especially weary of our assigned tasks, but as always, we must bear our burdens. Let me show you around the area. There are some earthen I would like you to meet.",starts={{npcID=212741,x=0.472,y=0.342,zoneID=14795}},ends={{npcID=212741,x=0.472,y=0.342,zoneID=14795}},coords={x=0.472,y=0.342,source="quest_giver",zoneID=14795},questType="standard"},
[78839] = {id=78839,name="Kobold Shoulder",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="The first step to stemming our losses and retaking the mines is straightforward, if unpleasant. Without minions, this Candle King will be less of a threat to Gundargaz. See if you can reduce the swarm, , before hostilities escalate further.",starts={{npcID=212519,x=0.576,y=0.292,zoneID=14795}},ends={{npcID=212519,x=0.576,y=0.292,zoneID=14795}},coords={x=0.576,y=0.292,source="quest_giver",zoneID=14795},questType="standard"},
[78860] = {id=78860,name="More Candles!",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="I, er, we...no, no, I! I have new deal for you, oh shadowy one. More candles ! In return, you get... er... You get more candles ! Then you give to us! To me! candles ! candles ! candles !",starts={{npcID=413694,x=0.481,y=0.32,mapID=2214}},ends={{npcID=413694,x=0.481,y=0.32,mapID=2214}},coords={x=0.481,y=0.32,source="quest_giver",mapID=2214},questType="standard"},
[78861] = {id=78861,name="Aiding the Accord",level=10,requiredLevel=10,faction="none",expansion=10,questType="standard"},
[78874] = {id=78874,name="Conjured Help",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="If you're looking for food--softy food--I'm afraid we're clean out. Nothing but good ol' rocks and gems here at the moment. It's starting to become a problem, actually. Say... you wouldn't be able to do anything about that, would you? Rustle us up some victuals for the fleshy folk?",starts={{npcID=213840,x=0.48,y=0.322,zoneID=14795}},ends={{npcID=213840,x=0.48,y=0.322,zoneID=14795}},coords={x=0.48,y=0.322,source="quest_giver",zoneID=14795},questType="standard"},
[78877] = {id=78877,name="Bless These Homes",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="Divine presence acknowledged. Every day for as long as my memory serves me, I have walked the routes and lit the incense around our homes. It has ground my joints to dust, but is it an important task. A sacred task. These are dark times we live in--perhaps you could add your own beatitudes to our little rituals?",starts={{npcID=213875,x=0.47,y=0.324,zoneID=14795}},ends={{npcID=213875,x=0.47,y=0.324,zoneID=14795}},coords={x=0.47,y=0.324,source="quest_giver",zoneID=14795},questType="standard"},
[78879] = {id=78879,name="Evoking the Forge",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="Harumph! This blasted forge is on its last legs. We'd repair it, but Stonemason Itsak picked up a shift at Ironhaul Station when the Coreway collapsed, and well... There's no one to fix it anymore. If you can figure out a way of getting it running hot again, Gundargaz would be in your debt!",starts={{npcID=213841,x=0.474,y=0.284,zoneID=14795}},ends={{npcID=213841,x=0.474,y=0.284,zoneID=14795}},coords={x=0.474,y=0.284,source="quest_giver",zoneID=14795},questType="standard"},
[78893] = {id=78893,name="A Scrap of Bronze",level=10,requiredLevel=10,faction="none",expansion=10,description="The vendors of Pandaria do not want the equipment you will find in this timeline. You can convert unwanted equipment into Bronze using the magic of the infinite dragonflight. Use the Unraveling Sands ability and scrap the Unraveling Tunic .",questType="standard"},
[78895] = {id=78895,name="A Shadow Over Gundargaz",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="You look dangerous. That's good. We need dangerous. Something is stalking Gundargaz. Something mean. Something... recent. Just before the Coreway collapsed I started getting reports of workers going missing mid-shift. Only thing we've been able to find have been the odd chunk of rock. Fingers, mostly. If you could sniff out what's stalking my town, I'd be in your debt.",starts={{npcID=213869,x=0.48,y=0.348,zoneID=14795}},ends={{npcID=213869,x=0.48,y=0.348,zoneID=14795}},coords={x=0.48,y=0.348,source="quest_giver",zoneID=14795},questType="standard"},
[78897] = {id=78897,name="Boom or Blight",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="This place is infested with cave borers. They pose a threat to the great roots that stretch through this place. Yes, the tree provides sustenance for many living things, but this is not some small band of bugs nibbling on a leaf. This is a blight. Their numbers must be culled for the good of the whole. By my oath I am unable to raise a hand to interfere. However... you have sworn no such oath. Will you do what must be done?",starts={{npcID=211652,x=0.422,y=0.426,zoneID=14752}},ends={{npcID=211652,x=0.422,y=0.426,zoneID=14752}},coords={x=0.422,y=0.426,source="quest_giver",zoneID=14752},questType="standard"},
[78898] = {id=78898,name="Intention vs Instinct",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="Cave borers are not social creatures as a rule. Seeing this many gather in one place speaks to intention. A wormcaller of the nerubians must be present. Find them and recover the tool they use to call these worms here. With it we can lead them away in time.",starts={{npcID=211652,x=0.422,y=0.426,zoneID=14752}},ends={{npcID=211652,x=0.422,y=0.426,zoneID=14752}},coords={x=0.422,y=0.426,source="quest_giver",zoneID=14752},questType="standard"},
[78900] = {id=78900,name="On Cold, Dark Wings",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="You came down the Coreway, right? From up top? They have it easy, those city earthen. Down here, death comes for you from all around. From below. From above. You look like you've killed a fair few beasts in your time. Care to add another to the list?",starts={{npcID=213869,x=0.48,y=0.348,zoneID=14795}},ends={{npcID=213869,x=0.48,y=0.348,zoneID=14795}},coords={x=0.48,y=0.348,source="quest_giver",zoneID=14795},questType="standard"},
[78901] = {id=78901,name="Heeeelllp!!!",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="Hey! You! Get me down! Away from these worms! Please! I'll pay you! I'll even owe you one! Heck, I'll gladly sell out any cartel member you need dirt on! Just get me down! Also, don't walk too much. They can hear your footsteps. Move from rock to rock if you don't want a swarm coming after you.",ends={{npcID=214168,x=0.408,y=0.398,zoneID=14752}},questType="standard"},
[78902] = {id=78902,name="Delegated Dig",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="Okay, I know when I'm beat. So I want to hire you as my Champion of Coin... or coinchamp. This is all a part of my brilliant enterprising venture. See, these worms here are great at rooting out rich minerals like a niffen sniffing out high-quality mushrooms. I'm willing to bet all of my money--and your life--that they found a vein of sivstone. Great stuff, though I doubt a would know how to use it. Tell you what, you bring me a shipment's worth and I'll go halfsies on the profits with ya!",starts={{npcID=214168,x=0.408,y=0.398,zoneID=14752}},ends={{npcID=214168,x=0.408,y=0.398,zoneID=14752}},coords={x=0.408,y=0.398,source="quest_giver",zoneID=14752},questType="standard"},
[78915] = {id=78915,name="Squashing the Threat",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,description="I need your help! The massive Shadow-Soured squash have begun to grow all over the place. They're stinky and crawling with nasty mites. Mom and Dad brought in some airships to help us yank them out, but it's risky business with all those bugs. Can you attach ropes to these Shadow-Soured Squash, and the airships can then haul them away without making a mess?",starts={{npcID=214428,x=0.636,y=0.338,zoneID=14838}},ends={{npcID=214428,x=0.636,y=0.338,zoneID=14838}},coords={x=0.636,y=0.338,source="quest_giver",zoneID=14838},questType="standard"},
[78918] = {id=78918,name="Brax's Brass Knuckles",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="I have a proposition for you. We get some rowdy patrons here from time to time. Nothing sinister, but our folk work hard and things can get out of hand faster than a dropped hammer. Usually I'd give 'em a considerate knock upside the head to remind them what's what, but I lost my brass knuckles while helping Watcher Toki clear monsters on the town's skirts. Mind fetching my knuckles and administering some love taps?",starts={{npcID=213840,x=0.48,y=0.322,zoneID=14795}},ends={{npcID=213840,x=0.48,y=0.322,zoneID=14795}},coords={x=0.48,y=0.322,source="quest_giver",zoneID=14795},questType="standard"},
[78929] = {id=78929,name="Tricks of the Dark",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="Kobyss lurk in the shallows of murky water and snatch any who come near, faster than a viper! And that's just when they hunt alone. In numbers, they are a swarm to be reckoned with. They've been a plague on our outskirt villages since the day we arrived. They eat victims alive, given the chance. We must rescue the villagers that have already been dragged to the water!",starts={{npcID=214378,x=0.538,y=0.314,zoneID=14838}},ends={{npcID=214377,x=0.538,y=0.308,zoneID=14838}},coords={x=0.538,y=0.314,source="quest_giver",zoneID=14838},questType="standard"},
[78932] = {id=78932,name="Fickle Fiendish Fish",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="Judging by the glint in your eye, you wish to join Faerin in this madness? To push into the kobyss waters? In the darkness? You are a fool with a death wish. Take as many of those damnable fish out as you can, before they drag you into the depths for their dinner.",starts={{npcID=214376,x=0.538,y=0.314,zoneID=14838}},ends={{npcID=214377,x=0.538,y=0.308,zoneID=14838}},coords={x=0.538,y=0.314,source="quest_giver",zoneID=14838},questType="standard"},
[78933] = {id=78933,name="The Sweet Eclipse",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,description="I've set out to create a dessert that transcends the ordinary, one that even the most devout followers of the light would savor! To balance the flavors of the desert, between light and shadow, I require ingredients from several areas within the darkness. Please assist me in harvesting the following ingredients: Frog-Kissed Caviar , Darkroot Persimmon and Ethereal Sugar .",starts={{npcID=206533,x=0.644,y=0.31,zoneID=14838}},ends={{npcID=206533,x=0.644,y=0.31,zoneID=14838}},coords={x=0.644,y=0.31,source="quest_giver",zoneID=14838},questType="standard"},
[78934] = {id=78934,name="Blades of the Arathi",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="I trust in your strength. I must ask you to go ahead to reinforce Sina's Yearning. Anduin and I can see my people to safety in Lorel's Crossing. With the darkness and the kobyss, the hearts of my people in Sina's Yearning will be faltering to fear. We can't let them wallow. Light a torch with the Sacred Flame in the center of town and use it to inspire my people's valor. Remind them of their strength. We will catch up with you. May the Flame guide you, my friend.",starts={{npcID=214378,x=0.538,y=0.314,zoneID=14838}},ends={{npcID=221100,x=0.552,y=0.326,zoneID=14838}},coords={x=0.538,y=0.314,source="quest_giver",zoneID=14838},questType="standard"},
[78936] = {id=78936,name="Something's Fishy",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="So you outsiders and Faerin managed to both survive and save the villagers at the beach? We're in trouble, here. The kobyss brought some of their strongest forces to the doorsteps of villagers. We have our hands full just holding the line. If you can take out those monsters, we might be able to turn the tide.",starts={{npcID=214376,x=0.538,y=0.314,zoneID=14838}},ends={{npcID=214376,x=0.538,y=0.314,zoneID=14838}},coords={x=0.538,y=0.314,source="quest_giver",zoneID=14838},questType="standard"},
[78937] = {id=78937,name="Shadow upon Shadow",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="Faerin 's wide eyes dart around in surprise.> What just happened? Did you see that shadow? And the oil well... it's gone dark? I've never seen anything like this before. Could it be the nearby dawntower? Hurry!",starts={{npcID=221100,x=0.552,y=0.326,zoneID=14838}},ends={{npcID=214405,x=0.558,y=0.412,zoneID=14838}},coords={x=0.552,y=0.326,source="quest_giver",zoneID=14838},questType="standard"},
[78939] = {id=78939,name="The Darkened Flame",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="This... Order of Night, as they call themselves, did some foul ritual to turn the tower's flame to darkness. I know not what. We should investigate.",starts={{npcID=214405,x=0.558,y=0.412,zoneID=14838}},ends={{npcID=214404,x=0.562,y=0.42,zoneID=14838}},coords={x=0.558,y=0.412,source="quest_giver",zoneID=14838},questType="standard"},
[78942] = {id=78942,name="The Might of Khaz Algar",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,description="The Harbinger thinks she can catch us off guard, but she's a fool if she expects to win this fight. The Algari Offensive stands at your back, . Spare no enemy.",starts={{npcID=214271,x=0.716,y=0.592,zoneID=14838}},ends={{npcID=214274,x=0.646,y=0.618,zoneID=14838}},coords={x=0.716,y=0.592,source="quest_giver",zoneID=14838},questType="standard"},
[78943] = {id=78943,name="Steel and Flames",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,description="Our forces may be able to hold their own, but seeing you in the fray may help their spirits. Take this warhorn. Let it ring out and fill our foes with terror. Once you're done rallying our troops, make your way to your commanders.",starts={{npcID=214271,x=0.716,y=0.592,zoneID=14838}},ends={{npcID=214275,x=0.686,y=0.642,zoneID=14838}},coords={x=0.716,y=0.592,source="quest_giver",zoneID=14838},questType="standard"},
[78948] = {id=78948,name="A Light in the Dark",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,description="Something is very wrong. As the battle continues, each side has become more aggressive. Alleria seems to know something - she ran off at one point during the battle. We've been giving chase, but I cannot leave these soldiers to die. She's just ahead, we can reconvene with her together.",starts={{npcID=214273,x=0.646,y=0.618,zoneID=14838}},ends={{npcID=220688,x=0.36,y=0.354,zoneID=14838}},coords={x=0.646,y=0.618,source="quest_giver",zoneID=14838},questType="standard"},
[78950] = {id=78950,name="Cutting Off the Legs",level=80,requiredLevel=80,faction="alliance",expansion=10,zoneID=14838,description="While we've yet to locate Xal'atath, we've received reports from deeper in the field of certain nerubians giving orders. It won't buy us too much but every action is critical. Take them out. Hopefully that will allow us some breathing room. Speak with Anduin after you are done. He and the Arathi girl went after Alleria.",starts={{npcID=214276,x=0.686,y=0.642,zoneID=14838}},ends={{npcID=214273,x=0.646,y=0.618,zoneID=14838}},coords={x=0.686,y=0.642,source="quest_giver",zoneID=14838},questType="standard"},
[78951] = {id=78951,name="Ever Deeper Shadow",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="When I reached for the Flame, I felt the overwhelming hopelessness and despair that had been poured into it. It pains me, but... my light alone is not enough to banish these shadows. And so, we take a more direct path. If the remaining cultists have withdrawn to Gloomcrag Bower, their combined power must be what's keeping the Flame dark. We must stop them before this darkness spreads.",starts={{npcID=214404,x=0.562,y=0.42,zoneID=14838}},ends={{npcID=214413,x=0.558,y=0.404,zoneID=14838}},coords={x=0.562,y=0.42,source="quest_giver",zoneID=14838},questType="standard"},
[78952] = {id=78952,name="The Final Resistance",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="Good work. But before we can leave, there's something else. Down this way are some powerful priests. I think they are summoning something-- something big. No doubt to strike at us above and drive us from the tower itself. It will be dangerous, but we must stop them. Are you with me?",starts={{npcID=214413,x=0.558,y=0.404,zoneID=14838}},ends={{npcID=221733,x=0.55,y=0.402,zoneID=14838}},coords={x=0.558,y=0.404,source="quest_giver",zoneID=14838},questType="standard"},
[78954] = {id=78954,name="Restore the Flame",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="Do you feel it? Hope, returning? Thank you for your help, . The dawntower's flame remains dark. But this time, I think we'll be able to restore it. Let's meet at the tower.",starts={{npcID=221733,x=0.55,y=0.402,zoneID=14838}},ends={{npcID=214404,x=0.562,y=0.42,zoneID=14838}},coords={x=0.55,y=0.402,source="quest_giver",zoneID=14838},questType="standard"},
[78972] = {id=78972,name="Harvest Havoc",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,description="Our parents went off to fight the monsters that invaded our farm. While they are gone, we try to keep the farm running. We have a harvestbot to help with chores, but I keep crashing it into the river. We could finish our chores if you could help us drive the harvestbot!",starts={{npcID=214428,x=0.636,y=0.338,zoneID=14838}},ends={{npcID=214428,x=0.636,y=0.338,zoneID=14838}},coords={x=0.636,y=0.338,source="quest_giver",zoneID=14838},questType="standard"},
[78996] = {id=78996,name="Weapons and Warriors",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="Gorloc raiders have been slaughtering these farmers and stealing their pearls. They seek our protection, but we may not be enough. I know of others nearby who can help. Seek them out and request their aid. If they are hesitant, offer them the promise of pearls as payment. We will also need to arm these farmers so they can defend themselves. Search for spare weapons and equipment that they might be able to use. I will go with the farmers and train them as best I can.",starts={{npcID=214444,x=0.426,y=0.716,zoneID=14717}},ends={{npcID=215201,x=0.498,y=0.766,zoneID=14717}},coords={x=0.426,y=0.716,source="quest_giver",zoneID=14717},questType="standard"},
[78997] = {id=78997,name="Pilfered Pearls",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="The pearls that these farmers harvest are their only source of livelihood. Some of these earthen even look at pearl farming as their primary reason for existing. The gorlocs continue to pilfer pearls at every opportunity. As you eliminate the gorlocs, search them for stolen pearls. Let us recover as many as we can.",starts={{npcID=215201,x=0.498,y=0.766,zoneID=14717}},ends={{npcID=215201,x=0.498,y=0.766,zoneID=14717},{npcID=215327,x=0.496,y=0.766,zoneID=14717}},coords={x=0.498,y=0.766,source="quest_giver",zoneID=14717},questType="standard"},
[78998] = {id=78998,name="Frontline Farmers",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="Most of the farmers are already out in the field, defending their positions. I have trained them as best I could given the circumstances, but they are still wielding farming tools. I need you to distribute the weapons you gathered to those on the frontlines. While it may not markedly improve their combat ability, at least it will boost their confidence that they are not alone in this fight.",starts={{npcID=215201,x=0.498,y=0.766,zoneID=14717}},ends={{npcID=215327,x=0.496,y=0.766,zoneID=14717}},coords={x=0.498,y=0.766,source="quest_giver",zoneID=14717},questType="standard"},
[78999] = {id=78999,name="Heart of a Hero",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="It seems the gorlocs have been bolstering their forces with summoned elementals. That explains how they were able to overrun the farmers so easily. It will take all of our strength to hold off the colossi already in the field. I need you to stop any new elementals from being created. Elementals of this size and power can only be created by the most powerful of gorloc shaman. Seek them out behind enemy lines and eliminate them. This should end the gorloc threat to the farmers once and for all.",starts={{npcID=215327,x=0.496,y=0.766,zoneID=14717}},ends={{npcID=215420,x=0.504,y=0.786,zoneID=14717}},coords={x=0.496,y=0.766,source="quest_giver",zoneID=14717},questType="standard"},
[79006] = {id=79006,name="Faction Switch",level=10,requiredLevel=10,faction="none",expansion=10,zoneID=14663,description="Default",questType="standard"},
[79009] = {id=79009,name="The Harbinger",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=7502,mapID=627,description="We are in need of your aid once more, champion. A mysterious figure moves within the shadows. The Harbinger... Let us speak in the Chamber of the Guardian. I've asked Alleria to meet us there as well.",questType="standard"},
[79022] = {id=79022,name="A Mysterious Signal",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,description="High Speaker Brinthe has sent an urgent missive for you, . She is eager to assist in the coming war effort, and is investigating a mysterious signal in the Deepforge Golemworks, a defunct golem manufacturing facility in the Ringing Deeps . Can you meet her there and provide your expertise?",starts={{npcID=223944,x=0.316,y=0.596,zoneID=14771}},ends={{npcID=214663,x=0.562,y=0.748,zoneID=14795}},coords={x=0.316,y=0.596,source="quest_giver",zoneID=14771},questType="standard"},
[79023] = {id=79023,name="Small Friend, Big Plans",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,description="I tracked down a distress signal that led me to this little maintenance machine. A curious find, but the real treasure is the defunct war golem facility to the southeast. If we can start producing war golems again we'll be able to contribute to the war effort. Unfortunately, it's been overrun by a goblin salvage group. And we'll need to investigate and assess if the facility is functional. Fortunately, I have a plan, and it involves our little friend here. Why don't you introduce yourself?",starts={{npcID=214663,x=0.562,y=0.748,zoneID=14795}},ends={{npcID=214663,x=0.562,y=0.748,zoneID=14795}},coords={x=0.562,y=0.748,source="quest_giver",zoneID=14795},questType="standard"},
[79024] = {id=79024,name="Factory Recon",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,description="ZZ-01-47 should be able to make its way in there without drawing too much attention. But be careful! These goblins are hungry for raw materials. If they spot our bot, they won't show it mercy.",starts={{npcID=214663,x=0.562,y=0.748,zoneID=14795}},ends={{npcID=214663,x=0.562,y=0.748,zoneID=14795}},coords={x=0.562,y=0.748,source="quest_giver",zoneID=14795},questType="standard"},
[79025] = {id=79025,name="A Plan Comes Together",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,description="We have our work cut out for us, . But I think, with Dagran's help, we can break this down and tackle it piece by piece. Why don't you take us through what we've learned so far.",starts={{npcID=217245,x=0.47,y=0.342,zoneID=14795}},ends={{npcID=217245,x=0.47,y=0.342,zoneID=14795}},coords={x=0.47,y=0.342,source="quest_giver",zoneID=14795},questType="standard"},
[79026] = {id=79026,name="Putting the Works in Waterworks",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15002,description="Overly enthusiastic kobolds, angry elementals, and a broken-down power plant. This place is in shambles! Do you spot those large wheels on each side? They should be moving, but they're not. We'll need to get those moving again if we want this place to come back to life.",starts={{npcID=217331,x=0.472,y=0.422,zoneID=14795}},ends={{npcID=217331,x=0.472,y=0.422,zoneID=14795}},coords={x=0.472,y=0.422,source="quest_giver",zoneID=14795},questType="standard"},
[79027] = {id=79027,name="Elemental Trepidation",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,description="ZZ-01-47 twitches back and forth, sensors scanning unceasingly. They seem afraid of this area, if they're even capable of feeling fear. Maybe clearing out some of the elementals will set them at ease.>",starts={{npcID=216137,x=0.472,y=0.422,zoneID=14795}},ends={{npcID=217331,x=0.472,y=0.422,zoneID=14795}},coords={x=0.472,y=0.422,source="quest_giver",zoneID=14795},questType="standard"},
[79028] = {id=79028,name="We Require More Minerals",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,description="Zee-Zee is ready to help you get the Shadowvein site up and running again.",starts={{npcID=216140,x=0.556,y=0.41,zoneID=14795}},ends={{npcID=230643,x=0.048,y=0.796,zoneID=14795}},coords={x=0.556,y=0.41,source="quest_giver",zoneID=14795},questType="standard"},
[79029] = {id=79029,name="It's Sabotage",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,description="We're back, and we're ready. You and ZZ-01-47 head in and cause some mayhem. Blow stuff up and make a mess that will draw them out of the manufacturing bay. I'll use the commotion to sneak inside. Join me when you're able, and we should have a chance at reactivating the facility and driving them out. We don't need to defeat them all. Defeating the Darkfuse leader supervising this operation should break their resolve. The Darkfuse lackeys will clear out when the coin stops flowing.",starts={{npcID=214663,x=0.562,y=0.748,zoneID=14795}},ends={{npcID=220928,x=0.56,y=0.776,zoneID=14795}},coords={x=0.562,y=0.748,source="quest_giver",zoneID=14795},questType="standard"},
[79030] = {id=79030,name="The Voice of the Speakers",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,description="Please take word of our victory to Alleria in Dornogal. I'm sure our allies will be pleased to hear what we can provide for the war effort.",starts={{npcID=220928,x=0.56,y=0.776,zoneID=14795}},ends={{npcID=223944,x=0.316,y=0.596,zoneID=14771}},coords={x=0.56,y=0.776,source="quest_giver",zoneID=14795},questType="standard"},
[79085] = {id=79085,name="A Pile of Fish",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=14838,mapID=2215,questType="standard"},
[79087] = {id=79087,name="A Pile of Clams",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=14838,mapID=2215,questType="standard"},
[79105] = {id=79105,name="Breach",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=15177,mapID=2305,description="As much as I'd love to hunt Xal'atath down, our first priority must be securing civilians. Rescue whoever you can and tell them to head to the landing nearby. I'll find mages to teleport everyone to safety.",starts={{npcID=214908,x=0.502,y=0.504,mapID=2305}},ends={{npcID=214908,x=0.502,y=0.504,mapID=2305}},coords={x=0.502,y=0.504,source="quest_giver",mapID=2305},questType="standard"},
[79106] = {id=79106,name="Rupture",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=15177,mapID=2305,description="Follow me. We'll work together to find any others in need of rescuing.",questType="standard"},
[79107] = {id=79107,name="After the Storm",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14717,description="Turalyon and Geya'rah are training our new earthen allies as ground forces. But we will need more than that. We will need the Stormriders. Many were lost in the infiltration of the Stormperch and more to the nerubians. Their leader, Stormward Baelgrim, died valiantly. The surviving Stormriders are being cared for at a triage station nearby. We need to do whatever is necessary to get them and their rooks back in the air. They will be the earthen's most potent weapon in the battles to come.",starts={{npcID=223944,x=0.316,y=0.596,zoneID=14771}},ends={{npcID=215039,x=0.374,y=0.82,zoneID=14771},{npcID=215039,x=0.256,y=0.572,zoneID=14717}},coords={x=0.316,y=0.596,source="quest_giver",zoneID=14771},questType="standard"},
[79108] = {id=79108,name="Seeds of Evil",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,description=", some of the shadowleaf plants are more... wrong than the rest. I don't know how to describe it better. My idiot brother, Tomothy, was supposed to help me get rid of these, but I haven't seen him and I can't wait. Clearly we don't want these to reproduce so I want you to cull as many as you can find, and then take their seeds. We'll burn those in holy fire to make sure we've cut off the infestation.",starts={{npcID=206528,x=0.612,y=0.304,zoneID=14838}},ends={{npcID=206528,x=0.612,y=0.304,zoneID=14838}},coords={x=0.612,y=0.304,source="quest_giver",zoneID=14838},questType="standard"},
[79109] = {id=79109,name="Follow Miral",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,description="Tomothy's lynx, Miral, has been bugging me. I don't know what she wants but it is unusual to see her without my brother. She's a great farm cat, but she's still a cat, so maybe she's just bored with Tomothy today? I don't know. Maybe Tomothy got into some sort of trouble. Can you find out what is bothering her for me?",starts={{npcID=206528,x=0.612,y=0.304,zoneID=14838}},ends={{npcID=215041,x=0.602,y=0.212,zoneID=14838}},coords={x=0.612,y=0.304,source="quest_giver",zoneID=14838},questType="standard"},
[79110] = {id=79110,name="Save Tomothy",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,starts={{npcID=215041,x=0.602,y=0.212,zoneID=14838}},ends={{npcID=206528,x=0.612,y=0.304,zoneID=14838}},coords={x=0.602,y=0.212,source="quest_giver",zoneID=14838},questType="standard"},
[79111] = {id=79111,name="Missing Lynx",level=80,requiredLevel=80,faction="none",expansion=10,questType="standard"},
[79114] = {id=79114,name="Beautification Project",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="A fine enough job, for one of your... ilk. If you wish to keep breathing, I suggest you continue to assist us. It may even prove lucrative for you, if you comply. Rak-Ush's former master allowed the stagshells to run feral, and abandoned the hollows to decay. Over time, invasive plants have infested the old stagshell hollows. Find a way to clear them. I don't care how.",starts={{npcID=214359,x=0.76,y=0.824,zoneID=14752}},ends={{npcID=214359,x=0.76,y=0.824,zoneID=14752}},coords={x=0.76,y=0.824,source="quest_giver",zoneID=14752},questType="standard"},
[79115] = {id=79115,name="Expert Consultant",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,mapID=2255,description="You alone are no longer sufficient. We require additional assistance, and the jawcrawlers and threadlings also need oversight. The niffen settlement, Mmarl, is not far. However, past forced conscription attempts have failed. Nerubians are now forbidden within the settlement. We need someone to communicate in our stead. Go and barter with the rats. Come back with able bodies.",starts={{npcID=214356,x=0.75,y=0.808,mapID=2255}},ends={{npcID=215037,x=0.772,y=0.644,mapID=2255}},coords={x=0.75,y=0.808,source="quest_giver",mapID=2255},questType="standard"},
[79117] = {id=79117,name="Bright Young Niffen",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="You need swarmhands, huh? Last time the nerubians wanted our help, they tried to force us. They're terrible negotiators! All we wanted was a little quid pro quo. We've got several arachnologists, but most of them are busy keeping the flyers at bay. I'm sure they won't refuse an opportunity to study some swarmbeasts up close and personal! Maybe if you lighten their workload, they'll take you up on your offer.",starts={{npcID=215037,x=0.772,y=0.644,zoneID=14752}},ends={{npcID=215037,x=0.772,y=0.644,zoneID=14752}},coords={x=0.772,y=0.644,source="quest_giver",zoneID=14752},questType="standard"},
[79118] = {id=79118,name="Rak-Ush Under New Management",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="Well, you got your swarmhands. What are you still doing here? Go on then, you don't need my permission! Make sure the nerubians treat them fairly, now.",starts={{npcID=215037,x=0.772,y=0.644,zoneID=14752}},ends={{npcID=214356,x=0.75,y=0.808,zoneID=14752}},coords={x=0.772,y=0.644,source="quest_giver",zoneID=14752},questType="standard"},
[79119] = {id=79119,name="It's Rough to Be a Bug!",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="Anub'azal gave his orders! We are the new masters of Rak-Ush! Yet Vix'aron decided to throw a tantrum and destroy our barn instead. Since this imbecile refuses to follow orders, perhaps you will, overcrawler. Maybe then we will decide not to kill you for eavesdropping. And recompense, I suppose. Go. We are to restore the stagshell hollows and fill them with swarmbeasts.",starts={{npcID=214359,x=0.76,y=0.824,zoneID=14752}},ends={{npcID=214359,x=0.76,y=0.824,zoneID=14752}},coords={x=0.76,y=0.824,source="quest_giver",zoneID=14752},questType="standard"},
[79120] = {id=79120,name="Beetle in a Haystack",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="There are still feral stagshells on the outskirts of Rak-Ush. This scent grenade should be sufficient in stunning the beasts and alerting the niffen to their location. Once they are stunned, one of the rats will take them back to their hollow. Capture them and bring them back. We will be waiting.",starts={{npcID=214356,x=0.75,y=0.808,zoneID=14752}},ends={{npcID=214356,x=0.75,y=0.808,zoneID=14752}},coords={x=0.75,y=0.808,source="quest_giver",zoneID=14752},questType="standard"},
[79121] = {id=79121,name="Bug Test",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="Oh, I'm sorry, did you think this was a one and done assignment? If you did, Vix'aron would gladly \"show you the door\", as it were. The stagshells will require constant maintenance. Food. Water. Those sorts of things. Loathe as I am to admit it, the niffen are much more skilled at caring for swarmbeasts than Vix'aron or I. They can enlighten you on your duties, if this was not explanation enough.",starts={{npcID=214359,x=0.76,y=0.824,zoneID=14752}},ends={{npcID=214359,x=0.76,y=0.824,zoneID=14752}},coords={x=0.76,y=0.824,source="quest_giver",zoneID=14752},questType="standard"},
[79122] = {id=79122,name="Scarab Scouting",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="The stagshells are of the utmost importance to Anub'azal's war campaign. We have a keen sense of smell, but only the stagshells are able to seek out valuable Kaheti truffles. The truffles are a key ingredient in several... explosive elixirs, as it were. If you desire details, Aromash can give you more.",starts={{npcID=214359,x=0.76,y=0.824,zoneID=14752}},ends={{npcID=214359,x=0.76,y=0.824,zoneID=14752}},coords={x=0.76,y=0.824,source="quest_giver",zoneID=14752},questType="standard"},
[79123] = {id=79123,name="Permanent Hire",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="Rak-Ush is beginning to look like a functioning swarmery. The role of delegation has suited me and Vix'aron well. You will continue to aid the niffen. In return, you may keep a portion of the wealth the swarmbeasts produce. Saffrin has more detailed plans around the development of the swarmery. Go speak to him, I have nothing else to say to you.",starts={{npcID=214359,x=0.76,y=0.824,zoneID=14752}},ends={{npcID=217250,x=0.748,y=0.81,zoneID=14752}},coords={x=0.76,y=0.824,source="quest_giver",zoneID=14752},questType="standard"},
[79124] = {id=79124,name="Conduit of the Southern Storm",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,description="I'll tell you what I told Baelgrim when we last spoke. The binding of stormrooks is wrong. These creatures are as smart as any earthen. Some I'd say are smarter. But... Lufsela seems to be different. If her stormrook follows her willingly, then perhaps others will make that choice as well if she summons them. To summon rooks, we need Baelgrim's conduit. It's tucked away here somewhere. Have a look around, and maybe ask these pilgrims if they have seen it.",starts={{npcID=214995,x=0.276,y=0.604,zoneID=14717}},ends={{npcID=215039,x=0.256,y=0.572,zoneID=14717},{npcID=215039,x=0.374,y=0.82,zoneID=14771}},coords={x=0.276,y=0.604,source="quest_giver",zoneID=14717},questType="standard"},
[79125] = {id=79125,name="The Kalimdor Cup Begins",level=30,requiredLevel=30,faction="alliance",expansion=10,zoneID=15969,description="Skyrider! Lord Andestrasz has left the Dragon Isles and is visiting Stormwind. He's looking for capable skyriders like yourself to compete in new races!",starts={{npcID=214031,x=0.618,y=0.752,zoneID=1519},{npcID=220307,x=0.46,y=0.548,zoneID=14771},{npcID=220865,x=0.568,y=0.288,zoneID=14771},{npcID=220870,x=0.554,y=0.61,zoneID=14771},{npcID=220307,x=0.512,y=0.764,zoneID=15969}},ends={{npcID=214111,x=0.6,y=0.66,zoneID=1519}},coords={x=0.618,y=0.752,source="quest_giver",zoneID=1519},questType="standard"},
[79126] = {id=79126,name="The Kalimdor Cup Begins",level=30,requiredLevel=30,faction="horde",expansion=10,zoneID=15969,description="Skyrider! Lord Andestrasz has left the Dragon Isles and is visiting Orgrimmar. He's looking for capable skyriders like yourself to compete in new races!",starts={{npcID=213769,x=0.528,y=0.794,zoneID=1637},{npcID=220307,x=0.46,y=0.548,zoneID=14771},{npcID=220865,x=0.568,y=0.288,zoneID=14771},{npcID=220870,x=0.554,y=0.61,zoneID=14771},{npcID=220307,x=0.512,y=0.764,zoneID=15969}},ends={{npcID=214112,x=0.522,y=0.598,zoneID=1637}},coords={x=0.528,y=0.794,source="quest_giver",zoneID=1637},questType="standard"},
[79129] = {id=79129,name="Rook Rally",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,description="Now that we've got the conduit all charged, I suppose it's time we joined everyone on the peak. Thrall talked me through what to expect, but also said summoning the stormrooks will require me to trust my feelings and instincts. An earthen trusting their feelings and instincts. That's... a challenge. You will help me, right? I'm not a fighter, and it looks dangerous up there. If anything happens to me, make sure Shraubendre makes it out safe. Please.",starts={{npcID=215039,x=0.256,y=0.572,zoneID=14717},{npcID=215039,x=0.374,y=0.82,zoneID=14771}},ends={{npcID=214919,x=0.278,y=0.608,zoneID=14717},{npcID=214919,x=0.38,y=0.708,zoneID=14771}},coords={x=0.256,y=0.572,source="quest_giver",zoneID=14717},questType="standard"},
[79139] = {id=79139,name="Alone in the Dark",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="My people do not think that this Black Blood is a threat to our world. It has sat dormant for ages, after all. Why should that change now? But the world is changing more quickly than my people realize. The nerubians' decision to extract the Blood for their own ends is proof of that. The nerubians hold a watchtower not far from here. The ones who survived the pit could not have gotten too far. We should give chase immediately.",starts={{npcID=215113,x=0.358,y=0.582,zoneID=14752}},ends={{npcID=216213,x=0.442,y=0.568,zoneID=14752}},coords={x=0.358,y=0.582,source="quest_giver",zoneID=14752},questType="standard"},
[79140] = {id=79140,name="Goldbricking",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14717,description="Is this what we are to rely on to help us defeat Xal'atath? The Unbound define themselves by their desertion. And the Oathsworn, for being made of stone, are pretty soft. City life hasn't done them any favors. We've got a lot of work to do. Get down there and give these earthen a taste of what it's like to face a real threat. Try not to knock any \"offline,\" but a maiming here or there would send a strong message to the rest.",starts={{npcID=215187,x=0.332,y=0.634,zoneID=14717}},ends={{npcID=215187,x=0.332,y=0.634,zoneID=14717}},coords={x=0.332,y=0.634,source="quest_giver",zoneID=14717},questType="standard"},
[79145] = {id=79145,name="Metal and Stone",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14717,description="While some of these recruits struggle with discipline, most have a strong work ethic. They only need training and the equipment to make the most of it. Earthen weaponsmiths and armorers have been working around the clock to equip this fledgling army. But we could use some help getting the new armaments into the hands of these trainees.",starts={{npcID=223205,x=0.332,y=0.634,zoneID=14717}},ends={{npcID=223205,x=0.332,y=0.634,zoneID=14717}},coords={x=0.332,y=0.634,source="quest_giver",zoneID=14717},questType="standard"},
[79146] = {id=79146,name="Ground Pounders",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,description="The rooks and their chosen riders will need time to bond. Perhaps you should use this time to check in on our other trainees. The Stormriders are the traditional army of the earthen, but many Unbound and Oathsworn have expressed willingness to fight at our side due to help in restoring their machines. Adelgonn , Geya'rah, and Turalyon are busy training them. Go and see if they need any assistance.",starts={{npcID=214919,x=0.278,y=0.608,zoneID=14717},{npcID=214919,x=0.38,y=0.708,zoneID=14771}},ends={{npcID=215277,x=0.332,y=0.634,zoneID=14717}},coords={x=0.278,y=0.608,source="quest_giver",zoneID=14717},questType="standard"},
[79147] = {id=79147,name="Flight Training 101",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14717,description="Now that all of our recruits are present, it's high time we took to the air. See what I did there? High time? No? Right then. We'll be puttin' these rookies through their paces. Startin' with the basics of aerial maneuverin' at speed, we'll do our best to simulate the kind of precision flyin' we might expect below ground. After that, we'll see what these rooks can really do--an I think Thrall and Lufsela have somethin' special cookin'.",starts={{npcID=215211,x=0.35,y=0.722,zoneID=14717}},ends={{npcID=215211,x=0.35,y=0.722,zoneID=14717}},coords={x=0.35,y=0.722,source="quest_giver",zoneID=14717},questType="standard"},
[79148] = {id=79148,name="The Nibelgaz Refinery",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="Quickly! Elementals have overrun the Nibelgaz Mine and the refinery crew are trapped down there with them. I am especially worried about my fused, Munderut. His memory is not the best these days. If you are a friend, rescue him and the refinery workers. Here, take this healing clay . It only helps a little, but it should be enough for any injured to make their way back. I wish we had a rejuvenating crystal, but that is the stuff of legends.",starts={{npcID=215208,x=0.51,y=0.148,zoneID=14795}},ends={{npcID=215208,x=0.51,y=0.148,zoneID=14795}},coords={x=0.51,y=0.148,source="quest_giver",zoneID=14795},questType="standard"},
[79149] = {id=79149,name="Rampage in the Refinery",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="Catastrophe! Oh, this is awful. Awful! Those accursed slag heap elementals are keeping my refinery workers from being able to do their jobs. Duty demands we carry on our work. These delays will not be tolerated. You look competent enough. Go on, get down there and get to work destroying elementals. Production must not be slowed!",starts={{npcID=215234,x=0.514,y=0.144,zoneID=14795}},ends={{npcID=215234,x=0.514,y=0.144,zoneID=14795}},coords={x=0.514,y=0.144,source="quest_giver",zoneID=14795},questType="standard"},
[79150] = {id=79150,name="Thespians at the Proscenium",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14776,description="When I wanted the Unbound to bring their plays to Dornogal, I didn't know what I would be up against. Or that my \"help\" would get in the way. My old friend Brokfor keeps interrupting us with his perfectionism. We try to build a set, but he stops everyone to inspect each nail. We try to paint, he complains the colors do not exactly match... you get the idea. I think Brokfor needs his own project. Maybe... cleaning up the Proscenium? Go ask him to help and keep him occupied.",starts={{npcID=214296,x=0.564,y=0.514,zoneID=14717},{npcID=214296,x=0.496,y=0.656,zoneID=14776}},ends={{npcID=214296,x=0.564,y=0.514,zoneID=14717},{npcID=214296,x=0.496,y=0.656,zoneID=14776}},coords={x=0.564,y=0.514,source="quest_giver",zoneID=14717},questType="standard"},
[79156] = {id=79156,name="The Edicts",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,description="Merrix and Adelgonn will be expecting an update. On my way here, I heard that they're all heading to the Proscenium to commit to the war officially. You should go and brief them on the readiness of the Stormriders. I'd like a moment with Zarein here. But we'll be along soon. And we'll be bringing Baelgrim's spirit with us.",starts={{npcID=214916,x=0.57,y=0.506,zoneID=14717},{npcID=214995,x=0.276,y=0.604,zoneID=14717},{npcID=214916,x=0.318,y=0.61,zoneID=14771}},ends={{npcID=214916,x=0.57,y=0.506,zoneID=14717},{npcID=214916,x=0.318,y=0.61,zoneID=14771}},coords={x=0.57,y=0.506,source="quest_giver",zoneID=14717},questType="standard"},
[79157] = {id=79157,name="Titanic Failsafe",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,description="So, the titans sent their ancient machines against their disobedient children. Would our creators have us protect the Coreway at the expense of all else? At the expense of Azeroth herself? Are we meant to preside over a road untraveled, leading to the world's dead heart? No, today we are all Unbound, and we will fight for our freedom. For Azeroth!",starts={{npcID=214916,x=0.57,y=0.506,zoneID=14717},{npcID=214916,x=0.318,y=0.61,zoneID=14771}},ends={{npcID=223944,x=0.316,y=0.596,zoneID=14771}},coords={x=0.57,y=0.506,source="quest_giver",zoneID=14717},questType="standard"},
[79158] = {id=79158,name="Seeds of Salvation",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,description="These once obedient harvestbots have run amok and are wreaking havoc in our fields. The success of our community depends on getting our seeds in the ground, but most of the seeds are in the hands of those harvesters! Would you venture into the fields, eliminate any rogue machines, gather the seeds, and finish the planting?",starts={{npcID=206441,x=0.652,y=0.28,zoneID=14838}},ends={{npcID=206441,x=0.652,y=0.28,zoneID=14838}},coords={x=0.652,y=0.28,source="quest_giver",zoneID=14838},questType="standard"},
[79159] = {id=79159,name="Dereliction of Duty",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="A moment, if you have one. One of my lieutenants, Shinda Creedpike , did not report in at first bonfire. That may not seem like a large issue to you, but the Arathi in Hallowfall survive only because we follow orders and stand for our brethren. I am not cruel. I do not want to punish a man for his weakness in this terrible environment. Can you find him and bring him back? Take all the time you need.",starts={{npcID=215306,x=0.414,y=0.524,zoneID=14838}},ends={{npcID=215301,x=0.406,y=0.506,zoneID=14838}},coords={x=0.414,y=0.524,source="quest_giver",zoneID=14838},questType="standard"},
[79160] = {id=79160,name="Fishing is Good for the Soul",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="I used to fish with my mother at the local pond when I was a child. It wasn't the fish that made the experience--my mother was famously terrible at cooking--but the tranquility and bonding time. Perhaps I could find a portion of that peace again here. There's a spot south of Mereldar that the others use to fish. I'll meet you there!",starts={{npcID=215301,x=0.406,y=0.506,zoneID=14838}},ends={{npcID=215301,x=0.406,y=0.506,zoneID=14838}},coords={x=0.406,y=0.506,source="quest_giver",zoneID=14838},questType="standard"},
[79162] = {id=79162,name="Burnout",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="Please return to Commander Dawnsurge and give them my sincere apologies for my absence. I will submit myself for punishment for my trespass after my shift.",starts={{npcID=215301,x=0.406,y=0.506,zoneID=14838}},ends={{npcID=215306,x=0.414,y=0.524,zoneID=14838}},coords={x=0.406,y=0.506,source="quest_giver",zoneID=14838},questType="standard"},
[79173] = {id=79173,name="Supply the Effort",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,description="When shadow fell upon our town, many necessary supplies were taken in the cover of darkness. With the light returning, it is time to rebuild, but first, we must retrieve what was lost. Search the surrounding areas, recover any supplies that might be useful.",starts={{npcID=206150,x=0.632,y=0.294,zoneID=14838}},ends={{npcID=206150,x=0.632,y=0.294,zoneID=14838}},coords={x=0.632,y=0.294,source="quest_giver",zoneID=14838},questType="standard"},
[79174] = {id=79174,name="Infested Infestation",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="These spore-afflicted beasts at Pillar-nest Vosh been a thorn in our side since setting up Faerin's Advance. They be spreading thick clouds of spores. I never be seeing anything like it! They already attacked once. Won't be long till they attack again. If we got any hope of survivin', we need to cull dere numbers. Go to Pillar-nest Vosh and take some of those spore-afflicted beasts out!",starts={{npcID=215349,x=0.578,y=0.196,zoneID=14752}},ends={{npcID=215349,x=0.578,y=0.196,zoneID=14752}},coords={x=0.578,y=0.196,source="quest_giver",zoneID=14752},questType="standard"},
[79175] = {id=79175,name="I Think I'm a Drone Now",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="There, I have extended some goodwill. You have a little goblin friend. I know how much your kind clings to each other for warmth. And now you both will do things for me. First, I will provide you with my pheromone scent mark. It will keep my loyal soldiers from attacking you. It marks you as mine.",starts={{npcID=217330,x=0.454,y=0.198,zoneID=14752}},ends={{npcID=217330,x=0.454,y=0.198,zoneID=14752}},coords={x=0.454,y=0.198,source="quest_giver",zoneID=14752},questType="standard"},
[79176] = {id=79176,name="Opals and Runes",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,description="You have certainly made my disaster of a day far less stressful, . For that, you have the thanks of the entire Forgegrounds and those who keep it running. Vokgret winks as she gives you a knowing smile.> Bevrusi was right to send you to me. Do tell her not to be a stranger now. I could use more friends from the Deeps. Here is her liquid opal. Give it to her with my compliments.",starts={{npcID=217091,x=0.452,y=0.488,zoneID=14771}},ends={{npcID=217097,x=0.604,y=0.332,zoneID=14771}},coords={x=0.452,y=0.488,source="quest_giver",zoneID=14771},questType="standard"},
[79186] = {id=79186,name="It's Hearthstone's Anniversary!",level=0,requiredLevel=0,faction="none",expansion=10,description="Hearthstone's been played for ten years, can you believe it? Farala, Master of Ceremonies, is hosting Hearthstone games at the Stormwind Harbor. Come join in the celebration!",questType="standard"},
[79189] = {id=79189,name="It's Hearthstone's Anniversary!",level=0,requiredLevel=0,faction="none",expansion=10,description="\"Hearthstone's been played for ten years, can you believe it? Farala, Master of Ceremonies, is hosting Hearthstone games in Durotar, between Orgrimmar and the docks. Come join in the celebration!",questType="standard"},
[79193] = {id=79193,name="Spinning Spore Spines",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="Orsenth sent you? And we are supposedly fused? Why... so I am wearing a medallion. But I have no memory... Well, no time for that. Did you see the spinning spores on your way here? I need the spines that they grow for... I need them for... now what was it again? Oh yes! There is no better instrument for carving out the fine detail that my work as a gem carver requires than those spines. Will you collect some? I will make my way back to the refinery. I am eager to get back and meet this Orsenth.",starts={{npcID=215209,x=0.51,y=0.148,zoneID=14795}},ends={{npcID=215209,x=0.51,y=0.148,zoneID=14795}},coords={x=0.51,y=0.148,source="quest_giver",zoneID=14795},questType="standard"},
[79194] = {id=79194,name="To the Source",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="Orsenth told me you have been instrumental in dealing with the elemental problem here at the mine. I am Keldaz , supervisor for the militia. We came as soon as word of the attack reached us in Gundargaz. The miners you rescued said that the elementals poured out of the northeast mine shaft. I will leave some of my guards here to lend their support and have sent for reinforcements. If you are still willing to help, meet me outside the cave and let us see what we can do to staunch the flow of elementals.",starts={{npcID=217474,x=0.51,y=0.148,zoneID=14795}},ends={{npcID=223000,x=0.552,y=0.11,zoneID=14795}},coords={x=0.51,y=0.148,source="quest_giver",zoneID=14795},questType="standard"},
[79196] = {id=79196,name="Renowned with The Severed Threads",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14752,description="The Weaver has been keeping an eye on you. She has determined you would be a better asset with more resources at your disposal. Come to the Weaver's Lair. I have a parcel waiting for you.",ends={{npcID=220867,x=0.552,y=0.412,zoneID=14752},{npcID=223750,x=0.552,y=0.412,zoneID=14752}},questType="standard"},
[79197] = {id=79197,name="Surface Bound",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14771,description=", the moment is upon us. We must make haste to the city of Dornogal, where our allies await. Only together do we stand a chance against Harbinger's machinations.",starts={{npcID=219252,x=0.556,y=0.44,zoneID=14752}},ends={{npcID=216149,x=0.36,y=0.802,zoneID=14771}},coords={x=0.556,y=0.44,source="quest_giver",zoneID=14752},questType="standard"},
[79199] = {id=79199,name="Renowned with Keg Leg's Crew",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=13644,mapID=2022,description="Your deeds have not gone unnoticed, and you continue to show that you are a renowned explorer! Return to the Dragonscale Basecamp as I have prepared more supplies to help you continue in your endeavours.",questType="standard"},
[79205] = {id=79205,name="Not Waste, Not Want",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="Everything have use, friend. Even things stoneheads throw away and think worthless. Kobolds know better. Go and see what you can find. Need to scavenge lots of scrap. Enough for kobold crafting of new homes!",starts={{npcID=212991,x=0.614,y=0.32,zoneID=14795}},ends={{npcID=212991,x=0.614,y=0.32,zoneID=14795}},coords={x=0.614,y=0.32,source="quest_giver",zoneID=14795},questType="standard"},
[79206] = {id=79206,name="Broken Memories",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="Something about this particular gemstone feels important. Perhaps it would be worthwhile to bring it to Speaker Brinthe .",ends={{npcID=212519,x=0.576,y=0.292,zoneID=14795}},questType="standard"},
[79213] = {id=79213,name="The Anachronism",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="Insert the batteries into the cylindrical holes on the console. Then, titans willing, we will see what it holds.",starts={{npcID=225478,x=0.616,y=0.702,zoneID=14717}},ends={{npcID=225478,x=0.616,y=0.702,zoneID=14717}},coords={x=0.616,y=0.702,source="quest_giver",zoneID=14717},questType="standard"},
[79216] = {id=79216,name="Web of Manipulation",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,description="This town has been under siege, overrun by spiders! Even when we clear them out, they always return. Something is behind these attacks! A small ledge northeast of Light's Bloom harbors these spiders. Scout out the ledge. Find out what is driving these spiders to attack us, and put an end to it!",starts={{npcID=206150,x=0.632,y=0.294,zoneID=14838}},ends={{npcID=206150,x=0.632,y=0.294,zoneID=14838}},coords={x=0.632,y=0.294,source="quest_giver",zoneID=14838},questType="standard"},
[79217] = {id=79217,name="Back to Base",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,description="Getting this factory up and running will be a challenge, but I think we'll figure out something. Let's head back to Gundargaz and consult with a friend of ours. His mind will be a big help to us here.",starts={{npcID=214663,x=0.562,y=0.748,zoneID=14795}},ends={{npcID=217245,x=0.47,y=0.342,zoneID=14795}},coords={x=0.562,y=0.748,source="quest_giver",zoneID=14795},questType="standard"},
[79218] = {id=79218,name="Renowned with the Hallowfall Arathi",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14838,description="Your labors on behalf of our people have not gone unnoticed. Nor will they go unrewarded. Find me in Mereldar.",ends={{npcID=213145,x=0.412,y=0.53,zoneID=14838}},questType="standard"},
[79219] = {id=79219,name="Renowned with the Council of Dornogal",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,description="The Council continues to be in your debt, friend. If you visit me in Dornogal, I will give you supplies to reduce that debt.",ends={{npcID=223728,x=0.392,y=0.242,zoneID=14771}},questType="standard"},
[79220] = {id=79220,name="Renowned with the Assembly of the Deeps",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14795,description="Good work deserves good reward, yes? Assembly is grateful. Waxmonger Squick is grateful. Show gratefulness with many supplies. Come see Waxmonger Squick in Gundargaz.",ends={{npcID=221390,x=0.472,y=0.328,zoneID=14795}},questType="standard"},
[79221] = {id=79221,name="The Unusual Bug",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14752,description="Nerubians in Rak-Ush may find this strange little spider of interest.",ends={{npcID=207471,x=0.556,y=0.438,zoneID=14752}},questType="standard"},
[79222] = {id=79222,name="Shadow-Hardened Mainspring",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,description="Speaker Kuldas in Gundargaz.>",ends={{npcID=217128,x=0.474,y=0.32,zoneID=14795}},questType="standard"},
[79224] = {id=79224,name="Gathering Intel",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14752,description="The Widow Arak'nai sent word via one of those \"weave-rats\" of hers. She has a lead that may be relevant to our cause, and has invited us to investigate. All the training in the world is useless without knowledge of our enemy. My own reconnaissance efforts in Azj-Kahet were met with... mixed results, as you may recall. I admit I am not keen on venturing down there again so soon. Fortunately, reinforcements have arrived with a capable spymaster. Unfortunately, she is... well. You'll see.",starts={{npcID=223944,x=0.316,y=0.596,zoneID=14771}},ends={{npcID=207471,x=0.556,y=0.438,zoneID=14752}},coords={x=0.316,y=0.596,source="quest_giver",zoneID=14771},questType="standard"},
[79225] = {id=79225,name="The Lost Flame",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,description="Hallowfall Expedition member, its return would help honor the memory of those who bravely gave their lives.> An expedition scout might possess knowledge about this item.>",ends={{npcID=215527,x=0.654,y=0.322,zoneID=14838}},questType="standard"},
[79227] = {id=79227,name="A Spider's-Eye View",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14753,description="I have eyes in every crevice of the city save for one that has... eluded me. The Transformatory is the grounds of Ansurek's most precocious minions and treasured pets. It is where the Ascension process was developed. I've only gotten my claws on it recently, thanks to dear Y'tekhi. Much of it remains uncomfortably shrouded. A more legs-on approach is in order. Place shadecasters to collect intel from my scouts, then meet Y'tekhi and your own spymaster Voss in a discreet corner of the district.",starts={{npcID=207471,x=0.556,y=0.438,zoneID=14752}},ends={{npcID=215626,x=0.696,y=0.716,zoneID=14753}},coords={x=0.556,y=0.438,source="quest_giver",zoneID=14752},questType="standard"},
[79230] = {id=79230,name="Creeping Through Corridors",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14753,description="I've identified three sites of interest to investigate. A stockpile on the east side of the complex, a warehouse in the center, and lastly, that big storehouse with royal Sureki flags outside it. We'll rendezvous there. There's less chance of discovery if we move separately through the area. You may be hidden from most nerubians, but the Ascended will sniff you out. Chuck some of these anger pheromones at them if you get heat, it'll distract them. Stay sharp, stay quiet.",starts={{npcID=215626,x=0.696,y=0.716,zoneID=14753}},ends={{npcID=215628,x=0.568,y=0.906,zoneID=14753}},coords={x=0.696,y=0.716,source="quest_giver",zoneID=14753},questType="standard"},
[79231] = {id=79231,name="Back to Headquarters! Again!",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=13647,mapID=2025,description="You've done truly incredible work! The proof is obvious: you are, in fact, a proper Azerothian Archivist. Meet us all back at our headquarters in Thaldraszus. Eadweard would like codify all your helpful labors and achievements for our group.",starts={{npcID=207311,x=0.77,y=0.384,zoneID=14433},{npcID=208362,x=0.172,y=0.164,zoneID=14433},{npcID=207763,x=0.382,y=0.498,mapID=2133},{npcID=208055,x=0.476,y=0.486,mapID=2133}},ends={{npcID=206107,x=0.614,y=0.312,mapID=2025}},coords={x=0.77,y=0.384,source="quest_giver",mapID=2025},questType="standard"},
[79233] = {id=79233,name="Lab Access",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14753,description="As much as I adore skulking in the shadows, the juiciest intel is going to be inside the laboratory of the Grand Splicer. Of course you'll need the proper pheromones once you're in, but we can take care of that with a little biological forgery. The nerubian loyalists here are surely on the invite list. Six of their secretions should be enough to disguise the three of us.",starts={{npcID=215637,x=0.696,y=0.72,zoneID=14753}},ends={{npcID=215659,x=0.57,y=0.908,zoneID=14753}},coords={x=0.696,y=0.72,source="quest_giver",zoneID=14753},questType="standard"},
[79234] = {id=79234,name="A Small Bag of Seeds",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,description="Aliya Hillhelm could make use of them.>",ends={{npcID=206528,x=0.612,y=0.304,zoneID=14838}},questType="standard"},
[79237] = {id=79237,name="Making of a Monster",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14753,description="We've got a new objective: Figure out what Ansurek's plans are for this... thing. We'll find our answers inside the laboratory of the Grand Splicer. I'd bet my blades on it. I scouted a maintenance hatch on the roof that you can grapple up to. Y'tekhi brewed up some weird concoction that they claim will get us the proper clearance once inside. Yuck. Meet you in there.",starts={{npcID=215628,x=0.568,y=0.906,zoneID=14753}},ends={{npcID=215628,x=0.568,y=0.906,zoneID=14753}},coords={x=0.568,y=0.906,source="quest_giver",zoneID=14753},questType="standard"},
[79239] = {id=79239,name="The Queen's Chains",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14753,description="Ansurek... that worm, that witless, gutless little-- Y'tekhi growls under their breath, struggling to maintain their composure.> If this is what's become of Neferess, we must free her. She is still our queen. My mistress will know what to do. When the Weaver discovers what they've all done, there will not be a crevice deep enough to escape her wrath.",starts={{npcID=215659,x=0.57,y=0.908,zoneID=14753}},ends={{npcID=215661,x=0.786,y=0.574,zoneID=14753}},coords={x=0.57,y=0.908,source="quest_giver",zoneID=14753},questType="standard"},
[79240] = {id=79240,name="Rogue Agent",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14753,description="We lost Y'tekhi . We can worry about the how of it later. Right now, we need to worry about taking them down before they make things worse. I guess we came down here to find out what Xal'atath had up her sleeve. ...I wish we'd minded our own business.",starts={{npcID=215661,x=0.786,y=0.574,zoneID=14753}},ends={{npcID=215662,x=0.786,y=0.398,zoneID=14753}},coords={x=0.786,y=0.574,source="quest_giver",zoneID=14753},questType="standard"},
[79241] = {id=79241,name="Go Loud",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14752,description="So much for keeping this operation quiet. At least now that our cover's blown, we can really mess things up. They're hauling weapons across the south bridge. If we turn those weapons against them, they'll have to resupply their whole army. That'll buy us time, at least. I've identified six weak spots across the convoy. Rig up bombs to all six, then get out of there and watch the fireworks.",starts={{npcID=215662,x=0.786,y=0.398,zoneID=14753}},ends={{npcID=215625,x=0.556,y=0.44,zoneID=14752}},coords={x=0.786,y=0.398,source="quest_giver",zoneID=14753},questType="standard"},
[79243] = {id=79243,name="Manufactured Mutiny",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14752,description="We don't have the firepower to dismantle their whole manufacturing operation, but what we do have is two leftover vials of anger pheromones. Let's make them count. There's a siege marshal and a quartermaster overseeing the preparations and giving everyone orders. Logistics types, but they still pack a punch. That's where those pheromones come in. Hit them with a vial, and their own armies will turn against them. Take out both, and we watch the operation crumble.",starts={{npcID=215662,x=0.786,y=0.398,zoneID=14753}},ends={{npcID=215625,x=0.556,y=0.44,zoneID=14752}},coords={x=0.786,y=0.398,source="quest_giver",zoneID=14753},questType="standard"},
[79244] = {id=79244,name="News From Below",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,description="I could hear the explosions from here. That'll buy us some time. Maybe I'd even be relieved, if this had gone less poorly. Y'tekhi is secured in the back, where they can't overhear anything. Whatever Xal'atath did... it hasn't worn off yet. The Weaver has people looking into it, but the outlook is grim. Alleria is going to want a status report. Good luck.",starts={{npcID=215625,x=0.556,y=0.44,zoneID=14752}},ends={{npcID=223944,x=0.316,y=0.596,zoneID=14771}},coords={x=0.556,y=0.44,source="quest_giver",zoneID=14752},questType="standard"},
[79245] = {id=79245,name="[Unused - Reuse Quest Bit]",level=80,requiredLevel=80,faction="none",expansion=10,questType="standard"},
[79256] = {id=79256,name="A Hint of Fear",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="My father thinks that while he and Dagran were dealing with the skardyn tae the south, he caught a sensation o' his old hammer, Fearbreaker. He said it slipped out o' his fingers when Dalaran crashed, and it's been bothering him mightily. That hammer belongs tae the Bronzebeard clan, and has for generations. But he hasn't been himself lately, either. I'm willing tae have a look, so he doesn't worry that he might've missed it. Meet me down at Camp Murroch, and we'll have a quick look around.",starts={{npcID=212742,x=0.47,y=0.34,zoneID=14795}},ends={{npcID=215781,x=0.55,y=0.632,zoneID=14795}},coords={x=0.47,y=0.34,source="quest_giver",zoneID=14795},questType="standard"},
[79258] = {id=79258,name="Mineral Water Woes",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="When that magic hammer fell into the Deeps, I knew it could be a formidable weapon against the skardyn menace. Your friend has told me that it's 'particular' about its wielder. Fortunately, I am a hero! And as a hero, I know how to get close to it. We need to have a good mix of pollen and water plastered onto us. That way, the beast standing over it will think we're just like it. That mineral water has to be the exact right temperature to mix with the lashroom dust and blend in.",starts={{npcID=215788,x=0.55,y=0.632,zoneID=14795}},ends={{npcID=215821,x=0.54,y=0.666,zoneID=14795}},coords={x=0.55,y=0.632,source="quest_giver",zoneID=14795},questType="standard"},
[79259] = {id=79259,name="Put On a Good Face",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="Berrund here says that the massive beast standing over Fearbreaker is very particular about what kinds of creatures it allows near it. If we blend in, he says, we can get close enough tae nab the hammer. But tae blend in, he says we have tae get covered by the dust an' pollen in the grotto. Those Lashrooms look like they're a good place to start. It all seems suspicious tae me, but fer now, we'll play along until I can recover Fearbreaker and bring it back to my father.",starts={{npcID=215781,x=0.55,y=0.632,zoneID=14795}},ends={{npcID=215788,x=0.55,y=0.632,zoneID=14795},{npcID=215822,x=0.54,y=0.666,zoneID=14795}},coords={x=0.55,y=0.632,source="quest_giver",zoneID=14795},questType="standard"},
[79260] = {id=79260,name="Epicenter",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="There is the creature standing between us and that magic hammer. It certainly made an impact when it landed here in the Ringing Deeps , didn't it? Look at the size of that crater! With the pollen and water splashed on you like this, you should be able to approach that beast and, theoretically, not be harmed. You'll blend right in with it! But if it does turn aggressive, don't worry, I'll be right behind you. We'll get that hammer out of here safely!",starts={{npcID=215822,x=0.54,y=0.666,zoneID=14795}},ends={{npcID=215821,x=0.54,y=0.666,zoneID=14795}},coords={x=0.54,y=0.666,source="quest_giver",zoneID=14795},questType="standard"},
[79261] = {id=79261,name="Boiling Mad",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="That gravel-brained ingrate! He took Fearbreaker and ran off to the north! It's not that I want that hammer for myself. I don't. But it belongs to the Bronzebeard clan. It should be in the hands of someone who respects its power! We need to track him down before he hurts himself or someone else with that hammer!",starts={{npcID=215821,x=0.54,y=0.666,zoneID=14795}},ends={{npcID=215824,x=0.56,y=0.5,zoneID=14795}},coords={x=0.54,y=0.666,source="quest_giver",zoneID=14795},questType="standard"},
[79262] = {id=79262,name="Clean Up House",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="It looks like the destruction around the Coreway rattled loose more than just a few stones down here. It's stirred up all sorts o' dark things. If this was a thriving mining operation, it ain't anymore. We need to help the earthen get it under control again, and that means thinning out these beasts.",starts={{npcID=215824,x=0.56,y=0.5,zoneID=14795}},ends={{npcID=215837,x=0.572,y=0.456,zoneID=14795}},coords={x=0.56,y=0.5,source="quest_giver",zoneID=14795},questType="standard"},
[79263] = {id=79263,name="Fault Lines",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="Berrund took Fearbreaker for himself. I suppose he thought he could save these people. Be the hero. But ye can't go about doing the wrong thing for the right reasons. I know from experience. If a rock is hollow tae begin with, it never can be solid again, no matter how hard ye try. He's likely tae need saving himself now. Let's find him in this blasted place.",starts={{npcID=215824,x=0.56,y=0.5,zoneID=14795}},ends={{npcID=215836,x=0.572,y=0.456,zoneID=14795}},coords={x=0.56,y=0.5,source="quest_giver",zoneID=14795},questType="standard"},
[79264] = {id=79264,name="These Strong Hands",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="Berrund the Gleaming coughs dustily.> I knew I couldn't take the skardyn without some help. I thought, if I just had that magic hammer, then nothing would stop me. I had to have it, you see, or else, maybe I wasn't who I was made to be. But it kept slipping out of my fingers. Like it didn't want anything to do with me. It fell out of my hands at the worst moment and now... It's clearly not mine. It never was. I'm... I'm... sorry.",starts={{npcID=215836,x=0.572,y=0.456,zoneID=14795}},ends={{npcID=217598,x=0.572,y=0.456,zoneID=14795}},coords={x=0.572,y=0.456,source="quest_giver",zoneID=14795},questType="standard"},
[79265] = {id=79265,name="Fearbreaker",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="The skardyn have taken over the operations here in the Rumbling Wastes. That's why Berrund thought he needed Fearbreaker . We're going to finish that job before I take the hammer back to Magni. What kind of a queen would I be if I wasn't willing tae put myself in danger for the good of others? Let's get in there and save as many as we can.",starts={{npcID=217598,x=0.572,y=0.456,zoneID=14795}},ends={{npcID=216085,x=0.618,y=0.466,zoneID=14795}},coords={x=0.572,y=0.456,source="quest_giver",zoneID=14795},questType="standard"},
[79266] = {id=79266,name="The Bronzebeard Legacy",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="Well, we did what we set out tae do... and more. We found Fearbreaker and did some good with it. Now it's time tae bring it back tae Magni. Let's hope Berrund learned a lesson here, but I suspect he'll manage tae get himself in trouble again soon. Hopefully, it'll be fer the right reasons an' with the right support.",starts={{npcID=216085,x=0.618,y=0.466,zoneID=14795}},ends={{npcID=217827,x=0.472,y=0.34,zoneID=14795}},coords={x=0.618,y=0.466,source="quest_giver",zoneID=14795},questType="standard"},
[79267] = {id=79267,name="Wax On, Pot Off",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="If candles are important to kobold society, I have an idea that might disrupt their production... or at least make sure there's an unpleasant surprise waiting for our enemy. Take that cinderbrew. Drop some in those large vats of wax the kobolds are prepping at the top of that hill. It's a powerful explosive. It burns aggressively, so try not to drop any. It should certainly make any candles made with that wax quite feisty, once they're lit.",starts={{npcID=212992,x=0.614,y=0.32,zoneID=14795}},ends={{npcID=212992,x=0.614,y=0.32,zoneID=14795}},coords={x=0.614,y=0.32,source="quest_giver",zoneID=14795},questType="standard"},
[79282] = {id=79282,name="The Grand Debut",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14776,description="The Proscenium is looking amazing! Are you ready to get on stage? Give us a hand as part of the crew, and we'll give you a chance to act. Will you accept this directive?",starts={{npcID=214296,x=0.564,y=0.514,zoneID=14717},{npcID=214296,x=0.496,y=0.656,zoneID=14776}},ends={{npcID=214296,x=0.564,y=0.514,zoneID=14717},{npcID=214296,x=0.496,y=0.656,zoneID=14776}},coords={x=0.564,y=0.514,source="quest_giver",zoneID=14717},questType="standard"},
[79297] = {id=79297,name="Nightwatch",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="Xal'atath is using the Order of Night to serve her whims. I overheard some of the Arathi complaining about a new wave of propaganda that has been put up around Mereldar. Find what you can and deliver it to General Steelstrike . I'll be there as soon as I can. We need to convince her of the severity of this threat.",starts={{npcID=218182,x=0.426,y=0.556,zoneID=14838}},ends={{npcID=213108,x=0.34,y=0.546,zoneID=14838}},coords={x=0.426,y=0.556,source="quest_giver",zoneID=14838},questType="standard"},
[79300] = {id=79300,name="The Notebook",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="$p, I need your help. My whole future is on the line! I came to Lightspark to be an airship captain, and I've put in a ton of work to excel here. But my notebook is missing, with my final report! I'm top in the class, but if I don't turn it in soon, I won't be our next airship captain. Please help me find it. I thought I left it out by the canyon where we review each other's skiff piloting, but it wasn't there when I checked. Can you help me look for it?",starts={{npcID=216001,x=0.526,y=0.602,zoneID=14838}},ends={{npcID=225925,x=0.534,y=0.594,zoneID=14838}},coords={x=0.526,y=0.602,source="quest_giver",zoneID=14838},questType="standard"},
[79301] = {id=79301,name="Height Club",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="I'm so tired of Edwyn. From the day we all arrived, he's been telling everyone he'll be selected as captain. He's a great flyer--very talented, and he knows his stuff. But his ego gets in the way of treating people as he should. And he knows my grades and flight review scores are higher. But if I can't turn in my report, he'll be the next captain. Take it back from him!",starts={{npcID=225925,x=0.534,y=0.594,zoneID=14838}},ends={{npcID=225925,x=0.534,y=0.594,zoneID=14838}},coords={x=0.534,y=0.594,source="quest_giver",zoneID=14838},questType="standard"},
[79302] = {id=79302,name="Gone with the Wind",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="I can't believe Edwyn threw my report out into the wind. Can you please track down what papers you can find? I'll look for any around the school grounds, you check the valley. This report is already late... But I had some really good insights around airship capabilities. When Headmaster Fynch sees them, maybe he'll still allow me to turn it in. Bring me whatever pages you find!",starts={{npcID=225925,x=0.534,y=0.594,zoneID=14838}},ends={{npcID=225926,x=0.534,y=0.606,zoneID=14838}},coords={x=0.534,y=0.594,source="quest_giver",zoneID=14838},questType="standard"},
[79303] = {id=79303,name="A Principled Principal",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="Great work gathering these up. I found a few blowing around up here, so I think we've got all the pages. Let's get this to Headmaster Fynch ! He's probably in the classroom. I sure hope he accepts it. He says he doesn't accept late work, but there were a lot of extenuating circumstances at play here. And if he doesn't, I'll be reporting to Edwyn as my captain. I'm not sure I could do that, after what's happened.",starts={{npcID=225926,x=0.534,y=0.606,zoneID=14838}},ends={{npcID=226074,x=0.528,y=0.592,zoneID=14838}},coords={x=0.534,y=0.606,source="quest_giver",zoneID=14838},questType="standard"},
[79304] = {id=79304,name="Care Package",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="My cousin Sophietta and I came to Hallowfall together as stalwarts. Since arriving, we both lived here in Dunelle's Kindness for years. But she left last year to follow her dream of being one of our airship captains, or at least joining an airship crew. She's a strong person, but I don't know how she's doing. Especially without Innkeeper Valrin's sweetrolls ! She can't get them at Lightspark, the Sky Academy. Will you take these to her, and make sure she's doing alright?",starts={{npcID=217609,x=0.692,y=0.438,zoneID=14838}},ends={{npcID=216001,x=0.526,y=0.602,zoneID=14838}},coords={x=0.692,y=0.438,source="quest_giver",zoneID=14838},questType="standard"},
[79309] = {id=79309,name="Status Report",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="Airships give the Arathi Army command of the skies. But roads are the lifeblood of empires. My scouts protect and light the passageways of Hallowfall for our citizens. One such patrol has been late to report their walk of the eastern road. Seek my missing scouts by the sight of smoke or flame. Arathi soldiers know better than to linger in the dark.",starts={{npcID=216061,x=0.704,y=0.45,zoneID=14838}},ends={{npcID=216063,x=0.754,y=0.496,zoneID=14838}},coords={x=0.704,y=0.45,source="quest_giver",zoneID=14838},questType="standard"},
[79310] = {id=79310,name="Seek the Lost",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="Guard our ways, repel the dark. Civilize this twisted land. All in the name of our empire. This is the mission of the Arathi Army. A mission I can heed no longer. I am afraid. I won't go back into the dark. Not after what I've seen. If Maevest or any of my other companions survived, they must crave the mercy of a swift death. And I left them to that terror. Tell Captain Trueflame her scouts died in darkness, one and all.",starts={{npcID=216063,x=0.754,y=0.496,zoneID=14838}},ends={{npcID=216063,x=0.754,y=0.496,zoneID=14838}},coords={x=0.754,y=0.496,source="quest_giver",zoneID=14838},questType="standard"},
[79311] = {id=79311,name="Stem the Flow",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="The roads were meant to be lit. But the path was overgrown, the lanterns dark. Swarming, frothing, and reeking with rot. It all happened so fast. By the time we realized the danger, the beasts were upon us. The largest of them was huge and black as night. It is our duty to slay monsters and push back the darkness. But the thought of going back fills with me fear. I've lost my nerve. But you, outsider, can still make this right.",starts={{npcID=216063,x=0.754,y=0.496,zoneID=14838}},ends={{npcID=216063,x=0.754,y=0.496,zoneID=14838}},coords={x=0.754,y=0.496,source="quest_giver",zoneID=14838},questType="standard"},
[79312] = {id=79312,name="Mow the Masses",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="Maevest and I broke away from the others and fled, their screams left in our wake. Foul muck smothered our lanterns and we stumbled in the dark through knee-high waters. I heard a splash like she had tripped and fallen in, but I couldn't bring myself to look back. Only later did I find the tiny bite marks on my ankles. Be warned, there's something in the water. I took notice of fronds growing from the pools. Swarming insects feast on their sickly nectar. Destroy those plants and starve the beasts.",starts={{npcID=216063,x=0.754,y=0.496,zoneID=14838}},ends={{npcID=216063,x=0.754,y=0.496,zoneID=14838}},coords={x=0.754,y=0.496,source="quest_giver",zoneID=14838},questType="standard"},
[79313] = {id=79313,name="What Grows in the Dark",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="We are told never to walk in the darkness. To carry light wherever we go. The thought of returning this way filled me with dread. But your courage shines with splendor, . At your side, my way is lit. No more hiding. The beast clad in black chitin, the one that killed my friends, dies in that cave. I am with you.",starts={{npcID=216063,x=0.754,y=0.496,zoneID=14838}},ends={{npcID=216061,x=0.704,y=0.45,zoneID=14838}},coords={x=0.754,y=0.496,source="quest_giver",zoneID=14838},questType="standard"},
[79324] = {id=79324,name="To the Waterworks",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,description="Getting the Waterworks up and running is our first objective. Nothing else we do matters if we can't get power to the facility. Meet up with Dagran and ZZ-01-47 once you get there. And try to keep them on the sidelines. I don't want to explain to Moira that her son was injured, or worse, under my care.",starts={{npcID=217245,x=0.47,y=0.342,zoneID=14795}},ends={{npcID=217331,x=0.472,y=0.422,zoneID=14795}},coords={x=0.47,y=0.342,source="quest_giver",zoneID=14795},questType="standard"},
[79325] = {id=79325,name="Shadowvein Extraction",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,description="I sent Zee-Zee ahead to the Shadowvein extraction site. From what they transmitted back it looks like the area is swarming with rock worms and covered in this... discharge. I gave them an upgrade while we were waiting for you. I don't know how effective it'll be in battle but the results should be shocking for anyone that tries to threaten them.",starts={{npcID=217331,x=0.472,y=0.422,zoneID=14795}},ends={{npcID=216140,x=0.556,y=0.41,zoneID=14795}},coords={x=0.472,y=0.422,source="quest_giver",zoneID=14795},questType="standard"},
[79327] = {id=79327,name="The Glittering Shard",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="Orsenth may be interested in examining this piece of ore.>",ends={{npcID=219042,x=0.51,y=0.148,zoneID=14795}},questType="standard"},
[79335] = {id=79335,name="One More Tradition",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="Before I shut down, I must craft an item that is meaningful to me. As a Stonebound, I worked the mines. I had a lantern I made and used until I lost it in a collapse. I became Unbound shortly after. I wish to forge a new lantern to guide my way through these final moments. The lantern was made of an ore found in small amounts around this area. I used a charged core in the lantern. You can find them in the stormfangs that roam these hills. Gather the materials, and I will forge the lantern.",starts={{npcID=213184,x=0.574,y=0.43,zoneID=14717}},ends={{npcID=216169,x=0.57,y=0.424,zoneID=14717}},coords={x=0.574,y=0.43,source="quest_giver",zoneID=14717},questType="standard"},
[79336] = {id=79336,name="The Forging of Memories",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="Before its shutdown, we earthen would descend to the Awakening Machine below and renew our cycle. But now, even if it was still working, I would see my cycle broken and be remembered as I am. Korgran lets out a deep sigh.> These hands look strong, but they become heavier with each passing moment. The stiffness in my wrists and elbows will not let me carry the items to the forge. Please, add the right material to the forge as I call them out.",starts={{npcID=216169,x=0.57,y=0.424,zoneID=14717}},ends={{npcID=216169,x=0.57,y=0.424,zoneID=14717}},coords={x=0.57,y=0.424,source="quest_giver",zoneID=14717},questType="standard"},
[79337] = {id=79337,name="The Last Journey",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="This lantern is perfect. Enough of this. It is time! I can feel my memory clouding. We have to get going. Urtago is waiting for us. They will join us on my final journey to Mourning Rise, where we will conduct a ceremony. Korgran forces a smile.> It is nothing fancy, I promise. As I said, it is more symbolic than anything else. My head feels heavy. What was I doing again? Hmm, oh, right! Meeting Urtago !",starts={{npcID=216169,x=0.57,y=0.424,zoneID=14717}},ends={{npcID=213187,x=0.574,y=0.43,zoneID=14717}},coords={x=0.57,y=0.424,source="quest_giver",zoneID=14717},questType="standard"},
[79338] = {id=79338,name="The Lost Earthen",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="This is horrible! I knew I should have been keeping a closer eye on him. Confusion is the last symptom before a shutdown. Our memory is finite and starts overwriting. The more an earthen exert themselves, the faster their energy depletes and they lose memories. Korgran must be scared not knowing where he is--maybe not even who he is. I am such a boulder head! , please, I think I saw him go east into the trees. Meet me there up the road!",starts={{npcID=213187,x=0.574,y=0.43,zoneID=14717}},ends={{npcID=216878,x=0.61,y=0.438,zoneID=14717}},coords={x=0.574,y=0.43,source="quest_giver",zoneID=14717},questType="standard"},
[79339] = {id=79339,name="A Change of Tradition",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="An Unbound earthen can't return to the Coreway, so we have Mourning Rise. But looking at Korgran, remembering our last conversation before... I may not be the Mourning Rise caretaker just yet, but with Korgran's condition, it falls to me to be in charge. As Unbound, we made our own rules and traditions. So what if he doesn't want to stand at Mourning Rise? If a seaside memorial is what Caretaker Korgran wants, that's what he gets. , meet me at the shore to the southeast of here.",starts={{npcID=216878,x=0.61,y=0.438,zoneID=14717}},ends={{npcID=216173,x=0.698,y=0.568,zoneID=14717}},coords={x=0.61,y=0.438,source="quest_giver",zoneID=14717},questType="standard"},
[79340] = {id=79340,name="Tools of Declaration",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="As Unbound caretakers, we have a tradition for when a master bequeaths their mantle to their apprentice. Figuratively, of course. To do that, Korgran will need a horn. He would then face me, blow the horn, and the sound signifies his passing the mantle of the Mourning Rise caretaker to me. I saw shalehorns to the west of here. I would be thankful if you could bring me several of their horns. I will choose one that is suitable.",starts={{npcID=216173,x=0.698,y=0.568,zoneID=14717}},ends={{npcID=216173,x=0.698,y=0.568,zoneID=14717}},coords={x=0.698,y=0.568,source="quest_giver",zoneID=14717},questType="standard"},
[79341] = {id=79341,name="Cleansing Ashes",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="The Unbound have a symbolic ceremony of cleansing. We perform it before a shutdown. It is a symbolic process of purification. For it, we need to gather ashenfold , a flower that grows around the isle. We waft the smoke of the burned flowers through the fissures and cracks in our bodies to symbolically remove impurities. We are then ready to embrace our final moments. Urtago looks at Korgran with a hand on her chest. Her face falls.>",starts={{npcID=216173,x=0.698,y=0.568,zoneID=14717}},ends={{npcID=216173,x=0.698,y=0.568,zoneID=14717}},coords={x=0.698,y=0.568,source="quest_giver",zoneID=14717},questType="standard"},
[79342] = {id=79342,name="As He Departs",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="It is time for the ceremony, . Please place the bowl of ashenfolds by Korgran and then hand him the horn. Once the ceremony concludes, I will be the new caretaker. Then I will have to say a final farewell to my friend. Korgran will shutdown peacefully, knowing we were here by his side in the place he loved most--something I wish and hope to have when it is my time. My core is mud, but it is a great honor to stand here with him... and with you.",starts={{npcID=216173,x=0.698,y=0.568,zoneID=14717}},ends={{npcID=216173,x=0.698,y=0.568,zoneID=14717}},coords={x=0.698,y=0.568,source="quest_giver",zoneID=14717},questType="standard"},
[79346] = {id=79346,name="Chew On That",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,description="Fishing out here is not easy, especially when the spooky sounds of the darkness start to wear on the nerves. I've taken to chewing on the Duskstem from the tall plants nearby. It's sweet and chewy, keeps the jaw busy, and helps me pass the time! If you could lend a hand by gathering some Duskstem with your flying mount, I would be most appreciative.",starts={{npcID=215956,x=0.658,y=0.244,zoneID=14838}},ends={{npcID=215956,x=0.658,y=0.244,zoneID=14838}},coords={x=0.658,y=0.244,source="quest_giver",zoneID=14838},questType="standard"},
[79349] = {id=79349,name="Entrepreneur, Inc.",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="Okay, color me impressed. You are officially my Coinchamp! It's like a champion, only I pay you to do things. A mercenary, only with better branding. You should meet my business partner, Ripsnoodle . He's working out some deals with his own coinchamps with the niffin over at Mmarl. He might have more work for you--though I recommend not buying anything he tries to sell you. You can find Mmarl east of here. Just follow your nose, you can smell it from a mile away.",starts={{npcID=214168,x=0.408,y=0.398,zoneID=14752}},ends={{npcID=216308,x=0.782,y=0.616,zoneID=14752}},coords={x=0.408,y=0.398,source="quest_giver",zoneID=14752},questType="standard"},
[79350] = {id=79350,name="Intro Dummy Quest Week 1 (Text Only)",level=70,requiredLevel=70,faction="none",expansion=10,questType="standard"},
[79354] = {id=79354,name="The Machine Speakers",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="Ah, $p! The of the hour... We were just discussing you. There is some unfinished business for us to attend to, now that the High Speaker's transgressions have been corrected and the Awakening Machine restored once more. Care to stick around?",starts={{npcID=212742,x=0.47,y=0.34,zoneID=14795}},ends={{npcID=212742,x=0.47,y=0.34,zoneID=14795}},coords={x=0.47,y=0.34,source="quest_giver",zoneID=14795},questType="standard"},
[79355] = {id=79355,name="Prisoner Preservation",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="The beasts took our people! Dragged them away when we were gettin' our first rest since our escape! We only just escaped those nerubians. We can't afford ta lose more people. Search Pillar-nest Vosh. It's where all those beasts came from. If we're lucky our people are still alive.",starts={{npcID=215349,x=0.578,y=0.196,zoneID=14752}},ends={{npcID=215349,x=0.578,y=0.196,zoneID=14752}},coords={x=0.578,y=0.196,source="quest_giver",zoneID=14752},questType="standard"},
[79356] = {id=79356,name="Antifungal Firestarter",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="Consider it a professional hunch, but those spores comin' out of those fungal pods and the ones afflictin' all da beasts are connected. Maybe if we destroy da fungal spore pods it'll slow whatever control those fungarians have on da beasts. Take these antifungal firebombs and torch as many fungal spore pods as you can!",starts={{npcID=215349,x=0.578,y=0.196,zoneID=14752}},ends={{npcID=215349,x=0.578,y=0.196,zoneID=14752}},coords={x=0.578,y=0.196,source="quest_giver",zoneID=14752},questType="standard"},
[79357] = {id=79357,name="Removing the Cap",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="Aemara's mention of a large fungarian planting fungal pods worries me. Gotta be someting down in dat cave. We can't just be waitin' for the fungarians to attack with a nest of mind-controlled beasts. We gotta prune dat plan before it has a chance to bloom. Get to Pillar-nest Vosh and kill that fungarian leader!",starts={{npcID=215349,x=0.578,y=0.196,zoneID=14752}},ends={{npcID=215349,x=0.578,y=0.196,zoneID=14752}},coords={x=0.578,y=0.196,source="quest_giver",zoneID=14752},questType="standard"},
[79367] = {id=79367,name="A Nebb in Need",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="You! You no spider. Please, must help before spiders come again. Nebb know Chittering Den. Never seen spiders here before. Eat grubs, eat kobolds. But spiders dark things from dark places. Hate light. Can't leave post. You take candles, yes? Light up barricade. Keep spiders away.",starts={{npcID=215737,x=0.658,y=0.426,zoneID=14795}},ends={{npcID=215737,x=0.658,y=0.426,zoneID=14795}},coords={x=0.658,y=0.426,source="quest_giver",zoneID=14795},questType="standard"},
[79368] = {id=79368,name="Hair of the Spider",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="Light good, but more to do. Spiders came from everywhere. Nebb quick, Nebb heard them. But friend Snubjaw... he bit. Sick now. Nebb might know a way, yes, turn venom into cure. Use bite to cure bite. Bring venom. Hurry now!",starts={{npcID=215737,x=0.658,y=0.426,zoneID=14795}},ends={{npcID=215737,x=0.658,y=0.426,zoneID=14795}},coords={x=0.658,y=0.426,source="quest_giver",zoneID=14795},questType="standard"},
[79369] = {id=79369,name="Protecting the Harvest",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="Nebb young, no see past own snout. If harvest lost, many kobolds lost. Not just Snubjaw . Can no waste time. Kobolds starve if spiders gobble grubs and eggs. Save them, gather eggs. As many as can carry before spiders snatch all.",starts={{npcID=217152,x=0.658,y=0.426,zoneID=14795}},ends={{npcID=217152,x=0.658,y=0.426,zoneID=14795}},coords={x=0.658,y=0.426,source="quest_giver",zoneID=14795},questType="standard"},
[79370] = {id=79370,name="A Poultice for Poison",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="Little venom, little wax... Nebb reaches into his pouch and gives you a handful of thick, pungent wax.> Yes, yes, should work. Finest poultice, family recipe. Hurry now, give to Snubjaw . He feel right better.",starts={{npcID=215737,x=0.658,y=0.426,zoneID=14795}},ends={{npcID=215737,x=0.658,y=0.426,zoneID=14795}},coords={x=0.658,y=0.426,source="quest_giver",zoneID=14795},questType="standard"},
[79371] = {id=79371,name="A Royal Cure",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="Poultice no work! Wax right, venom wrong? Yes... yes! Strongest cure need strongest venom. Nebb saw crawler. She queen in red and black, too big to bother with kobolds. Queen smelled juicy grubs and skittered for cave. Now you must follow. Collect royal venom. Please, Snubjaw have little time.",starts={{npcID=215737,x=0.658,y=0.426,zoneID=14795}},ends={{npcID=215737,x=0.658,y=0.426,zoneID=14795}},coords={x=0.658,y=0.426,source="quest_giver",zoneID=14795},questType="standard"},
[79372] = {id=79372,name="A Clutch of Hope",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="Nebb . He and the other Grubtenders would know what to do with it.>",starts={{npcID=423581,x=0.681,y=0.391,zoneID=14795}},ends={{npcID=215737,x=0.658,y=0.426,zoneID=14795}},coords={x=0.681,y=0.391,source="quest_giver",zoneID=14795},questType="standard"},
[79475] = {id=79475,name="Charging Up That Hill",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,description="Before we use the conduit to summon the stormrooks, we need to recharge it. There are other, gentler ways to do this but... we have to work with what's on hand. The way to the peak is overrun with hostile elementals cast off from the storm. If we send them back to their plane, we can capture their residual energy and re-energize the conduit. While you work on recharging the conduit, we will go ahead and prepare for the ritual at the peak.",starts={{npcID=214995,x=0.276,y=0.604,zoneID=14717}},ends={{npcID=215039,x=0.256,y=0.572,zoneID=14717},{npcID=215039,x=0.374,y=0.82,zoneID=14771}},coords={x=0.276,y=0.604,source="quest_giver",zoneID=14717},questType="standard"},
[79476] = {id=79476,name="Heeding the Call",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,description="Earthen from across the island have been drawn to this place. Kind of a strange coincidence you'd show up now too. Maybe it's because Baelgrim's gone or... a new Stormward's coming. Or it could just be barometric pressure... Bah! There's time enough to spin wild theories later. Right now, we need to assist the pilgrims that have foolishly attempted the summit unprepared. We can't be worrying about them while we try to summon the stormrooks.",starts={{npcID=214995,x=0.276,y=0.604,zoneID=14717}},ends={{npcID=215039,x=0.256,y=0.572,zoneID=14717},{npcID=215039,x=0.374,y=0.82,zoneID=14771}},coords={x=0.276,y=0.604,source="quest_giver",zoneID=14717},questType="standard"},
[79477] = {id=79477,name="Strays",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,description="Kurdran Wildhammer has come to train the new Stormriders in aerial maneuvers. Thrall says his clan rides gryphons--much like the Stormriders ride stormrooks--so he should be of great help to us. Unfortunately, a few of our new recruits seem to have, uh, wandered off with their stormrooks. I wanted them to have a chance to bond, but it's time to come home. Would you mind rounding them up? Thrall and I are putting together something special for these \"rookies\" lessons.",starts={{npcID=215039,x=0.256,y=0.572,zoneID=14717},{npcID=215039,x=0.374,y=0.82,zoneID=14771}},ends={{npcID=215211,x=0.35,y=0.722,zoneID=14717}},coords={x=0.256,y=0.572,source="quest_giver",zoneID=14717},questType="standard"},
[79480] = {id=79480,name="Paying Respects",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14717,description="Please excuse my absence. It was never my intention to turn my back on the Stormriders, then or now. But I needed to come here and pay my respects to Baelgrim. Unfortunately, these blasted nerubians are still lingering. I think they're searching for something, but I don't know what. Whatever their reasons, I cannot abide them lurking where Baelgrim fell.",starts={{npcID=214995,x=0.276,y=0.604,zoneID=14717}},ends={{npcID=214995,x=0.276,y=0.604,zoneID=14717}},coords={x=0.276,y=0.604,source="quest_giver",zoneID=14717},questType="standard"},
[79481] = {id=79481,name="Tending to the Terrified",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="All happen so fast. One moment, we gathering eggs and grubs. Next, spiders swarming. Nebb drag me here, many others trapped. Caught in webs, soon to be feasts. Must save the Grubtenders. We tenders, not fighters. Do not let friends become meals.",starts={{npcID=217152,x=0.658,y=0.426,zoneID=14795}},ends={{npcID=217152,x=0.658,y=0.426,zoneID=14795}},coords={x=0.658,y=0.426,source="quest_giver",zoneID=14795},questType="standard"},
[79504] = {id=79504,name="Dripsy Forgot Her Candle",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="Gather round, tenderfoots, and Granny Scribbles tell you story. Story of what happen when Dripsy forgot her candle. Dripsy little tenderfoot, like you, who wander away from tribe...",starts={{npcID=216438,x=0.478,y=0.358,zoneID=14795}},ends={{npcID=216438,x=0.478,y=0.358,zoneID=14795}},coords={x=0.478,y=0.358,source="quest_giver",zoneID=14795},questType="standard"},
[79505] = {id=79505,name="Chomps and the Cave-In",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="Sit down, stop talk, and Granny Scribbles tell you story. Story that maybe save life one day. About what happen when not listen to old, wise kobold. Like me! Story of Chomps and the cave-in...",starts={{npcID=216438,x=0.478,y=0.358,zoneID=14795}},ends={{npcID=216438,x=0.478,y=0.358,zoneID=14795}},coords={x=0.478,y=0.358,source="quest_giver",zoneID=14795},questType="standard"},
[79507] = {id=79507,name="The Day the Stoneheads Came",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="What? Want scary story? You ask. Granny Scribbles give what want. Maybe then sit still like good tenderfoots. Scariest story Granny know, yes. Story about the day the stoneheads came...",starts={{npcID=216438,x=0.478,y=0.358,zoneID=14795}},ends={{npcID=216438,x=0.478,y=0.358,zoneID=14795}},coords={x=0.478,y=0.358,source="quest_giver",zoneID=14795},questType="standard"},
[79508] = {id=79508,name="Mipsy Mole-Rider",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="Time for happy story. Not all days bad. Granny Scribbles gently scratches Ol' Snorler behind his ears.> Tell story of how be friends with moles. Story of Mipsy mole-rider...",starts={{npcID=216438,x=0.478,y=0.358,zoneID=14795}},ends={{npcID=216438,x=0.478,y=0.358,zoneID=14795}},coords={x=0.478,y=0.358,source="quest_giver",zoneID=14795},questType="standard"},
[79510] = {id=79510,name="The Wickless Candle",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="Now tell story of very far place called \"surface\". New friend from there, yes, so they know what Granny Scribbles talk about. Granny Scribbles nods sagely as she points you out.> Story of how kobold discover it long go, and what find when do. Story of the wickless candle...",starts={{npcID=216438,x=0.478,y=0.358,zoneID=14795}},ends={{npcID=216438,x=0.478,y=0.358,zoneID=14795}},coords={x=0.478,y=0.358,source="quest_giver",zoneID=14795},questType="standard"},
[79521] = {id=79521,name="Seizing Evidence",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,description="Councilward Merrix has authorized trade goods from the Deeps to be transported through this depot. However, we have received a tip that more than crafting materials are being sent and received here. Dornogal observes strict rules about what we trade and with whom. All commerce must serve the Edicts, not the interests of individuals. We do not abide unsanctioned trading. We have started going through the crates here to find smuggled goods, but we haven't found anything--yet. Help us take a look.",starts={{npcID=219394,x=0.498,y=0.494,zoneID=14771}},ends={{npcID=219394,x=0.498,y=0.494,zoneID=14771}},coords={x=0.498,y=0.494,source="quest_giver",zoneID=14771},questType="standard"},
[79522] = {id=79522,name="Withheld Information",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,description="There has to be something we're missing. The tip we received was from a very reliable source. We have no reason to believe we were being misled. The Councilward will want us to get to the bottom of this, and I refuse to disappoint him. We haven't been able to get any additional information out of the workers, but maybe you'll have more luck. Speak to the ones we have detained here, and see if you can learn anything.",starts={{npcID=219394,x=0.498,y=0.494,zoneID=14771}},ends={{npcID=219394,x=0.498,y=0.494,zoneID=14771}},coords={x=0.498,y=0.494,source="quest_giver",zoneID=14771},questType="standard"},
[79523] = {id=79523,name="Something Hidden",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,mapID=2339,description="So, they have built extra compartments in the crates to hide extra items, eh? That explains how they have been smuggling goods into and out of Dornogal without our auditors knowing. Excellent work, ! But now the fun part of our job: those crates will have to be broken open and the smuggled goods taken into evidence. Smash the bottoms out of the crates and bring anything you find back to me.",starts={{npcID=219394,x=0.498,y=0.494,mapID=2339}},ends={{npcID=219394,x=0.498,y=0.494,mapID=2339}},coords={x=0.498,y=0.494,source="quest_giver",mapID=2339},questType="standard"},
[79525] = {id=79525,name="Report to the Councilward",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,description="Those receipts you found... Steelvein is a known smuggler that we've been chasing for a long time. The Councilward will be pleased to finally have solid evidence on his activities, and maybe even on his whereabouts. Bring these receipts to Merrix immediately. He will want to study them in detail. He said he was heading back to his office, so you should be able to find him at the Councilward's Rise. I'll package up the rest of the evidence to be brought to him later. Good work today.",starts={{npcID=219394,x=0.498,y=0.494,zoneID=14771}},coords={x=0.498,y=0.494,source="quest_giver",zoneID=14771},questType="standard"},
[79526] = {id=79526,name="Sedition",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,description="MERRIX is CORRUPT! STEELVEIN is WEAK! They cannot protect the earthen! They do not care about them! They spit upon the Edicts! MERRIX was BRIBED to reopen Steelvein's smuggling operation! Steelvein HIDES behind MERRIX 's authority! They are taking from YOUR pockets to line THEIRS! DO NOT TRUST THEIR LIES!",starts={{npcID=429303,x=0.459,y=0.473,zoneID=14771}},ends={{npcID=219400,x=0.556,y=0.058,zoneID=14771}},coords={x=0.459,y=0.473,source="quest_giver",zoneID=14771},questType="standard"},
[79527] = {id=79527,name="Damage Mitigation",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,description="Obstorn has confirmed that Ardgrin, the overseer in charge of my supply line that runs from the Deeps into Dornogal, is the one who tipped off my peacekeepers. It is therefore also my opinion that Ardgrin is the one who penned this sedition. He must have sent his workers upstairs to post them around the city. It is imperative that we remove them before these rumors spread further. Tear them down for me.",starts={{npcID=219400,x=0.556,y=0.058,zoneID=14771}},ends={{npcID=219400,x=0.556,y=0.058,zoneID=14771}},coords={x=0.556,y=0.058,source="quest_giver",zoneID=14771},questType="standard"},
[79528] = {id=79528,name="Dispelling Rumors",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,description="Many of my peacekeepers have already caught wind of Ardgrin's sedition. I am told some are losing faith in my integrity as Councilward, believing that I have been taking bribes from smugglers to bolster my own coffers. I can provide proof that no such transactions have taken place--clearly--but we need to stop them from murmuring amongst themselves and giving the rumors power. Lies become truths through repetition. If you find any discussing the matter, kindly disperse them.",starts={{npcID=219400,x=0.556,y=0.058,zoneID=14771}},ends={{npcID=219400,x=0.556,y=0.058,zoneID=14771}},coords={x=0.556,y=0.058,source="quest_giver",zoneID=14771},questType="standard"},
[79529] = {id=79529,name="Forcing My Hand",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,description="I do not know if Ardgrin merely intended to sabotage me or if he wanted to force a confrontation. Either way, a confrontation he will have. I believe this situation can be rectified peacefully, but I cannot do it as the Councilward. Steelvein has never appeared in the stone, but he must now. I will parlay with Ardgrin in the Deeps and this situation will be concluded. I would have you accompany me, but there are some things I want you to know before that. Help me prepare and I will speak with you.",starts={{npcID=219400,x=0.556,y=0.058,zoneID=14771}},ends={{npcID=219475,x=0.556,y=0.056,zoneID=14771}},coords={x=0.556,y=0.058,source="quest_giver",zoneID=14771},questType="standard"},
[79530] = {id=79530,name="Bad Business",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14795,description="I have not been to the Deeps since their machines shut down. Obstorn will have to guide us to Ardgrin's depot. Once there, I will attempt a conversation. If Ardgrin is not amenable, which I suspect will be the case, we will respond with equal force. Our goal is to bring him back into the fold, not to beat him into submission. Ruling by fear only breeds resentment. We will meet you in the Deeps. Come swiftly--and, of course, speak of this to no one.",starts={{npcID=219475,x=0.556,y=0.056,zoneID=14771}},ends={{npcID=220192,x=0.424,y=0.24,zoneID=14795}},coords={x=0.556,y=0.056,source="quest_giver",zoneID=14771},questType="standard"},
[79532] = {id=79532,name="Tinker, Tailor, Soldier, Spider",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14753,description="I must thank you again for rescuing little Spindle from her predicament, my morsel. As a reward for your work, I would like to let you take loom and direct the weave of my newest tapestry. Meesk the Venomtongue threatens my weave-rats. He slanders my Queen. And he lends creedence to Ansurek's campaign of misinformation without a single thought to the consequences. I believe it is time that I sent Meesk and his ilk a message. Go into the city and find out as much as you can about our 'Venomtongue.'",starts={{npcID=207471,x=0.556,y=0.438,zoneID=14752}},ends={{npcID=227428,x=0.534,y=0.692,zoneID=14752},{npcID=227428,x=0.62,y=0.126,zoneID=14753},{npcID=227428,x=0.63,y=0.118,zoneID=14753}},coords={x=0.556,y=0.438,source="quest_giver",zoneID=14752},questType="standard"},
[79538] = {id=79538,name="Smelly Shrubberies",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="Jenni here says she's got some creepers attackin' the goblins. I haven't seen any myself, but I do smell opportunity! We've got our own anti-creeper perfume. It's the same recipe we use for the incense around town. Rub it on, and everything stays away! I'm sure we can sell some to the goblins. But I'm out of materials--smellsage branches, specifically. If you gather some for me, I'll cut you in on the profits!",starts={{npcID=216996,x=0.778,y=0.628,zoneID=14752}},ends={{npcID=216996,x=0.778,y=0.628,zoneID=14752}},coords={x=0.778,y=0.628,source="quest_giver",zoneID=14752},questType="standard"},
[79539] = {id=79539,name="Electrifying!",level=78,requiredLevel=78,faction="none",expansion=10,zoneID=14752,description="You wanna help the Venture Company? And you don't mind being disposable? Okay, listen up. When we moved in here, there were no monsters in town. But now we're finding dead workers, chewed up. It's bad for business. Fortunately, I've got a way to make money off this: an electrocution helmet. I call it my Debugger Hat . Take the latest model for a test run outside town. Kill the bugs. The niffen will see you, see that Debugger Hat at work, and know it's got good reviews.",starts={{npcID=216994,x=0.778,y=0.628,zoneID=14752}},ends={{npcID=216994,x=0.778,y=0.628,zoneID=14752}},coords={x=0.778,y=0.628,source="quest_giver",zoneID=14752},questType="standard"},
[79540] = {id=79540,name="The Party's Over",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="Nope, nope, nope! Look, I'm used to dealing with the additives in our swimming hole and keeping things at \"marginally safe\" levels, but spiders emerging to chew us to death? That's a hard pass from me. This is OUR place, why are they buggin' us?",starts={{npcID=217402,x=0.776,y=0.596,zoneID=14752}},ends={{npcID=216996,x=0.778,y=0.628,zoneID=14752}},coords={x=0.776,y=0.596,source="quest_giver",zoneID=14752},questType="standard"},
[79541] = {id=79541,name="Burn It With Fire",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="So the goblins removed the incense the niffen used to keep those creepy pests out... because it smelled bad? Honestly, I'm not surprised. Maybe we can show them that they need to work together. Leading by example! Here, I'll lend you a flamethrower. I know mine works, without weird... chicken-like effects. Head in, clear out the nests, and put the right incense back in there!",starts={{npcID=217029,x=0.778,y=0.628,zoneID=14752}},ends={{npcID=216994,x=0.778,y=0.628,zoneID=14752}},coords={x=0.778,y=0.628,source="quest_giver",zoneID=14752},questType="standard"},
[79542] = {id=79542,name="The Councilward's Summons",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14795,description="Councilward Merrix requests your presence in his office. He received the documents you left and would like to discuss the Steelvein situation with you further. Saradi regards you as if she is unimpressed. She also seems to be an earthen of few words.>",starts={{npcID=225426,x=0.46,y=0.474,zoneID=14771},{npcID=225426,x=0.474,y=0.326,zoneID=14795}},ends={{npcID=217069,x=0.552,y=0.062,zoneID=14771}},coords={x=0.46,y=0.474,source="quest_giver",zoneID=14771},questType="standard"},
[79543] = {id=79543,name="Dornogal's Benefactor",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,description="You are in a unique position, . A position to learn. You met those who would bring this \"Bender of Edicts\" to justice, but what of the people of Dornogal? What do the earthen think of this Steelvein fellow? Humor me. Take the smuggled goods you intercepted and bring them to their intended recipients. Tell them the items are a gift from a \"mutual friend.\" You might be surprised to learn who benefits from these... illicit deeds.",starts={{npcID=217069,x=0.552,y=0.062,zoneID=14771}},ends={{npcID=217095,x=0.492,y=0.262,zoneID=14771}},coords={x=0.552,y=0.062,source="quest_giver",zoneID=14771},questType="standard"},
[79544] = {id=79544,name="Security Through Trade",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,description="If we're to solve this quarrel between Steelvein and Ardgrin amicably, then we'll need to make some new friends. One of Ardgrin's employees, Obstorn, frequents a cinderbrew speakeasy here in Dornogal. Only Machine Speakers may enter it. Even as Councilward, I am not able to access it. However, there are others in the city who can. Bevrusi , a Gundargaz trader, should be able to give you access. If you can grease her palm, she may be able to supply you access.",starts={{npcID=217095,x=0.492,y=0.262,zoneID=14771}},ends={{npcID=217072,x=0.554,y=0.502,zoneID=14771}},coords={x=0.492,y=0.262,source="quest_giver",zoneID=14771},questType="standard"},
[79545] = {id=79545,name="The Market Reeve of the Forgegrounds",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,description="I've heard liquid opal tastes remarkable but no matter how often I peruse the auctions here, it's never for sale. It's quite rare. Luckily for you, there is one person who can find the stuff. Vokgret , the market reeve of the Forgegrounds. Nothing circulates in the city's flow of trade without her knowledge. I don't often try to do business with one as... connected as her. But you'll have no qualms about it, I'm sure! At this hour, you'll find her over by the inn.",starts={{npcID=217072,x=0.554,y=0.502,zoneID=14771}},ends={{npcID=217091,x=0.452,y=0.488,zoneID=14771}},coords={x=0.554,y=0.502,source="quest_giver",zoneID=14771},questType="standard"},
[79546] = {id=79546,name="The Machine Speakeasy",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,description="Machine Speakers are odd and secretive units, some prone to paranoia. Even so, the grievance they have against Steelvein must be smoothed over. As you have seen in the Forgegrounds, their quarrel with a single smuggler has put the entire city at risk. As Councilward, I will not stand for it. Let us go talk to Ardgrin's employee, Obstorn, and see if he can deliver a diplomatic message to his overseer in the Deeps. I will meet you in the tunnels.",starts={{npcID=217097,x=0.604,y=0.332,zoneID=14771}},ends={{npcID=219566,x=0.62,y=0.384,zoneID=14771}},coords={x=0.604,y=0.332,source="quest_giver",zoneID=14771},questType="standard"},
[79552] = {id=79552,name="Hot Wax",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14717,description="Oh. Fire bees bit bigger than Janky expect. Look mean. Other hives meaner, though. This best spot. You go grab wax. Janky stay here to...supervise. Yes!",starts={{npcID=219674,x=0.72,y=0.42,zoneID=14717}},ends={{npcID=219674,x=0.72,y=0.42,zoneID=14717}},coords={x=0.72,y=0.42,source="quest_giver",zoneID=14717},questType="standard"},
[79553] = {id=79553,name="A Natural Remedy",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="We stabilized most of the injured. But many of the earthen you saved need more help. Nerubians often fight with corrosive poisons that eats away even our stone bodies. Fungarian flesh has long been used by our healers for its medicinal powers. The fungarian takeover of the quarry is one unexpected boon to our situation, one we will adapt to. Adelgonn looks grimly proud.> One we will adapt to. As the Unbound always do. But I can't leave Ebona's side. Will you help me?",starts={{npcID=217879,x=0.418,y=0.726,zoneID=14717}},ends={{npcID=217879,x=0.418,y=0.726,zoneID=14717}},coords={x=0.418,y=0.726,source="quest_giver",zoneID=14717},questType="standard"},
[79554] = {id=79554,name="Holy Hydrocarbons",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="These devotional candles might be of interest to Janky the kobold candlesmith in Gundargaz.",ends={{npcID=216598,x=0.476,y=0.332,zoneID=14795}},questType="standard"},
[79555] = {id=79555,name="Deep Wax Galactic",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14752,description="While sourcing it may not be pleasant, this waxy substance seems like it might make a fine candle. Janky the candlesmith in Gundargaz might be interested in this.",ends={{npcID=216598,x=0.476,y=0.332,zoneID=14795}},questType="standard"},
[79556] = {id=79556,name="On the Job Training",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="Stoneheads use steam to run whole place. Have lava, have water, make sense. Repairs not going well, we hear. No new parts from factory. \"Against rules\" to use scrap, been told. A lot. Help get old machines work. We watch, learn. Maybe not get yelled at for helping.",starts={{npcID=217131,x=0.472,y=0.318,zoneID=14795}},ends={{npcID=217131,x=0.472,y=0.318,zoneID=14795}},coords={x=0.472,y=0.318,source="quest_giver",zoneID=14795},questType="standard"},
[79559] = {id=79559,name="The Verdigrease Knight",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,description="Think you brave? Been looking for brave, but not find much. Not sure you count, look like tenderfoot who run home to granny if scrape knee. How about way to prove it? You hit me as hard as can. Try kill me. If I not dead, then I get kill you, later. Not look like it take more than one chop for you. Deal?",starts={{npcID=230841,x=0.68,y=0.804,zoneID=14795}},ends={{npcID=218864,x=0.668,y=0.786,zoneID=14795}},coords={x=0.68,y=0.804,source="quest_giver",zoneID=14795},questType="standard"},
[79561] = {id=79561,name="Lord of the Giants",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,description="Can tell you not new to questing. Fell many beasts in your time, am sure, like good knight must. Greasebaddaden , king of giant slimes, lair nearby. Perfect chance to prove valor to court! Has giant fork jammed in head, can't miss. You know what do.",starts={{npcID=218866,x=0.668,y=0.786,zoneID=14795}},ends={{npcID=218866,x=0.668,y=0.786,zoneID=14795}},coords={x=0.668,y=0.786,source="quest_giver",zoneID=14795},questType="standard"},
[79563] = {id=79563,name="Lady of the Lake",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,description="Shown great bravery. Humbility. Honor. Would make good Knight of Brown Table. Only task left now is most sacred. Beseech Lady of Lake for blessing. She will judge whether worthy or not. Lake in back of cave. More pond, really, but no tell her that. Puddle Lady not have same ring.",starts={{npcID=218837,x=0.668,y=0.784,zoneID=14795}},ends={{npcID=218837,x=0.668,y=0.784,zoneID=14795}},coords={x=0.668,y=0.784,source="quest_giver",zoneID=14795},questType="standard"},
[79564] = {id=79564,name="The Verdigrease Knight Returns",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,description="Am back, as promise. Hear you now brave knight. Ready fulfill your end of oath? My turn strike YOU down. Kneel.",starts={{npcID=216566,x=0.668,y=0.786,zoneID=14795}},ends={{npcID=216566,x=0.668,y=0.786,zoneID=14795}},coords={x=0.668,y=0.786,source="quest_giver",zoneID=14795},questType="standard"},
[79565] = {id=79565,name="Janky Candles",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="With new candle almost ready, now all need is to set up stall! Bring quality candle at good price to people! That Janky guarantee. Only problem is not have stall. You talk to Bosh in Gun-dar-ghaz for me? He have everything we need. May need barter, but you talk good! Make him give parts. Meet you down there!",starts={{npcID=219674,x=0.72,y=0.42,zoneID=14717}},ends={{npcID=216598,x=0.476,y=0.332,zoneID=14795}},coords={x=0.72,y=0.42,source="quest_giver",zoneID=14717},questType="standard"},
[79574] = {id=79574,name="The Second Front",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="Our reinforcements are already inbound. These spiders just decided where our next wall will go. Clear a landing zone for General Steelstrike .",starts={{npcID=217133,x=0.294,y=0.416,zoneID=14752}},ends={{npcID=212076,x=0.276,y=0.45,zoneID=14752}},coords={x=0.294,y=0.416,source="quest_giver",zoneID=14752},questType="standard"},
[79579] = {id=79579,name="That Airspace is Mine(d)!",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="Our advantage is air superiority. The nerubians are threatening that with their mines. Your mount is more maneuverable than our skiffs. Get in the air and take those mines out. I will deploy what resources I can to provide you some blessings to improve your capabilities.",starts={{npcID=212076,x=0.276,y=0.45,zoneID=14752}},ends={{npcID=212076,x=0.276,y=0.45,zoneID=14752}},coords={x=0.276,y=0.45,source="quest_giver",zoneID=14752},questType="standard"},
[79580] = {id=79580,name="Offensive Counter",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="I will not yield this ground. Get out there and kill anything with more than two legs!",starts={{npcID=212076,x=0.276,y=0.45,zoneID=14752}},ends={{npcID=212076,x=0.276,y=0.45,zoneID=14752}},coords={x=0.276,y=0.45,source="quest_giver",zoneID=14752},questType="standard"},
[79625] = {id=79625,name="Not Quite Dead",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="I am General Anub'azal . I loathe having little bipeds like you in the Siegehold. However, that is no longer up to me. Zev'kall is pushing me out of my own military stronghold, and collecting overcrawlers to boot! The Queen has deemed him High General, but he is unnatural, warped, and unfit. This will not stand! I have decided to use you and your kind against Zev'kall. And yes, you will get something out of it. Search that rubbish pile there. You will see.",starts={{npcID=217330,x=0.454,y=0.198,zoneID=14752}},ends={{npcID=217330,x=0.454,y=0.198,zoneID=14752}},coords={x=0.454,y=0.198,source="quest_giver",zoneID=14752},questType="standard"},
[79627] = {id=79627,name="Wine and Die",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14753,description="I can see it now, morsel. The pattern of our newest weave is laid bare before my mind. Meesk is well-guarded. He believes himself to be safe. That is where his weakness lies. Go to the city. Procure a bottle of his favorite drink and present it to him as a gift from your benefactor. Once he is sufficiently wooed by your affable charms, bring him to the High Hollows for his well-earned reward. I trust you, . And if you lay our threads out properly, I can guarantee you quite the show.",starts={{npcID=227428,x=0.534,y=0.692,zoneID=14752},{npcID=227428,x=0.62,y=0.126,zoneID=14753},{npcID=227428,x=0.63,y=0.118,zoneID=14753}},ends={{npcID=216298,x=0.628,y=0.226,zoneID=14753}},coords={x=0.534,y=0.692,source="quest_giver",zoneID=14752},questType="standard"},
[79630] = {id=79630,name="Searching the Web",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14753,description="Oh, thank the hollows! You look like someone that can help. It's just horrible! Terrible! A tragedy! My husband has gone missing! We were just wedded yesterday! It was such a wonderful ceremony... But when we were to retire for the evening, he disappeared. Please, could you find him and bring him home to me?",starts={{npcID=217356,x=0.64,y=0.16,zoneID=14753}},ends={{npcID=217355,x=0.478,y=0.132,zoneID=14753}},coords={x=0.64,y=0.16,source="quest_giver",zoneID=14753},questType="standard"},
[79631] = {id=79631,name="Klaskin's Great Escape",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14753,description="Silken threads, I'm saved! It's incredibly important that I make it back home without my wife seeing me. I took off after our wedding last night, and if she sees me, she's going to kill me! If the guards catch me, they'll surely alert Arax'ne . Will you help me avoid the guards and get back home?",starts={{npcID=217355,x=0.478,y=0.132,zoneID=14753}},ends={{npcID=217356,x=0.64,y=0.16,zoneID=14753}},coords={x=0.478,y=0.132,source="quest_giver",zoneID=14753},questType="standard"},
[79633] = {id=79633,name="The Weaver's Legacy",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14752,description="Oh, this is exciting! A meeting with someone who commands even overcrawlers to do their bidding. I have been waiting for a moment like this. Ah, I won't have to go too far though, will I? I am meant to host some up-and-coming Sureki socialites for dinner later tonight.",starts={{npcID=216298,x=0.628,y=0.226,zoneID=14753}},ends={{npcID=207471,x=0.556,y=0.438,zoneID=14752}},coords={x=0.628,y=0.226,source="quest_giver",zoneID=14753},questType="standard"},
[79641] = {id=79641,name="Wipe Away Their Smiles",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="The kobyss grow bold if they feel they can defile our Veneration Grounds. I think we should collect their teeth to wipe the smiles off their faces. Come! My brother and I will cleanse our lands from this filth. Try to keep up!",starts={{npcID=217424,x=0.29,y=0.618,zoneID=14838}},coords={x=0.29,y=0.618,source="quest_giver",zoneID=14838},questType="standard"},
[79642] = {id=79642,name="Stave Them Off",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="Without their magical weapons, the kobyss casters won't be able to use their foul necromancy. Steal their staves so we might toss them into the Sacred Flame and be done with them.",starts={{npcID=217426,x=0.31,y=0.556,zoneID=14838}},coords={x=0.31,y=0.556,source="quest_giver",zoneID=14838},questType="standard"},
[79643] = {id=79643,name="Dreaded Dreadfang",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="My brother and I have dealt heavy blows to the kobyss, , but you could have done more. The most foul kobyss of them all has yet to taste my blade. If we take out their leader, the rest will flee back into the waters from which they came. Let's take the head of Dreadfang!",ends={{npcID=217424,x=0.29,y=0.618,zoneID=14838}},questType="standard"},
[79644] = {id=79644,name="Go to the Priory",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="I... I do not have the words. Theleon... I will take h-his body. They will know what to do at the priory. Oh, brother... It was not supposed to end like this...",starts={{npcID=217424,x=0.29,y=0.618,zoneID=14838}},ends={{npcID=217398,x=0.396,y=0.372,zoneID=14838}},coords={x=0.29,y=0.618,source="quest_giver",zoneID=14838},questType="standard"},
[79645] = {id=79645,name="Sweet-Sting Infestation",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="Poor Theleon. I gave him some of his first lessons in combat. I'll see him to his final pyre. But first, you. I've been trying to fight back an infestation of sweet-stings harassing our wine-making operations. I need someone else to finish them off while I tend to Theleon's remains. Be fast and clever and bring me some of their venom as you take care of things. We'll turn that into a poison for the nesting sites and be done with the nuisance.",starts={{npcID=217398,x=0.396,y=0.372,zoneID=14838}},ends={{npcID=217398,x=0.396,y=0.372,zoneID=14838}},coords={x=0.396,y=0.372,source="quest_giver",zoneID=14838},questType="standard"},
[79646] = {id=79646,name="Memorial Wine",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="Oh, Theleon. He always did follow his big brother into anything. While we prepare Theleon for his final rest, would you please help Brother Abealard with a batch of Memorial Wine for the service?",starts={{npcID=217398,x=0.396,y=0.372,zoneID=14838}},ends={{npcID=217398,x=0.396,y=0.372,zoneID=14838}},coords={x=0.396,y=0.372,source="quest_giver",zoneID=14838},questType="standard"},
[79647] = {id=79647,name="Burning Reflections",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="Sybaestan could use your support now. His little brother was his best friend. Only death could separate them... and it has. He is not taking it well. It is customary to burn written memories of the deceased. By committing them to the flames, we let go our heartache and let the warmth of memory heal us. It is a bittersweet time. You were with Theleon at the end, too. That might help Sybaestan.",starts={{npcID=217398,x=0.396,y=0.372,zoneID=14838}},ends={{npcID=217398,x=0.396,y=0.372,zoneID=14838}},coords={x=0.396,y=0.372,source="quest_giver",zoneID=14838},questType="standard"},
[79648] = {id=79648,name="Missing Somebody",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="Theleon was a good one, but now we must commit his body to the Flames. Sybaestan is in no shape to bear his brother. Would you collect his remains from among those others awaiting their final rest?",starts={{npcID=217398,x=0.396,y=0.372,zoneID=14838}},ends={{npcID=217398,x=0.396,y=0.372,zoneID=14838}},coords={x=0.396,y=0.372,source="quest_giver",zoneID=14838},questType="standard"},
[79649] = {id=79649,name="Sacred Flame Inquisition",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="All the dead are missing? How can that be? They were all laid out in preparation for their pyres. Who would want to move them? Someone must have seen something. Go ask anyone in the area who might have seen something and I'll go talk to some of the upper clergy. We'll get to the bottom of this and return our dead so they can be properly tended to.",starts={{npcID=217398,x=0.396,y=0.372,zoneID=14838}},ends={{npcID=217398,x=0.396,y=0.372,zoneID=14838}},coords={x=0.396,y=0.372,source="quest_giver",zoneID=14838},questType="standard"},
[79650] = {id=79650,name="Priory of the Sacred Flame: A Brother's Grief",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14954,description="I fear that the Prioress may be behind our missing dead-- and our missing baron. Sybaestan has disappeared as well and I don't believe in coincidences. She and Sybaestan have taken our recent losses hard. I fear what their overwhelming grief might be doing to their souls. We must confront them and bring them back to sanity... If we can. Tell General Steelstrike what you have learned. We might need her backup. I'll be waiting for you here.",starts={{npcID=217398,x=0.396,y=0.372,zoneID=14838}},ends={{npcID=217398,x=0.396,y=0.372,zoneID=14838}},coords={x=0.396,y=0.372,source="quest_giver",zoneID=14838},questType="dungeon"},
[79651] = {id=79651,name="Trade Partners",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="Have you visited Mmarl? It's a trade town to the southeast of here. Try some of Corby's barbeque while you're over there!",starts={{npcID=223754,x=0.558,y=0.436,zoneID=14752}},ends={{npcID=217029,x=0.778,y=0.628,zoneID=14752}},coords={x=0.558,y=0.436,source="quest_giver",zoneID=14752},questType="standard"},
[79655] = {id=79655,name="Hallowfall Arathi",level=70,requiredLevel=70,faction="none",expansion=10,questType="standard"},
[79659] = {id=79659,name="The Severed Threads",level=70,requiredLevel=70,faction="none",expansion=10,questType="standard"},
[79679] = {id=79679,name="Muddled Mind in the Mine",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="The workers said they saw Munderut near the back of the mining area. Please find him and tell him that I said he needs to report back in. He might not remember me, or that I am his fused. Tell him to look down at his chest, at the medallion he wears. His memory of our time together fades in and out these days, but the medallion tells of our story and bond forever.",starts={{npcID=215208,x=0.51,y=0.148,zoneID=14795}},ends={{npcID=215209,x=0.51,y=0.148,zoneID=14795}},coords={x=0.51,y=0.148,source="quest_giver",zoneID=14795},questType="standard"},
[79680] = {id=79680,name="Pipe Patching",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="Earthquake do number on old pipes. Many start leaking steam everywhere. Especially ones too tall to reach. Fourman Grimes points up to the pipes stretching from Gundargaz to the surface.> Stoneheads not have \"approved replacements,\" but we not have time wait. Take glue and seal leaks with flappy-flying thing. Made of only best bugs, boiled myself. Will do for today.",starts={{npcID=217131,x=0.472,y=0.318,zoneID=14795}},ends={{npcID=217131,x=0.472,y=0.318,zoneID=14795}},coords={x=0.472,y=0.318,source="quest_giver",zoneID=14795},questType="standard"},
[79681] = {id=79681,name="Plumber Power",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="Not all leaky pipes accessible from outside. Some inside tunnels run all under Gundargaz. Tunnels small for stoneheads, but kobolds love tunnel! Just need someone to show layout. You, someone. Check with crew boss if have problems. He help go over maps.",starts={{npcID=217131,x=0.472,y=0.318,zoneID=14795}},ends={{npcID=217131,x=0.472,y=0.318,zoneID=14795}},coords={x=0.472,y=0.318,source="quest_giver",zoneID=14795},questType="standard"},
[79682] = {id=79682,name="Critical Pressure!",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="Pressure still too high! Something else wrong, not just old pipes. Open main release before something burst. Not have time for manuals. Consequences for deal with later!",starts={{npcID=217131,x=0.472,y=0.318,zoneID=14795}},ends={{npcID=217131,x=0.472,y=0.318,zoneID=14795}},coords={x=0.472,y=0.318,source="quest_giver",zoneID=14795},questType="standard"},
[79683] = {id=79683,name="Home Is Where the Candle Is",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="Exciting to have new place call home, . Not quite settled, though. We not know Gundargaz. Gundargaz not know us. Time to fix both! Find out how help here. Teach new friends about us. Kobolds clever and friendly, so should be easy! Start with help three kobolds. Fourman Grimes want get to work right away. She very task oriented. Granny Scribbles tell you lot about kobold culture. And Janky want set up new business in town, sell candle to Gundargaz.",starts={{npcID=213152,x=0.47,y=0.34,zoneID=14795},{npcID=222803,x=0.47,y=0.332,zoneID=14795}},ends={{npcID=213152,x=0.47,y=0.34,zoneID=14795},{npcID=222803,x=0.47,y=0.332,zoneID=14795}},coords={x=0.47,y=0.34,source="quest_giver",zoneID=14795},questType="standard"},
[79686] = {id=79686,name="Concerning Fungarians",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="Log Entry: 235-18-7 Date: Fabrication Quarter Cycle Observation: Fungarians exhibit accelerated growth and increased territorial aggression. Spore dispersal seems to have quadrupled compared to previous recorded rates.",starts={{npcID=428135,x=0.358,y=0.771,zoneID=14717}},ends={{npcID=218729,x=0.414,y=0.714,zoneID=14717}},coords={x=0.358,y=0.771,source="quest_giver",zoneID=14717},questType="standard"},
[79691] = {id=79691,name="Monsters in the Dark",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="The local quarry was an active source of clay and ore for us until the fungarians took over some time ago. We were worried about the fungarians encroaching upon the village, but there's something more. Multiple sightings of a creature much larger than our native wildlife have been reported at night. Combined with villager Modhina's disappearance, I fear this is no coincidence. She visited the quarry recently and hasn't returned. We would be in your debt if you searched the tunnels.",starts={{npcID=216094,x=0.422,y=0.732,zoneID=14717}},ends={{npcID=216094,x=0.422,y=0.732,zoneID=14717}},coords={x=0.422,y=0.732,source="quest_giver",zoneID=14717},questType="standard"},
[79692] = {id=79692,name="Buried, Not Forgotten",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="Several suns ago, my friend Modhina ventured into the quarry cave. She wanted to find rare ore for Hreka, to help her craftsmanship. Modhina was excited, I remember. A rare feeling for earthen. She hasn't returned. The fungarians prevent us from searching the area. It would mean a great deal to us if you could look for her. I didn't know it was possible to spend so much of the day thinking about what if's.",starts={{npcID=216094,x=0.422,y=0.732,zoneID=14717}},ends={{npcID=216094,x=0.422,y=0.732,zoneID=14717}},coords={x=0.422,y=0.732,source="quest_giver",zoneID=14717},questType="standard"},
[79701] = {id=79701,name="The Cavalry is Here",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="Baelgrim quakes with fury.> These cursed nerubians. Attacking a triage site! So many wounded and defenseless... and yet, it looks like you outlanders are putting up a fight! Let's grind every last one of the bugs back into the ground.",starts={{npcID=217766,x=0.564,y=0.48,zoneID=14717}},ends={{npcID=217766,x=0.564,y=0.48,zoneID=14717}},coords={x=0.564,y=0.48,source="quest_giver",zoneID=14717},questType="standard"},
[79703] = {id=79703,name="Hope, An Anomaly",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="Hreka looks through the things you retrieved, one by one.> So you risked your life to find our friend. Modhina is gone, then. Her notes are about the rare ore from the cave. Melted down, it becomes a beautiful glaze for pottery. What can I do? I'm no fighter. I can't avenge her. Besides, her body has already been reclaimed by the earth. That much is certain by the state of her memory gem fragment. What can I do now, but make a pot? Will you help me?",starts={{npcID=217961,x=0.418,y=0.708,zoneID=14717}},ends={{npcID=217961,x=0.418,y=0.708,zoneID=14717}},coords={x=0.418,y=0.708,source="quest_giver",zoneID=14717},questType="standard"},
[79710] = {id=79710,name="A Fin of Every Kind",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="Oh! My! LEGS! You're perfect! Yes! You're a perfect, little, unassuming biped for my work. Alchemy is my trade, and an alchemist is only as good as their ingredients. See these kobyss below? I've been camped out here for weeks observing them. They seem tougher than average kobyss. My conclusion? They must be made of stronger stuff! And I want that stuff! Here's a sack. Fill it up! Fill it up with their innards! As much as you can carry!",starts={{npcID=217565,x=0.6,y=0.662,zoneID=14752}},ends={{npcID=217565,x=0.6,y=0.662,zoneID=14752}},coords={x=0.6,y=0.662,source="quest_giver",zoneID=14752},questType="standard"},
[79711] = {id=79711,name="That's Pretty Gross",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="familiar-looking appendage from the silt. It doesn't seem particularly kobyss, but perhaps a unique specimen will earn you an increased reward from Al'kubian .>",starts={{npcID=443995,x=0.597,y=0.692,zoneID=14752}},ends={{npcID=217565,x=0.6,y=0.662,zoneID=14752}},coords={x=0.597,y=0.692,source="quest_giver",zoneID=14752},questType="standard"},
[79713] = {id=79713,name="Moonlight Gutter Swim",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="An Ascended's leg... A kobyss tribe feasting one or two dozen trueborns or skitterlings, perhaps even a sageform such as myself... But an Ascended is a different story. Let us approach this as intellectuals, and use the tools at our disposal to collect more data. What tools do we have? You. You are the tool. An intellectual tool of kobyss disposal. Dive into the lake's depths. Slay the largest of these creatures or their pets. And of course, bring me their innards.",starts={{npcID=217565,x=0.6,y=0.662,zoneID=14752}},ends={{npcID=217565,x=0.6,y=0.662,zoneID=14752}},coords={x=0.6,y=0.662,source="quest_giver",zoneID=14752},questType="standard"},
[79714] = {id=79714,name="Rescuing the Food",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=5723,description="While awaiting your innards-bestowing return, I observed some fascinating activity below. A consistent train of kobyss are dragging the limp bodies of my kin from the lake's waters and westerly into their cavern. My conclusion? Nerubians are being hunted and stored in the lake for consumption by these beasts. It's not so much for research than it is for civic duty, but I would reward you might be able to save from their fate.",starts={{npcID=217565,x=0.6,y=0.662,zoneID=14752}},ends={{npcID=217565,x=0.6,y=0.662,zoneID=14752}},coords={x=0.6,y=0.662,source="quest_giver",zoneID=14752},questType="standard"},
[79715] = {id=79715,name="Grand, Gutsy Solutions",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="I require one final piece of data. These beasts think. They organize. They coordinate. To be characteristically honest, there's nothing worse than an amphibian with an abacus. My final task for you: Bring me the brain of the biggest beast. I need it fresh, and preferably non-liquified. And, you know, perhaps it will slow them down as well.",starts={{npcID=217565,x=0.6,y=0.662,zoneID=14752}},ends={{npcID=217565,x=0.6,y=0.662,zoneID=14752}},coords={x=0.6,y=0.662,source="quest_giver",zoneID=14752},questType="standard"},
[79716] = {id=79716,name="The History Beneath Us",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="The titan console is a huge find. And look at these ruins! There has tae be more here! But goin' out into the site is dangerous. Accordin' to Brinthe, now that the titan vault has been unearthed, elementals have come. Elementals dunnae like order magic, an' titan relics just ooze the stuff. They're on a rampage! Can ye go out there an' get some relics back from the elementals? We need tae preserve what we can!",starts={{npcID=225453,x=0.616,y=0.702,zoneID=14717}},ends={{npcID=225453,x=0.616,y=0.702,zoneID=14717}},coords={x=0.616,y=0.702,source="quest_giver",zoneID=14717},questType="standard"},
[79717] = {id=79717,name="Means of Ingress",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14753,description="Ah, look at you! Just the sort of rogue element I need. My name is Ar'syn , and I am something of a connoisseur for the fine arts and histories of our people. It is my intent to enter the Royal Preservatory--that's that large enclave just over there-- and rob it blind. But gracious, the guards will never let me get close enough to survey their security! If only I had someone to help me find a somewhat more subtle way into the building. Ar'syn looks at you meaningfully.>",starts={{npcID=217692,x=0.296,y=0.188,zoneID=14753}},ends={{npcID=217692,x=0.296,y=0.188,zoneID=14753}},coords={x=0.296,y=0.188,source="quest_giver",zoneID=14753},questType="standard"},
[79718] = {id=79718,name="Skeins Street Irregulars",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14753,description="I would like nothing more than to go in and take a few of these pompous Sureki royalists out. It would make our infiltration that much easier, and it would serve them right for trampling upon our history. But I cannot get close without bringing a whole host of guards down upon the Skeins. You, though? No one will bat an eye at wanton violence if it comes from an overcrawler. Why not get in there and thin them out a bit? Oh, don't give me that look. You were going to do it anyway.",starts={{npcID=217692,x=0.296,y=0.188,zoneID=14753}},ends={{npcID=217692,x=0.296,y=0.188,zoneID=14753}},coords={x=0.296,y=0.188,source="quest_giver",zoneID=14753},questType="standard"},
[79721] = {id=79721,name="Fire in the Hole",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="Who are you? But of course, another outlander! I'm Wenbrandt , tamer of cinderbees and creator of cinderbrew. Wenbrandt squares himself up as if you should be impressed.> I had brought barrels of cinderbrew to help the injured. I thought drinking it would ease their pain, but for most it just caused more... burning... pain... I refuse to let my brew go to waste. Maybe it can be weaponized. The nerubians are just bugs after all--organic and flammable. This burrow here is a perfect test subject.",starts={{npcID=212295,x=0.566,y=0.52,zoneID=14717}},ends={{npcID=212295,x=0.566,y=0.52,zoneID=14717}},coords={x=0.566,y=0.52,source="quest_giver",zoneID=14717},questType="standard"},
[79723] = {id=79723,name="Repatriation by Subtraction",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14753,description="Ansurek and her ilk are so short-sighted. They think that by filling our museum with trophies of their recent conquests instead of relics of our own history, we will be less inclined to remember where we came from. Well, they are probably right--in the long term, at least. History has a habit of bending towards the voice of its teller. But that is where we come in, . Those relics that the Sureki forces stole? It's time to steal them back.",starts={{npcID=217692,x=0.296,y=0.188,zoneID=14753}},ends={{npcID=217692,x=0.296,y=0.188,zoneID=14753}},coords={x=0.296,y=0.188,source="quest_giver",zoneID=14753},questType="standard"},
[79724] = {id=79724,name="A Titanic Expedition!",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="Our merchant friend told us about some small islands off the northeast coast called \"The Three Shields.\" Apparently, there was a lot of titan activity there long ago. To me, the \"activity\" sounded like titan research and development. Exciting stuff! Tuberros and I are going there to check it out. Tharessa, my new Algari Expedition trainee, is coming along to see true professionals at work. Care to join us?",starts={{npcID=217763,x=0.588,y=0.282,zoneID=14717}},ends={{npcID=217657,x=0.778,y=0.302,zoneID=14717}},coords={x=0.588,y=0.282,source="quest_giver",zoneID=14717},questType="standard"},
[79725] = {id=79725,name="Not a Heating Pack",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="Tharessa has done some reconnaissance for us and found the gorlocs are digging up artifacts and... cuddling with them. I think it means that the artifacts emit heat? Maybe that means some artifacts are still functioning? Imagine--the titans created technology to shape worlds, and now a fish uses it to warm their fins. Hah! The gorlocs won't give them up, and I don't want to be a Rannan-kabob either. I hate to ask because they just want to be warm, but could you do something about them?",starts={{npcID=217657,x=0.778,y=0.302,zoneID=14717},{npcID=217828,x=0.78,y=0.302,zoneID=14717}},ends={{npcID=217828,x=0.78,y=0.302,zoneID=14717}},coords={x=0.778,y=0.302,source="quest_giver",zoneID=14717},questType="standard"},
[79726] = {id=79726,name="\"Cataloguing\"",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="As ya know, we are here to collect some titan shinies, artifacts, whatever! And Rannan thinks the more shinies--er, you know what I mean--the better chance we have figurin' out something about the titans. That'll make Rannan happy, but it'll also ensure I have some extras to take to my store back home. My wife, Perisimona, is waiting for 'em back in Loamm. I can't go back empty handed!",starts={{npcID=217656,x=0.778,y=0.302,zoneID=14717}},ends={{npcID=217656,x=0.778,y=0.302,zoneID=14717}},coords={x=0.778,y=0.302,source="quest_giver",zoneID=14717},questType="standard"},
[79727] = {id=79727,name="Because It's Shiny",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="While these two were ordering you around, I thought I would do something useful and make sure the gorlocs were not going to surprise us here on the beach. None of them seemed interested in us, but then I saw one huge gorloc. It killed off some smaller gorlocs then took off. It had something glowing in its claw though! It had to be an artifact. And it looked like it was working! We've got to get it back. By \"we\" I mean \"you.\" Larger-than-average gorlocs are above my Dragonscale pay grade.",starts={{npcID=217659,x=0.78,y=0.302,zoneID=14717}},ends={{npcID=217659,x=0.78,y=0.302,zoneID=14717}},coords={x=0.78,y=0.302,source="quest_giver",zoneID=14717},questType="standard"},
[79728] = {id=79728,name="It's Probably Nothing",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="You found a buzz orb! ...Er, that's what the niffen call it. I just kind of went with it. It's still in a good condition. Still buzzing, humming, and warm to the touch! I haven't seen one since we were in Zaralek Cavern! , you should see if we can get it to work. I will stand back here, just in case it is, um, not friendly. Nothing to worry about, I'm sure.",starts={{npcID=217828,x=0.78,y=0.302,zoneID=14717}},ends={{npcID=217828,x=0.78,y=0.302,zoneID=14717}},coords={x=0.78,y=0.302,source="quest_giver",zoneID=14717},questType="standard"},
[79729] = {id=79729,name="Educate Yourself",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14753,description="The Relics of Founding have always been the centerpieces of the Preservatory's collection. Together, those four artifacts tell our most reverent tale--that of the founding of Azj-Kahet, and of our people's rejection of our Old Masters. With luck, they will still be inside the Preservatory. Once you are inside, I want you to tamper with the shadecasters in front of each of the relics. Make sure that their messages are heard by anyone nearby--whether they wish to listen or not.",starts={{npcID=217692,x=0.296,y=0.188,zoneID=14753}},ends={{npcID=217692,x=0.296,y=0.188,zoneID=14753}},coords={x=0.296,y=0.188,source="quest_giver",zoneID=14753},questType="standard"},
[79730] = {id=79730,name="Dogged Pursuit",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14753,description="But of course, simply stealing the relics isn't enough. We need to teach the Queen's pet burrow-worms a lesson in futility, or they will simply start the whole process again! That shouting buffoon near the central passage is Rez'kal, a member of Ansurek's personal academic entourage. He's... not very bright, but he makes up for it with enough strength to send either of us through a wall. I'm not inclined to go toe to toe with the big oaf today. Would you mind overmuch doing one last favor for me?",starts={{npcID=217692,x=0.296,y=0.188,zoneID=14753}},ends={{npcID=217692,x=0.296,y=0.188,zoneID=14753}},coords={x=0.296,y=0.188,source="quest_giver",zoneID=14753},questType="standard"},
[79944] = {id=79944,name="Raging Rifts",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="The elementals are coming from inside that cave. We only made it part of the way in before needing to retreat. I could see some flickering within, some strange glowing thing that looked almost like a tear in space from which the elementals poured forth! We managed to close one of these portals, but there are more. I need to stay with Nanthaz. It is up to you now, if you can manage. Destroy the rifts and find their source. I suspect it lies deeper within the cave.",starts={{npcID=223000,x=0.552,y=0.11,zoneID=14795}},ends={{npcID=223000,x=0.552,y=0.11,zoneID=14795}},coords={x=0.552,y=0.11,source="quest_giver",zoneID=14795},questType="standard"},
[79954] = {id=79954,name="Spiders!",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14753,description="Why, hello there, little $pr. You seem like you might be able to assist me. You see, my dear mate Ami'thax fell onto a sharp dagger. Her body was taken to Pillar-nest Xesh, just below where we stand. Xesh is used to dispose of all sorts of bodies that we never speak of again. Unfortunately I have need to speak of Ami'thax, because she had the key to my new High Hollows burrow on her when she died. Dreadful timing, really. Would you go and fetch it? Do beware of the spiders, I need my key.",starts={{npcID=217255,x=0.774,y=0.684,zoneID=14753}},ends={{npcID=217255,x=0.774,y=0.684,zoneID=14753}},coords={x=0.774,y=0.684,source="quest_giver",zoneID=14753},questType="standard"},
[79955] = {id=79955,name="...And Now I'm Arachnophobic",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14753,mapID=2213,description="Who is there? Someone? Did I imagine you? I am Albert . I was a Pathfinder once. Now that I'm blind, I see no path. It seems wrong to call myself Pathfinder Henson. I can hear, though. I can hear them eating. They eat the fresh parts. My eyes. My insides. It hurts all the time. They do not want my rotten pieces. The decayed parts are all I have left. The worst of me. I wasn't alone here, I had fellow Pathfinders. I keep hearing sobbing from the walls. Do you hear them too?",questType="standard"},
[79956] = {id=79956,name="Legs in the Ceiling",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14753,mapID=2213,description="I don't require vengeance on my behalf, but I would like vengeance for all of my friends that were eaten. I didn't think the Horror of Xesh was real, but she is. Xishirra. A shadow of a nightmare, making a brood of monsters while she stays out of reach. The horror is ancient, and beyond us, but we can still make her pay! Pull hard on a web strand if you need to, and deal with whatever comes. We'll escape after some justice is had!",questType="standard"},
[79957] = {id=79957,name="Maggots in your Eyes",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="Albert is no longer alive. All that remains is his head, still full of maggots. Taking him back to the Pathfinders seems like the right thing to do.>",ends={{npcID=211708,x=0.592,y=0.192,zoneID=14752}},questType="standard"},
[79998] = {id=79998,name="Mite Not Right",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14717,description="This not good. Fancy fire bees have mites! Janky seen this before. Hive get infested, good bugs get sucked dry. End bad. Need do something! Blast bees with smoke. Makes bees sleepy but mites hate! When jump off, you squish before they bite bees again.",starts={{npcID=219674,x=0.72,y=0.42,zoneID=14717}},ends={{npcID=219674,x=0.72,y=0.42,zoneID=14717}},coords={x=0.72,y=0.42,source="quest_giver",zoneID=14717},questType="standard"},
[79999] = {id=79999,name="Igniting Hope",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,mapID=2215,description="One dawntower has fallen, but a faint glimmer of hope remains with the smaller keyflame atop the wall. The shattered remnants needed to sustain that light were taken by the nerubians. Gather the remnants from nerubians you slay, and help ignite a beacon of hope!",starts={{npcID=213116,x=0.684,y=0.45,mapID=2215}},ends={{npcID=213116,x=0.684,y=0.45,mapID=2215}},coords={x=0.684,y=0.45,source="quest_giver",mapID=2215},questType="standard"},
[80000] = {id=80000,name="Beebiter",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14717,description="Mites kill fire bees. No good! Janky hate mites. Bite you when not even stealing wax. Not even make wax! Give bees chance. Kill biggest, bite-iest mite before eats more bees.",starts={{npcID=219674,x=0.72,y=0.42,zoneID=14717}},ends={{npcID=219674,x=0.72,y=0.42,zoneID=14717}},coords={x=0.72,y=0.42,source="quest_giver",zoneID=14717},questType="standard"},
[80004] = {id=80004,name="Crab Grab",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,starts={{npcID=424347,x=0.615,y=0.174,zoneID=14838}},ends={{npcID=206150,x=0.632,y=0.294,zoneID=14838},{npcID=206441,x=0.652,y=0.28,zoneID=14838}},coords={x=0.615,y=0.174,source="quest_giver",zoneID=14838},questType="standard"},
[80022] = {id=80022,name="Calling the Stormriders",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,description="I know the Unbound can repair and unblock the Coreway expediently--but I also know the nerubians. If they see an opportunity for an ambush, they will take it. With our backs turned and our focus on the Coreway, we are prime targets. I need to rally my Stormriders and form a perimeter around Dornogal in case of an attack from within or from without. Meet me outside of the Stormperch. I will call upon my troops there.",starts={{npcID=212747,x=0.358,y=0.526,zoneID=14771}},ends={{npcID=212746,x=0.36,y=0.526,zoneID=14771}},coords={x=0.358,y=0.526,source="quest_giver",zoneID=14771},questType="standard"},
[80058] = {id=80058,name="Kobold Kleanup",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="New home little shabby. Not good, full of fun stuff and good bits shabby. Old, everybody died and now it fall apart shabby. We help! Lots of kobolds, now, so we make place presentable for stonehead friends. Make feel like home. You help, too. Grab broom, get going!",starts={{npcID=216568,x=0.478,y=0.354,zoneID=14795}},ends={{npcID=217131,x=0.472,y=0.318,zoneID=14795}},coords={x=0.478,y=0.354,source="quest_giver",zoneID=14795},questType="standard"},
[80082] = {id=80082,name="Back to Gundargaz",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="We may not have overthrown the Candle King, but our work here has surely relieved some of the pressure facing Gundargaz. And it's made us more than a few new allies, as well. Our new friends will not be forgotten, on my word as Speaker. There is a...regrettable amount of available housing in Gundargaz as of late. It will be nice to feel the city come to life again, and we can certainly use the manpower. Shall we bring them home, ?",starts={{npcID=212992,x=0.614,y=0.32,zoneID=14795}},ends={{npcID=218715,x=0.47,y=0.332,zoneID=14795}},coords={x=0.614,y=0.32,source="quest_giver",zoneID=14795},questType="standard"},
[80096] = {id=80096,name="The Shovel in the Stone",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,description="Now, friend, we quest for blade of legend! Whoever pull from stone it stuck in destined for greatness. Only problem is that it very stuck. In very big rock. No idea how even get there, really. Come! We try you hand at fate!",starts={{npcID=218878,x=0.668,y=0.784,zoneID=14795}},ends={{npcID=218878,x=0.668,y=0.784,zoneID=14795}},coords={x=0.668,y=0.784,source="quest_giver",zoneID=14795},questType="standard"},
[80144] = {id=80144,name="The Holey Grail",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,description="Holey Grail , one of very best relics, lost for long time, . Very old, very powerful. Would mean a lot if could find. Set you grand quest for to search for Holey Grail ! Try start with Fishcan . He old as dirt, might know something. Seek him by pools to north-east.",starts={{npcID=218878,x=0.668,y=0.784,zoneID=14795}},ends={{npcID=218878,x=0.668,y=0.784,zoneID=14795}},coords={x=0.668,y=0.784,source="quest_giver",zoneID=14795},questType="standard"},
[80145] = {id=80145,name="The Motherlode",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,mapID=2214,starts={{npcID=230643,x=0.048,y=0.796,mapID=2214}},ends={{npcID=230643,x=0.048,y=0.796,mapID=2214}},coords={x=0.048,y=0.796,source="quest_giver",mapID=2214},questType="standard"},
[80175] = {id=80175,name="The Last Mage",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="I want you to check in on someone. He's a mage... the only one of us who is. All the others died in the crash. He's trying to make a portal to the Empire, so we can get reinforcements and have a way to and from home. We all know it's a lost cause, but he still hasn't given up. Maybe meeting a seasoned traveler like you will give him the reality check he needs. Check on him, will you?",starts={{npcID=215335,x=0.404,y=0.508,zoneID=14838}},ends={{npcID=219135,x=0.488,y=0.644,zoneID=14838}},coords={x=0.404,y=0.508,source="quest_giver",zoneID=14838},questType="standard"},
[80176] = {id=80176,name="Arcane Trickles",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="I've almost got it! I'm making a new kind of teleportation spell to get us back home to the Empire. These crabs might just be the key. They're practically radiating arcane teleportation magic! I need more samples to study. Take this focus, it will let you see traces of the arcane. There aren't many other arcane sources around here, so any you see should lead you straight to the affected crabs!",starts={{npcID=219135,x=0.488,y=0.644,zoneID=14838}},ends={{npcID=219135,x=0.488,y=0.644,zoneID=14838}},coords={x=0.488,y=0.644,source="quest_giver",zoneID=14838},questType="standard"},
[80177] = {id=80177,name="Arcane Experiments",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="This is it! The energy crackling from these crabs is charged with teleportation magic! I just need to extract it and adjust the formula-- I can do this, my new friend! I just need another hand. Help me test this?",starts={{npcID=219135,x=0.488,y=0.644,zoneID=14838}},ends={{npcID=219173,x=0.486,y=0.646,zoneID=14838}},coords={x=0.488,y=0.644,source="quest_giver",zoneID=14838},questType="standard"},
[80178] = {id=80178,name="A Murder Most Foul",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,starts={{npcID=219173,x=0.486,y=0.646,zoneID=14838}},ends={{npcID=219173,x=0.486,y=0.646,zoneID=14838}},coords={x=0.486,y=0.646,source="quest_giver",zoneID=14838},questType="standard"},
[80179] = {id=80179,name="Finding Justice",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,starts={{npcID=219173,x=0.486,y=0.646,zoneID=14838}},ends={{npcID=215335,x=0.404,y=0.508,zoneID=14838}},coords={x=0.486,y=0.646,source="quest_giver",zoneID=14838},questType="standard"},
[80184] = {id=80184,name="Preserving in Battle",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,description="There is much to learn on the battlefield, even in lesser coordinated environments. Go ahead and give it a try.",starts={{npcID=219260,x=0.588,y=0.752,zoneID=14771}},ends={{npcID=219260,x=0.588,y=0.752,zoneID=14771}},coords={x=0.588,y=0.752,source="quest_giver",zoneID=14771},questType="pvp"},
[80185] = {id=80185,name="Preserving Solo",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,description="Battling on your own will build strength and courage. Display your solo capabilities in small battles, then return to me.",starts={{npcID=219260,x=0.588,y=0.752,zoneID=14771}},ends={{npcID=219260,x=0.588,y=0.752,zoneID=14771}},coords={x=0.588,y=0.752,source="quest_giver",zoneID=14771},questType="pvp"},
[80186] = {id=80186,name="Preserving in War",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,description="Partaking in large-scale conflicts will hone your ability to look at the larger picture. Go off and garner that experience, then come back to see me.",starts={{npcID=219260,x=0.588,y=0.752,zoneID=14771}},ends={{npcID=219260,x=0.588,y=0.752,zoneID=14771}},coords={x=0.588,y=0.752,source="quest_giver",zoneID=14771},questType="pvp"},
[80187] = {id=80187,name="Preserving in Skirmishes",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,description="Part of training is repetition. I am told there are others out there like yourself that partake in small-scale skirmishes. Go off and find training partners to battle against, then return to me. Let us see what you can prove, then return to me.",starts={{npcID=219260,x=0.588,y=0.752,zoneID=14771}},ends={{npcID=219260,x=0.588,y=0.752,zoneID=14771}},coords={x=0.588,y=0.752,source="quest_giver",zoneID=14771},questType="pvp"},
[80188] = {id=80188,name="Preserving in Arenas",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,description="Fast paced and coordinated combat is a mighty test for the strongest combatants. Find others to battle alongside you to fight worthy opponents in the arena.",starts={{npcID=219260,x=0.588,y=0.752,zoneID=14771}},ends={{npcID=219260,x=0.588,y=0.752,zoneID=14771}},coords={x=0.588,y=0.752,source="quest_giver",zoneID=14771},questType="pvp"},
[80189] = {id=80189,name="Preserving Teamwork",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,description="The ability to strategize with others to take objectives is key to becoming a strong warrior. Go onto the battlefield, then return to me.",starts={{npcID=219260,x=0.588,y=0.752,zoneID=14771}},ends={{npcID=219260,x=0.588,y=0.752,zoneID=14771}},coords={x=0.588,y=0.752,source="quest_giver",zoneID=14771},questType="pvp"},
[80196] = {id=80196,name="Extract a Gem",level=10,requiredLevel=10,faction="none",expansion=10,description="Any gem can be removed from your equipment using the Extract Gem ability. The gem will not be destroyed. Extract a gem now.",questType="standard"},
[80197] = {id=80197,name="Combine Gems",level=10,requiredLevel=10,faction="none",expansion=10,description="Prismatic gems can be combined to create a more powerful gem. Combine three Deadly Chipped Sapphires to create a Flawed Deadly Sapphire that grants additional Critical Strike when socketed.",questType="standard"},
[80202] = {id=80202,name="Hot Pollenate-o",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14717,description="Important to make sure not take too much. Make sure hive healthy so can come back. Bees eat pollen, yes? So fire bees eat fire pollen? Yes. Bring fire pollen to bees. Grow strong. Bee productive. Check edge of hive for flowers bees not get to yet. When catch fire, you got good one.",starts={{npcID=219674,x=0.72,y=0.42,zoneID=14717}},ends={{npcID=219674,x=0.72,y=0.42,zoneID=14717}},coords={x=0.72,y=0.42,source="quest_giver",zoneID=14717},questType="standard"},
[80203] = {id=80203,name="Social Clues",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14753,description="The Weaver sent you, yes? I arrived to petition the Magistrate's approval for Ascension--to infiltrate high society, of course. But he's missing. A rather large inconvenience. I need to ask around. You're just what I've been waiting for! You may pretend to be my... servant. Pet? Whatever makes it more palatable to you. I so rarely get to work alongside a friend. We will have fun together, fellow spy.",starts={{npcID=219357,x=0.714,y=0.442,zoneID=14753}},ends={{npcID=221092,x=0.656,y=0.402,zoneID=14753}},coords={x=0.714,y=0.442,source="quest_giver",zoneID=14753},questType="standard"},
[80204] = {id=80204,name="Espionage and Ventriloquism",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14753,description="The Puppetmaster is our best lead for finding the Magistrate. But is it just me, or did those puppets seem... horrifically lifelike? If this artist is behind the Magistrate's disappearance, he certainly isn't just off to see a puppet show. We should investigate the Puppetmaster's workshop. Question him, or at least ransack his things. Just a bit. Until we find something useful. You'll have to keep playing your rather undignified role in this charade. But it will pay off for us.",starts={{npcID=221092,x=0.656,y=0.402,zoneID=14753}},ends={{npcID=221093,x=0.656,y=0.402,zoneID=14753}},coords={x=0.656,y=0.402,source="quest_giver",zoneID=14753},questType="standard"},
[80205] = {id=80205,name="Pulling Strings",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14753,description="Just think of it! Overcrawlers, war prisoners, civilians, fellow nerubians, important nobility being kidnapped and turned into puppets right under the Magistrate's nose. It's horrific--and exactly what I needed! If we save the Magistrate from this fate, he'll owe me. Not just for saving his life, but to keep quiet about all this. We're off to the theater, then. If you can keep the Puppetmaster occupied, I'll free High Elevator Etak'kaht from his grasp. Hopefully he's not part of the show yet.",starts={{npcID=221093,x=0.656,y=0.402,zoneID=14753}},ends={{npcID=221088,x=0.714,y=0.454,zoneID=14753}},coords={x=0.656,y=0.402,source="quest_giver",zoneID=14753},questType="standard"},
[80206] = {id=80206,name="Marionette Mercy",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14753,description="It's perfect! The Puppetmaster is so interested in adding you to his collection, he literally invited us to go rescue the Magistrate. I don't want to imply I've been using you as bait this entire time, but... Let's just say certain calculated risks have paid off. Even such a skilled artist must have a way to correct potential errors. There has to be an antitoxin of sorts for that paralytic around here somewhere! Find it. And perhaps we test it before we go use it on the Magistrate. Just in case.",starts={{npcID=221093,x=0.656,y=0.402,zoneID=14753}},ends={{npcID=221093,x=0.656,y=0.402,zoneID=14753}},coords={x=0.656,y=0.402,source="quest_giver",zoneID=14753},questType="standard"},
[80207] = {id=80207,name="How Scandalous!",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,description="Did you see anything? I was just at the Forgegrounds picking up a jewelry commission and all of a sudden everyone was shouting like the Coreway was under attack--again. But it was not that... Some peacekeepers were heading towards the depot--where crafting shipments are sent up from the Deeps. I bet it's something to do with the machine speakers! The peacekeepers ushered everyone away before I could see what had happened. But maybe you can sneak a glimpse?",starts={{npcID=219393,x=0.626,y=0.218,zoneID=14771}},ends={{npcID=219394,x=0.498,y=0.494,zoneID=14771}},coords={x=0.626,y=0.218,source="quest_giver",zoneID=14771},questType="standard"},
[80209] = {id=80209,name="An Oddball in Dornogal",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,description="We have received reports that an eccentric Arathi is accosting our citizens. We have little experience with outsiders and my superiors are wary of a diplomatic incident. I have been tasked with finding this \"Lamplighter\" and resolving his concerns. You have worked with the Arathi before - can you assist me? I have a list of earthen who have reported the Lamplighter. You can interview half the list. Between us, we can hopefully locate the Arathi before he troubles more citizens.",starts={{npcID=222224,x=0.544,y=0.194,zoneID=14771}},ends={{npcID=222268,x=0.67,y=0.186,zoneID=14771}},coords={x=0.544,y=0.194,source="quest_giver",zoneID=14771},questType="standard"},
[80210] = {id=80210,name="Found Around the Unbound",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="This Lamplighter is looking for his fellow Arathi. The foreman says he directed an Arathi shipwright to Freywold Village. My superiors insist that Peacekeepers do not leave Dornogal... but per their orders, I must assist Kaerter. And to do that, I have no choice but to leave the city. It is decided then. If you are willing, please meet us at Freywold Village. Your continued aid would be appreciated.",starts={{npcID=222268,x=0.67,y=0.186,zoneID=14771}},ends={{npcID=222314,x=0.426,y=0.71,zoneID=14717}},coords={x=0.67,y=0.186,source="quest_giver",zoneID=14771},questType="standard"},
[80211] = {id=80211,name="The Pillage of Freywold Village",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="The Arathi shipwright was here but has moved on with most of her entourage. She had left a few Arathi behind but... Soon after the shipwright left, earthen started disappearing. The villagers suspected the Arathi but had no proof. Then one day, the remaining Arathi left town in the middle of the night. The locals said the Arathi stayed at the inn. Can you look there for any clues as to where the Arathi are now? Given the villagers' hostility, the Lamplighter and I shall remain here for the moment.",starts={{npcID=222314,x=0.426,y=0.71,zoneID=14717}},ends={{npcID=222314,x=0.426,y=0.71,zoneID=14717}},coords={x=0.426,y=0.71,source="quest_giver",zoneID=14717},questType="standard"},
[80212] = {id=80212,name="The Abductors' Obstructors",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="The Order of Night is clearly interested in our resources. They have abducted earthen to harvest for them and may continue taking others. We must stop them. The next largest earthen settlement is Rambleshire. If the Order needs more workers, they might have gone there to get them. Go on ahead . I must first speak with Kaerter about why the Arathi are doing this.",starts={{npcID=222314,x=0.426,y=0.71,zoneID=14717}},ends={{npcID=222353,x=0.574,y=0.3,zoneID=14717}},coords={x=0.426,y=0.71,source="quest_giver",zoneID=14717},questType="standard"},
[80213] = {id=80213,name="Holy Fire in Rambleshire",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="I'm certain there are still Order folks sneaking around here. Now they might be carrying messages on them, just like the clues you found in Freywold. You and I are gonna find out. Here, take these thuribles. They might look like tiny incense burners, but I've enchanted them with Sacred Flame. Just throw one down and you'll get a big bang with a bright flash! Should be enough to stun anyone sneaking around. Just don't throw one at me! Got it?",starts={{npcID=222352,x=0.574,y=0.3,zoneID=14717}},ends={{npcID=222356,x=0.62,y=0.306,zoneID=14717}},coords={x=0.574,y=0.3,source="quest_giver",zoneID=14717},questType="standard"},
[80214] = {id=80214,name="A Time to Kill at the Lumber Mill",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="Alright, let me see if I get all of this. The shipwright brings an entourage up here to get lumber for airships. But the shipwright is actually Order of Night, along with most of her group. So they murder the loyal Arathi, kidnap earthen, and force them to run the lumber mill up here. And now we gotta deal with the Order AND whoever their new friends are. C'mon, let's head to the mill. We got a lot of bad guys to kill and time's wastin'.",starts={{npcID=222356,x=0.62,y=0.306,zoneID=14717}},ends={{npcID=222360,x=0.67,y=0.312,zoneID=14717}},coords={x=0.62,y=0.306,source="quest_giver",zoneID=14717},questType="standard"},
[80215] = {id=80215,name="Ungirthin' the Earthen",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="While I do enjoy beating the black blood out of nerubians, we must save the earthen prisoners first. I saw they're being held by Arathi ball and chain. Someone like you should be able to shatter them pretty quick. Just... do that thing you do! Oh, and we should split up to cover more ground. Yeah Leif's gonna complain, but he's always complaining anyway.",starts={{npcID=222360,x=0.67,y=0.312,zoneID=14717}},ends={{npcID=222360,x=0.67,y=0.312,zoneID=14717},{npcID=222362,x=0.658,y=0.246,zoneID=14717}},coords={x=0.67,y=0.312,source="quest_giver",zoneID=14717},questType="standard"},
[80216] = {id=80216,name="Concealed in the Weald",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="The nerubians seem to be in league with the Arathi. Many of them are guarding the mill, but I am sure there are more than we can see. We cannot allow such a large enemy force to operate unimpeded this close to Rambleshire. The nerubians attacked and destroyed large sections of Dornogal not too long ago. The Order of Night Arathi are abducting and enslaving our people. We must eliminate as many of them as we can. Preferably all of them.",starts={{npcID=222358,x=0.67,y=0.312,zoneID=14717}},ends={{npcID=222362,x=0.658,y=0.246,zoneID=14717}},coords={x=0.67,y=0.312,source="quest_giver",zoneID=14717},questType="standard"},
[80217] = {id=80217,name="A Lamplight for the Shipwright",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="Where is Kaerter now? Did he go off on his own again? We've rescued the earthen and eliminated many hostile forces, but our task is not yet complete. Shortly before you arrived, we spotted a group of Arathi traveling up this hill. One of them was identified as the Arathi shipwright. The shipwright is the leader here. Losing her will cripple their efforts to utilize the mill. Head up the hill and find her before she can escape.",starts={{npcID=222362,x=0.658,y=0.246,zoneID=14717}},ends={{npcID=222363,x=0.66,y=0.238,zoneID=14717}},coords={x=0.658,y=0.246,source="quest_giver",zoneID=14717},questType="standard"},
[80218] = {id=80218,name="Up to No Good Down in Silkwood",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="The Order is moving the wood through the nerubians. Leif said he saw the shipwright leave the cave and head down to the beach. The nerubian tunnel must be down there. You're going to have to seal that Flameforsaken passage. While slinking around, I noticed the Order brought explosive barrels with them. Find a few and use them to blow the tunnel. Get going . I'll be right behind you.",starts={{npcID=222364,x=0.66,y=0.238,zoneID=14717}},ends={{npcID=222365,x=0.654,y=0.204,zoneID=14717}},coords={x=0.66,y=0.238,source="quest_giver",zoneID=14717},questType="standard"},
[80219] = {id=80219,name="Dornogal Drift",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=14717,mapID=2248,questType="standard"},
[80220] = {id=80220,name="Storm's Watch Survey",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=14717,mapID=2248,questType="standard"},
[80221] = {id=80221,name="Basin Bypass",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=14717,mapID=2248,questType="standard"},
[80222] = {id=80222,name="The Wold Ways",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=14717,mapID=2248,questType="standard"},
