[81719] = {id=81719,name="Report to the Trading Post",level=1,requiredLevel=1,faction="both",expansion=10,zoneID=14771,mapID=2339,starts={{npcID=219244,x=0.446,y=0.56,mapID=2339}},ends={{npcID=219244,x=0.446,y=0.56,mapID=2339}},coords={x=0.446,y=0.56,source="quest_giver",mapID=2339},questType="standard"},
[81720] = {id=81720,name="Report to the Trading Post",level=1,requiredLevel=1,faction="both",expansion=10,zoneID=14771,mapID=2339,starts={{npcID=219244,x=0.446,y=0.56,mapID=2339}},ends={{npcID=219244,x=0.446,y=0.56,mapID=2339}},coords={x=0.446,y=0.56,source="quest_giver",mapID=2339},questType="standard"},
[81721] = {id=81721,name="Report to the Trading Post",level=1,requiredLevel=1,faction="horde",expansion=10,zoneID=15969,mapID=2393,starts={{npcID=249041,x=0.488,y=0.782,mapID=2393}},ends={{npcID=249041,x=0.488,y=0.782,mapID=2393}},coords={x=0.488,y=0.782,source="quest_giver",mapID=2393},questType="standard"},
[81722] = {id=81722,name="Report to the Trading Post",level=1,requiredLevel=1,faction="both",expansion=10,zoneID=14771,mapID=2339,starts={{npcID=249041,x=0.488,y=0.782,mapID=2393}},ends={{npcID=249041,x=0.488,y=0.782,mapID=2393},{npcID=219244,x=0.446,y=0.56,mapID=2339}},coords={x=0.488,y=0.782,source="quest_giver",mapID=2339},questType="standard"},
[81723] = {id=81723,name="Report to the Trading Post",level=1,requiredLevel=1,faction="both",expansion=10,zoneID=14771,mapID=2339,starts={{npcID=219244,x=0.446,y=0.56,mapID=2339}},ends={{npcID=219244,x=0.446,y=0.56,mapID=2339}},coords={x=0.446,y=0.56,source="quest_giver",mapID=2339},questType="standard"},
[81724] = {id=81724,name="Report to the Trading Post",level=1,requiredLevel=1,faction="both",expansion=10,zoneID=14771,mapID=2339,starts={{npcID=219244,x=0.446,y=0.56,mapID=2339}},ends={{npcID=219244,x=0.446,y=0.56,mapID=2339}},coords={x=0.446,y=0.56,source="quest_giver",mapID=2339},questType="standard"},
[81725] = {id=81725,name="Report to the Trading Post",level=1,requiredLevel=1,faction="both",expansion=10,zoneID=14771,mapID=2339,starts={{npcID=219244,x=0.446,y=0.56,mapID=2339}},ends={{npcID=219244,x=0.446,y=0.56,mapID=2339}},coords={x=0.446,y=0.56,source="quest_giver",mapID=2339},questType="standard"},
[81726] = {id=81726,name="Report to the Trading Post",level=1,requiredLevel=1,faction="both",expansion=10,zoneID=14771,mapID=2339,starts={{npcID=219244,x=0.446,y=0.56,mapID=2339}},ends={{npcID=219244,x=0.446,y=0.56,mapID=2339}},coords={x=0.446,y=0.56,source="quest_giver",mapID=2339},questType="standard"},
[81751] = {id=81751,name="Fire and Gemstone",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,description="What's this? A tinderbox? I've heard tell of these Arathi contraptions, but have never held one in my hands. It's smaller than I would have thought... Upgraded, you say? Ha! We can do that. The next time we're Awakening the Machine , keep an eye out for an Awakened Cog and Ringing Gemstone .",starts={{npcID=217128,x=0.474,y=0.32,zoneID=14795}},ends={{npcID=217128,x=0.474,y=0.32,zoneID=14795}},coords={x=0.474,y=0.32,source="quest_giver",zoneID=14795},questType="standard"},
[81793] = {id=81793,name="Sparks of War: Isle of Dorn",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,description="Powerful creatures are causing havoc across the Isle of Dorn . Get out there and clear things up!",starts={{npcID=219260,x=0.588,y=0.752,zoneID=14771}},ends={{npcID=219260,x=0.588,y=0.752,zoneID=14771}},coords={x=0.588,y=0.752,source="quest_giver",zoneID=14771},questType="standard"},
[81794] = {id=81794,name="Sparks of War: The Ringing Deeps",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,description="Unseen forces have overrun multiple Earthen outposts. Seek them out and cleanse the deeps.",starts={{npcID=219260,x=0.588,y=0.752,zoneID=14771}},ends={{npcID=219260,x=0.588,y=0.752,zoneID=14771}},coords={x=0.588,y=0.752,source="quest_giver",zoneID=14771},questType="standard"},
[81795] = {id=81795,name="Sparks of War: Hallowfall",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,description="The light beneath is fickle, but it will save you from the dark if you master it. Go. Travel to Hallowfall , and lend your strength to the Arathi.",starts={{npcID=219260,x=0.588,y=0.752,zoneID=14771}},ends={{npcID=219260,x=0.588,y=0.752,zoneID=14771}},coords={x=0.588,y=0.752,source="quest_giver",zoneID=14771},questType="standard"},
[81796] = {id=81796,name="Sparks of War: Azj-Kahet",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,description="We've received strange readings coming Azj-Kahet .. Investigate these locations, but stay vigilant.",starts={{npcID=219260,x=0.588,y=0.752,zoneID=14771}},ends={{npcID=219260,x=0.588,y=0.752,zoneID=14771}},coords={x=0.588,y=0.752,source="quest_giver",zoneID=14771},questType="standard"},
[81797] = {id=81797,name="Targeted Recon",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="If you've spent much time in Hallowfall , no doubt by now you've run across the foul magic of the kobyss. Reports that their illusions have been evolving are fiercely debated within the Arathi Army. Your outside perspective is just what I'm looking for. Venture to the Sunless Strand, slay a few of their illusory assassins, and then report your findings. You'll likely find them hiding in the shadows.",starts={{npcID=218508,x=0.424,y=0.552,zoneID=14838}},ends={{npcID=218508,x=0.424,y=0.552,zoneID=14838}},coords={x=0.424,y=0.552,source="quest_giver",zoneID=14838},questType="standard"},
[81798] = {id=81798,name="Return to Moira",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="Speaker Brinthe's impulsiveness is getting the better of her. You'd best return to your comrades and let them know of her intentions!",starts={{npcID=213672,x=0.49,y=0.174,zoneID=14795}},ends={{npcID=213763,x=0.47,y=0.206,zoneID=14795}},coords={x=0.49,y=0.174,source="quest_giver",zoneID=14795},questType="standard"},
[81869] = {id=81869,name="Can Catch More Fires with Honey",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14717,description="Crafting with flame demands a fuel that burns pure and has sustainable power. Among these, the honey created by Cinderwold bees stands out! A source of elemental fire, organic and untainted. I've longed for a supply of this honey, yet never had the chance to procure it. Take my harvesting device and gather a quantity for our purpose. We shall infuse it into your tinderbox. Exercise caution, for some of the earthen revere these bees as sacred creatures.",starts={{npcID=217128,x=0.474,y=0.32,zoneID=14795}},ends={{npcID=217128,x=0.474,y=0.32,zoneID=14795}},coords={x=0.474,y=0.32,source="quest_giver",zoneID=14795},questType="standard"},
[81890] = {id=81890,name="Unfulfilled Requests",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="I have heard the citizens of the Silken Ward are having trouble with a group of Ascended called the Pale Weavelashers. The new ward is supposed to be a fresh start for citizens of the capital, at least that is the way the Queen tells it. In actuality it is a way for her to tighten her grip on those she distrust. Meet with my assistant Sum'latha . I sent her there ahead of time to gather information. She can fill you in on any details.",starts={{npcID=208782,x=0.528,y=0.462,zoneID=14753}},ends={{npcID=221948,x=0.514,y=0.638,zoneID=14752}},coords={x=0.528,y=0.462,source="quest_giver",zoneID=14753},questType="standard"},
[81896] = {id=81896,name="New and Improved",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,description="I've completed the modifications. I must say, this is some of my finest work! Despite its modest design, a bit of cog grease and elbow dust has transformed it into a device that even the surliest of the flame worshippers could appreciate. If any of them want to know how it's done, send them my way.",starts={{npcID=217128,x=0.474,y=0.32,zoneID=14795}},ends={{npcID=217128,x=0.474,y=0.32,zoneID=14795}},coords={x=0.474,y=0.32,source="quest_giver",zoneID=14795},questType="standard"},
[81908] = {id=81908,name="A Flame in the Dark",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14753,mapID=2213,description="Contained within the Underkeep lies a tinderbox, once belonging to the late Aelric Leid. This item reeks of powerful, corruptive energy. Its close proximity has leeched out to touch many nerubians. Your task is to retrieve that box and deliver it to me. To be safe, gather any tinderboxes you may find--we'll destroy them all, just in case.",questType="standard"},
[81909] = {id=81909,name="Absolute Power",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,description="The dark allure of this item surpasses my initial expectations. I can sense a surge of power coursing through me. We must delve deeper into its mysteries. However, it is unwise to discuss this matter openly. Follow me inside, where we may deliberate further.",ends={{npcID=214380,x=0.432,y=0.564,zoneID=14838}},questType="standard"},
[81910] = {id=81910,name="A Great Responsibility",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,description="To witness such corruption is deeply unsettling. Despite the dark energies intertwined with this tinderbox, there remains a flicker of the Sacred Flame, struggling to escape. I will not destroy that flicker, champion. Yet I dare not hold onto it any longer. Perhaps your purity of spirit can withstand the darkness it holds. Please, , carry it with you. Protect that small spark of purity, and help it break free of the dark magic that ensnares it.",starts={{npcID=214380,x=0.432,y=0.564,zoneID=14838}},ends={{npcID=214380,x=0.432,y=0.564,zoneID=14838}},coords={x=0.432,y=0.564,source="quest_giver",zoneID=14838},questType="standard"},
[81912] = {id=81912,name="Flight Training 102",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14717,description="Dunnae think I had nae noticed those rooks spittin' lightnin'. Sure beats tossin' hammers. But it won't mean nothin' if the Stormriders can't hit what they're fightin'. Let's test their aim. Got some gnomish contraptions here that'll project easy targets for practice. Take Shraubendre back out there an' show them how it's done!",starts={{npcID=215211,x=0.35,y=0.722,zoneID=14717}},ends={{npcID=215211,x=0.35,y=0.722,zoneID=14717}},coords={x=0.35,y=0.722,source="quest_giver",zoneID=14717},questType="standard"},
[81913] = {id=81913,name="Flight Training 103",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14717,description="These recruits seem tae be up for a challenge. Let's find them somethin' with a little bite! I saw a poor giant just off shore bein' pestered by a swarm of flying devils. Let's see if these rooks can shoot the wings off 'em an' provide some relief. You and Shraubendre are settin' a good example for the rest. Keep it up!",starts={{npcID=215211,x=0.35,y=0.722,zoneID=14717}},ends={{npcID=214995,x=0.276,y=0.604,zoneID=14717}},coords={x=0.35,y=0.722,source="quest_giver",zoneID=14717},questType="standard"},
[81914] = {id=81914,name="Dhar Oztan",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,description="I love the stormrooks. Taking care of them was my directive, so they're all I've ever known. But even so, there are questions about them that even I don't have answers to. Baelgrim--Stormward Baelgrim--he was the expert. I'd pester him about them at every opportunity. And he shared what he could. He told me once about summoning rooks at Dhar Oztan. It's an old Stormrider outpost that predates the Stormperch. If you want to know more about stormrooks, that's where we need to go.",starts={{npcID=215039,x=0.256,y=0.572,zoneID=14717},{npcID=215039,x=0.374,y=0.82,zoneID=14771}},ends={{npcID=214995,x=0.276,y=0.604,zoneID=14717}},coords={x=0.256,y=0.572,source="quest_giver",zoneID=14717},questType="standard"},
[81915] = {id=81915,name="Home to Roost",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,description="You've already done us a great service here, . We will carry on by the example you have set. You should return to Dhar Oztan and see to these new Stormriders you've recruited. They will undoubtedly benefit from the same diligence you have shown here. And, you can get away from these two and their posturing. I envy you, ...",starts={{npcID=215277,x=0.332,y=0.634,zoneID=14717}},ends={{npcID=215039,x=0.256,y=0.572,zoneID=14717},{npcID=215039,x=0.374,y=0.82,zoneID=14771}},coords={x=0.332,y=0.634,source="quest_giver",zoneID=14717},questType="standard"},
[81928] = {id=81928,name="The Voice of the People",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="As you might have heard, things haven't gone as intended for the citizens of the Silken Ward. The Pale Weavelashers have been keeping a tight grasp on the citizens. I wasn't able to find much before an Ascended kicked me out for snooping around. You are a fresh face, go around the Silken Ward and speak to the citizens, see if you can find a way to help them. Also seek out Alchemist Talbax . I heard his name spoken a few times. He could be a useful contact.",starts={{npcID=221948,x=0.514,y=0.638,zoneID=14752}},ends={{npcID=221842,x=0.598,y=0.54,zoneID=14752}},coords={x=0.514,y=0.638,source="quest_giver",zoneID=14752},questType="standard"},
[81929] = {id=81929,name="Here's the Plan",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14752,description=", the time has come to deal with the nerubian army. General Zev'kall is massing a sizeable force to the east. He intends to breach the wall and invade Hallowfall. There isn't much time. We do not have the strength for an all-out assault. To that end, the Weaver has sent Gazlowe here to assist us. I'm willing to do what it takes to save my people. And as fate would have it, I have a personal matter to attend to while we are there.",starts={{npcID=211409,x=0.592,y=0.194,zoneID=14752}},ends={{npcID=211409,x=0.592,y=0.194,zoneID=14752}},coords={x=0.592,y=0.194,source="quest_giver",zoneID=14752},questType="standard"},
[81945] = {id=81945,name="To Arathi's End",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14752,description="We will regroup on the outskirts of Arathi's End to the east. Their forces are nearly ready and there isn't much time, .",starts={{npcID=211409,x=0.592,y=0.194,zoneID=14752}},ends={{npcID=221977,x=0.636,y=0.178,zoneID=14752}},coords={x=0.592,y=0.194,source="quest_giver",zoneID=14752},questType="standard"},
[81950] = {id=81950,name="BOOM Treats!",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14752,description="If we're gonna stop this invasion, we need to take out their big guns. In this case, big guns equals ballistae. Remember how I had ya pick up them Betelsnax? Yeah, I didn't do that for no good reason. See, the nerubians here have their beetles haul their bombs. And those haulers love them some snacks. I mean, who doesn't? You place the snacks next to a ballista, then a bomb beetle walks up, and BOOM!",starts={{npcID=221977,x=0.636,y=0.178,zoneID=14752},{npcID=221982,x=0.645,y=0.06,zoneID=14752}},ends={{npcID=221982,x=0.645,y=0.06,zoneID=14752}},coords={x=0.636,y=0.178,source="quest_giver",zoneID=14752},questType="standard"},
[81959] = {id=81959,name="Collecting a Concoction",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="The Pale Weavelashers did indeed throw my alchemical supply down the cliffside. The potions will give the citizens of the Silken Ward the edge they need to rise up. I need someone to go down the Whispering Cliffs and collect any bottles that haven't broken open. I would go myself but the kobyss have made the area a hunting ground and I'm no fighter. This would be a simple task for one such as yourself, eh?",starts={{npcID=221842,x=0.598,y=0.54,zoneID=14752}},ends={{npcID=221842,x=0.598,y=0.54,zoneID=14752}},coords={x=0.598,y=0.54,source="quest_giver",zoneID=14752},questType="standard"},
[81962] = {id=81962,name="A Nudge in the Right Direction",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="Wonderful, wonderful! Now that we have recovered my Brightshade Potions, I want you to go around the Silken Ward and show them off! This will draw the ire of the Pale Weavelashers, I'm sure, but I want to show the populace that we don't need to live under their thumb. With a little aggressive motivation we can strike out on our own. Yes, yes, this will do! Go around the Silken Ward and kill Pale Weavelashers. My potions will provide an extra kick the citizens will certainly love.",starts={{npcID=221842,x=0.598,y=0.54,zoneID=14752}},ends={{npcID=221842,x=0.598,y=0.54,zoneID=14752}},coords={x=0.598,y=0.54,source="quest_giver",zoneID=14752},questType="standard"},
[81963] = {id=81963,name="The Fruits of Our Labor",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="You put on quite the show, yes? The orders are already coming in. The citizens can't wait to get their mandibles on the potions. I have one final task for you. I want you to take these latest orders and deliver them. You will accept, yes? The citizens are stirring. Now is the time to show the Pale Weavelashers what we can do. If any try and stop you, you know what to do.",starts={{npcID=221842,x=0.598,y=0.54,zoneID=14752}},ends={{npcID=221842,x=0.598,y=0.54,zoneID=14752}},coords={x=0.598,y=0.54,source="quest_giver",zoneID=14752},questType="standard"},
[81964] = {id=81964,name="The Blacksmith's Fate",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14752,description="While we're here, I must find out what happened to my old friend, Ryton Blackholme. He was Hallowfall's finest blacksmith--and he was taken in a surprise nerubian attack. I could not save him. I searched for him, but found nothing except for his bloodied helm. I'd given up hope. But recently, I heard rumor about a blacksmith from a survivor who'd been pulled down off the Aegis Wall. Could it be Ryton? Will you help me, ?",starts={{npcID=221961,x=0.636,y=0.178,zoneID=14752},{npcID=221980,x=0.646,y=0.063,zoneID=14752}},ends={{npcID=221980,x=0.646,y=0.063,zoneID=14752}},coords={x=0.636,y=0.178,source="quest_giver",zoneID=14752},questType="standard"},
[81965] = {id=81965,name="Invasion Disruption",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14752,description="While we cannot eliminate the nerubian threat here, we can disrupt their invasion plans. There are any number of opportunities to accomplish our goal. Let's see what kind of damage we can do.",starts={{npcID=221961,x=0.636,y=0.178,zoneID=14752},{npcID=221980,x=0.646,y=0.063,zoneID=14752}},ends={{npcID=221980,x=0.646,y=0.063,zoneID=14752}},coords={x=0.636,y=0.178,source="quest_giver",zoneID=14752},questType="standard"},
[81966] = {id=81966,name="Slept Like a Rock",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=7502,mapID=627,description="Champion, Da's awake. Please return to Dalaran .",questType="standard"},
[81969] = {id=81969,name="An End to the End",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14752,description="I want to honor my friend. But first, we need to deal the killing blow to this Light-forsaken place. It's known that General Zev'kall has been overseeing the creation of a monstrosity... a void-corrupted, malformed nerubian. The scouting report pinpointed the location at the top of the canyon. We're going to deprive him of his horrific pet. That should put an end to his plans to invade Hallowfall. At least for a little while longer.",starts={{npcID=221980,x=0.646,y=0.063,zoneID=14752}},coords={x=0.646,y=0.063,source="quest_giver",zoneID=14752},questType="standard"},
[81976] = {id=81976,name="Bazaar, Isn't It?",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=5785,mapID=371,starts={{npcID=222186,x=0.286,y=0.14,mapID=371}},ends={{npcID=222186,x=0.286,y=0.14,mapID=371}},coords={x=0.286,y=0.14,source="quest_giver",mapID=371},questType="standard"},
[81985] = {id=81985,name="Worldsoul Memory: The Worldcarvers",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=14717,mapID=2248,questType="standard"},
[81999] = {id=81999,name="New Home, New Candle!",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14717,description="Janky hears there are giant fire bees on surface. Fire bees make fire beeswax, yes? What if make candle from fire bee wax? What that be like? Janky must know!",starts={{npcID=216567,x=0.478,y=0.354,zoneID=14795}},ends={{npcID=219674,x=0.72,y=0.42,zoneID=14717}},coords={x=0.478,y=0.354,source="quest_giver",zoneID=14795},questType="standard"},
[82007] = {id=82007,name="Tale of Tails",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,description="The newborn lynx have wandered off again! Those rascally cats are always up to mischief, darting off without a care. With Peevish missing and only Vesper and I to hold this position, your assistance would be a boon! I reckon those pesky felines are somewhere nearby. See if you can bring them back. I would use a light and search the cave, the spider-infested area to the south, and the coast to the north.",starts={{npcID=212419,x=0.644,y=0.188,zoneID=14838}},ends={{npcID=212419,x=0.644,y=0.188,zoneID=14838}},coords={x=0.644,y=0.188,source="quest_giver",zoneID=14838},questType="standard"},
[82121] = {id=82121,name="Demand Satisfaction",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14752,description="We have worked together for some time now, . I hope you have come to respect my vision as it pertains to the art of warfare. There are, as ever, rules that must be followed. Lines that must not be crossed. Zev'kall has to die, and I have to be the one to do it. Every day that Ascended ruffian tramples upon the ideals of war tarnishes the legacy of our kingdom. Please, do this last thing for me. Travel to the enemy stronghold and plant this flag on its steps. We will do this the correct way.",starts={{npcID=224345,x=0.55,y=0.412,zoneID=14752}},ends={{npcID=222788,x=0.46,y=0.248,zoneID=14752}},coords={x=0.55,y=0.412,source="quest_giver",zoneID=14752},questType="standard"},
[82122] = {id=82122,name="Duel of the Fates",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14752,description="I am no hapless rube, . I do not expect Zev'kall to honor the nature of this challenge in even the most nominal sense. We are in the enemy's fortress, and we are surrounded by his teeming sycophants. There will be interference. I have two orders for you, soldier. First, you will ward off any malcontents who wish to interrupt the duel. Second and more importantly, you will bring neither sword nor spell to bear against Zev'kall himself. He will fall by my claws.",starts={{npcID=222788,x=0.46,y=0.248,zoneID=14752}},ends={{npcID=224547,x=0.46,y=0.246,zoneID=14752}},coords={x=0.46,y=0.248,source="quest_giver",zoneID=14752},questType="standard"},
[82123] = {id=82123,name="The General's Conviction",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14752,description="Anub'azal retches roughly. Ichor spews from his disjointed maw.> My cohort's obligation to the Severed Threads yet remains. You would do well to report what happened here to the Weaver. Vexing as she is, she will have some idea of how to proceed from here.",starts={{npcID=224547,x=0.46,y=0.246,zoneID=14752}},ends={{npcID=207471,x=0.556,y=0.438,zoneID=14752}},coords={x=0.46,y=0.246,source="quest_giver",zoneID=14752},questType="standard"},
[82124] = {id=82124,name="The Beginning of the End",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14753,description="Queen Ansurek has been busy since the assassination attempt. Her grip is tightening on Azj-Kahet and her ever loyal nobles attend to her darkest whims. On behest of the Queen, her two most loyal nobles Skeinspinner Takazj and Anub'arash, have locked down the Umbral Bazaar. Takazj's insufferable propaganda machinations and Anub'arash's increased military presence have painted a clear picture, ascend or die. I need you to go to the Umbral Bazaar and disrupt their hold.",starts={{npcID=208782,x=0.528,y=0.462,zoneID=14753}},ends={{npcID=208782,x=0.528,y=0.462,zoneID=14753}},coords={x=0.528,y=0.462,source="quest_giver",zoneID=14753},questType="standard"},
[82125] = {id=82125,name="A Spy Like Us",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14753,description="Distressing news comes from the Burrows, a sinister plan is unfolding in the gutters below. Citizens of the ward have been disappearing at an alarming rate. Skeinspinner Takazj and Anub'arash have all the subtlety of a hammer. I doubt it is their work. This is the hand of someone more subtle. I have a contact in the Burrows. His name is Gut'usul . Meet with him in the Burrows and find out what is going on down below.",starts={{npcID=208782,x=0.528,y=0.462,zoneID=14753}},ends={{npcID=222790,x=0.572,y=0.41,zoneID=14753}},coords={x=0.528,y=0.462,source="quest_giver",zoneID=14753},questType="standard"},
[82126] = {id=82126,name="Defense of the People",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14753,mapID=2213,description="The Vizier no doubt filled you in on some of the details. Citizens in the Burrows are missing, that much you know. But whispers on the wind tell a bigger story. Our citizens are being taken to the Transformatory and never returned! We must stop this at all costs. More have been taken but it's not too late for them yet. They are still being kept in the Burrows. Find them and free them.",questType="standard"},
[82127] = {id=82127,name="Make Them Prey",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14753,mapID=2213,description="These abductors are rounding up citizens and no one in the Burrows can stop them. I think it is about time somebody did something. They stalk the Burrows thinking they are unseen but I can see them, we can all see them. It's just nobody here can oppose them. That is where you come in. Hunt these abductors down and show them who is really the prey.",questType="standard"},
[82130] = {id=82130,name="A Shot at the Top",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14753,description="While you have been out, I've been keeping busy as well. Your exploits in the Burrows drew the attention of someone much higher up. A strange being wrapped in bandages, with a scent like despair. Fortunately, this unusual monster is paying a visit all the way down in the Burrows to find out why their abductors are missing. Now is our chance to strike, and take down this whole operation.",questType="standard"},
[82141] = {id=82141,name="To Kill a Queen",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14753,description="Tightening her grip on the citizens is something I expected of the Queen but forcefully ascending the population of the Burrows is too far. Queen Ansurek has fallen far greater than I ever expected. I can't sit idly by and watch her lead our people to ruin. The time is now. We must kill Queen Ansurek and lead the people to a brighter future. Otherwise who knows how far she will fall.",starts={{npcID=208782,x=0.528,y=0.462,zoneID=14753}},ends={{npcID=208782,x=0.528,y=0.462,zoneID=14753}},coords={x=0.528,y=0.462,source="quest_giver",zoneID=14753},questType="raid"},
[82143] = {id=82143,name="The Path of Dissonance",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="Hannan is correct only in that my presence here is not... strictly allowed. But this corruption echoes in my mind, like a disruptive chord in the otherwise pure song of the world. Like a cry for help. I must heed that call. I must follow the dissonance to its source and find the heart of it, so that I may discover how to cleanse it. Join me.",questType="standard"},
[82144] = {id=82144,name="On the Road",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="This is the only road to the elevator, he should have been here by now. Unless... he didn't take the road! He wouldn't want to be seen. He has no idea how dangerous the deeps can be. We have to find him!",starts={{npcID=220600,x=0.604,y=0.456,zoneID=14795}},ends={{npcID=220600,x=0.604,y=0.456,zoneID=14795}},coords={x=0.604,y=0.456,source="quest_giver",zoneID=14795},questType="standard"},
[82146] = {id=82146,name="Special Assignment: Cinderbee Surge",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=14717,mapID=2248,questType="standard"},
