[82161] = {id=82161,name="Special Assignment: Bombs from Behind",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=14752,mapID=2255,questType="standard"},
[82164] = {id=82164,name="Worldsoul Memory: Reign of the Old Gods",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=14838,mapID=2215,questType="standard"},
[82195] = {id=82195,name="Rust and Redemption",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="As you approach, a rusty lever catches your eye, stubbornly stuck in its place. \"This thing hasn't moved in ages,\" you muse, as you feel the rough metal resist your touch. Glancing around, you note the oily sheen on the plantlike Crawlers. \"Perhaps a bit of natural lubricant would do the trick,\" you ponder, realizing that these flora foes might yield what you need to ease the lever's grip.",starts={{npcID=443532,x=0.534,y=0.446,mapID=2214}},ends={{npcID=443532,x=0.534,y=0.446,mapID=2214}},coords={x=0.534,y=0.446,source="quest_giver",mapID=2214},questType="standard"},
[82207] = {id=82207,name="Worldsoul Memory: Descendant of Distant Waters",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=14838,mapID=2215,questType="standard"},
[82224] = {id=82224,name="Check on the Compiler",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="That's everything up here. Would you check on Brennok ? Recitations can be stressful, I'm sure he'd appreciate the help.",starts={{npcID=220600,x=0.604,y=0.456,zoneID=14795}},ends={{npcID=220597,x=0.618,y=0.454,zoneID=14795}},coords={x=0.604,y=0.456,source="quest_giver",zoneID=14795},questType="standard"},
[82226] = {id=82226,name="Papers? Please!",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="Hey pal, what's it gonna take to get you to leave me alone? How about a trip? A POWER trip... I told Boss Sparkshot that I would man the worksite's...er, resort's! Yeah, that I would man the resort's front desk for a bit. Care to take my place? It's just your usual paper-pushing busy work. Check credentials, keep an eye out for corporate sabotage, call in the occasional air strike, etcetera, etcetera...",starts={{npcID=223184,x=0.648,y=0.786,zoneID=14795}},ends={{npcID=223184,x=0.648,y=0.786,zoneID=14795}},coords={x=0.648,y=0.786,source="quest_giver",zoneID=14795},questType="standard"},
[82248] = {id=82248,name="Advance to Faerin",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14752,description="I have a little morsel all wrapped up from a corner of my web. Shall I share it with you? It's sure to mean your doom, little . Very well... I can smell your eager impatience. I've sent that little green blob of a goblin you call Gazlowe off to the northeast. He tells me the queen and high general are marshalling their elite shock troops. No doubt they are readying to invade Hallowfall. Scurry off to your Lamplighter friend. I'm certain she will want to smash everything in sight.",starts={{npcID=207471,x=0.556,y=0.438,zoneID=14752}},ends={{npcID=211409,x=0.592,y=0.194,zoneID=14752}},coords={x=0.556,y=0.438,source="quest_giver",zoneID=14752},questType="standard"},
[82260] = {id=82260,name="Worldsoul Memory: Primal Predators",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=14795,mapID=2214,questType="standard"},
[82263] = {id=82263,name="Worldsoul Memory: Elemental Fury",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=14795,mapID=2214,questType="standard"},
[82268] = {id=82268,name="The Sorrowful Journey Home",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,description="I intend to burn Ryton's breastplate and Sir Ashrealm's tinderbox at Mereldar. I would be honored if you would join me. Would you carry the breastplate there?",ends={{npcID=220406,x=0.432,y=0.562,zoneID=14838}},questType="standard"},
[82284] = {id=82284,name="Remembrance for the Fallen",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,description="It is our custom to pay homage to the fallen by burning whatever we can recover of their belongings. Usually, it is their tinderboxes as those are easier to carry. We then return those items to the flame. While we were able to retrieve Sir Ashrealm's tinderbox, Ryton's breastplate will serve to honor his memory. You have placed your life in danger not only for me, but also for Hallowfall . I would be honored if you would assist me this one last time in remembering our fallen.",starts={{npcID=220406,x=0.432,y=0.562,zoneID=14838}},ends={{npcID=220406,x=0.432,y=0.562,zoneID=14838}},coords={x=0.432,y=0.562,source="quest_giver",zoneID=14838},questType="standard"},
[82285] = {id=82285,name="Worldsoul Memory: A Wounded Soul",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=14752,mapID=2255,questType="standard"},
[82286] = {id=82286,name="Worldsoul Memory: Old Gods Forsaken",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=14752,mapID=2255,questType="standard"},
[82321] = {id=82321,name="Worldsoul Memory: Ancient Explorers",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=14717,mapID=2248,questType="standard"},
[82333] = {id=82333,name="Weathered Crests",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,mapID=2339,starts={{npcID=223728,x=0.392,y=0.242,mapID=2339}},ends={{npcID=223728,x=0.392,y=0.242,mapID=2339}},coords={x=0.392,y=0.242,source="quest_giver",mapID=2339},questType="standard"},
[82335] = {id=82335,name="Crystals",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14838,mapID=2215,starts={{npcID=213145,x=0.412,y=0.53,mapID=2215}},ends={{npcID=213145,x=0.412,y=0.53,mapID=2215}},coords={x=0.412,y=0.53,source="quest_giver",mapID=2215},questType="standard"},
[82338] = {id=82338,name="Absent Errand",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14753,description="Do you remember the logbook you discovered in Zev'kall's office? It contained critical information about Zev'kall's misuse of our people. I gave it to my assistant, Anub'okki, to bring to the historians in the Skeins. But I have not heard back from Anub'okki. I suspect foul play. See if anyone in the Skeins will admit to having seen him!",starts={{npcID=223765,x=0.474,y=0.228,zoneID=14752},{npcID=224345,x=0.55,y=0.412,zoneID=14752}},ends={{npcID=223760,x=0.41,y=0.334,zoneID=14753}},coords={x=0.474,y=0.228,source="quest_giver",zoneID=14752},questType="standard"},
[82339] = {id=82339,name="An Honorless Kill",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="If it will get you out of here sooner, I will tell you what I saw. I did not see what happened to Anub'okki. But I can tell you that corpses are dumped into Pillar-nest Xesh to be forgotten about. The cleanup crew dragged Anub'okki out of here not long ago. If you hurry, you may be able to examine the remains before they are gone.",starts={{npcID=223760,x=0.41,y=0.334,zoneID=14753}},ends={{npcID=224345,x=0.55,y=0.412,zoneID=14752}},coords={x=0.41,y=0.334,source="quest_giver",zoneID=14753},questType="standard"},
[82340] = {id=82340,name="Loss of Limb",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14753,mapID=2213,description="Happy greetings! I am Mr. Sunflower , and this is my tea room and therapy space. It is a safe place for everyone! I wonder if you might be willing to help a patient of mine. Vi'azl is deathly afraid of creatures with fewer limbs. I think it has grown into a deep phobia of dismemberment. I'm trying to get to the bottom of this diagnosis. Would you speak to him, and demonstrate that you, who do not have eight limbs, are not so terrifying after all?",questType="standard"},
[82342] = {id=82342,name="A Small Bundle of Goods",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,mapID=2339,starts={{npcID=223728,x=0.392,y=0.242,mapID=2339}},ends={{npcID=223728,x=0.392,y=0.242,mapID=2339}},coords={x=0.392,y=0.242,source="quest_giver",mapID=2339},questType="standard"},
