[82509] = {id=82509,name="Worldsoul: Nerub-ar Palace",level=70,requiredLevel=70,faction="none",expansion=10,description="Queen Ansurek has proven herself both cruel and cunning. We cannot allow her forces to continue to grow in strength with Xal'atath's black blood. It has come to this. A daunting task indeed. With the greatest of our forces, we shall lay siege to Nerub-ar Palace!",questType="standard"},
[82510] = {id=82510,name="Worldsoul: Nerub-ar Palace",level=70,requiredLevel=70,faction="none",expansion=10,description="Queen Ansurek has proven herself both cruel and cunning. We cannot allow her forces to continue to grow in strength with Xal'atath's black blood. It has come to this. A daunting task indeed. With the greatest of our forces, we shall lay siege to Nerub-ar Palace!",questType="standard"},
[82511] = {id=82511,name="Worldsoul: Awakening Machine",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,description="The earthen tell me of this \"Awakening Machine\" that is part of their life cycle. It imbues them with energy, once a gift of the titans but now from the Worldsoul. They hold it in high reverence--as we do Beledar. I will fight to defend it with the same fervor as I would defend our own star! Aid me, . We can't let them down.",ends={{npcID=223875,x=0.46,y=0.494,zoneID=14771}},questType="standard"},
[82512] = {id=82512,name="Worldsoul: World Boss",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,description="Hallowfall is not the only land beset by enemies. Great monsters wander all of Khaz Algar--savage beasts and intelligent fiends alike. They murder Arathi, earthen, and adventurers in equal measure from innocent farmers to great warriors. I know the Sacred Flame burns in you. You are our best hope to hunt these great evils.",ends={{npcID=223875,x=0.46,y=0.494,zoneID=14771}},questType="standard"},
[82516] = {id=82516,name="Worldsoul: Forging a Pact",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,description="I've heard some reports of the goings on in Azj-Kahet. Nerubians have killed my people mercilessly since we arrived... it is very difficult to imagine them as allies. But... I understand feeling... different from the rest of your people. Perhaps these nerubians who have interest in us are also... different. No matter the cost... I can't bear to not give them a chance. Are they not also inhabitants of Khaz Algar? See what aid you can bring them, my friend.",ends={{npcID=223875,x=0.46,y=0.494,zoneID=14771}},questType="standard"},
[82539] = {id=82539,name="Radiant Echoes",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=7502,mapID=627,description="$p, please come to Dalaran at once. Strange phenomena are appearing all across Azeroth. We believe they may be connected to the Radiant Song. I'd like you to investigate.",questType="standard"},
[82540] = {id=82540,name="Memories of Adventures Past",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=7502,mapID=627,description="It seems that Azeroth has grown... agitated? Something must have happened when Magni tried to commune with her. Past events have now come to life once more. I believe they're Azeroth's memories. Memories they may be, these Radiant Echoes are all too real and could cause serious danger if left unattended. I ask that you investigate one of them and help however you can.",questType="standard"},
[82544] = {id=82544,name="The War Within (80) E",level=80,requiredLevel=80,faction="none",expansion=10,questType="standard"},
