[82980] = {id=82980,name="Queue Bonus",level=50,requiredLevel=50,faction="none",expansion=10,questType="standard"},
[82990] = {id=82990,name="Undoing the Damage",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="Apologies. Arbauch was not here for repairs--he stole that golem. Arbauch and I worked alongside it for years in the darkest reaches of the Deeps. The work took its toll on the golem. It became erratic, dangerous even. We planned to decommission it, but when the time came, Arbauch couldn't bear it. He'd become attached. Before it could be destroyed, he took it and fled. It must be found, but the damage to this substation is catastrophic. With your help, I will attempt repairs.",starts={{npcID=224602,x=0.59,y=0.642,zoneID=14795}},ends={{npcID=224602,x=0.59,y=0.642,zoneID=14795}},coords={x=0.59,y=0.642,source="quest_giver",zoneID=14795},questType="standard"},
[82992] = {id=82992,name="Stormcharged Goods",level=68,requiredLevel=68,faction="both",expansion=10,zoneID=14771,description="Greetings my friend! I am looking for someone who is willing to run a quick errand. I am running out of goods and I have not heard from my leather supplier for quiet some time. If I can not supply skins and leathers, the leatherworker will not be able to produce apparels. I will reward you if you can bring me several Stormcharged leathers .",starts={{npcID=219083,x=0.544,y=0.574,zoneID=14771}},ends={{npcID=219083,x=0.544,y=0.574,zoneID=14771}},coords={x=0.544,y=0.574,source="quest_giver",zoneID=14771},questType="standard"},
[82993] = {id=82993,name="From Shadows",level=68,requiredLevel=68,faction="both",expansion=10,zoneID=14771,description="Hello there! I have heard of fantastic materials that can be thread and put together from some... peculiar materials. If you are the type who enjoys travelling through the last sunny parts of Khaz-Algar, will you be kind enough to gather Kaheti Swarm Chitin and Sunless Carapace for me? I will reward you nicely if you can supply me with some samples.",starts={{npcID=219083,x=0.544,y=0.574,zoneID=14771}},ends={{npcID=219083,x=0.544,y=0.574,zoneID=14771}},coords={x=0.544,y=0.574,source="quest_giver",zoneID=14771},questType="standard"},
[82994] = {id=82994,name="Wax Contribution",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=14795,mapID=2214,questType="standard"},
[82995] = {id=82995,name="Nerubian Device",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,description="A strange device of Nerubian origins. Aevery Flamestonge at Hillhelm Stead might be intrigued by this.",ends={{npcID=215523,x=0.618,y=0.29,zoneID=14838}},questType="standard"},
[83021] = {id=83021,name="LFGDungeons - TWW - Normal Random - 1st",level=70,requiredLevel=70,faction="none",expansion=10,questType="standard"},
[83023] = {id=83023,name="Short-Supply Reward",level=80,requiredLevel=80,faction="none",expansion=10,questType="standard"},
[83027] = {id=83027,name="LFGDungeons - TWW - Heroic Random - 1st",level=80,requiredLevel=80,faction="none",expansion=10,questType="standard"},
[83031] = {id=83031,name="The Hardest Part",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14717,description="Dalaran... once a symbol of unity and arcane mastery, now reduced to rubble and ash. Again. So much loss and so much pain. Friends and comrades gone in an instant, their voices silenced by Xal'atath. But now is the time for action--not grief. We must regroup with the remaining Kirin Tor. However, the right words do not come easily.",starts={{npcID=225355,x=0.296,y=0.58,zoneID=14717}},ends={{npcID=225355,x=0.296,y=0.58,zoneID=14717}},coords={x=0.296,y=0.58,source="quest_giver",zoneID=14717},questType="standard"},
[83043] = {id=83043,name="Carved Crests",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,mapID=2214,starts={{npcID=223726,x=0.392,y=0.24,mapID=2339}},ends={{npcID=223726,x=0.392,y=0.24,mapID=2339},{npcID=221390,x=0.472,y=0.328,mapID=2214}},coords={x=0.392,y=0.24,source="quest_giver",mapID=2214},questType="standard"},
[83046] = {id=83046,name="Carved Crests",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,mapID=2214,starts={{npcID=223726,x=0.392,y=0.24,mapID=2339}},ends={{npcID=223726,x=0.392,y=0.24,mapID=2339},{npcID=221390,x=0.472,y=0.328,mapID=2214}},coords={x=0.392,y=0.24,source="quest_giver",mapID=2214},questType="standard"},
[83055] = {id=83055,name="Signed, Sealed",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15347,mapID=2346,questType="standard"},
[83057] = {id=83057,name="Setting Boundaries",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14753,mapID=2213,description="Vi'azl has undergone a level of torture that I was unaware of. We cannot help Vi with his fear until Vi is actually safe. Whenever possible, I advocate friendship, recovery, and reconciliation. I ask others to act with compassion and empathy. Everyone deserves a chance to recover. I dedicate my life to this. But hearing and seeing what is happening to Vi'azl... I think I've changed my mind. Enough is enough. We must act.",questType="standard"},
[83069] = {id=83069,name="Special Assignment: Titanic Resurgence",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=14717,mapID=2248,questType="standard"},
[83070] = {id=83070,name="Special Assignment: Titanic Resurgence",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=14717,mapID=2248,questType="standard"},
[83071] = {id=83071,name="Queue Bonus",level=35,requiredLevel=35,faction="none",expansion=10,questType="standard"},
[83072] = {id=83072,name="Queue Bonus",level=35,requiredLevel=35,faction="none",expansion=10,questType="standard"},
[83073] = {id=83073,name="Queue Bonus",level=40,requiredLevel=40,faction="none",expansion=10,questType="standard"},
[83074] = {id=83074,name="Queue Bonus",level=25,requiredLevel=25,faction="none",expansion=10,questType="standard"},
[83081] = {id=83081,name="Not Enough Minerals",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="I did nae think the Opalcreg would be under attack! I'm sure Brinthe did nae either. Peacekeeper Hektare will nae let me fight, but maybe she will let you. I'll stay here an' tend to this earthen. I know a trick or two after bein' in Dornogal. Oh, but... Brinthe really needed those opals...",starts={{npcID=225451,x=0.448,y=0.644,zoneID=14717}},ends={{npcID=225451,x=0.448,y=0.644,zoneID=14717}},coords={x=0.448,y=0.644,source="quest_giver",zoneID=14717},questType="standard"},
[83082] = {id=83082,name="The Opalfront",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="I'm a city guard, not a soldier! But these people need our help! There are too many nerubians for us to clear out. We can only keep this chokepoint and hope the miners make their way to us. That one was too small. But you look like a fighter. Help us!",starts={{npcID=225454,x=0.448,y=0.642,zoneID=14717}},ends={{npcID=225454,x=0.448,y=0.642,zoneID=14717}},coords={x=0.448,y=0.642,source="quest_giver",zoneID=14717},questType="standard"},
[83083] = {id=83083,name="A Place Forgotten",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="There is... a place behind Dornogal that I cannot go. And I am not the only one. Something--a force, most likely titan in origin--keeps the earthen from investigating a small portion of the island behind the city. This, of course, fires my curiosity. But for thousands of years I have dutifully kept away. It seemed the titans' will. The site emits a faint signal like the one from this device. Perhaps it is \"the key\" in a literal sense to what lies there. We will see.",starts={{npcID=225478,x=0.616,y=0.702,zoneID=14717}},ends={{npcID=226841,x=0.448,y=0.206,zoneID=14717}},coords={x=0.616,y=0.702,source="quest_giver",zoneID=14717},questType="standard"},
[83084] = {id=83084,name="The Old Orders",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="Long ago, there were once plans to build a tunnel through the mountain into Dornogal. Before excavation could begin, the surrounding area was suddenly abandoned. There is no record of what happened. Only a... deterrence--the field--that keeps earthen away from this region. Every part of my cognitive matrix is pressing for me to leave. But we must persist. The device's signal indicates something lies within the nearby tower.",starts={{npcID=226841,x=0.448,y=0.206,zoneID=14717}},ends={{npcID=225472,x=0.448,y=0.206,zoneID=14717}},coords={x=0.448,y=0.206,source="quest_giver",zoneID=14717},questType="standard"},
[83085] = {id=83085,name="DEPRECATED",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=14717,mapID=2248,questType="standard"},
[83087] = {id=83087,name="The Old Guard",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="Dornic... Galan... I've heard those names at the Proscenium! But who was speakin'? They were nae happy with Galan. All those earthen bodies... Repurposed... like reprogrammed? Tae protect what? Let's chase the other signal. Looks like it leads up ahead intae the hills. I'm goin' to stay here with Brinthe an' investigate this tower further. You take the device.",starts={{npcID=225472,x=0.448,y=0.206,zoneID=14717}},ends={{npcID=225472,x=0.448,y=0.206,zoneID=14717}},coords={x=0.448,y=0.206,source="quest_giver",zoneID=14717},questType="standard"},
[83088] = {id=83088,name="Caustic Collectables",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Boxenkle is my boss--and my mentor. Best slimediver there ever was! Until now... It's not him--slimediving isn't what it used to be! The slimes have gotten more toxic over time. I think it's gotten so bad that we all should be wearin' eye protection--not just me. But ol' Enkle's a traditionalist. It'll take more than a few red eyes to convince him. That's where you come in. If you can get residue samples from the really nasty slimes, maybe I can make a compelling case for ol' Enkle!",starts={{npcID=225481,x=0.406,y=0.87,zoneID=15347}},ends={{npcID=225481,x=0.406,y=0.87,zoneID=15347}},coords={x=0.406,y=0.87,source="quest_giver",zoneID=15347},questType="standard"},
[83089] = {id=83089,name="Giving Goblins Goggles",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="My mentor Enkle may be the loudest voice around here, but he's not the only one who needs help. Our whole crew only listens to him! Which means no one's wearing proper protective equipment. Take these goggles and convince everyone to take 'em on a trial run. Maybe if they all start changing their minds, Enkle will listen.",starts={{npcID=225481,x=0.406,y=0.87,zoneID=15347}},ends={{npcID=225481,x=0.406,y=0.87,zoneID=15347}},coords={x=0.406,y=0.87,source="quest_giver",zoneID=15347},questType="standard"},
[83091] = {id=83091,name="Shield Your Eyes",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Causticaria ? Is he crazy? No one has ever been able to process that monster! We have to stop Enkle before he gets himself hurt! Causticaria lurks down this canal. Grab your goggles and follow me!",starts={{npcID=225481,x=0.406,y=0.87,zoneID=15347}},ends={{npcID=228095,x=0.348,y=0.8,zoneID=15347}},coords={x=0.406,y=0.87,source="quest_giver",zoneID=15347},questType="standard"},
[83092] = {id=83092,name="An Igneous End",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="When the magma transport pipe failed, our workers rushed down to begin repairs. The elementals caught us unawares, rising up and attacking with great gouts of lava. Fortunately, we earthen are made of stern stuff and a little magma is hardly going to be the end of us. Unfortunately, the cooling magma has hardened into stone shells, entombing our repair crews where they stood. Smash their stony prisons and free my workers!",starts={{npcID=225582,x=0.41,y=0.214,zoneID=14795}},ends={{npcID=225582,x=0.41,y=0.214,zoneID=14795}},coords={x=0.41,y=0.214,source="quest_giver",zoneID=14795},questType="standard"},
[83096] = {id=83096,name="Welcome to Undermine",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="There ya are! I'm Grimla. Welcome to Undermine . If you wanna get up to speed with the current situation, you've come to the right goblin. Pamsy vouched for you, that's good enough for me. I've got a coupon you can use at the Incontinental Hotel. We'll start there. Let's take a ride in \" Gramps ,\" my hot rod! Hop in when you're ready.",starts={{npcID=225500,x=0.24,y=0.512,zoneID=15347}},ends={{npcID=225500,x=0.24,y=0.512,zoneID=15347}},coords={x=0.24,y=0.512,source="quest_giver",zoneID=15347},questType="standard"},
[83097] = {id=83097,name="Cinder and Storm",level=68,requiredLevel=68,faction="both",expansion=10,zoneID=15522,description="The wild creatures here have stunning properties. I wonder what might happen if I combine them? Be on the lookout for Bottled Storm and Burning Cinderbee Setae . I'll reward you generously if you can bring me some samples. Oh, and if you gather them yourself, mind that you don't get burned. Or zapped. Or both.",starts={{npcID=219083,x=0.544,y=0.574,zoneID=14771}},ends={{npcID=219083,x=0.544,y=0.574,zoneID=14771}},coords={x=0.544,y=0.574,source="quest_giver",zoneID=14771},questType="standard"},
[83098] = {id=83098,name="Snap and Crackle",level=68,requiredLevel=68,faction="both",expansion=10,zoneID=14771,description="Do you have a moment? I'm looking for some materials with an edge. Something sharp and with a bit of sizzle. If you can find me Honed Bone Shards and Thunderous Hide , I'd be more than happy to compensate you.",starts={{npcID=219083,x=0.544,y=0.574,zoneID=14771}},ends={{npcID=219083,x=0.544,y=0.574,zoneID=14771}},coords={x=0.544,y=0.574,source="quest_giver",zoneID=14771},questType="standard"},
[83099] = {id=83099,name="Mergers and Acquisitions",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14717,description="When the nerubians launched their attack on my meadery, they left it a burnt-out husk. Adelgonn promised to rebuild it, but I got impatient and accepted the Venture Co.'s offer to help with its \"restructuring.\" But now, it's clear they had their own agenda. Blasted goblins have taken over, and they're driving the place into the ground. They've ramped up production to unsafe levels, pushing the cinderbees and our equipment to their limits. Please help fix this, .",starts={{npcID=216088,zoneID=15103},{npcID=226409,x=0.756,y=0.434,zoneID=14717}},ends={{npcID=216088,zoneID=15103},{npcID=226409,x=0.756,y=0.434,zoneID=14717}},coords={x=0.756,y=0.434,source="quest_giver",zoneID=14717},questType="dungeon"},
[83100] = {id=83100,name="Cracking the Shell",level=68,requiredLevel=68,faction="both",expansion=10,zoneID=14771,description="Welcome! You wouldn't believe the amount of materials we go through up here, and not just the rare stuff! We could always do with more Gloom Chitin . If you find some, bring it to me. I'll see to it you get paid.",starts={{npcID=219083,x=0.544,y=0.574,zoneID=14771}},ends={{npcID=219083,x=0.544,y=0.574,zoneID=14771}},coords={x=0.544,y=0.574,source="quest_giver",zoneID=14771},questType="standard"},
[83102] = {id=83102,name="Bismuth is Business",level=68,requiredLevel=68,faction="both",expansion=10,zoneID=14771,description="Do you know the backbone of a good mining operation? It's not the rare, flashy ores. It's good, common Bismuth . And we don't have nearly enough! Wherever you go, keep an eye out for Bismuth . Bring me as much as you can. Compensation is assured.",starts={{npcID=219097,x=0.526,y=0.526,zoneID=14771}},ends={{npcID=219097,x=0.526,y=0.526,zoneID=14771}},coords={x=0.526,y=0.526,source="quest_giver",zoneID=14771},questType="standard"},
[83103] = {id=83103,name="Acquiring Aqirite",level=68,requiredLevel=68,faction="both",expansion=10,zoneID=14717,description="You there! Have you heard of Aqirite ? Valuable, versatile, very often surrounded by nerubians. I need that ore, and I don't care how you get it. If a nerubian does try to stop you, give them a whack for me.",starts={{npcID=219097,x=0.526,y=0.526,zoneID=14771}},ends={{npcID=219097,x=0.526,y=0.526,zoneID=14771}},coords={x=0.526,y=0.526,source="quest_giver",zoneID=14771},questType="standard"},
[83104] = {id=83104,name="Identifying Ironclaw",level=68,requiredLevel=68,faction="both",expansion=10,zoneID=14717,description="I sent a team to mine some Ironclaw Ore , they said they didn't see any. Can you believe that? It's a blasted great claw coming out of the ground! I'm not sending them again. I trust you'll know Ironclaw Ore when you see it. Bring it to me, and you'll be rewarded.",starts={{npcID=219097,x=0.526,y=0.526,zoneID=14771}},ends={{npcID=219097,x=0.526,y=0.526,zoneID=14771}},coords={x=0.526,y=0.526,source="quest_giver",zoneID=14771},questType="standard"},
[83105] = {id=83105,name="Rush-order Requisition",level=68,requiredLevel=68,faction="both",expansion=10,zoneID=14717,description="Good to see you, I've got work. The blacksmiths just sent a last-minute requisition for rare ores. Gravel-munching hammer-heavers, would it kill them to plan ahead? Well, I'm sure you can handle it. Looks like you'll need to track down Aqirite and Ironclaw Ore .",starts={{npcID=219097,x=0.526,y=0.526,zoneID=14771}},ends={{npcID=219097,x=0.526,y=0.526,zoneID=14771}},coords={x=0.526,y=0.526,source="quest_giver",zoneID=14771},questType="standard"},
[83106] = {id=83106,name="Null Pebble Excavation",level=68,requiredLevel=68,faction="both",expansion=10,zoneID=14717,description="Ever seen a Null Stone ? Well, you will. They're rare, but we know how to put them to good use. Don't worry, I only need a couple. While you're at it, pick up any Bismuth you find. You can never have enough Bismuth .",starts={{npcID=219097,x=0.526,y=0.526,zoneID=14771}},ends={{npcID=219097,x=0.526,y=0.526,zoneID=14771}},coords={x=0.526,y=0.526,source="quest_giver",zoneID=14771},questType="standard"},
[83108] = {id=83108,name="Daily Diagnostics",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14883,description="It is my duty and honor to take diagnostic readings every day. I determine the output and efficiency of the Stonevault's great machines. The burden is mine. Describing complication: now that skardyn have overrun the Stonevault, I cannot reach my machines! Solution proposed: I have heard that you are a hero of great renown. Please go in and gather today's readings for me. Timing will be critical in the event anything goes wrong. Awaiting confirmation.",starts={{npcID=225533,x=0.472,y=0.316,zoneID=14795}},ends={{npcID=225533,x=0.472,y=0.316,zoneID=14795}},coords={x=0.472,y=0.316,source="quest_giver",zoneID=14795},questType="dungeon"},
[83109] = {id=83109,name="The Grimla Express",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Next stop, Tailgate Park. Bilgewater Cartel used to be in charge there, but Gallywix had other plans. Now the Darkfuse act like they own the place and the Bilgewater... Well, they do the best they can. I'm not sure who runs it now, if anyone does.",starts={{npcID=225500,x=0.24,y=0.512,zoneID=15347}},ends={{npcID=229246,x=0.452,y=0.422,zoneID=15347}},coords={x=0.24,y=0.512,source="quest_giver",zoneID=15347},questType="standard"},
[83110] = {id=83110,name="Deliver Equipment",level=80,requiredLevel=80,faction="none",expansion=10,questType="standard"},
[83113] = {id=83113,name="Recover Tools",level=80,requiredLevel=80,faction="none",expansion=10,questType="standard"},
[83114] = {id=83114,name="Red Tape",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="First it was just Black Blood, now ethereals? I don't know how all this squares, but we need help if we wanna find out. Orweyna left to get Alleria a while ago. We should head over to Slam Central Station to see if they've made it down here yet.",starts={{npcID=229236,x=0.424,y=0.514,zoneID=15347}},ends={{npcID=225570,x=0.18,y=0.508,zoneID=15347}},coords={x=0.424,y=0.514,source="quest_giver",zoneID=15347},questType="standard"},
[83115] = {id=83115,name="In the Mix",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="I don't like thinkin' that Noggenfogger's part of this, but the only way we'll know is if we go and talk to him. Steamwheedle's headquarters is probably a good place to start lookin' for him. We'll give him a chance to explain himself. If it's a misunderstanding, or he's just gotten himself into trouble, I need to know.",starts={{npcID=225570,x=0.18,y=0.508,zoneID=15347}},ends={{npcID=225625,x=0.274,y=0.71,zoneID=15347}},coords={x=0.18,y=0.508,source="quest_giver",zoneID=15347},questType="standard"},
[83116] = {id=83116,name="Potion Commotion",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="It really is great to see you and Gazlowe! I was just thinkin' about how much I wanted to see you both on my birthday. A day when I'm under no forms of duress or coercion whatsoever! N-None at all. I'll tell you whatever I can if you get rid of them.",starts={{npcID=225624,x=0.274,y=0.71,zoneID=15347}},ends={{npcID=225625,x=0.274,y=0.71,zoneID=15347}},coords={x=0.274,y=0.71,source="quest_giver",zoneID=15347},questType="standard"},
[83117] = {id=83117,name="Chasing a Lead",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Venture doesn't exactly have a history of being an upstanding cartel. Their loyalties can be bought cheap, and they don't got qualms about means justifyin' ends. We knew they was working with Gallywix, we just didn't know how deep they were in with him. Let's go check out those kaja'mite supply lines. No time to lose.",starts={{npcID=225625,x=0.274,y=0.71,zoneID=15347}},ends={{npcID=225635,x=0.46,y=0.788,zoneID=15347}},coords={x=0.274,y=0.71,source="quest_giver",zoneID=15347},questType="standard"},
[83118] = {id=83118,name="Check the Schedule",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="If there's one thing Venture does keep in order, it's their paperwork. They're real particular with dividing their workforce and keepin' everything on schedule. They're efficient, I'll give 'em that. Up ahead is one of their scrapyards. They should have schedules posted around the place for Venture employees to record their hours worked and see what they got comin' up. Grab as many as you can find. We'll check out Venture's headquarters in the meantime.",starts={{npcID=225635,x=0.46,y=0.788,zoneID=15347}},ends={{npcID=225639,x=0.532,y=0.71,zoneID=15347}},coords={x=0.46,y=0.788,source="quest_giver",zoneID=15347},questType="standard"},
[83119] = {id=83119,name="It's Worth a Shot",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Venture Co. has a pretty bad track record, but not everyone workin' for the cartel is bad news. Some of us are tryin' to make ends meet. Maybe we can talk sense into some of 'em. Less Venture workers means less people doin' Gallywix's dirty work. Venture Co. employs a lot of non-goblins, so no one will question you bein' around as long as you've got a uniform on. I've got a spare that will probably, mostly, sorta fit you. See if you can get 'em to quit. If they start a fight, do what you gotta do.",starts={{npcID=225637,x=0.46,y=0.788,zoneID=15347}},ends={{npcID=225638,x=0.534,y=0.71,zoneID=15347}},coords={x=0.46,y=0.788,source="quest_giver",zoneID=15347},questType="standard"},
[83120] = {id=83120,name="Stealing the Keys",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="If you gotta get to a confidential work site like the Kaja'Coast, you gotta check out a punch card from Krome's office up here. Lead Foreman Krome is one of the big bosses who organizes how Venture's workforce gets split up. Should be easy enough for Renzik to slip in and grab the punch card, but you'll need to take care of Krome and his guard hyena. If we're gettin' to the Kaja'Coast, let's do it without becomin' chew toys first, yeah?",starts={{npcID=225638,x=0.534,y=0.71,zoneID=15347}},ends={{npcID=225639,x=0.532,y=0.71,zoneID=15347}},coords={x=0.534,y=0.71,source="quest_giver",zoneID=15347},questType="standard"},
[83121] = {id=83121,name="Asset Management",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=8499,description="I took a quick look inside that mine up ahead while you were gone. Looks like they've got Venture Co. mining out all the kaja'mite and bringin' it down to the beach. It's gettin' packaged up down there, but I couldn't tell where it was goin' afterward. We need to cut off the supply at the origin. Deal with the supervisors in the mine, and I'm willin' to bet their workers will have enough sense to run afterward.",starts={{npcID=228132,x=0.22,y=0.576,zoneID=8499}},ends={{npcID=228132,x=0.22,y=0.576,zoneID=8499}},coords={x=0.22,y=0.576,source="quest_giver",zoneID=8499},questType="standard"},
[83122] = {id=83122,name="Crashing the Market",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=8499,description="When I left the Bilgewater Cartel in charge of the kaja'mite mining in Zuldazar, it was clean and safe. Well, cleaner and safer. We made a lot of deals with the Zandalari to secure that. So not only is Gallywix steppin' on our territory, but he's threatenin' the respect and trust we earned by letting Venture make a mess of this operation. Blow up the kaja'mite stockpiles you find in that mine. I don't want any dishonest kaja'mite goin' anywhere, no matter who's buyin' or sellin'.",starts={{npcID=225648,x=0.22,y=0.576,zoneID=8499}},ends={{npcID=225648,x=0.22,y=0.576,zoneID=8499}},coords={x=0.22,y=0.576,source="quest_giver",zoneID=8499},questType="standard"},
[83123] = {id=83123,name="A Miner Mistake",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=8499,description="Undermine . Below the full address of the employer, there is a header stamped in red ink.> GALLYWIX'S SECRET KAJA'MITE WAREHOUSE - INTERNAL ONLY DO NOT ACTUALLY PRINT THAT",starts={{npcID=452685,x=0.227,y=0.603,zoneID=8499}},ends={{npcID=225648,x=0.22,y=0.576,zoneID=8499}},coords={x=0.227,y=0.603,source="quest_giver",zoneID=8499},questType="standard"},
[83124] = {id=83124,name="B.I.R.D. Watching",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=8499,description="I took those parts you collected and hotwired the components into some new machinery, then stuffed it back into the bot. Now it can be piloted usin' this remote control. The remote also lets us see and hear anything the bot does. I don't think we're gonna learn what we need to just by killin'. We're gonna need to beat Gallywix at his own game and spy on his workers. You wanna do us the honors, ? I'll talk you through it.",starts={{npcID=225648,x=0.22,y=0.576,zoneID=8499}},ends={{npcID=225648,x=0.22,y=0.576,zoneID=8499}},coords={x=0.22,y=0.576,source="quest_giver",zoneID=8499},questType="standard"},
[83125] = {id=83125,name="Price Hike",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="So Noggenfogger wasn't lyin'. Darkfuse strongarmed Steamwheedle into figurin' out how to make kaja'mite contain Black Blood. Looks like that's how they've been gettin' it into weapons without blowin' themselves up--or worse. These stakes are higher than I thought, and I get the feeling this goes even deeper. I need to get Noggenfogger somewhere safe. You and Renzik take out that overseer, then meet us back at Steamwheedle.",starts={{npcID=225648,x=0.22,y=0.576,zoneID=8499}},ends={{npcID=225667,x=0.292,y=0.694,zoneID=15347}},coords={x=0.22,y=0.576,source="quest_giver",zoneID=8499},questType="standard"},
[83126] = {id=83126,name="Ethereal Invasion",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Just moments ago, these ethereals appeared out of nowhere. They attacked Noggenfogger and attempted to haul him off. I made short work of the first attackers, but they keep coming. Now they're searching every building and killing anyone who stands in their way. I don't know what they're looking for, but we can't allow them to continue this slaughter. Let's teach them a lesson.",starts={{npcID=225669,x=0.294,y=0.694,zoneID=15347},{npcID=232660,x=0.33,y=0.688,zoneID=15347}},ends={{npcID=232660,x=0.33,y=0.688,zoneID=15347}},coords={x=0.294,y=0.694,source="quest_giver",zoneID=15347},questType="standard"},
[83127] = {id=83127,name="Racing the Clock",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="We were out of time before, but now we're REALLY out of time. The ethereals are gonna beat us to the warehouse, but we might still be able to beat them to the Dark Heart. C'mon!",starts={{npcID=229261,x=0.27,y=0.718,zoneID=15347}},ends={{npcID=225719,x=0.556,y=0.636,zoneID=15347}},coords={x=0.27,y=0.718,source="quest_giver",zoneID=15347},questType="standard"},
[83128] = {id=83128,name="Get Our People Out",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="While Alleria looks for the Dark Heart, we need to look for the hostages. Here's hoping they're still safe. They left some ambushers behind, but we got the best of SI:7 on our side. You think you see one of them hidin', point them out to Renzik. He'll toss a smoke bomb. That'll flush 'em out and stun 'em, so we can turn the tables.",starts={{npcID=225719,x=0.556,y=0.636,zoneID=15347}},ends={{npcID=225730,x=0.584,y=0.594,zoneID=15347}},coords={x=0.556,y=0.636,source="quest_giver",zoneID=15347},questType="standard"},
[83129] = {id=83129,name="Nowhere Left to Hide",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="This barricade looks intentional. Hobart said Gallywix went off to a cave, and I'd say this sure looks like one. Gallywix has to have the Dark Heart in there. Help me blast this barricade open and get ready to fight.",starts={{npcID=225730,x=0.584,y=0.594,zoneID=15347}},ends={{npcID=234048,x=0.616,y=0.624,zoneID=15347}},coords={x=0.584,y=0.594,source="quest_giver",zoneID=15347},questType="standard"},
[83130] = {id=83130,name="Sour Victory",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="That's it. It's over. We're done. Gallywix lost, but the ethereals got the Dark Heart. Alleria needs to track them down. We need to check on everyone back at Bilgewater Flats, and then we need to go. There's nothin' else in this town for us.",starts={{npcID=234048,x=0.616,y=0.624,zoneID=15347}},ends={{npcID=225756,x=0.388,y=0.248,zoneID=15347}},coords={x=0.616,y=0.624,source="quest_giver",zoneID=15347},questType="standard"},
[83137] = {id=83137,name="When Opportunity Explodes",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,description="There ya are, ! Have you heard the latest news? There's a big hole blown in the side of the mountain out by Opportunity Point in the Ringing Deeps . There were opportunistic folks taking it over, and now there's even more. We'd better hurry over there.",starts={{npcID=225571,x=0.422,y=0.27,zoneID=14771}},ends={{npcID=227531,x=0.63,y=0.784,zoneID=14795}},coords={x=0.422,y=0.27,source="quest_giver",zoneID=14771},questType="standard"},
[83138] = {id=83138,name="End of the Day",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Sprinkle and Seahorn are fine. Marin and Hobart are recoverin'. We didn't stop Gallywix, but at least the Dark Heart is... well, it's not in his hands. Which means we can leave. Nothin' left for us to do here. Finish up whatever business you've got in Undermine . I need to get out of this damn place.",starts={{npcID=225756,x=0.388,y=0.248,zoneID=15347}},ends={{npcID=225757,x=0.398,y=0.242,zoneID=15347}},coords={x=0.388,y=0.248,source="quest_giver",zoneID=15347},questType="standard"},
[83139] = {id=83139,name="Mixed Messages",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,description="Lots of these workers are headed to a Venture camp just down the road. That's a great first stop for information. We'll pay the tollbooth fee. It's best to just play along for now.",starts={{npcID=227531,x=0.63,y=0.784,zoneID=14795}},ends={{npcID=225587,x=0.658,y=0.754,zoneID=14795}},coords={x=0.63,y=0.784,source="quest_giver",zoneID=14795},questType="standard"},
[83140] = {id=83140,name="Hostile Work Environment",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,description="Bigger and more dangerous than Opportunity Point? These south mines sound real bad, even if ya have a high tolerance for bad working conditions. But what are they mining? Something here is worth big money. We'll need to check it out. I'll head past the big Darkfuse camp with Renzik, stealth mode. Make a big distraction for us, will ya? I'm sure you can slow down production while you're over there.",starts={{npcID=225587,x=0.658,y=0.754,zoneID=14795}},ends={{npcID=225587,x=0.658,y=0.754,zoneID=14795},{npcID=225597,x=0.724,y=0.792,zoneID=14795}},coords={x=0.658,y=0.754,source="quest_giver",zoneID=14795},questType="standard"},
[83141] = {id=83141,name="Miner Investigations",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,description="What \"riches\" are they mining out of the earth? Could this deep digging be related to my visions? Surely these goblins would not find value in something like Black Blood. We must get a closer look. Together we will gain insight into their operation.",starts={{npcID=227691,x=0.658,y=0.754,zoneID=14795}},ends={{npcID=227688,x=0.724,y=0.792,zoneID=14795}},coords={x=0.658,y=0.754,source="quest_giver",zoneID=14795},questType="standard"},
[83142] = {id=83142,name="Order of Magnitude",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,starts={{npcID=456062,x=0.721,y=0.784,zoneID=14795}},ends={{npcID=225587,x=0.658,y=0.754,zoneID=14795},{npcID=225597,x=0.724,y=0.792,zoneID=14795}},coords={x=0.721,y=0.784,source="quest_giver",zoneID=14795},questType="standard"},
[83143] = {id=83143,name="Good Honest Work",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,description="You're new here, right? I can tell by your questions. But don't worry, Zirdo 's your best pal! I'll give you a personalized tour. Gutterville, the Venture Company town, is just south down the road. It'll be informative and interactive. You can't ask for a better experience, trust me!",starts={{npcID=228017,x=0.724,y=0.792,zoneID=14795}},ends={{npcID=225596,x=0.718,y=0.804,zoneID=14795}},coords={x=0.724,y=0.792,source="quest_giver",zoneID=14795},questType="standard"},
[83144] = {id=83144,name="Bloodletting",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,description="The land aches underfoot. These pipes carry Black Blood north in a massive volume! I've never seen the land become infected this rapidly. Clear away the rot--perhaps we can save it yet. I'll go after the structures. Point out weak spots as you find them and I will focus our assault!",starts={{npcID=225596,x=0.718,y=0.804,zoneID=14795}},ends={{npcID=228034,x=0.696,y=0.84,zoneID=14795}},coords={x=0.718,y=0.804,source="quest_giver",zoneID=14795},questType="standard"},
[83145] = {id=83145,name="Paranoia Prevention",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,description="What information is Gallywix after here in Gutterville? Let's see if some of these goblins will give us a hint. Let's start with any Bilgewater goblins we can find.",starts={{npcID=225597,x=0.724,y=0.792,zoneID=14795}},ends={{npcID=232491,x=0.722,y=0.822,zoneID=14795}},coords={x=0.724,y=0.792,source="quest_giver",zoneID=14795},questType="standard"},
[83146] = {id=83146,name="Pamsy's Prized Pump",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,description="I got a team of engineers. All of them got families. They keep having horrible accidents and infections from the Black Blood. I just couldn't stand another death. I opened the wall. I wanted it to bring us some hope. You show up and want to stop the Black Blood. It doesn't do anythin' good to stop these pipes up here. We gotta get to the pump station. So, my crew and the pumps? They're all at the same station. But we should hurry.",starts={{npcID=232491,x=0.722,y=0.822,zoneID=14795}},ends={{npcID=228214,x=0.706,y=0.886,zoneID=14795}},coords={x=0.722,y=0.822,source="quest_giver",zoneID=14795},questType="standard"},
[83147] = {id=83147,name="Bloody Business",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,description="The horrors of the Black Blood here cannot be underestimated. The strength of it in this place is causing my visions to feel distant, like odd whispers. Kill the manifestations of this rot, before they grow stronger.",starts={{npcID=228894,x=0.706,y=0.886,zoneID=14795}},ends={{npcID=228894,x=0.706,y=0.886,zoneID=14795}},coords={x=0.706,y=0.886,source="quest_giver",zoneID=14795},questType="standard"},
[83148] = {id=83148,name="X-Treme Chill",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,description="Pamsy and I came up with an idea. Since we can't access the controls, and we can't blow it up, what if we freeze the pump station? Stay with me! Pamsy mentioned that a lot of the machines up north are overheating lately, because all the coolant is being used down south. And it's even harder to get, because the blood slimes eat it. What if we found all of that coolant supply and dumped it into the pump station? We put the whole operation on ice, and it'd take ages to fix!",starts={{npcID=225598,x=0.704,y=0.886,zoneID=14795}},ends={{npcID=225598,x=0.704,y=0.886,zoneID=14795}},coords={x=0.704,y=0.886,source="quest_giver",zoneID=14795},questType="standard"},
[83149] = {id=83149,name="Avenge Them",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,description="I followed Zirdo's trail south. I found a nasty piece o' work named Gozzic Cogcrane pushin' workers around and talking about \"another lesson.\" Zirdo must have snitched to this Gozzic guy, but I need to confirm it. I think this Gozzic will have the proof on him. Gozzic could've given the orders, but lookin' at that bloody shredder and the marks on Pamsy's crew, I'm sure he got involved personally. You should do the same. Kill Gozzic and check him for any sign Zirdo got word to him.",starts={{npcID=225599,x=0.702,y=0.894,zoneID=14795}},ends={{npcID=225599,x=0.702,y=0.894,zoneID=14795}},coords={x=0.702,y=0.894,source="quest_giver",zoneID=14795},questType="standard"},
[83150] = {id=83150,name="Expanding the Plan",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,description="Here's the plan. If we just freeze the outside, it'll all melt in a bit and go back to normal. But we got Orweyna. She can target cracks and leaks in the pipes so the coolant can get inside and really muck things up. Since you gathered all the canisters, I think you should get the honor of freezing the pipe solid. Pamsy has a rocketboard, and you'll be able to dispense icy justice down upon the station's key areas. Follow Orweyna!",starts={{npcID=225598,x=0.704,y=0.886,zoneID=14795}},ends={{npcID=228887,x=0.702,y=0.896,zoneID=14795}},coords={x=0.704,y=0.886,source="quest_giver",zoneID=14795},questType="standard"},
[83151] = {id=83151,name="Down Undermine",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="We've done what we could here. It's time to get a look at Undermine. Pamsy 's got a contact, a Venture goblin named Grimla. We can start there when we arrive. Let's get Gazlowe and get going. Undermine's not the kinda problem you solve with a knife. We need someone like Gazlowe on board for this. You know, the builder and leader type.",starts={{npcID=225599,x=0.702,y=0.894,zoneID=14795}},ends={{npcID=225661,x=0.24,y=0.51,zoneID=15347}},coords={x=0.702,y=0.894,source="quest_giver",zoneID=14795},questType="standard"},
[83152] = {id=83152,name="Magmanagement",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="As if the pipe going down wasn't enough, a horde of magmatic elementals burst out when it failed. We can't risk sending anyone else down to attempt repairs while the area is overrun, but that magma is vital to powering the whole Deeps. If you are capable, clear them out so we can get that magma flowing again.",starts={{npcID=225582,x=0.41,y=0.214,zoneID=14795}},ends={{npcID=225582,x=0.41,y=0.214,zoneID=14795}},coords={x=0.41,y=0.214,source="quest_giver",zoneID=14795},questType="standard"},
[83153] = {id=83153,name="Sampling Steam",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="The effects of the magmatic buildup are clear to see, but what we still do not understand is the root cause. In order to determine it, and prevent it in the future, I need samples of the volcanic gases you can see bursting from the ground. Fresh samples. Very fresh. You're going to have to stand in them as they erupt in order to gather what I need.",starts={{npcID=225583,x=0.41,y=0.214,zoneID=14795}},ends={{npcID=225583,x=0.41,y=0.214,zoneID=14795}},coords={x=0.41,y=0.214,source="quest_giver",zoneID=14795},questType="standard"},
[83154] = {id=83154,name="Knicknack's Knickknacks",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,description="Not fair! Not fair! Knicknack collect many shiny things over long life. But now stupid wax for brains Candleclaws push out Knicknack and family. Shiny things all left behind! Here, goblin friend helped made list of all my treasures inside Darkflame Cleft. You go take back!",starts={{npcID=225555,x=0.464,y=0.302,zoneID=14795}},ends={{npcID=225555,x=0.464,y=0.302,zoneID=14795}},coords={x=0.464,y=0.302,source="quest_giver",zoneID=14795},questType="dungeon"},
[83155] = {id=83155,name="Tired of Tripping",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="All that's between us and the juiciest excavation site I've ever seen is a couple of moles and a leggy deer. Sorry, getting ahead of myself. See these shredders? State of the art in the field of maiming and killing. And they keep getting stuck in holes! Listen, I'm as ecologically conscientious as the next goblin, but these moles have got to go. I'm gonna need you to give these hardheads a hard time. And if you see any of my crew, help 'em out, wontcha?",starts={{npcID=225608,x=0.638,y=0.792,zoneID=14795}},ends={{npcID=225608,x=0.638,y=0.792,zoneID=14795}},coords={x=0.638,y=0.792,source="quest_giver",zoneID=14795},questType="standard"},
[83159] = {id=83159,name="A Little Off the Top",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="Ever seen a deepstrider before? This one sure ain't happy to see us. Made quick work of the shredders that made it past the moles. Real shame, those pilots are gonna have to work overtime to pay off the damages. Now if someone were to take care of it and bring back something as proof, well, I'm sure there'd be a nice payday.",starts={{npcID=225608,x=0.638,y=0.792,zoneID=14795}},ends={{npcID=226336,x=0.638,y=0.792,zoneID=14795}},coords={x=0.638,y=0.792,source="quest_giver",zoneID=14795},questType="standard"},
[83160] = {id=83160,name="Cinderbrew Reserve",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="Trade may have been restricted, but I'll calcify before I let my Cinderbrew Reserve fall into the hands of these stripped screws or go up when some elemental looks at it funny. The inspectors are watching me, stranger, so I can't go fetch it myself, but they won't be paying any special attention to you. I left it behind the desk in my old office, down below. Just don't get too close to an enforcer or they'll confiscate any cinderbrew you're carrying and I'll be left with nothing to drink.",starts={{npcID=225616,x=0.414,y=0.224,zoneID=14795}},ends={{npcID=225616,x=0.414,y=0.224,zoneID=14795}},coords={x=0.414,y=0.224,source="quest_giver",zoneID=14795},questType="standard"},
[83162] = {id=83162,name="Put it Back, Put it Back!",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="It's going to ruin everything! Who wants to visit a resort with a thirty-foot tall ghost-deer? Ok, no need to panic. It's probably just a little miffed you took its skull. First, you gotta get rid of some of these slimes. Then, get that skull out of here. The farther the better. Oh man, they're gonna get ectoplasm in the hot pools!",starts={{npcID=226336,x=0.638,y=0.792,zoneID=14795}},ends={{npcID=225608,x=0.638,y=0.792,zoneID=14795}},coords={x=0.638,y=0.792,source="quest_giver",zoneID=14795},questType="standard"},
[83163] = {id=83163,name="Split Venture",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="We're headed to my home turf next, Venturewood. It's next to the Heaps. The Venture Company is mostly on board for Gallywix. That means a lot of the top brass are as dirty as him. Watch your step. But there are some good folks there too. Like Pamsy and her crew. The little guy at Venture gets it rough. Everyone thinks of Venture Co. as just the baddies, so no one looks after them. But I gotta try right? Hop in the hot rod, I'll show you what I mean.",starts={{npcID=229246,x=0.452,y=0.422,zoneID=15347}},ends={{npcID=229247,x=0.434,y=0.606,zoneID=15347}},coords={x=0.452,y=0.422,source="quest_giver",zoneID=15347},questType="standard"},
[83164] = {id=83164,name="City of Threads: Splice the Splicer",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14752,description="\"Ascension\" is no true evolution. It is defilement. It is doom. And Ansurek further etches that doom in stone with each passing day. If we bring down the Transformatory, then we can potentially rid Azj-Kahet of these abominations for good. Izo the Grand Splicer is Ansurek's chosen overseer of the Ascension process. Cut that wretch's head from her body, and perhaps these mutations will cease.",starts={{npcID=224733,x=0.562,y=0.422,zoneID=14752}},ends={{npcID=224733,x=0.562,y=0.422,zoneID=14752}},coords={x=0.562,y=0.422,source="quest_giver",zoneID=14752},questType="dungeon"},
[83165] = {id=83165,name="Badly Behaved Bot",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="Go ahead, laugh. I would be as well if I didn't have such pressing business. My bot's foot clipped a nearby rock, spilled me out and then righted herself. Without me in the cockpit! I'm grounded while she floats there quite cheerfully. Can you believe it? Listen, if you are heading up to Shadowvein Point, will you let Kagfritha know that I'll be late for my shift? I need to wait for this hunk of metal to run out of fuel and dip low enough for me to get back in the driver's seat.",starts={{npcID=223759,x=0.602,y=0.57,zoneID=14795}},ends={{npcID=220417,x=0.622,y=0.468,zoneID=14795}},coords={x=0.602,y=0.57,source="quest_giver",zoneID=14795},questType="standard"},
[83166] = {id=83166,name="Ara-Kara, the City of Echoes: Harvest's End",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14752,description="You've seen it yourself, haven't you? The \"Black Blood,\" as we call it. We will not stand idle any longer. Not while Ansurek mutilates, drills, and exsanguinates our precious land for the last, fetid dribbles of the old gods' death rattle. Seek out the old city beneath us--Ara-Kara, The City of Echoes. You will receive a handsome bounty should you slay the crony in charge of the excavation. Her people call her Ki'katal, the Harvester.",starts={{npcID=224733,x=0.562,y=0.422,zoneID=14752}},ends={{npcID=224733,x=0.562,y=0.422,zoneID=14752}},coords={x=0.562,y=0.422,source="quest_giver",zoneID=14752},questType="dungeon"},
[83167] = {id=83167,name="Eyes from Above",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="That was rough, with Nikki. And worse, those Darkfuse spy-copters saw everything. Feels like we can't get away from all the spies, don't it? The last thing Venture needs is Gallywix thinking these workers ain't loyal 'cause they got caught on footage during one of Nikki's tantrums. We don't want a repeat of what happened to my last crew. Go take the footage from the spy-copters. They usually lurk around the workshops, or follow Venture workers around.",starts={{npcID=225618,x=0.436,y=0.608,zoneID=15347}},ends={{npcID=225618,x=0.436,y=0.608,zoneID=15347}},coords={x=0.436,y=0.608,source="quest_giver",zoneID=15347},questType="standard"},
[83168] = {id=83168,name="A Trail of Black Blood",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="While you have been getting familiar with the state of Undermine , I have been tracking our prey. The presence of Black Blood is everywhere, hidden behind noisy distractions. But this city cannot fool me. I discovered a Black Blood shipment at a place called Hovel Hill, but there were machines guarding it. We should go together.",starts={{npcID=225659,x=0.434,y=0.608,zoneID=15347}},ends={{npcID=229233,x=0.33,y=0.478,zoneID=15347}},coords={x=0.434,y=0.608,source="quest_giver",zoneID=15347},questType="standard"},
[83169] = {id=83169,name="Long Way from Booty Bay",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="There is no doubt about it. These shipments have Blackwater Cartel written all over them... literally. The Black Blood comes in here and then Blackwater takes it somewhere in the city by couriers. So if we want to find out where, we go right to the top-- Baron Revilgaz . Grimla mentioned Revilgaz has a temporary set up nearby, here in Hovel Hill. Let's go pay him a visit. The ethereal thing will have to wait.",starts={{npcID=229233,x=0.33,y=0.478,zoneID=15347}},ends={{npcID=225686,x=0.308,y=0.394,zoneID=15347}},coords={x=0.33,y=0.478,source="quest_giver",zoneID=15347},questType="standard"},
[83170] = {id=83170,name="Not Again!",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="The Darkfuse are moving into Hovel Hill. It's the same thing they did at Blackwater Marina. Once they move in, they start pushing the locals around. Sometimes they just make 'em go away. It ain't right. I want to fight back, but my hands are tied. If an outsider showed up and started making trouble, that'd be a different story.",starts={{npcID=225686,x=0.308,y=0.394,zoneID=15347}},ends={{npcID=225686,x=0.308,y=0.394,zoneID=15347}},coords={x=0.308,y=0.394,source="quest_giver",zoneID=15347},questType="standard"},
[83171] = {id=83171,name="Eye Sores for Sore Eyes",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="They call them recruitment posters, but that ain't all they're for. They're there to remind everyone the Darkfuse are in charge and can do whatever they want. If me or one of the locals rip 'em down, it goes bad for us. But the Darkfuse hate you anyway. If you torched all the posters, I would owe you one.",starts={{npcID=225686,x=0.308,y=0.394,zoneID=15347}},ends={{npcID=225686,x=0.308,y=0.394,zoneID=15347}},coords={x=0.308,y=0.394,source="quest_giver",zoneID=15347},questType="standard"},
[83172] = {id=83172,name="Black Blood Baton Pass",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Blackwater is just one step on the journey, and they like to keep this stuff moving. Revilgaz has his people take it from the station, hide it for a bit, then deliver it to the drop sites. The drop sites change, but the current one is a depot in the Heaps. We're gonna check it out and find out where the Black Blood goes from there. He says it's guarded, so look for us out near the edge.",starts={{npcID=229242,x=0.308,y=0.394,zoneID=15347}},ends={{npcID=229243,x=0.616,y=0.718,zoneID=15347}},coords={x=0.308,y=0.394,source="quest_giver",zoneID=15347},questType="standard"},
[83173] = {id=83173,name="Clearing Out the Depot",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="The Heaps are crawling with guards. We've got an opportunity to disrupt the Black Blood operation in Undermine and we should take it. We can't stop all the Black Blood from getting around the city, but we can clear out some guards and smash some shipments. Mess them up enough to disrupt things. Every little bit helps.",starts={{npcID=229243,x=0.616,y=0.718,zoneID=15347}},ends={{npcID=229243,x=0.616,y=0.718,zoneID=15347}},coords={x=0.616,y=0.718,source="quest_giver",zoneID=15347},questType="standard"},
[83174] = {id=83174,name="Our Good Pal",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Our old pal Zirdo 's back. It looks like he's been promoted to Overseer of the Heaps, keeping track of the Black Blood shipments. We owe him some payback for sellin' us out in Gutterville. He got a lot of good goblins killed to get on Gallywix's good side. Give the little snitch what he deserves.",starts={{npcID=229235,x=0.616,y=0.718,zoneID=15347}},ends={{npcID=229235,x=0.616,y=0.718,zoneID=15347}},coords={x=0.616,y=0.718,source="quest_giver",zoneID=15347},questType="standard"},
[83175] = {id=83175,name="Another Piece of the Puzzle",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Undermine . Multiple entries in the ledger stick out as odd: - One thousand units for Secret Project, Deliver to Secret Project Site. - Twenty units for Developmental Ammunition, Deliver via Courier. Transfers approved by Noggenfogger of Steamwheedle.>",starts={{npcID=500619,x=0.656,y=0.806,zoneID=15347}},ends={{npcID=229235,x=0.616,y=0.718,zoneID=15347}},coords={x=0.656,y=0.806,source="quest_giver",zoneID=15347},questType="standard"},
[83176] = {id=83176,name="Just a Hunch",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="It's time to sort out what to do next. This Noggenfogger business has Gazlowe on edge and we gotta move quickly to find out what's going on. Something's got me on edge too. We should get outta the Heaps fast. But let's make sure Gazlowe's on board.",starts={{npcID=229243,x=0.616,y=0.718,zoneID=15347}},ends={{npcID=229236,x=0.424,y=0.514,zoneID=15347}},coords={x=0.616,y=0.718,source="quest_giver",zoneID=15347},questType="standard"},
[83177] = {id=83177,name="Socialized Medicine",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14753,description="It has come to my attention that the most downtrodden residents of the Burrows have fallen prey to some sort of malady. Take this potion and dose the sick. This will strengthen the citizens and curtail further outbreak.",starts={{npcID=208782,x=0.528,y=0.462,zoneID=14753}},ends={{npcID=208782,x=0.528,y=0.462,zoneID=14753}},coords={x=0.528,y=0.462,source="quest_giver",zoneID=14753},questType="standard"},
[83178] = {id=83178,name="Rules and Consequences",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14753,description="I fear I have grown too brazen in my offerings of succor as of late. I seem to have attracted some untoward eyes. Be on guard. A veiled threat looms.",starts={{npcID=208782,x=0.528,y=0.462,zoneID=14753}},ends={{npcID=208782,x=0.528,y=0.462,zoneID=14753}},coords={x=0.528,y=0.462,source="quest_giver",zoneID=14753},questType="standard"},
[83181] = {id=83181,name="Best Friends, Same Ends",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="I saw the shipwright leave the cave and head down to the beach. She was accompanied by a formidable looking nerubian. The shipwright is the mastermind behind this entire operation. She knows precisely how the lumber is to be cut and what lumber is needed for their airships. The nerubians know this and likely assigned one of their best to protect her. If we can eliminate the shipwright, we can bring all of their carefully laid plans to ruin.",starts={{npcID=222363,x=0.66,y=0.238,zoneID=14717}},ends={{npcID=222363,x=0.66,y=0.238,zoneID=14717},{npcID=222366,x=0.654,y=0.204,zoneID=14717}},coords={x=0.66,y=0.238,source="quest_giver",zoneID=14717},questType="standard"},
[83194] = {id=83194,name="Under Fire",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="I'm only standing here because of Renzik. He didn't even think about it--he just...",starts={{npcID=225757,x=0.398,y=0.242,zoneID=15347}},ends={{npcID=225523,x=0.398,y=0.242,zoneID=15347}},coords={x=0.398,y=0.242,source="quest_giver",zoneID=15347},questType="standard"},
[83195] = {id=83195,name="Rally the People",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="No one's been stepped on harder by Gallywix than the Bilgewater Cartel. Plenty already want to rise up, but that ain't enough. We gotta show them what Gallywix has done and convince them that now is the time. Let's start with a headline. C'mon, pitch me. A big shot like you carries our message better than anyone else.",starts={{npcID=226660,x=0.486,y=0.408,zoneID=15347}},ends={{npcID=225866,x=0.51,y=0.36,zoneID=15347}},coords={x=0.486,y=0.408,source="quest_giver",zoneID=15347},questType="standard"},
[83196] = {id=83196,name="Disperse!",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Gallywix can't hide the truth, but he can beat us down until folks have no choice but to accept it. We ain't lettin' that happen again. You see someone hurting a Bilgewater goblin, return the favor.",starts={{npcID=226660,x=0.486,y=0.408,zoneID=15347}},ends={{npcID=225866,x=0.51,y=0.36,zoneID=15347}},coords={x=0.486,y=0.408,source="quest_giver",zoneID=15347},questType="standard"},
[83197] = {id=83197,name="Who Owns the Streets?",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Her! Nikki the Fixer, Venture Company's top enforcer. Renzik's blood is on her hands. I can't worry if she's got another bullet. We gotta go after her. You with me, ?",starts={{npcID=234551,x=0.51,y=0.358,zoneID=15347}},ends={{npcID=225868,x=0.584,y=0.33,zoneID=15347}},coords={x=0.51,y=0.358,source="quest_giver",zoneID=15347},questType="standard"},
[83198] = {id=83198,name="Backyard Navy",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Gallywix and his crew have been meddling in our business for too long. Look at what they're doing to my marina! So comfortable with their holdings that they're doing donuts on jetskis! It's time we introduce them to a little high seas firepower. Take this cannon and blow those Darkfuse vessels skimming our waters sky-high. After that, do me a favor and check up on the big guy, won't ya?",starts={{npcID=225868,x=0.584,y=0.33,zoneID=15347}},ends={{npcID=225870,x=0.638,y=0.174,zoneID=15347}},coords={x=0.584,y=0.33,source="quest_giver",zoneID=15347},questType="standard"},
[83199] = {id=83199,name="Been Savin' This One",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Listen , Sprinkle's been cooking something for a long time that I'm finally ready to cash in. A little alchemist's secret ingredient. Citrus! Delivers twice the kick of Noggenfogger's Restorative Elixirs at half the speed. Strengthens your bones, grows your muscles, does your taxes. The whole nine yards! Problem is, I've got nothing of the sort on hand. These resort types may have what you need. We've been saving this recipe for a heavy hitter. Make sure Seahorn's alright before cooking it up, yeah?",starts={{npcID=225867,x=0.584,y=0.33,zoneID=15347}},ends={{npcID=225870,x=0.638,y=0.174,zoneID=15347}},coords={x=0.584,y=0.33,source="quest_giver",zoneID=15347},questType="standard"},
[83200] = {id=83200,name="A Vast, Ye Swabs",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Urgh. I've been locked up for so long. In my anger, I got reckless. Whatever Noggenfogger gave ya, I promise not to squander. Get me back in the fight and we'll bring the full swell of Blackwater's might down on these invaders.",starts={{npcID=225870,x=0.638,y=0.174,zoneID=15347}},ends={{npcID=233296,x=0.638,y=0.174,zoneID=15347}},coords={x=0.638,y=0.174,source="quest_giver",zoneID=15347},questType="standard"},
[83201] = {id=83201,name="Expedited Delivery",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Blackwater can take the marina from here. But the people aren't safe with Black Blood that's already out there. Those flying transports must be taking the Black Blood somewhere under Venture Co. control. Commandeer one, and you might find Grimla. She was headed in that direction when we split up, shouting that a friend of hers was on the way.",starts={{npcID=235849,x=0.69,y=0.509,zoneID=15347}},ends={{npcID=225871,x=0.452,y=0.572,zoneID=15347}},coords={x=0.69,y=0.509,source="quest_giver",zoneID=15347},questType="standard"},
[83202] = {id=83202,name="Punching Up",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="The time for talking out our differences is over. I'm done second-guessing who is still standing with Gallywix. Some of Nikki's people are keeping these new weapons in production. So, we take them out. It makes cleaning up Venture Co. after all this is done way simpler too. Just be careful. Nikki won't stick her neck out for her lieutenants, but she'll take the chance to rig a fight against you.",starts={{npcID=225871,x=0.452,y=0.572,zoneID=15347}},ends={{npcID=225874,x=0.484,y=0.774,zoneID=15347}},coords={x=0.452,y=0.572,source="quest_giver",zoneID=15347},questType="standard"},
[83203] = {id=83203,name="Weapons Hot",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="The destructive impulses of those who harvest Azeroth for their own profit never cease to horrify me. But these weapons are like nothing that has come before. All containers of Black Blood must be overturned and destroyed. Weapons fueled by it crushed and dismantled. Those who wield it against others, put down. The people of this city, and this world, won't be safe until we do.",starts={{npcID=225873,x=0.452,y=0.574,zoneID=15347}},ends={{npcID=234728,x=0.484,y=0.774,zoneID=15347}},coords={x=0.452,y=0.574,source="quest_giver",zoneID=15347},questType="standard"},
[83204] = {id=83204,name="The Thingamajig",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Nikki's tech is powered by Black Blood. I know that because I worked on half of it. That also means I have an idea on how we might knock her out of the sky for long enough to take her out. No time for pre-production. We gotta build. Remember our flashy little hoverboard adventure? Ice is nice, eh? I'm thinkin' of a similar principle--the trash heap oughta have all the salvage we'll need to build this hypothetical thingamajig.",starts={{npcID=233390,x=0.484,y=0.774,zoneID=15347}},ends={{npcID=233390,x=0.484,y=0.774,zoneID=15347}},coords={x=0.484,y=0.774,source="quest_giver",zoneID=15347},questType="standard"},
[83205] = {id=83205,name="Production Halted",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Orweyna rubs her palms with dirt, then cracks her knuckles.> Now, we teach those who toy with Black Blood nature's wrath. I am eager to call upon the roots twisting through Azeroth. Join me. Unleash nature's fury as we did before. Let us destroy their prized stockpiles of Black Blood.",starts={{npcID=234728,x=0.484,y=0.774,zoneID=15347}},ends={{npcID=225876,x=0.564,y=0.678,zoneID=15347}},coords={x=0.484,y=0.774,source="quest_giver",zoneID=15347},questType="standard"},
[83206] = {id=83206,name="We Own the Streets",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="The trade princes ain't exactly been fair to the goblins here, so this can't be just another cartel war. The crowd needs to know they ain't fighting for Bilgewater or Steamwheedle. They're fightin' for Undermine . We need someone who ain't a cartel big shot to help rile 'em up and keep 'em safe. Do whatever it takes to get them to the Gallagio and show these goblins this is their city.",starts={{npcID=230268,x=0.564,y=0.674,zoneID=15347}},ends={{npcID=225878,x=0.564,y=0.446,zoneID=15347}},coords={x=0.564,y=0.674,source="quest_giver",zoneID=15347},questType="standard"},
[83207] = {id=83207,name="My Top Gal",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="We've got Gallywix backed against the wall. Seeing Undermine and its people he's kept under his thumb finally rising up. He thinks this \"Fixer\" of his will keep him safe. Let's show Gallywix, Nikki, and everyone else that things are different this time. Watch this.",starts={{npcID=225878,x=0.564,y=0.446,zoneID=15347}},ends={{npcID=235238,x=0.57,y=0.446,zoneID=15347}},coords={x=0.564,y=0.446,source="quest_giver",zoneID=15347},questType="standard"},
[83240] = {id=83240,name="The Theater Troupe",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14776,description="Since you're an honorary member of the theater troupe, , what do you think about playing a part in our plays? No big parts--I don't want to upset the rest of the troupe by taking away their limelight. You know how they are. Are you available, say, once a week?",starts={{npcID=214296,x=0.564,y=0.514,zoneID=14717},{npcID=214296,x=0.496,y=0.656,zoneID=14776}},ends={{npcID=214296,x=0.564,y=0.514,zoneID=14717},{npcID=214296,x=0.496,y=0.656,zoneID=14776}},coords={x=0.564,y=0.514,source="quest_giver",zoneID=14717},questType="standard"},
[83247] = {id=83247,name="Suspicious Minds",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="For many years, the only non-Arathi we ever saw in Hallowfall were trying to kill us. Nerubians, shadow creatures, beasts. So, forgive me if I view your sudden arrival with suspicion. However, my better half would urge me to be more welcoming... and I want to try to be better. For her. Some of the salamanthers in Rumshackle have been bothering us. Kill them and bring me proof.",starts={{npcID=225879,x=0.68,y=0.442,zoneID=14838}},ends={{npcID=225879,x=0.68,y=0.442,zoneID=14838}},coords={x=0.68,y=0.442,source="quest_giver",zoneID=14838},questType="standard"},
[83274] = {id=83274,name="An Original Path Through Time",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=1637,description="Old warriors keep spinning tales about how things were so much tougher around Azeroth back in their day. I bet they would say you're not tough enough to last 10 minutes in their world. Think you're tough enough to find out? How 'bout you show me.",starts={{npcID=223884,x=0.628,y=0.502,zoneID=440},{npcID=234555,x=0.56,y=0.19,zoneID=1519},{npcID=234555,x=0.528,y=0.83,zoneID=1637}},ends={{npcID=223884,x=0.628,y=0.502,zoneID=440},{npcID=234555,x=0.56,y=0.19,zoneID=1519},{npcID=234555,x=0.528,y=0.83,zoneID=1637}},coords={x=0.628,y=0.502,source="quest_giver",zoneID=440},questType="standard"},
[83275] = {id=83275,name="Gear Enchanting",level=68,requiredLevel=68,faction="both",expansion=10,zoneID=14771,description="Hello, outlander! I've heard of your exploits since your dramatic arrival on our shores. We earthen welcome your aid. I can teach you how to enchant your gear with resources from my land. To defeat our enemies, every bit of power helps.",starts={{npcID=226287,x=0.518,y=0.486,zoneID=14771}},ends={{npcID=226287,x=0.518,y=0.486,zoneID=14771}},coords={x=0.518,y=0.486,source="quest_giver",zoneID=14771},questType="standard"},
[83276] = {id=83276,name="Saving Private Spindle",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14753,description="One of my weave-rats has failed to check in for an unusually long time. I sent Spindle to retrieve information we could use against one of Ansurek's favored wretches, but she has not returned from her assignment. Meesk the Venomtongue is a wretch and a sycophant, but he is dangerous all the same. While I have much trust in my dear Spindle 's abilities, I fear what a malefactor such as Meesk would do to one of my little ones should he find them. Find Spindle . Make sure she is well.",starts={{npcID=207471,x=0.556,y=0.438,zoneID=14752}},ends={{npcID=226019,x=0.878,y=0.592,zoneID=14753}},coords={x=0.556,y=0.438,source="quest_giver",zoneID=14752},questType="standard"},
[83277] = {id=83277,name="Personal Pilfering",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14752,description="Spindle .>",starts={{npcID=226019,x=0.878,y=0.592,zoneID=14753}},ends={{npcID=207471,x=0.556,y=0.438,zoneID=14752}},coords={x=0.878,y=0.592,source="quest_giver",zoneID=14753},questType="standard"},
[83278] = {id=83278,name="Hillhelm Family: A Lost Shoe",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,description="Aliya Hillhelm can shed some light on it.>",ends={{npcID=206528,x=0.612,y=0.304,zoneID=14838}},questType="standard"},
[83279] = {id=83279,name="Prove One's Mettle",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="Yes, you helped us out with these pests, but it is not enough. I need more. One of the areas near our town has been overrun by shadow. If you are truly not being controlled by your... strange background, you would have no problem destroying the source of this danger, would you?",starts={{npcID=225879,x=0.68,y=0.442,zoneID=14838}},ends={{npcID=225879,x=0.68,y=0.442,zoneID=14838}},coords={x=0.68,y=0.442,source="quest_giver",zoneID=14838},questType="standard"},
[83282] = {id=83282,name="Hillhelm Family: A Clutch of Eggs",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,description="chicken eggs , they must have come from a nearby farm. Maybe Aliya Hillhelm can shed some light on it.>",ends={{npcID=206528,x=0.612,y=0.304,zoneID=14838}},questType="standard"},
[83283] = {id=83283,name="For Morale",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14838,description="Please excuse my husband's rudeness. When we signed up for our expedition, we expected to be away from our families for a few years at worst. Instead, we settled here as we guard against--well, against the end, against Renilash. Who knows when our watch will end? I've been stockpiling a cache of wine from our church vineyards to share with everyone when tensions got high. My hiding place, Rumshackle, has been overrun by creatures. Can you get the wine for me?",starts={{npcID=225857,x=0.68,y=0.442,zoneID=14838}},ends={{npcID=225857,x=0.68,y=0.442,zoneID=14838}},coords={x=0.68,y=0.442,source="quest_giver",zoneID=14838},questType="standard"},
[83285] = {id=83285,name="The Ancient Scroll",level=1,requiredLevel=1,faction="both",expansion=10,zoneID=1637,description="A haze seems to obscure the details of the scroll at first. As you concentrate on making out the scroll's features, the haze briefly dissipates revealing a pristine scroll made of the finest vellum, with a seal that looks so fresh the wax doesn't even seem set yet. In a blink, the scroll feels dangerously brittle, and the seal so delicate it could crack at any moment. As the haze begins to form again, you see the scroll shimmer through all possible points between these two extremes.",ends={{npcID=223885,x=0.626,y=0.504,zoneID=440},{npcID=234556,x=0.558,y=0.188,zoneID=1519},{npcID=234556,x=0.528,y=0.828,zoneID=1637}},questType="standard"},
[83306] = {id=83306,name="Where the Wild Things Camp",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="Some of my people found a few haranir setting up one of their camps to the southwest. They were missing some vital supplies, so my people offered to help out. However, I worry about how they're all getting along over there. Could you check in on them? Make sure we're being good hosts to the haranir... and that nobody has inadvertently offended anyone. Please.",starts={{npcID=211409,x=0.592,y=0.194,zoneID=14752}},ends={{npcID=220595,x=0.446,y=0.664,zoneID=14752}},coords={x=0.592,y=0.194,source="quest_giver",zoneID=14752},questType="standard"},
[83321] = {id=83321,name="Strange Bats",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="Hey. Her ladyship has a lead on some really strange bat that was flying around the Wormlands. The spies reported it behaving more like a person than a bat. We think we might have a druid out there, but it ain't revealin' itself to the nerubians on purpose. You have one of those faces that make people hesitate before punching. Head out there and take a look.",starts={{npcID=223754,x=0.558,y=0.436,zoneID=14752}},ends={{npcID=211652,x=0.422,y=0.426,zoneID=14752}},coords={x=0.558,y=0.436,source="quest_giver",zoneID=14752},questType="standard"},
[83322] = {id=83322,name="The Dawnbreaker: The Christening",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,description="The flagship of the Arathi armada is the Dawnbreaker. She is a marvel of Arathi engineering and faith in the Sacred Flame. Her presence in the Hallowfall sky will help us push back the nerubians when next they dare launch another assault on our lands. As someone who has helped us so much in the past, you are cordially invited to the christening ceremony of the Dawnbreaker. If you could make sure it goes off without a hitch, you will have my personal gratitude.",starts={{npcID=215335,x=0.404,y=0.508,zoneID=14838}},ends={{npcID=215335,x=0.404,y=0.508,zoneID=14838}},coords={x=0.404,y=0.508,source="quest_giver",zoneID=14838},questType="dungeon"},
[83324] = {id=83324,name="A Silken Thread",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="You looking for work or something? If you're just hanging around I've heard some whispers from the capital. An associate of the Weaver is looking into some business in the Silken Ward. The new ward is supposed to be a fresh start for citizens of the capital but the Queen's Pale Weavelashers have been treating it like a military camp. This isn't sittin' well with the populace. Meet with a nerubian named Sum'latha outside the ward. She can fill you in on the details.",starts={{npcID=223754,x=0.558,y=0.436,zoneID=14752}},ends={{npcID=221948,x=0.514,y=0.638,zoneID=14752}},coords={x=0.558,y=0.436,source="quest_giver",zoneID=14752},questType="standard"},
[83325] = {id=83325,name="Bountiful Beetles",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="General Anub'azal has great plans in motion for the swarmery, Rak-Ush. He intends to return it to working order, to support his war campaign. However... I have my reservations about the two he left in charge. Kish'nal seems to have a good head on his shoulders, but Vix'aron? Volatile is an understatement. They may require some... prodding. Seek out Kish'nal at Rak-Ush and follow up on Anub'azal's orders.",starts={{npcID=224729,x=0.558,y=0.422,zoneID=14752},{npcID=229184,x=0.558,y=0.422,zoneID=14752}},ends={{npcID=214359,x=0.76,y=0.824,zoneID=14752}},coords={x=0.558,y=0.422,source="quest_giver",zoneID=14752},questType="standard"},
[83326] = {id=83326,name="The Final Candle",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,mapID=2214,description="You are good candle-taker. We have one last job for you, your waxiness! One more job! Then no more sticky business. BIG candle in basement. Stone-ones use it to keep rats away from their honey juice. We no rats! We kobo--ooolds. Nothing rhymes with kobolds, hm. Get us big candle!",starts={{npcID=413694,x=0.481,y=0.32,mapID=2214}},ends={{npcID=413694,x=0.481,y=0.32,mapID=2214}},coords={x=0.481,y=0.32,source="quest_giver",mapID=2214},questType="standard"},
[83331] = {id=83331,name="Preserve and Pretend",level=73,requiredLevel=73,faction="both",expansion=10,zoneID=14795,description="Chive dig for history. You help find? Got history detector from goblin. Said it finds history underground! You use. Chive dig.",starts={{npcID=226255,x=0.582,y=0.32,zoneID=14795}},ends={{npcID=226255,x=0.582,y=0.32,zoneID=14795}},coords={x=0.582,y=0.32,source="quest_giver",zoneID=14795},questType="standard"},
[83333] = {id=83333,name="Gearing Up for Trouble",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,description="Greetings friend, The machine is once again in disrepair and requires restoration. I am in need of your expertise to successfully perform maintenance. A reward shall be provided for well-executed assistance.",starts={{npcID=216164,x=0.476,y=0.352,zoneID=14795},{npcID=217128,x=0.474,y=0.32,zoneID=14795}},ends={{npcID=216164,x=0.476,y=0.352,zoneID=14795},{npcID=217128,x=0.474,y=0.32,zoneID=14795}},coords={x=0.476,y=0.352,source="quest_giver",zoneID=14795},questType="standard"},
[83334] = {id=83334,name="The Wealth of an Empire",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14838,mapID=2215,starts={{npcID=213145,x=0.412,y=0.53,mapID=2215}},ends={{npcID=213145,x=0.412,y=0.53,mapID=2215}},coords={x=0.412,y=0.53,source="quest_giver",mapID=2215},questType="standard"},
[83335] = {id=83335,name="Wanted: The Boroughbreaker",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,description="For crimes impeding the Edicts of Dornogal, the Council has deemed a reward be yielded to any who slays the chitinous beast known as Stik'kar. A sample of Stik'kar's armor is attached. If you are unable to damage it, you are urged to carry on in your duties and leave this task for another.",starts={{npcID=454463,x=0.552,y=0.559,zoneID=14717}},ends={{npcID=226761,x=0.54,y=0.2,zoneID=14771}},coords={x=0.552,y=0.559,source="quest_giver",zoneID=14717},questType="standard"},
[83336] = {id=83336,name="The Earthwound",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="Ground is shaking. 'Tis no good. Troubles are awakening the elements again. Stirs rot in them. Danger to us all. Bring them to heel and give its heart here. Only then the earth can begin to heal. Only then can Etterca do her duties.",starts={{npcID=226750,x=0.554,y=0.558,zoneID=14717}},ends={{npcID=226750,x=0.554,y=0.558,zoneID=14717}},coords={x=0.554,y=0.558,source="quest_giver",zoneID=14717},questType="standard"},
[83337] = {id=83337,name="Stormscarred",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="Take a look around this beautiful town. What do you see? Ranchers 'n' their mosswools. But where is this rancher's flock? In the guts of a beast, they are. Stormscar they call 'im. Stormscar , whose howl is as the thunder. Whose bite is lightning. Whose belly is full of my life's work. I came here to buy weapons and all we have is ranching equipment. You look strong. Would you put an end to Stormscar 's reign in our pastures?",starts={{npcID=226792,x=0.584,y=0.282,zoneID=14717}},ends={{npcID=226792,x=0.584,y=0.282,zoneID=14717}},coords={x=0.584,y=0.282,source="quest_giver",zoneID=14717},questType="standard"},
[83338] = {id=83338,name="The Mage Slayer",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="I confess I have come here with reason. There is one entity that may be out there still that cannot be allowed its freedom. A prisoner from the Violet Hold that we begrudgingly know as the Mage Slayer. I had come to request aid from these people, but they are farmers and ranchers. I hope you are better equipped for a challenge. Seek out this fiend and put an end to its existence.",starts={{npcID=226791,x=0.582,y=0.272,zoneID=14717}},ends={{npcID=226791,x=0.582,y=0.272,zoneID=14717}},coords={x=0.582,y=0.272,source="quest_giver",zoneID=14717},questType="standard"},
[83339] = {id=83339,name="The Spirebreaker",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="We are no strangers to nerubian attacks. The Kirin Tor is well equipped to handle such a threat. Dalaran... Was equipped. I cannot fend off all of this town's foes, but you might be able to. I spotted an ambush near the road on the way here. An all too familiar tactic of an all too familiar foe. Go spring the trap and slay the monster that lurks below.",starts={{npcID=226791,x=0.582,y=0.272,zoneID=14717}},ends={{npcID=226791,x=0.582,y=0.272,zoneID=14717}},coords={x=0.582,y=0.272,source="quest_giver",zoneID=14717},questType="standard"},
[83347] = {id=83347,name="Emissary of War",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,description="Are you up for a real challenge? Delve into the darkest places and soar to the highest heights while upping the challenge. By pressing ourselves to the extreme we can truly test our skills.",starts={{npcID=226919,x=0.464,y=0.492,zoneID=14771}},ends={{npcID=226919,x=0.464,y=0.492,zoneID=14771}},coords={x=0.464,y=0.492,source="quest_giver",zoneID=14771},questType="dungeon"},
[83357] = {id=83357,name="The Very Best",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,description="The bond between us and our machines is much like the one others have with their pets. You must be in harmony with your companions in order to accomplish great things! Show me that you can work as a team with your pets. Defeat your enemies with their assistance!",starts={{npcID=226919,x=0.464,y=0.492,zoneID=14771}},ends={{npcID=226919,x=0.464,y=0.492,zoneID=14771}},coords={x=0.464,y=0.492,source="quest_giver",zoneID=14771},questType="standard"},
[83358] = {id=83358,name="The Arena Calls",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,description="Have you proven your mettle in the arena? Win enough battles, and we might even find your tales worthy of storage in the Archives one day.",starts={{npcID=226919,x=0.464,y=0.492,zoneID=14771}},ends={{npcID=226919,x=0.464,y=0.492,zoneID=14771}},coords={x=0.464,y=0.492,source="quest_giver",zoneID=14771},questType="standard"},
[83359] = {id=83359,name="A Shattered Path Through Time",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,description="One of your people brought me a strange tale of the cataclysm that tore Azeroth apart. In your lands, this was felt most direly due to the machinations of the wicked creature Deathwing. Travel through space and time and engage with him and other threats.",starts={{npcID=226919,x=0.464,y=0.492,zoneID=14771}},ends={{npcID=226919,x=0.464,y=0.492,zoneID=14771}},coords={x=0.464,y=0.492,source="quest_giver",zoneID=14771},questType="standard"},
[83360] = {id=83360,name="A Fel Path Through Time",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,description="I have heard tales of an entire Legion of threats that lurks along the paths of space and time. Defeat them and bring me back news of their demise.",starts={{npcID=226919,x=0.464,y=0.492,zoneID=14771}},ends={{npcID=226919,x=0.464,y=0.492,zoneID=14771}},coords={x=0.464,y=0.492,source="quest_giver",zoneID=14771},questType="standard"},
[83362] = {id=83362,name="A Shrouded Path Through Time",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,description="One of your people brought me tales of Pandaria! I would very much like to fly through those skies one day. Walk through mist and time and bring back news of your deeds.",starts={{npcID=226919,x=0.464,y=0.492,zoneID=14771}},ends={{npcID=226919,x=0.464,y=0.492,zoneID=14771}},coords={x=0.464,y=0.492,source="quest_giver",zoneID=14771},questType="standard"},
[83363] = {id=83363,name="A Burning Path Through Time",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,description="Your people have brought me tales of a Dark Portal wherein lie many enemies and challenges. I would like to hear more of these tales. Travel through time and space to this outlandish place, vanquish its foes, and bring me news of their demise.",starts={{npcID=226919,x=0.464,y=0.492,zoneID=14771}},ends={{npcID=226919,x=0.464,y=0.492,zoneID=14771}},coords={x=0.464,y=0.492,source="quest_giver",zoneID=14771},questType="standard"},
[83364] = {id=83364,name="A Savage Path Through Time",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,description="Ever since your city fell out of the sky, I have learned more of this world's history and the challenges that heroes like yourself have faced. Learning from the past is how we ensure our future. Walk through time to a past limed with hellfire to defeat those threats once more and bring those lessons forward.",starts={{npcID=226919,x=0.464,y=0.492,zoneID=14771}},ends={{npcID=226919,x=0.464,y=0.492,zoneID=14771}},coords={x=0.464,y=0.492,source="quest_giver",zoneID=14771},questType="standard"},
[83365] = {id=83365,name="A Frozen Path Through Time",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,description="Ever since your city fell out of the sky, I have learned more of this world's history and the challenges that heroes like yourself have faced. Learning from the past is how we ensure our future. Walk through time to the frozen past, defeat those threats once more, and bring those lessons forward.",starts={{npcID=226919,x=0.464,y=0.492,zoneID=14771}},ends={{npcID=226919,x=0.464,y=0.492,zoneID=14771}},coords={x=0.464,y=0.492,source="quest_giver",zoneID=14771},questType="standard"},
[83366] = {id=83366,name="The World Awaits",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,description="Perhaps we can turn your tragedy into a mutually beneficial experience for us both. There is much you can do to be of assistance to the earthen. Lend a hand where you can.",starts={{npcID=226919,x=0.464,y=0.492,zoneID=14771}},ends={{npcID=226919,x=0.464,y=0.492,zoneID=14771}},coords={x=0.464,y=0.492,source="quest_giver",zoneID=14771},questType="standard"},
[83417] = {id=83417,name="Out-laws",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="We're a traditional goblin family, an' my sweetie's intended's from one too. Young people start work on a contract, an' buy each other out when they get hitched so they can get time off. I've got the cash for my sweetie to buy her intended's contract out, but it would be... embarrassin' if her intended didn't have the moolah for my perfect peach's contract, ya know? Go talk to that kid and make sure he's set for the big day. And if he's not? Fix it.",starts={{npcID=226518,x=0.254,y=0.418,zoneID=15347}},ends={{npcID=226518,x=0.254,y=0.418,zoneID=15347}},coords={x=0.254,y=0.418,source="quest_giver",zoneID=15347},questType="standard"},
[83418] = {id=83418,name="The Perfect Coat",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="My princess deserves only the very best Azeroth has to offer--and that goes double for her clothes. How else are people supposed'ta know how incredible I think she is? I got a guy who's hooked me up with an amazin' and rare pelt for my little girl to turn into a fabulous coat. Go meet the guy and bring back the goods. And you better not get anythin' on it.",starts={{npcID=226518,x=0.254,y=0.418,zoneID=15347}},ends={{npcID=226518,x=0.254,y=0.418,zoneID=15347}},coords={x=0.254,y=0.418,source="quest_giver",zoneID=15347},questType="standard"},
[83419] = {id=83419,name="The Perfect Guest List",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="The perfect weddin' has the perfect guest list! But I'm still waiting on some RSVPs. Papa said he'd make sure they showed up, so that means you gotta remind them they'd love to come to my weddin'. It's gonna be the biggest bash this town has ever seen! Why wouldn't they want to come? We're family! Mostly. Anyway, get everyone on this list to agree to come to my weddin'. Remind them Papa said \"or else.\"",starts={{npcID=226522,x=0.254,y=0.418,zoneID=15347}},ends={{npcID=226522,x=0.254,y=0.418,zoneID=15347}},coords={x=0.254,y=0.418,source="quest_giver",zoneID=15347},questType="standard"},
[83420] = {id=83420,name="Catering to Perfection",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="My perfect day needs the perfect food! I've been looking at things on Gobstagram, and Chef Hardslice is my one and only choice for catering. Papa promised I'd have the best, and he's good to his word! I need you to make sure that everything on my menu makes it to the table for picture perfection. Everyone needs to see how fabulous my wedding is. Ahh! I am so excited! I can't wait to see Chef Hardslice 's creations on my table at my wedding!",starts={{npcID=226522,x=0.254,y=0.418,zoneID=15347}},ends={{npcID=226522,x=0.254,y=0.418,zoneID=15347}},coords={x=0.254,y=0.418,source="quest_giver",zoneID=15347},questType="standard"},
[83421] = {id=83421,name="The Perfect Wedding",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="I hired some goons to crash the wedding. Only the best weddings get crashed, right? But, I don't want to lose my deposit on this here venue. So, I need you to stop my crashers from getting too crashy, ya know?",starts={{npcID=226518,x=0.254,y=0.418,zoneID=15347}},ends={{npcID=226518,x=0.254,y=0.418,zoneID=15347}},coords={x=0.254,y=0.418,source="quest_giver",zoneID=15347},questType="standard"},
[83432] = {id=83432,name="The Rookery",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14938,description="My contacts around Dornogal have told me to keep this a secret, but I trust you mainly because I need someone to do the job. We have a problem within the Rookery's walls--a skardyn outbreak. I need someone to clear the Rookery of skardyn, find the source of the outbreak, and drop the boulder on it. Once you complete the mission, come back to me for your reward. And remember... this stays between us.",starts={{npcID=226623,x=0.466,y=0.482,zoneID=14771}},ends={{npcID=226623,x=0.466,y=0.482,zoneID=14771}},coords={x=0.466,y=0.482,source="quest_giver",zoneID=14771},questType="dungeon"},
[83436] = {id=83436,name="Cinderbrew Meadery",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15103,description="Word has come from a contact of mine named Wenbrandt. You may have heard of him. He runs the Cinderbrew Meadery. He says that goblins affiliated with an organization calling itself Venture Co. are trying to take over the meadery. We cannot have that. I need you to get into the meadery and remove that threat. Cinderbrew is an earthen product and should be under earthen control. Wenbrandt will teach them this lesson--but until then, I will count on you to finish the job.",starts={{npcID=226623,x=0.466,y=0.482,zoneID=14771}},ends={{npcID=226623,x=0.466,y=0.482,zoneID=14771}},coords={x=0.466,y=0.482,source="quest_giver",zoneID=14771},questType="dungeon"},
[83442] = {id=83442,name="Tossed and Torqued",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="All my notes. My plans! I just know it was Mite Sparkcog who tossed my apartment. He's my work rival and probably wanted my newest invention for himself--the Smellersweller 5000! It's an attachment for the grills we design. I'd just finished the schematic for our boss when I stepped out for some grub. By the time I got back... Maybe he didn't find it. Help me look first, then we can deal with Mite.",starts={{npcID=226569,x=0.322,y=0.31,zoneID=15347}},ends={{npcID=226569,x=0.322,y=0.31,zoneID=15347}},coords={x=0.322,y=0.31,source="quest_giver",zoneID=15347},questType="standard"},
[83443] = {id=83443,name="Darkflame Cleft",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,description="A new ally of ours, a kobold from the Ringing Deeps named Skitter, has contacted me. I need you to go to Darkflame Cleft and remove a certain threat--something that Skitter called The Darkness. How can a kobold be afraid of the darkness when they spend most of their time underground? It makes no sense to me. But kobolds will be kobolds, and I will not busy myself with understanding.",starts={{npcID=226623,x=0.466,y=0.482,zoneID=14771}},ends={{npcID=226623,x=0.466,y=0.482,zoneID=14771}},coords={x=0.466,y=0.482,source="quest_giver",zoneID=14771},questType="dungeon"},
[83445] = {id=83445,name="Something Smells",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Ooh! That Mite makes me so mad! He even took credit for it. An' I was right. He's going to present the Smellersweller to our boss! In fact, he's probably presenting it right now! That gives me an idea though. We may not have the schematic, but Mite won't know how to operate it. If we can show the boss it's not Mite's design, maybe I'll still get credit! How good are you at pressing buttons? Will you help me present the prototype?",starts={{npcID=226569,x=0.322,y=0.31,zoneID=15347}},ends={{npcID=226703,x=0.272,y=0.354,zoneID=15347}},coords={x=0.322,y=0.31,source="quest_giver",zoneID=15347},questType="standard"},
[83446] = {id=83446,name="Cease and Desist",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Our presentation showed that we were the ones that could actually operate the device! If Sammy weren't so focused on the documentation bein' in Mite's hands... Anyone else could clearly see we had made the thing even if we didn't have the schematics! But this ain't over. You saw how Mite overloaded the Smellersweller? We can do that too! Punch a bunch of buttons all at once and we can exploit his half-baked, all-stolen idea! We go in, we mess up the prototype, an' we set production back months!",starts={{npcID=226703,x=0.272,y=0.354,zoneID=15347}},ends={{npcID=226709,x=0.276,y=0.348,zoneID=15347}},coords={x=0.272,y=0.354,source="quest_giver",zoneID=15347},questType="standard"},
[83457] = {id=83457,name="The Stonevault",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14883,description="I have a job for you from High Speaker Brinthe herself. The skardyn corruption is taking over the Stonevault. To contain the panic, High Speaker Brinthe has asked us for help. I told her she could trust us like we trust the bedrock under our feet. Go to The Stonevault and remove the skardyn corruption. Let me know when the job is done.",starts={{npcID=226623,x=0.466,y=0.482,zoneID=14771}},ends={{npcID=226623,x=0.466,y=0.482,zoneID=14771}},coords={x=0.466,y=0.482,source="quest_giver",zoneID=14771},questType="dungeon"},
[83458] = {id=83458,name="Priory of the Sacred Flame",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14954,description="Good to see you, . I have a job just for you. Sister Etna Blayze of the Arathi is convinced that something is wrong within the Sacred Flame Priory. She did not expand on the matter at hand. Please head out to the Priory of the Sacred Flame and join the sister. A stomach pebble tells me she might be right and will need your help.",starts={{npcID=226623,x=0.466,y=0.482,zoneID=14771}},ends={{npcID=226623,x=0.466,y=0.482,zoneID=14771}},coords={x=0.466,y=0.482,source="quest_giver",zoneID=14771},questType="dungeon"},
[83459] = {id=83459,name="The Dawnbreaker",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,description="I have received word from General Steelstrike of the Arathi. She asked for you to attend a ceremony aboard The Dawnbreaker. By attending, she means she needs an extra pair of eyes--maybe two or five. Have you ever secured a ceremony before? It feels like a puddle of sticky mud down in the Forgegrounds. I'm sorry, but General Steelstrike asked, and I replied with a simple \"yes.\" As the saying goes, not every hill is going to be exciting.",starts={{npcID=226623,x=0.466,y=0.482,zoneID=14771}},ends={{npcID=226623,x=0.466,y=0.482,zoneID=14771}},coords={x=0.466,y=0.482,source="quest_giver",zoneID=14771},questType="dungeon"},
[83465] = {id=83465,name="Ara-Kara, City of Echoes",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15093,description="Tulumun, an agent of a new contact known as the Vizier, has approached us. I never expected a nerubian to come to us for help, but what they brought to our attention could threaten us all. I will need you to descend into Azj-Kahet and infiltrate Ara-Kara, the City of Echoes. If what Tulumun told me is true, we cannot let whatever they have woven down there escape. Put an end to their operation. Bring back evidence of what you find.",starts={{npcID=226623,x=0.466,y=0.482,zoneID=14771}},ends={{npcID=226623,x=0.466,y=0.482,zoneID=14771}},coords={x=0.466,y=0.482,source="quest_giver",zoneID=14771},questType="dungeon"},
[83469] = {id=83469,name="City of Threads",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14979,description="Tulumun, our Nerubian ally, contacted us once again. He spoke of a place called the Transformatory where horrific experiments take place. I will need you to infiltrate the city and then rendezvous with the Vizier himself for the rest of the mission. Eliminate the Vizier's enemies, end the threat, and return to me for your payment.",starts={{npcID=226623,x=0.466,y=0.482,zoneID=14771}},ends={{npcID=226623,x=0.466,y=0.482,zoneID=14771}},coords={x=0.466,y=0.482,source="quest_giver",zoneID=14771},questType="dungeon"},
[83484] = {id=83484,name="Oh, Rats!",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Okay, scout's honor this ain't a joke. I need help because... I turned my best friend into a rat. My friend Allie is the cook here. She tries her best but she's... no good. She's got a bum sniffer. So, I bought her a potion that would make her smell better! ...I mean, improve her sense of smell. But it turned her into a rat! Then she ran off! Ya gotta find her for me. Dealer had another potion to understand rats. I'm too afraid to drink it though. Can you use it an' find her?",starts={{npcID=226728,x=0.382,y=0.882,zoneID=15347}},ends={{npcID=226710,x=0.33,y=0.842,zoneID=15347}},coords={x=0.382,y=0.882,source="quest_giver",zoneID=15347},questType="standard"},
[83485] = {id=83485,name="Potent Potables",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="This potion has the scent of the Vatworks on it. There's a vendor at the northern edge there who sells potions. It must be from him. If you can find him, maybe you can get him to hand over an antidote. Please help. You're the only one who can understand me!",starts={{npcID=226710,x=0.33,y=0.842,zoneID=15347}},ends={{npcID=454456,x=0.324,y=0.559,zoneID=15347}},coords={x=0.33,y=0.842,source="quest_giver",zoneID=15347},questType="standard"},
[83486] = {id=83486,name="Remote Work",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=8499,mapID=862,description="If you're reading this, I'm out scavenging for reagents along the Kaja'Coast. If you're here to collect on a debt, you are TRESPASSING and must disregard this note . -Getry",starts={{npcID=454456,x=0.324,y=0.559,mapID=2346}},ends={{npcID=466110,x=0.209,y=0.588,mapID=862}},coords={x=0.324,y=0.559,source="quest_giver",mapID=862},questType="standard"},
[83487] = {id=83487,name="Occupational Hazard",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,starts={{npcID=466110,x=0.209,y=0.588,zoneID=8499}},ends={{npcID=226728,x=0.382,y=0.882,zoneID=15347}},coords={x=0.209,y=0.588,source="quest_giver",zoneID=8499},questType="standard"},
[83489] = {id=83489,name="Gathering All Gladiators!",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,description="Come one, come all, straight to Dornogal ! In addition to the usual selection of powerful equipment offered at the Contender's Gate, aspiring combatants and proven gladiators can purchase heraldry tokens which can be used to craft equipment certified for use in arenas and battlegrounds! Present this brochure to Hotharn to receive a few of these, on us! - Aisha",ends={{npcID=219215,x=0.554,y=0.77,zoneID=14771}},questType="standard"},
[83492] = {id=83492,name="Warbands: Warbanding Together",level=20,requiredLevel=20,faction="both",expansion=10,zoneID=440,description=", some adventurers have gotten together to form a warband and could use your help. Find Blue and her group in Gadgetzan.",starts={{npcID=133362,x=0.532,y=0.152,zoneID=1519},{npcID=133407,x=0.394,y=0.792,zoneID=1637}},ends={{npcID=226658,x=0.524,y=0.268,zoneID=440}},coords={x=0.532,y=0.152,source="quest_giver",zoneID=1519},questType="standard"},
[83493] = {id=83493,name="Warbands: Rift Reader",level=20,requiredLevel=20,faction="both",expansion=10,zoneID=440,description="I bet you're wondering what we're working on, huh? We're going to make our Warband Bank accessible from anywhere! Rivet's calling it a Warband Bank Distance Inhibitor until I can think of something more fun, but we need a little help to get it over the finish line. If we're going to make sure we can access our shared stash from multiple locations, we're going to need portals! And we tracked some doozies down out here. If you could get us some scans of the local anomalies, it'd be a big help!",starts={{npcID=226658,x=0.524,y=0.268,zoneID=440}},ends={{npcID=226658,x=0.524,y=0.268,zoneID=440}},coords={x=0.524,y=0.268,source="quest_giver",zoneID=440},questType="standard"},
[83494] = {id=83494,name="Warbands: Space Ghosts by the Coast",level=20,requiredLevel=20,faction="both",expansion=10,zoneID=440,description="There are an awful lot of half-teleported things wandering around the desert not too far from here. Really, any at all would be a surprising amount, but there are a bunch of them for some reason! They don't seem particularly nice, but I bet we could learn from their predicament to ensure the Warband Bank Distance Inhibitor doesn't teleport our sweet loot into a tree! See if you can find anything that might help us figure out what went wrong. It's not like people randomly teleport around, right?",starts={{npcID=226658,x=0.524,y=0.268,zoneID=440}},ends={{npcID=226658,x=0.524,y=0.268,zoneID=440}},coords={x=0.524,y=0.268,source="quest_giver",zoneID=440},questType="standard"},
[83495] = {id=83495,name="Warbands: Twinsposition",level=20,requiredLevel=20,faction="both",expansion=10,zoneID=440,description="We're on a roll! We picked up an even more anomalous anomaly while you were out and tracked it down to just west of town. We've got a brand-new Transpositional Signal Recombobulatron already set up out there, but I didn't want to start without you. You've been a big help, after all. All you have to do is dial it in and throw the switch! Easy as pie, which I'm told is very easy. Rivet says that the odds of something cataclysmic happening are pretty good, so I know nothing bad can happen!",starts={{npcID=226658,x=0.524,y=0.268,zoneID=440}},ends={{npcID=226658,x=0.524,y=0.268,zoneID=440}},coords={x=0.524,y=0.268,source="quest_giver",zoneID=440},questType="standard"},
[83496] = {id=83496,name="Warbands: Spacetime is Money",level=20,requiredLevel=20,faction="both",expansion=10,zoneID=440,description="Now that we've got all the transpositional data we could ever hope for, all we need to do is set up a wormhole in a suitable banking establishment and we'll be dropping gear into each other's pockets from the field in no time! And there just happens to be a bank right here in Gadgetzan! You can even attune your own portal at the same time so you can access your own Warband Bank from anywhere. It's going to be so convenient!",starts={{npcID=226658,x=0.524,y=0.268,zoneID=440}},ends={{npcID=226658,x=0.524,y=0.268,zoneID=440}},coords={x=0.524,y=0.268,source="quest_giver",zoneID=440},questType="standard"},
[83497] = {id=83497,name="A Concerned Friend",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14838,description="Ah, , there you are! Great Kyron was asking after you and your friend Anduin. I think they want to talk to you about Faerin. Nothing urgent mind you, she probably just needs some good company. But we're all a bit worried about her. Check in with Kyron when you have a moment, will you?",starts={{npcID=226708,x=0.51,y=0.462,zoneID=14771}},ends={{npcID=215341,x=0.43,y=0.524,zoneID=14838}},coords={x=0.51,y=0.462,source="quest_giver",zoneID=14771},questType="standard"},
[83499] = {id=83499,name="Arcane Wasteland",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14717,description="Kirin Tor survivors have been hesitant to return to this area. A great deal of energy was dispelled before and after Dalaran's crash. An invisible yet tangible miasma lingers in the area for those who are sensitive to it. It is unclear if the site is hazardous or if other more corporeal dangers still lurk here. I can protect us, but I expended all my reagents at the Proscenium. Will you aid me in procuring more?",starts={{npcID=225355,x=0.296,y=0.58,zoneID=14717}},ends={{npcID=225355,x=0.296,y=0.58,zoneID=14717}},coords={x=0.296,y=0.58,source="quest_giver",zoneID=14717},questType="standard"},
[83500] = {id=83500,name="Zekvir, Hand of the Harbinger",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=15001,description="We'll have tae watch out for Zekvir as we go exploring into delves. I don't think we're strong enough tae take him on just yet, but we will be! Let's keep explorin' and gettin' treasure until we're tough enough tae track down his lair and defeat him.",starts={{npcID=206017,x=0.476,y=0.444,zoneID=14771}},ends={{npcID=206017,x=0.476,y=0.444,zoneID=14771}},coords={x=0.476,y=0.444,source="quest_giver",zoneID=14771},questType="standard"},
[83502] = {id=83502,name="Lessons in Defensive Magic",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14717,description="The spell for the barrier is ready, but I must channel it and define its perimeter. While I channel the spell, take these wards and place them at the edges of our would-be barrier. We will empower the spell when you are finished.",starts={{npcID=225355,x=0.296,y=0.58,zoneID=14717}},ends={{npcID=226895,x=0.296,y=0.58,zoneID=14717}},coords={x=0.296,y=0.58,source="quest_giver",zoneID=14717},questType="standard"},
[83519] = {id=83519,name="But What About the Casino?",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Times are a changing. Now that ol' Jastor is kaput, the cartel heads are chomping at the bit to settle the fate of Undermine 's crown jewel: the Gallagio. There's a court proceeding tomorrow to make a final determination, but luckily the deed is squarely in the hands of someone I trust. Their name: Rosebud Gallywix. I know. I know. But Rosey is a good egg. I'll introduce you to him later on. First, do me a favor. Ask the power players here at the party how they feel about the new owner.",starts={{npcID=226273,x=0.668,y=0.446,zoneID=15347}},ends={{npcID=226273,x=0.668,y=0.446,zoneID=15347}},coords={x=0.668,y=0.446,source="quest_giver",zoneID=15347},questType="standard"},
[83521] = {id=83521,name="Little Help, Please?",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15347,mapID=2346,description="So, uh, I swear this never happens, but this kind fellow here pulled me over for a busted tail light. I just got that fixed. I swear it! Would you do me a favor? Keep him and any of his colleagues entertained. My license is in one of these compartments somewhere, I just gotta find it. Shouldn't be more than a minute. Two at most!",questType="standard"},
[83522] = {id=83522,name="Debting For A Living",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="First of Rosebud's Chiefs on our list are the genius gaming duo: Kayjay and Fantastic Davey. Now, I heard from my wife's brother that Venture Co. bought up all the debt those boys got. Happened the minute Rosebud was done in. Did they murder him? Not a great motive if their debt was sky high, but you never know whose pocket a goblin is in either. Best we see how comfortable they are here at the ol' Venturewood landfill. If they don't want to sign the new deed, we might have our culprits!",starts={{npcID=226277,x=0.506,y=0.7,zoneID=15347}},ends={{npcID=228420,x=0.526,y=0.73,zoneID=15347}},coords={x=0.506,y=0.7,source="quest_giver",zoneID=15347},questType="standard"},
[83524] = {id=83524,name="Gold In Them There Trash",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Kayjay and Davey are indeed masters of creating games. They've created a new one for me that's been an absolute hit. If you're willing to accept the risk, then I will give you the chance to win their employment, and debt, from me. Grab a pickaxe, and enter the landfill. When the whistle blows, you'll compete against all my other \"employees.\" Win by the final bell, and I'll let these two go. Lose, and I'll own you. It's called Slot Mining. And it will indebt you to me for life.",starts={{npcID=228420,x=0.526,y=0.73,zoneID=15347}},ends={{npcID=228474,x=0.558,y=0.76,zoneID=15347}},coords={x=0.526,y=0.73,source="quest_giver",zoneID=15347},questType="standard"},
[83527] = {id=83527,name="Winning is for Losers, Anyway",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="This is the worst job I've ever had. And I used to work Turtle Toss at Darkmoon Faire. We're not imprisoned here physically with shackles, but Tarbonara owns all of our debts. He imprinted the information on Debt Markers, which his goons hold on to in case any of us want to know where we stand. But if you get a hold of those markers, we're all free. You'd have to crack some skulls to get them though, so I'll give you points for each of his goons bring down. You like collecting points, don'tcha?",starts={{npcID=228473,x=0.558,y=0.76,zoneID=15347}},ends={{npcID=232823,x=0.564,y=0.656,zoneID=15347}},coords={x=0.558,y=0.76,source="quest_giver",zoneID=15347},questType="standard"},
[83528] = {id=83528,name="All Part of the Game",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Look. I know we're the ones that incurred our own debts, but Rosebud believed in us! With him, there was a light at the end of the casino floor. With him gone... We're just two halves of a gaming genius, working for hire instead of salary. But Zoomcart told us there's still a chance we could work the Gallagio. Is that true? If it is, Davey and I are in. Problem is that Davey and I's Debt Markers are held by the gaming commissioner himself: Kudd Milktooth. And he's deep in Tarby's pocket.",starts={{npcID=228474,x=0.558,y=0.76,zoneID=15347}},ends={{npcID=232823,x=0.564,y=0.656,zoneID=15347}},coords={x=0.558,y=0.76,source="quest_giver",zoneID=15347},questType="standard"},
[83534] = {id=83534,name="Ain't No Warm Up Act",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Can't believe Revilgaz scheduled us first! No one shows up for the first band! Whatever. You the one that oldhair Marty mentioned? He already gave me the lowdown on your plan to keep the Gallagio from going to auction. Seems ridiculous. Which makes it our kinda plan. Let's make a deal. Our manager dumped us when the casino deal went south, so YOU are gonna fill in for her today. Don't worry, couldn't be worse than any other job you've done. First thing on your list: gather us a crowd.",starts={{npcID=226899,x=0.568,y=0.352,zoneID=15347}},ends={{npcID=232005,x=0.71,y=0.24,zoneID=15347}},coords={x=0.568,y=0.352,source="quest_giver",zoneID=15347},questType="standard"},
[83535] = {id=83535,name="Plunder Party Rockin' Rumble",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Here! Take this Mecha-Trianbell! I don't care that you can't play an instrument because you WILL be playing this one. While we're jamming, members of rival bands will storm the stage to stop us. Not only will the Trianbell ring out in perfect pitch, it'll also blast anyone not in our band all the way to the cheap seats.",starts={{npcID=232005,x=0.71,y=0.24,zoneID=15347}},ends={{npcID=226899,x=0.568,y=0.352,zoneID=15347}},coords={x=0.71,y=0.24,source="quest_giver",zoneID=15347},questType="standard"},
[83539] = {id=83539,name="Feeling Blue",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14717,description="I fear... that it may just be me that remains, . Or that the others are too far away to receive my missive. It may be up to us to build an outpost here and see to the cleansing of the crash site. So be it. It is just as well...",starts={{npcID=226895,x=0.296,y=0.58,zoneID=14717}},ends={{npcID=227067,x=0.298,y=0.578,zoneID=14717}},coords={x=0.296,y=0.58,source="quest_giver",zoneID=14717},questType="standard"},
[83540] = {id=83540,name="Work the Line",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Not sure if your schnoz picked up what mine did on the drive over, but there were some delightful smells coming from the street below. Problem was, the crowds were too thick for me to find Gobdre anywhere. That's where Noggy comes in. He's a pretty important fella these days, so I figure he'd have some sorta in for us. He's generally an unfeeling scientist-type who doesn't spill secrets. But his pride is also fragile as my wife's Rumble figurines. Give it a poke and he should spill.",starts={{npcID=226932,x=0.328,y=0.802,zoneID=15347}},ends={{npcID=226934,x=0.368,y=0.878,zoneID=15347}},coords={x=0.328,y=0.802,source="quest_giver",zoneID=15347},questType="standard"},
[83541] = {id=83541,name="Review Bombed",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Show me you ain't just talk. I give Diner Cards to each customer. They're supposed to fill it out with their reviews on my menu, and return it here. But I haven't seen any yet. Fishy much? Definitely. And not the kind I like. Go. Fetch. Get my reviews back. I ain't budging an inch in the Gallagio's direction without them.",starts={{npcID=226934,x=0.368,y=0.878,zoneID=15347}},ends={{npcID=226934,x=0.368,y=0.878,zoneID=15347}},coords={x=0.368,y=0.878,source="quest_giver",zoneID=15347},questType="standard"},
[83542] = {id=83542,name="Quick Gills for Gold Now",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Ah, crabs... I knew this would happen. The diners overwhelmingly scored one dish above all others: pan-seared deepwalker thigh with blood-spiced confit algarian orbinid. Long name, right? I was hoping that would dissuade the customers from writing it on their cards. Trouble is that I can't make pan-seared anything without a pan, now can I? And I sold my best pan when the Gallagio deal fell through. Want me back on board? Then get my pan. Those deepwalker thighs ain't gonna sear themselves.",starts={{npcID=226934,x=0.368,y=0.878,zoneID=15347}},ends={{npcID=226934,x=0.368,y=0.878,zoneID=15347}},coords={x=0.368,y=0.878,source="quest_giver",zoneID=15347},questType="standard"},
[83543] = {id=83543,name="Adventuring in Khaz Algar",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,description="We've got scouts in every corner o' Khaz Algar, an' they all report the same thing: trouble. Seems we got here just in time, eh? Check the scouting map on the table behind ye and lend a hand where ye can.",starts={{npcID=206017,x=0.476,y=0.444,zoneID=14771}},coords={x=0.476,y=0.444,source="quest_giver",zoneID=14771},questType="standard"},
[83546] = {id=83546,name="Responsibility",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Today's the day for shiny shoes, ! We've got our deed signatures. We've got support from the cartels. And we've got... my kids. My wife was supposed to come with us today as well, but she slipped in the shower! Can you believe that? She'll be at the chiropractor all morning. I feel awful for her. Absolutely awful. Welp! Her loss! Let's pack up what we need and I'll drive us all over to the court room!",starts={{npcID=227018,x=0.386,y=0.338,zoneID=15347}},ends={{npcID=227032,x=0.568,y=0.444,zoneID=15347}},coords={x=0.386,y=0.338,source="quest_giver",zoneID=15347},questType="standard"},
[83547] = {id=83547,name="Welcome to the Neighborhood",level=0,requiredLevel=0,faction="none",expansion=10,zoneID=6170,mapID=37,description="Welcome to Borogrove, ! I'm Llyssabel Dawnpetal, the local steward. I'll be helping you get better acquainted with the neighborhood. Once you've settled in, please come see me at Town Hall.",questType="standard"},
[83548] = {id=83548,name="Isle of Dorn",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="Survivors from the attack on Dalaran are beset by nerubians led by Queensguard Zirix. Lend your aid to protect whomever remains.",ends={{npcID=211994,x=0.294,y=0.55,zoneID=14717}},questType="standard"},
[83550] = {id=83550,name="The Ringing Deeps",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14795,description="Speaker Brinthe has gone to The Ringing Deeps to see how the Machine Speakers have fared while she was away. She has asked for adventurers to join her at the bottom of the Coreway.",ends={{npcID=212592,x=0.42,y=0.284,zoneID=14795}},questType="standard"},
[83551] = {id=83551,name="Hallowfall",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14838,description="Anduin Wrynn hopes to gain the trust and aid of the Arathi in Hallowfall . He will need help to win over these potential allies.",ends={{npcID=213116,x=0.684,y=0.45,zoneID=14838}},questType="standard"},
[83552] = {id=83552,name="Azj-Kahet",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14752,description="An Arathi airship is stranded in Azj-Kahet following a vicious nerubian ambush. Aid the survivors as they withstand the nerubian assault.",ends={{npcID=211699,x=0.294,y=0.422,zoneID=14752}},questType="standard"},
[83553] = {id=83553,name="Magic-stealing Kobolds",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14717,description="I'm afraid that our \"clean up\" of Dalaran extends far from the shores of the Isle of Dorn . In my attempts to find you, I circled this island many times. During my flight, I sensed the magic of many familiar items--items that were formerly housed in Dalaran. Dangerous items. Someone or something has taken them who knows where. We must find these objects before innocent bystanders come to harm. Follow me.",starts={{npcID=227067,x=0.298,y=0.578,zoneID=14717}},ends={{npcID=227063,x=0.616,y=0.416,zoneID=14717}},coords={x=0.298,y=0.578,source="quest_giver",zoneID=14717},questType="standard"},
[83554] = {id=83554,name="Trinkets, Curios and Other Powerful Objects",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14753,description="The kobolds here could get up to untold mischief with the items they have stolen. Take what you can back from them by... whatever means you see fit. While you deal with the kobolds around Mourning Rise's grave sites, I will go underground and search Kriegval's Rest and do the same. Meet me near Kriegval's Rest when you have secured the Kirin Tor artifacts the kobolds stole.",starts={{npcID=227063,x=0.616,y=0.416,zoneID=14717}},ends={{npcID=227375,x=0.614,y=0.428,zoneID=14717}},coords={x=0.616,y=0.416,source="quest_giver",zoneID=14717},questType="standard"},
[83558] = {id=83558,name="Casino Court",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="I'm all set to make our case. Just one tiny, little, minor thing to let you know about... There's a bomb under my desk here. Don't be alarmed! It ain't the first time this has happened. But there's a lot of people here, and I'd hate to interrupt the proceeding for one little explosive. Take this X-Plo-Dar 64k. Use it to trace the bomb's signature back to the goblin with the trigger. My lawyer's instinct is telling me that the culprit behind this explosive is also Rosebud's killer. Just a hunch.",starts={{npcID=227032,x=0.568,y=0.444,zoneID=15347}},ends={{npcID=227032,x=0.568,y=0.444,zoneID=15347}},coords={x=0.568,y=0.444,source="quest_giver",zoneID=15347},questType="standard"},
[83563] = {id=83563,name="Coffee is for Closers",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="You've got us the hard evidence we needed. All that's left to do is reveal Rosebud's killer to the judge. I imagine Tarbonara won't go down lightly, so be prepared for one of any number of goblin-like reactions. You know what I mean. Explosions or cannons or crying or casino heists or whatever. I'm not worried though, you seem capable.",starts={{npcID=227032,x=0.568,y=0.444,zoneID=15347}},ends={{npcID=226894,x=0.558,y=0.348,zoneID=15347}},coords={x=0.568,y=0.444,source="quest_giver",zoneID=15347},questType="standard"},
[83566] = {id=83566,name="Oh, That Casino!",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="You'd make a good lawyerer, you know that? Hah! Just kidding! The real industry secret is that there's no such thing as a good lawyerer! Why don't you join me at the Gallagio's entrance? It'll be a nice send off for the kids who are gonna run this place now. Not to mention that we should actually hand them the notarized deed!",starts={{npcID=226894,x=0.558,y=0.348,zoneID=15347}},ends={{npcID=226273,x=0.668,y=0.446,zoneID=15347}},coords={x=0.558,y=0.348,source="quest_giver",zoneID=15347},questType="standard"},
[83569] = {id=83569,name="Death and Taxes",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="He just... exploded... If a goblin's gotta go, that's the way. All I can say for poor Rosey. And that I'm gonna miss him. AND that we're gonna find out who did this! But the more immediate pickle is this: Who owns the Gallagio now? It's time to turn to an expert on legal mumbo jumbo. The State of Undermine assigned a public defender to us for the court case tomorrow, a fella named Zoomcart. He's all we got. Take what's left of the deed to his office in Hovel Hill, and sort this out.",starts={{npcID=226273,x=0.668,y=0.446,zoneID=15347}},ends={{npcID=228369,x=0.388,y=0.338,zoneID=15347}},coords={x=0.668,y=0.446,source="quest_giver",zoneID=15347},questType="standard"},
[83587] = {id=83587,name="Our Chance to Strike",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=14753,description="The balance of power is shifting in Azj-Kahet . The Queen grows more unstable by the day and I fear we must act before our opportunity to stop her slips from our grasp. Meet me at the Royal Apothecary when you receive this letter.",starts={{npcID=227217,x=0.57,y=0.418,zoneID=14752},{npcID=227217,x=0.316,y=0.63,zoneID=14771}},ends={{npcID=208782,x=0.528,y=0.462,zoneID=14753}},coords={x=0.57,y=0.418,source="quest_giver",zoneID=14752},questType="standard"},
[83616] = {id=83616,name="The Entrenched",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="And now the other piece to this coup. I've been operating under Grand Overspinner Antourix 's mandibles for a while now. She's entrenched in Rak-Ahat, and thinks nothing can touch her at the top. She has already refused to submit to Ren'khat. Even she knows that if Ren'khat has the backing of the throne then it is only a matter of time. Let us expedite her attempts to oust this upstart. See how quickly they turn on each other.",starts={{npcID=222136,x=0.696,y=0.48,zoneID=14752}},ends={{npcID=221557,x=0.756,y=0.524,zoneID=14752}},coords={x=0.696,y=0.48,source="quest_giver",zoneID=14752},questType="standard"},
[83627] = {id=83627,name="The Beginning of Something Beautiful",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14753,ends={{npcID=218171,x=0.454,y=0.134,zoneID=14753}},questType="standard"},
[83628] = {id=83628,name="Tense Recovery",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="Things with these strangers are... tense. We do appreciate being allowed to take cover here in their camp. But they only seem to tolerate us at best. We offered to share our supplies, but that offended them, somehow. My sister is gravely wounded. I can see herbs I could use to help her in that tent over there, but that giant snail is blocking the entrance. I can't get to them. I asked the guard on the hill for aid, but all he did was glare. I don't know what to do! Perhaps he'll listen to you?",starts={{npcID=227222,x=0.236,y=0.522,zoneID=14752}},ends={{npcID=227224,x=0.238,y=0.406,zoneID=14752}},coords={x=0.236,y=0.522,source="quest_giver",zoneID=14752},questType="standard"},
[83629] = {id=83629,name="Ancient Respite",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="This was once a great lake. Over time the roots ruptured its floor, and drained the water away. I have lived here for all of my lifetime and witnessed it all. But now, darker changes have come. Sometimes changes comes with death. Decay is natural. But the mites that feed upon my people are not. They spread an odd infestation that makes my bark feel like it crawls from my body. Destroy these mites, so that I may rest without fear of their mouths upon my sleeping form.",starts={{npcID=227224,x=0.238,y=0.406,zoneID=14752}},ends={{npcID=227224,x=0.238,y=0.406,zoneID=14752}},coords={x=0.238,y=0.406,source="quest_giver",zoneID=14752},questType="standard"},
[83632] = {id=83632,name="Rings of Memory",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="I appreciate what you have done. Do not worry--I am not finished yet. If you please, take this root to those who sent you. They can read the history of my life within the rings of wood therein. My life is one of many in the tapestry, but we are all intertwined. These strangers you encountered may be reclusive--secretive even--but they understand this tapestry like no other, and guard it with their lives.",starts={{npcID=227224,x=0.238,y=0.406,zoneID=14752}},ends={{npcID=215724,x=0.23,y=0.532,zoneID=14752}},coords={x=0.238,y=0.406,source="quest_giver",zoneID=14752},questType="standard"},
[83639] = {id=83639,name="Open Communications",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="You understand that others lead lives different to your own. Our ways restrict us. Our traditions are not for the ears of strangers. I have only spoken to you at all due to Orweyna's word. But I can feel On'hiea's disapproval from here. It is uncomfortable to have mysteries at times. It is why so many fear the dark. It is unknown. I know I must seem cryptic. But our ways do not mean we are offended by the Arathi. They are creating tension where it does not exist for us.",starts={{npcID=215724,x=0.23,y=0.532,zoneID=14752}},ends={{npcID=227222,x=0.236,y=0.522,zoneID=14752}},coords={x=0.23,y=0.532,source="quest_giver",zoneID=14752},questType="standard"},
[83641] = {id=83641,name="Trapped Between Life and Death",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15991,description="A pocket dimension. This is old magic. Malygos used pocket dimensions on occasion when he did not wish to be disturbed. They were mainly used by mages as research spaces or for testing dangerous spells. Or if a mage wanted to hide what they were doing... I wonder who made this one? I suppose it doesn't matter. We need to get out. Thankfully, every pocket dimension has an exit. Though, it is normally well hidden. Let's find it.",starts={{npcID=227208,zoneID=5031},{npcID=227208,zoneID=14882},{npcID=227208,zoneID=14990},{npcID=227208,zoneID=15000}},ends={{npcID=227392,x=0.616,y=0.428,zoneID=14717}},questType="standard"},
[83707] = {id=83707,name="LFGDungeons - 11.0 The War Within - Raid Finder - 1st",level=80,requiredLevel=80,faction="none",expansion=10,questType="standard"},
[83711] = {id=83711,name="Weapons of Conquest",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,starts={{npcID=219222,x=0.552,y=0.762,zoneID=14771}},coords={x=0.552,y=0.762,source="quest_giver",zoneID=14771},questType="pvp"},
[83716] = {id=83716,name="Beneath the Roots",level=78,requiredLevel=78,faction="both",expansion=10,zoneID=14752,description="I am glad to see you are well, . I have recently received word that a number of the Aeroknights have taken shelter in a camp close to where the airship was seized in mid-air. Would you check on them?",starts={{npcID=211409,x=0.592,y=0.194,zoneID=14752}},ends={{npcID=227295,x=0.236,y=0.52,zoneID=14752}},coords={x=0.592,y=0.194,source="quest_giver",zoneID=14752},questType="standard"},
[83719] = {id=83719,name="Those Are Chitin Words",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14753,description="Well now, this is certainly an interesting specimen. It seems the original creator who worked on this creature made grave errors in balancing the genetic materials. No wonder the creature you encountered was an abomination. What terrible technique! With the right materials however, I may just be able to perfect it. Siesbarg here will be our test-subject. Perhaps his Ascension will finally catch the attention of those in charge of administering promotions!",starts={{npcID=218171,x=0.454,y=0.134,zoneID=14753}},ends={{npcID=218171,x=0.454,y=0.134,zoneID=14753}},coords={x=0.454,y=0.134,source="quest_giver",zoneID=14753},questType="standard"},
[83720] = {id=83720,name="Venom? More Like Get 'Em",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14753,description="Now that we've acquired enough chitin samples to splice into the perfect armor, we need the perfect venom. Don't look at me like that. Our forms should always be powerful and capable of defending themselves! I'll begin incorporating the new carapace requirements for Siesbarg's Ascension while you harvest what I need. Do keep in mind though, it must be nerubian venom , specifically. I'm afraid beetles and spiders simply won't do this time around. As for where you find it, well that's up to you.",starts={{npcID=218171,x=0.454,y=0.134,zoneID=14753}},ends={{npcID=218171,x=0.454,y=0.134,zoneID=14753}},coords={x=0.454,y=0.134,source="quest_giver",zoneID=14753},questType="standard"},
[83721] = {id=83721,name="A Small Ocean's Worth of Blood",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14753,description="Excellent! The end draws near! But although we near completion, we cannot go without the most important part of this genetic equation--the blood. We need a small ocean's worth of nerubian blood . However, to make this new form foolproof, the blood must come from the strongest nerubians to exist. Whether skyrazor or Ascended, it doesn't matter. This will guarantee we have the best genetic material available. The kind of material that Siesbarg deserves!",starts={{npcID=218171,x=0.454,y=0.134,zoneID=14753}},ends={{npcID=218171,x=0.454,y=0.134,zoneID=14753}},coords={x=0.454,y=0.134,source="quest_giver",zoneID=14753},questType="standard"},
[83722] = {id=83722,name="Consolation Flies",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14753,description="Well... that's unfortunate. It appears my experiment has failed and Siesbarg paid the price. Still, I am optimistic for the future I am destined to acquire. It's only a matter of time until I perfect my process. When I do, perhaps I shall engineer my own Ascension! While his physical form isn't what I intended, it appears Siesbarg 's mind is intact. I'm certain he can still be of use. Take him. His new form can provide better service on the field of battle than in my tiny shop.",starts={{npcID=218171,x=0.454,y=0.134,zoneID=14753}},ends={{npcID=228200,x=0.442,y=0.136,zoneID=14753}},coords={x=0.454,y=0.134,source="quest_giver",zoneID=14753},questType="standard"},
[83738] = {id=83738,name="Notorious with The Weaver",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14752,description="Many many thanks for you from the Weave-mother. Come back to the Lair. I have good goods for you. I have webbed up and protected them, so no you worry!",ends={{npcID=224734,x=0.564,y=0.432,zoneID=14752}},questType="standard"},
[83739] = {id=83739,name="Notorious with The General",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14752,description="Word of your deeds has reached many of The General's acolytes! Find me at the Weaver's Lair. We have prepared a tribute for you!",ends={{npcID=229184,x=0.558,y=0.422,zoneID=14752}},questType="standard"},
[83740] = {id=83740,name="Notorious with The Vizier",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14752,description="The Vizier has asked me to provide you with additional resources towards your efforts. Come to the Weaver's Lair. I'll be waiting for you with a parcel.",ends={{npcID=224733,x=0.562,y=0.422,zoneID=14752}},questType="standard"},
[83742] = {id=83742,name="Call to Attention",level=78,requiredLevel=78,faction="none",expansion=10,questType="standard"},
[83743] = {id=83743,name="Arcane Cold War",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14752,description="A few mages have come but... I expected more to act on Aethas's call to action. But perhaps that was wishful thinking. We need more help despite what you and Kalecgos did at Mourning Rise. Aside from Kel'Thuzad's pendant, the kobolds' plunder was middling-powered artifacts. Meanwhile, there have been reports of powerful magical objects filtering through Azj-Kahet, meaning the nerubians must have scavenged Dalaran's crash first! We must find these artifacts before they are used against us.",starts={{npcID=227409,x=0.298,y=0.578,zoneID=14717}},ends={{npcID=227529,x=0.352,y=0.53,zoneID=14752}},coords={x=0.298,y=0.578,source="quest_giver",zoneID=14717},questType="standard"},
[83749] = {id=83749,name="Delves: The Waterworks",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14795,description="What a trip! Can ye believe how much exists below the depths here? The Machine Speakers were telling me of problems they're having over at a place called the Waterworks. Sounds like kobolds are making trouble again. They're also storing some treasure deeper within the place. What do ye say? Let's go on an adventure and help out these folks!",starts={{npcID=227477,x=0.472,y=0.318,zoneID=14795}},ends={{npcID=227492,x=0.462,y=0.48,zoneID=14795}},coords={x=0.472,y=0.318,source="quest_giver",zoneID=14795},questType="standard"},
[83750] = {id=83750,name="Wanted: Zuramat the Obliterator",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=14752,mapID=2255,description="_",questType="standard"},
[83752] = {id=83752,name="Threats of Zekvir",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14795,description="Someone's watchin' us, . They put this chest here for us to find. Let me know when you're ready. I'll trigger the trap here to see just what exactly is going on.",starts={{npcID=227492,x=0.462,y=0.48,zoneID=14795}},ends={{npcID=227492,x=0.462,y=0.48,zoneID=14795}},coords={x=0.462,y=0.48,source="quest_giver",zoneID=14795},questType="standard"},
[83753] = {id=83753,name="Cannon Karma",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=10416,description="This is gettin' serious, ! Those pirate goons have a cannon and are threatenin' to blow us outta the sky! But this may also be an opportunity. If youse get rid of the monkey firin' the cannon, we maybe can get control of it for ourselves for some payback!",starts={{npcID=227818,x=0.692,y=0.434,zoneID=10416}},ends={{npcID=227818,x=0.692,y=0.434,zoneID=10416}},coords={x=0.692,y=0.434,source="quest_giver",zoneID=10416},questType="standard"},
[83755] = {id=83755,name="Delves: Nightfall Sanctum",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14838,description="Good tae see you again! I've run into a bit of a mess since we last met. Some nerubian called \"Zekvir\" wants the expedition to stop explorin' this land. You know what that means. We've got to explore even more! These Order of Night cultists might have information regarding Zekvir. Let's go to Nightfall Sanctum and see what we can find out.",starts={{npcID=227523,x=0.434,y=0.562,zoneID=14838}},ends={{npcID=227528,x=0.352,y=0.458,zoneID=14838}},coords={x=0.434,y=0.562,source="quest_giver",zoneID=14838},questType="standard"},
[83758] = {id=83758,name="Delver's Call: Fungal Folly",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14957,description="We've got more reports of fungarians returning to a place we've dubbed \"Fungal Folly.\" Explore the cave and eliminate any threats you find.",starts={{npcID=455716,x=0.553,y=0.559,zoneID=14717},{npcID=485669,x=0.614,y=0.803,zoneID=14957}},ends={{npcID=224566,x=0.552,y=0.558,zoneID=14717}},coords={x=0.553,y=0.559,source="quest_giver",zoneID=14717},questType="standard"},
[83759] = {id=83759,name="Delver's Call: Kriegval's Rest",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14717,description="HELP WANTED Kriegval's Rest has become overrun by kobolds! This once sacred resting place of the earthen must be restored.",starts={{npcID=455713,x=0.355,y=0.271,zoneID=15000},{npcID=455716,x=0.553,y=0.559,zoneID=14717}},ends={{npcID=224566,x=0.552,y=0.558,zoneID=14717}},coords={x=0.355,y=0.271,source="quest_giver",zoneID=15000},questType="standard"},
[83761] = {id=83761,name="Delves: The Underkeep",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14752,description="Who would've thought I'd be cozying up in a nerubian's lair! There's a nasty named Zekvir threatening folks trying to explore the island. I've been asking the Weaver for any information she's got. Supposedly, there's a place called the Underkeep that might have records on him. Let's check it out and see what we can find!",starts={{npcID=227544,x=0.572,y=0.422,zoneID=14752}},ends={{npcID=227548,x=0.6,y=0.188,zoneID=14752}},coords={x=0.572,y=0.422,source="quest_giver",zoneID=14752},questType="standard"},
[83763] = {id=83763,name="Preserve the Legacy",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14717,description="The larger threat has been contained, , but I believe there are still other artifacts important to our legacy--good and bad--here in Azj-Kahet . While they are still dangerous, their knowledge may benefit us in the long run. And, we must not allow the nerubians to profit from what they and Xal'atath did to Dalaran. Leave no dark corners here in the Breathing Pit unexplored, .",starts={{npcID=229763,x=0.354,y=0.524,zoneID=14752}},ends={{npcID=228963,x=0.314,y=0.51,zoneID=14717}},coords={x=0.354,y=0.524,source="quest_giver",zoneID=14752},questType="standard"},
[83766] = {id=83766,name="Delver's Call: Dread Pit",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=15003,description="Two things are bad for business. Earnest competition and the Dread Pit caves. We need someone to deal with the latter! Something bad is going on here. We lost a bunch of workers in this cave. We need you to deal with the threat, so we can keep business booming!",starts={{npcID=455685,x=0.584,y=0.643,zoneID=14795},{npcID=455685,x=0.304,y=0.546,zoneID=15003}},ends={{npcID=216311,x=0.588,y=0.642,zoneID=14795}},coords={x=0.584,y=0.643,source="quest_giver",zoneID=14795},questType="standard"},
[83767] = {id=83767,name="Delver's Call: The Sinkhole",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=15175,description="We have reports of large amounts of kobyss gathering towards a lair called the Sinkhole. There are concerns they plan to attack the smaller coast villages when they get the chance. There's a hefty reward for anyone who can go into the Sinkhole and stop whatever they're planning!",starts={{npcID=455704,x=0.487,y=0.396,zoneID=14838},{npcID=455704,x=0.53,y=0.201,zoneID=15175}},ends={{npcID=214019,x=0.492,y=0.41,zoneID=14838}},coords={x=0.487,y=0.396,source="quest_giver",zoneID=14838},questType="standard"},
[83768] = {id=83768,name="Delver's Call: The Skittering Breach",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=15004,description="Call For Any Who Can Swing a Sword or Sling a Spell! The nerubians perform foul rituals in the shadow of our once beautiful Aegis Wall. Word is that a dark temple dedicated to their cursed gods rests beneath the ground. Someone must investigate this foul place and put an end to their schemes.",starts={{npcID=455694,x=0.678,y=0.456,zoneID=14838},{npcID=455694,x=0.726,y=0.55,zoneID=15004}},ends={{npcID=225857,x=0.68,y=0.442,zoneID=14838}},coords={x=0.678,y=0.456,source="quest_giver",zoneID=14838},questType="standard"},
[83769] = {id=83769,name="Delver's Call: Mycomancer Cavern",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14998,description="Spice Help Needed! Fungarians in the Mycomancer Caverns have been raiding spice crates bound for Lorel's Crossing. Someone needs to go into those caverns and push back the fungarian menace! Will pay well.",starts={{npcID=455690,x=0.689,y=0.445,zoneID=14838},{npcID=455690,x=0.194,y=0.369,zoneID=14998}},ends={{npcID=217611,x=0.692,y=0.456,zoneID=14838}},coords={x=0.689,y=0.445,source="quest_giver",zoneID=14838},questType="standard"},
[83770] = {id=83770,name="Delver's Call: Spiral Weave",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14752,description="A lot of us survivors have heard stories about the Spiral Weave. Seems like it's a place where the nerubians have some heavy military operations going on. Taking the fight to them would help put a serious dent in the nerubians' war plans.",starts={{npcID=211721,x=0.588,y=0.186,zoneID=14752}},ends={{npcID=211721,x=0.588,y=0.186,zoneID=14752}},coords={x=0.588,y=0.186,source="quest_giver",zoneID=14752},questType="standard"},
[83771] = {id=83771,name="Delver's Call: Tak-Rethan Abyss",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=15008,description="WEAVER'S ORDERS The Tak-Rethan Abyss continues to be a place of great unrest and trouble. Someone must keep the threats in check before they interfere with our plans.",starts={{npcID=455720,x=0.567,y=0.408,zoneID=14752},{npcID=455720,x=0.531,y=0.202,zoneID=15008}},ends={{npcID=207471,x=0.556,y=0.438,zoneID=14752}},coords={x=0.567,y=0.408,source="quest_giver",zoneID=14752},questType="standard"},
[83773] = {id=83773,name="Farewell, City of Magic",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,description="Not all the Kirin Tor's issues can be solved in one day. But one way we can act is to honor those who have fallen. After speaking with everyone here, we have cobbled together a ceremony to send off those we have lost... and Dalaran. We would be honored if you would join us and participate in remembering our fallen comrades in the Kirin Tor.",starts={{npcID=227436,x=0.314,y=0.51,zoneID=14717},{npcID=227436,x=0.424,y=0.272,zoneID=14771}},ends={{npcID=227436,x=0.314,y=0.51,zoneID=14717},{npcID=227436,x=0.424,y=0.272,zoneID=14771}},coords={x=0.314,y=0.51,source="quest_giver",zoneID=14717},questType="standard"},
[83794] = {id=83794,name="Soggy Celebration Crate",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=440,description="Alyx would appreciate the supplies returned.>",ends={{npcID=226683,x=0.63,y=0.502,zoneID=440},{npcID=232404,x=0.63,y=0.502,zoneID=440},{npcID=232410,x=0.63,y=0.502,zoneID=440}},questType="standard"},
[83825] = {id=83825,name="Restoring A Grand Tale",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=440,description="It was terrible! My book was shredded, and the pages flew everywhere! I saw some caught in the sand devils that went down the tunnel, others caught on adventurers heading out to face the big monsters in Tanaris, and others are scattered around here. Maybe that bird thing of yours could find them? Please help me get the pages back so I can restore my book! Oh, and watch out for that shady Cravitz Lorent. He's selling new copies for a hundred gold under the Fashion Frenzy stage. Robbery!",questType="standard"},
[83832] = {id=83832,name="Torn Dreams",level=10,requiredLevel=30,faction="both",expansion=10,zoneID=440,description="Hello again! I could really use your help here. A visitor by the name of Addie Fizzlebog had a book damaged by some time devils that swept through here last night. I am still dealing with all the other problems they caused and was hoping you could help Addie with her issue.",starts={{npcID=226683,x=0.63,y=0.502,zoneID=440},{npcID=232404,x=0.63,y=0.502,zoneID=440}},ends={{npcID=231433,x=0.63,y=0.52,zoneID=440}},coords={x=0.63,y=0.502,source="quest_giver",zoneID=440},questType="standard"},
[83931] = {id=83931,name="Battered Celebration Crate",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14771,description="Alyx would appreciate the supplies returned.>",ends={{npcID=226683,x=0.63,y=0.502,zoneID=440},{npcID=232404,x=0.63,y=0.502,zoneID=440},{npcID=232406,x=0.63,y=0.502,zoneID=440},{npcID=232410,x=0.63,y=0.502,zoneID=440},{npcID=234262,x=0.504,y=0.386,zoneID=14771}},questType="standard"},
[83932] = {id=83932,name="Historical Documents",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=10416,description="Imagine having the chance to accompany Sky-Captain Elaena Lancekat on such a great adventure. This is the opportunity of a lifetime! But if I'm going to write a book about this journey, I need to gather some historical information about this island. Perhaps you could collect any notes or documents that you find? Anything might be useful and tell us about the history of this place!",starts={{npcID=229716,x=0.708,y=0.398,zoneID=10416}},ends={{npcID=229716,x=0.708,y=0.398,zoneID=10416}},coords={x=0.708,y=0.398,source="quest_giver",zoneID=10416},questType="standard"},
[83933] = {id=83933,name="The Kaja'Coast",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=8499,description="Alright, we got the punch card to the Kaja'Coast and a pretty good reason to believe Venture's shmoozin' up to Gallywix a lot more than we thought. Noggenfogger said we'd find answers at those mines, and that means goin' down to the Kaja'Coast for a look. Let's go. We'll meet you over at Slam Central.",starts={{npcID=225639,x=0.532,y=0.71,zoneID=15347}},ends={{npcID=225645,x=0.222,y=0.544,zoneID=8499}},coords={x=0.532,y=0.71,source="quest_giver",zoneID=15347},questType="standard"},
[84020] = {id=84020,name="A Mech in Need",level=1,requiredLevel=1,faction="both",expansion=10,zoneID=14795,description="This mechsuit has seen better days. Maybe a skilled Machine Speaker could assist you. I know Speaker Jurlax has been assigning machinists to mechsuit maintenance lately. He probably has some advice for you.",ends={{npcID=213875,x=0.47,y=0.324,zoneID=14795}},questType="standard"},
[84021] = {id=84021,name="Machine Without Cogs",level=1,requiredLevel=1,faction="both",expansion=10,zoneID=14795,description="Diagnosis: This machine's movement is impaired. We must get it moving again. I'm going to need some replacement parts. The gears must keep grinding.",starts={{npcID=213875,x=0.47,y=0.324,zoneID=14795}},ends={{npcID=213875,x=0.47,y=0.324,zoneID=14795}},coords={x=0.47,y=0.324,source="quest_giver",zoneID=14795},questType="standard"},
[84023] = {id=84023,name="Orienting Ourselves",level=1,requiredLevel=1,faction="both",expansion=10,zoneID=14795,description="The machine moves without intent. Let us guide it toward purpose. Deliver direction unto this device.",starts={{npcID=213875,x=0.47,y=0.324,zoneID=14795}},ends={{npcID=213875,x=0.47,y=0.324,zoneID=14795}},coords={x=0.47,y=0.324,source="quest_giver",zoneID=14795},questType="standard"},
[84024] = {id=84024,name="Clutching Control",level=1,requiredLevel=1,faction="both",expansion=10,zoneID=14795,description="The machine breathes without life. We must provide ours. Find a conduit for the will of the divine.",starts={{npcID=213875,x=0.47,y=0.324,zoneID=14795}},ends={{npcID=213875,x=0.47,y=0.324,zoneID=14795}},coords={x=0.47,y=0.324,source="quest_giver",zoneID=14795},questType="standard"},
[84025] = {id=84025,name="Repurposed, Restored",level=1,requiredLevel=1,faction="both",expansion=10,zoneID=14795,mapID=2214,starts={{npcID=213875,x=0.47,y=0.324,mapID=2214}},ends={{npcID=213875,x=0.47,y=0.324,mapID=2214}},coords={x=0.47,y=0.324,source="quest_giver",mapID=2214},questType="standard"},
[84084] = {id=84084,name="Just a Pinch",level=68,requiredLevel=68,faction="both",expansion=10,zoneID=14771,description="Dust is the foundation of the art of enchantment. Where novice enchanters turn up their noses at such a common material, a master understands its versatility. Bring me Storm Dust . No matter our expertise, we must always return to the fundamentals.",starts={{npcID=219085,x=0.528,y=0.712,zoneID=14771}},ends={{npcID=219085,x=0.528,y=0.712,zoneID=14771}},coords={x=0.528,y=0.712,source="quest_giver",zoneID=14771},questType="standard"},
[84085] = {id=84085,name="The Power of Potential",level=68,requiredLevel=68,faction="both",expansion=10,zoneID=14771,description="As enchanters, we do not merely trade in runes or wands. Our true commodity is potential. We take the power of possibility and infuse it into tangible forms. For this, Gleaming Shards are essential. I require several to continue my work.",starts={{npcID=219085,x=0.528,y=0.712,zoneID=14771}},ends={{npcID=219085,x=0.528,y=0.712,zoneID=14771}},coords={x=0.528,y=0.712,source="quest_giver",zoneID=14771},questType="standard"},
[84086] = {id=84086,name="A Rare Necessity",level=68,requiredLevel=68,faction="both",expansion=10,zoneID=14771,description="Occasionally, we are called upon to provide our greatest and most powerful boons. For these, I require a Refulgent Crystal . True, such crystals are rare, but necessary for us to reach the heights of our art. Worry not, it will not be squandered.",starts={{npcID=219085,x=0.528,y=0.712,zoneID=14771}},ends={{npcID=219085,x=0.528,y=0.712,zoneID=14771}},coords={x=0.528,y=0.712,source="quest_giver",zoneID=14771},questType="standard"},
[84098] = {id=84098,name="Level 37",level=70,requiredLevel=70,faction="none",expansion=10,questType="standard"},
[84121] = {id=84121,name="A Little Insurance",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=8499,description="There are too many Darkfuse guardin' this place for us to sneak around them. We're gonna have to thin 'em out the old fashioned way. Take out as many Darkfuse as you can. Me and Gazlowe will do some reconnaissance.",starts={{npcID=227937,x=0.222,y=0.544,zoneID=8499}},ends={{npcID=228132,x=0.22,y=0.576,zoneID=8499}},coords={x=0.222,y=0.544,source="quest_giver",zoneID=8499},questType="standard"},
[84122] = {id=84122,name="Cut the Cameras",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=8499,description="Gallywix ain't an idiot. He's got those surveillance birds keepin' an eye on this entire area. We're gonna need to bring 'em offline if we wanna keep a low profile--and by that, I mean smash 'em to itty bitty pieces. If you need help grabbin' them outta the air, use this auto-grappler. Oh, and scoop some of their parts up for me when you're done. I've got an idea.",starts={{npcID=225645,x=0.222,y=0.544,zoneID=8499}},ends={{npcID=225648,x=0.22,y=0.576,zoneID=8499}},coords={x=0.222,y=0.544,source="quest_giver",zoneID=8499},questType="standard"},
[84127] = {id=84127,name="Blacksmithing Services Requested",level=68,requiredLevel=68,faction="both",expansion=10,zoneID=14771,description="Greetings, . The Artisan's Consortium is looking for highly skilled artisans to complete orders for local clientele. If you think your work is up to the standards and quality we expect, please take a at shot at filling out some of our public orders. You can also fill orders for patrons of your own, guild orders, or personal orders. Come speak with me once you've completed your designs, and may the wind guide your hands and heart.",starts={{npcID=228177,x=0.592,y=0.554,zoneID=14771}},ends={{npcID=228177,x=0.592,y=0.554,zoneID=14771}},coords={x=0.592,y=0.554,source="quest_giver",zoneID=14771},questType="standard"},
[84128] = {id=84128,name="Engineering Services Requested",level=68,requiredLevel=68,faction="both",expansion=10,zoneID=14771,description="Greetings, . The Artisan's Consortium is looking for highly skilled artisans to complete orders for local clientele. If you think your work is up to the standards and quality we expect, please take a at shot at filling out some of our public orders. You can also fill orders for patrons of your own, guild orders, or personal orders. Come speak with me once you've completed your designs, and may the wind guide your hands and heart.",starts={{npcID=228177,x=0.592,y=0.554,zoneID=14771}},ends={{npcID=228177,x=0.592,y=0.554,zoneID=14771}},coords={x=0.592,y=0.554,source="quest_giver",zoneID=14771},questType="standard"},
