[85546] = {id=85546,name="Resonance Crystals",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,mapID=2339,starts={{npcID=223728,x=0.392,y=0.242,mapID=2339}},ends={{npcID=223728,x=0.392,y=0.242,mapID=2339}},coords={x=0.392,y=0.242,source="quest_giver",mapID=2339},questType="standard"},
[85562] = {id=85562,name="Tougher Than We Thought",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Hah! I've never been feeling better! Now, we seize back what rightfully belongs to Blackwater, . They've turned our prized headquarters into a smuggler's cove for that foul sludge. There are too many crates of Black Blood to deal with right now, but they can't move their cargo without fresh bodies. Let's cut them down.",starts={{npcID=233296,x=0.638,y=0.174,zoneID=15347}},ends={{npcID=235849,x=0.69,y=0.509,zoneID=15347}},coords={x=0.638,y=0.174,source="quest_giver",zoneID=15347},questType="standard"},
[85570] = {id=85570,name="The Tattered Journal",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=10416,description="Stellin Verasa would be interested in this journal back in camp.>",starts={{npcID=494923,x=0.376,y=0.759,zoneID=15827}},ends={{npcID=229716,x=0.708,y=0.398,zoneID=10416}},coords={x=0.376,y=0.759,source="quest_giver",zoneID=15827},questType="standard"},
[85571] = {id=85571,name="Scattered To The Winds",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=10416,description="My goodness! This journal is missing many of its pages! This journal doesn't look very old... and it seems to be of human origin? Could this be the key to discovering what happened to the humans that came here? What a mystery! But less of a mystery if we could find the missing pages... Would you keep an eye out for them while you're out in the field?",starts={{npcID=229716,x=0.708,y=0.398,zoneID=10416}},ends={{npcID=229716,x=0.708,y=0.398,zoneID=10416}},coords={x=0.708,y=0.398,source="quest_giver",zoneID=10416},questType="standard"},
[85572] = {id=85572,name="A Group Effort",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=10416,description="This is, um, quite the mess you've handed me. All these pages... what order do they go in? Aha! This journal seems to have belonged to a Kul Tiran that came here... ...and it might hold the key to learning about their time on the isle. But the pages are hard to read... perhaps we should ask around to see if anyone can read them? Here, take a few pages. I'll keep trying to decipher the base journal while you go to camp and ask around.",starts={{npcID=229716,x=0.708,y=0.398,zoneID=10416}},ends={{npcID=229716,x=0.708,y=0.398,zoneID=10416}},coords={x=0.708,y=0.398,source="quest_giver",zoneID=10416},questType="standard"},
[85573] = {id=85573,name="Laid To Rest At Last",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=10416,description="This poor fellow was part of a crew that sailed here aboard a ship called the Maiden's Whisper. They were almost wiped out by a storm, but then even the survivors disappeared! He was the last one and... didn't make it either in the end. Perhaps we can put his memory to rest? I spotted a graveyard out behind the Kul Tiran's base... perhaps setting the journal there amongst his crew's graves will bring his memory some peace.",starts={{npcID=229716,x=0.708,y=0.398,zoneID=10416}},ends={{npcID=229716,x=0.708,y=0.398,zoneID=10416}},coords={x=0.708,y=0.398,source="quest_giver",zoneID=10416},questType="standard"},
[85574] = {id=85574,name="Hazy Celebration Crate",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14771,description="Alyx would likely appreciate the supplies returned.>",ends={{npcID=226683,x=0.63,y=0.502,zoneID=440},{npcID=232404,x=0.63,y=0.502,zoneID=440},{npcID=232410,x=0.63,y=0.502,zoneID=440},{npcID=234262,x=0.504,y=0.386,zoneID=14771}},questType="standard"},
[85589] = {id=85589,name="Ruffled Pages",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=10416,description="Many of the wyvern on this isle have crafted their nests from folios, scrolls, and documents they scavenge from the isle's ruins. Because of this, their nests may hold the clues we need to understand the full history of this place. Our scouts have secured grappling holds for you to climb to their nests, but use any means you like to recover the paper the wyverns have used as nesting material. Our knowledge of the isle's history depends on it!",starts={{npcID=229716,x=0.708,y=0.398,zoneID=10416}},ends={{npcID=229716,x=0.708,y=0.398,zoneID=10416}},coords={x=0.708,y=0.398,source="quest_giver",zoneID=10416},questType="standard"},
[85648] = {id=85648,name="Delver's Call: Earthcrawl Mines",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14999,description="HELP WANTED Troubles continue within Earthcrawl Mines. Fine pay to whoever can handle it.",starts={{npcID=455716,x=0.553,y=0.559,zoneID=14717},{npcID=487805,x=0.447,y=0.121,zoneID=14999}},ends={{npcID=224566,x=0.552,y=0.558,zoneID=14717}},coords={x=0.553,y=0.559,source="quest_giver",zoneID=14717},questType="standard"},
[85649] = {id=85649,name="Delver's Call: The Waterworks",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14795,description="NOTICE The Waterworks have become unstable. Request aid in addressing issues.",starts={{npcID=487815,x=0.466,y=0.177,zoneID=15002}},ends={{npcID=213875,x=0.47,y=0.324,zoneID=14795}},coords={x=0.466,y=0.177,source="quest_giver",zoneID=15002},questType="standard"},
[85664] = {id=85664,name="Delver's Call: Nightfall Sanctum",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14838,description="CALL FOR AID! The Order of Night may have a base set up in a location called Nightfall Sanctum. It is imperative that we stop any of their operations as soon as possible.",starts={{npcID=487847,x=0.73,y=0.274,zoneID=15005}},ends={{npcID=214380,x=0.432,y=0.564,zoneID=14838}},coords={x=0.73,y=0.274,source="quest_giver",zoneID=15005},questType="standard"},
[85666] = {id=85666,name="Delver's Call: Spiral Weave",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14752,description="HELP WANTED Word is the nerubians have big military operations within the Spiral Weave. Help out the survivors of the Dalaran crash by putting a stop to them!",starts={{npcID=487851,x=0.531,y=0.762,zoneID=15007}},ends={{npcID=211721,x=0.588,y=0.186,zoneID=14752}},coords={x=0.531,y=0.762,source="quest_giver",zoneID=15007},questType="standard"},
[85667] = {id=85667,name="Delver's Call: The Underkeep",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14752,description="WEAVER'S ORDERS Dark operations are happening within a place called the Underkeep. I wish for it to halt.",starts={{npcID=487855,x=0.357,y=0.265,zoneID=15009}},ends={{npcID=207471,x=0.556,y=0.438,zoneID=14752}},coords={x=0.357,y=0.265,source="quest_giver",zoneID=15009},questType="standard"},
[85678] = {id=85678,name="Repair Yourself",level=1,requiredLevel=1,faction="alliance",expansion=10,zoneID=10424,mapID=1409,description="Your gear isn't looking too great from your last excursion. Speak to Quartermaster Richter to get it repaired.",starts={{npcID=156807,x=0.522,y=0.552,mapID=1409},{npcID=245394,x=0.522,y=0.556,mapID=1409}},ends={{npcID=156807,x=0.522,y=0.552,mapID=1409},{npcID=245394,x=0.522,y=0.556,mapID=1409}},coords={x=0.522,y=0.552,source="quest_giver",mapID=1409},questType="standard"},
[85710] = {id=85710,name="Sizing Them Up",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="We have been trying to do medical checkups on the slatebacks, but they are... aggressive in their disagreement. Ve'nari has provided this shrinking device to help. Collect some for me.",starts={{npcID=230736,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=230736,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[85711] = {id=85711,name="Unsolicited Feedback",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Alice is back, and she's a much better cook than she ever was before she became a rat. But don't take my word for it. Here, hand out some food and hear it straight from the customers!",starts={{npcID=226728,x=0.382,y=0.882,zoneID=15347}},ends={{npcID=226728,x=0.382,y=0.882,zoneID=15347}},coords={x=0.382,y=0.882,source="quest_giver",zoneID=15347},questType="standard"},
[85716] = {id=85716,name="Rune-Seared Spear",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=10416,description="Angorla may have interest in studying this weapon.>",ends={{npcID=228074,x=0.712,y=0.442,zoneID=10416}},questType="standard"},
[85718] = {id=85718,name="A Shining Stone",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,mapID=2339,starts={{npcID=223728,x=0.392,y=0.242,mapID=2339}},ends={{npcID=223728,x=0.392,y=0.242,mapID=2339}},coords={x=0.392,y=0.242,source="quest_giver",mapID=2339},questType="standard"},
[85721] = {id=85721,name="Killer Instinct",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="The hunting training seems to be working with the Thorntail Matriarch , and we'd like to keep up with it. Can ye have her hunt a few more lapbugs at your direction?",starts={{npcID=235353,x=0.758,y=0.34,zoneID=15336}},ends={{npcID=235353,x=0.758,y=0.34,zoneID=15336}},coords={x=0.758,y=0.34,source="quest_giver",zoneID=15336},questType="standard"},
[85722] = {id=85722,name="Making a Deposit",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Ve'nari may find this useful for powering the eco-domes.>",ends={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},questType="standard"},
[85724] = {id=85724,name="Repel the Invaders",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="A big lunk of a hobgoblin, Skeez, took over the docks around the time that Gallywix had me thrown in the brig. He moved his Darkfuse in, and a lot of my Blackwater lads went missing. Captain took that personal, and so do I. Skeez thinks Gallywix will keep him safe. Let's kill him.",starts={{npcID=233296,x=0.638,y=0.174,zoneID=15347}},ends={{npcID=235849,x=0.69,y=0.509,zoneID=15347}},coords={x=0.638,y=0.174,source="quest_giver",zoneID=15347},questType="standard"},
[85730] = {id=85730,name="Salvaging What's Left",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="The loss of an eco-dome is unimaginable. The death of Om'bera... I cannot leave without retrieving the research crates! Her work must live on, even if she cannot. Om'bera's manifest says that there were at least five crates full of research and resources.",starts={{npcID=230294,x=0.71,y=0.58,zoneID=15336}},ends={{npcID=230603,x=0.684,y=0.52,zoneID=15336}},coords={x=0.71,y=0.58,source="quest_giver",zoneID=15336},questType="standard"},
[85753] = {id=85753,name="The Drain",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=10416,mapID=2369,questType="standard"},
