[85765] = {id=85765,name="Shuddering Hollow",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=10416,mapID=2369,questType="standard"},
[85769] = {id=85769,name="The Party Must Go On",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15347,mapID=2346,questType="standard"},
[85780] = {id=85780,name="Right Where We Want Him",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Gallywix is down, but he ain't out. The Gallagio is built like a fortress. If we want to keep him from threatening Undermine , or Azeroth, we gotta figure out how to get him outta there. Meet me and the other bosses back at the Incontinental Hotel.",starts={{npcID=235238,x=0.57,y=0.446,zoneID=15347}},ends={{npcID=233482,x=0.434,y=0.51,zoneID=15347}},coords={x=0.57,y=0.446,source="quest_giver",zoneID=15347},questType="standard"},
[85804] = {id=85804,name="The Parent Trap",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="I'm happy to help in any way that I can. To find Alleria, you must fly far north from here. She's hunting a new Shadowguard lieutenant in the hope of extracting information from him. Last I heard, she was on the outskirts of a place called the Fracture of Laacuna.",starts={{npcID=234263,x=0.512,y=0.198,zoneID=15781}},ends={{npcID=231987,x=0.552,y=0.278,zoneID=15336}},coords={x=0.512,y=0.198,source="quest_giver",zoneID=15781},questType="standard"},
[85805] = {id=85805,name="Renowned with the Cartels of Undermine",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Thanks for the hard work there, pal! We've got some supplies prepped for you in the hotel. Come grab 'em from Smaks Topskimmer .",ends={{npcID=231409,x=0.436,y=0.508,zoneID=15347}},questType="standard"},
[85806] = {id=85806,name="Exalted with the Bilgewater Cartel",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="You done good for the Bilgewater when they needed you. They won't forget that. Talk to Rocco Razzboom , he'll take care of ya.",ends={{npcID=231406,x=0.39,y=0.22,zoneID=15347}},questType="standard"},
[85807] = {id=85807,name="Exalted with the Blackwater Cartel",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="The Blackwater Cartel is sailing smooth thanks to you. Boatswain Hardee has readied yer cut o' the plunder... that is to say, a respectable reward for your work.",ends={{npcID=231405,x=0.632,y=0.168,zoneID=15347}},questType="standard"},
[85808] = {id=85808,name="Exalted with Darkfuse Solutions",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Helpin' the Darkfuse ain't real popular, so they want to say thanks. They gotta do it quiet like, so find Stitch Lowdown down in the sewers near Hovel Hill.",ends={{npcID=231396,x=0.306,y=0.388,zoneID=15347}},questType="standard"},
[85809] = {id=85809,name="Exalted with the Steamwheedle Cartel",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="The Steamwheedle Cartel wants to thank you for all the work you have done. Observe all safety protocols and see Lab Assistant Laszly for a reward.",ends={{npcID=231408,x=0.272,y=0.724,zoneID=15347}},questType="standard"},
[85810] = {id=85810,name="Exalted with Venture Co.",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Venture Co. is ready to pay dividends on all the work you've done for us. Speak to Shredz the Scrapper for your reward.",ends={{npcID=231407,x=0.532,y=0.726,zoneID=15347}},questType="standard"},
[85827] = {id=85827,name="Glinting and Gleaming",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=15347,mapID=2346,starts={{npcID=231409,x=0.436,y=0.508,mapID=2346}},ends={{npcID=231409,x=0.436,y=0.508,mapID=2346}},coords={x=0.436,y=0.508,source="quest_giver",mapID=2346},questType="standard"},
[85862] = {id=85862,name="A Prince's Duty",level=10,requiredLevel=10,faction="both",expansion=10,description="It's a big day, lad. We've got a parade of the troops, a visiting contingent from Ironforge, and I hear word your father--er, King Terenas--will be here to oversee everything. It's days like today that you've been forged for, Arthas. Inspire your men. Prove yourself. Whip these troops into shape. No doubt Muradin has been itching for a brawl as well...",questType="standard"},
[85869] = {id=85869,name="Many Jobs, Handle It!",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Shipping & Handling is tryin' out a new driver incentive program. Do some jobs and let's see how it goes eh?",starts={{npcID=231409,x=0.436,y=0.508,zoneID=15347}},ends={{npcID=231409,x=0.436,y=0.508,zoneID=15347}},coords={x=0.436,y=0.508,source="quest_giver",zoneID=15347},questType="standard"},
[85871] = {id=85871,name="Lorewalking: The Blade's Forces",level=10,requiredLevel=10,faction="both",expansion=10,description="Xal'atath brings with her an army of shadows and tricks. They are nothing to our evolved forms! You have been chosen--blessed with power by N'Zoth to serve as his champion. Go now and destroy them!",questType="standard"},
[85873] = {id=85873,name="Another Shadowy Invitation",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15336,mapID=2371,description="$p, do you like paperwork and forms as much as I do? Then let us dispense with the expedited entry to Tazavesh and experience once more the joy of jumping through bureaucratic hoops and paying bribes as is the tradition of all great broker stories. WARNING! COMPLETING THIS QUEST WILL REQUIRE YOU TO FINISH CHAPTER 1 OF THE 11.2 CAMPAIGN!",questType="standard"},
[85876] = {id=85876,name="Reading the Runes",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15827,description="My curiosity is still not terminated, . I would like to know more about these vrykul and why they came to this land. Bargus 's wiry brows knit together and his mustache bristles as he thinks.> The tablets you found were by far the best source of information on the vrykul and whoever this \"Cyrce\" is. Perhaps there are additional tablets we missed? I have my ordained duties here, but please examine them and report back to me.",starts={{npcID=230242,x=0.676,y=0.42,zoneID=10416}},ends={{npcID=230242,x=0.676,y=0.42,zoneID=10416}},coords={x=0.676,y=0.42,source="quest_giver",zoneID=10416},questType="standard"},
[85878] = {id=85878,name="O' Thanagor",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=4820,description="You are the Lich King. The whole of Azeroth is arrayed against you. Show them what it means to be king.",ends={{npcID=236114,x=0.642,y=0.162,zoneID=1519},{npcID=236114,x=0.542,y=0.566,zoneID=1637},{npcID=236114,x=0.496,y=0.316,zoneID=14771},{npcID=236114,x=0.586,y=0.708,zoneID=15969}},questType="standard"},
[85879] = {id=85879,name="Reduce, Reuse, Resell",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="The guys over at S.C.R.A.P. could use some extra hands this week. You want a piece of the pie, go find one of their reps named Carlo out in the field and see if he's got any work for you. But if you find a piece of pie in any of those trash piles, don't, uh... Don't actually eat it. I hope that kinda goes without sayin'.",starts={{npcID=231409,x=0.436,y=0.508,zoneID=15347},{npcID=237659,x=0.266,y=0.374,zoneID=15347}},ends={{npcID=231409,x=0.436,y=0.508,zoneID=15347},{npcID=237659,x=0.266,y=0.374,zoneID=15347}},coords={x=0.436,y=0.508,source="quest_giver",zoneID=15347},questType="standard"},
[85884] = {id=85884,name="Lorewalking: The Prince Who Would Be King",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=65,description="Before I can tell you the story of the Lich King, we must learn about who he was before he put on his crown. Before he pulled that cursed sword from the depths of Frostmourne Cavern. We must talk about the prince who was promised the world, and the people who championed his cause. We must start in Lordaeron, many years ago, on a day of pomp and circumstance.",starts={{npcID=236114,x=0.642,y=0.162,zoneID=1519},{npcID=236114,x=0.542,y=0.566,zoneID=1637},{npcID=236114,x=0.496,y=0.316,zoneID=14771},{npcID=236114,x=0.586,y=0.708,zoneID=15969}},ends={{npcID=236114,x=0.642,y=0.162,zoneID=1519},{npcID=236114,x=0.542,y=0.566,zoneID=1637},{npcID=236114,x=0.496,y=0.316,zoneID=14771},{npcID=236114,x=0.586,y=0.708,zoneID=15969}},coords={x=0.642,y=0.162,source="quest_giver",zoneID=1519},questType="standard"},
[85885] = {id=85885,name="Lorewalking: No King Rules Forever",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=15969,description="What makes a king? Is it his crown? Is it the sharpness of his sword? The coldness of his heart? Perhaps the undying servitude of his people? Just as it is difficult to say when a sapling becomes a tree, or a mountain becomes a hill, so too is it difficult to know when exactly Arthas Menethil passed into memory, and the Lich King was born. Where do we draw the line between man and monster?",starts={{npcID=236114,x=0.642,y=0.162,zoneID=1519},{npcID=236114,x=0.542,y=0.566,zoneID=1637},{npcID=236114,x=0.496,y=0.316,zoneID=14771},{npcID=236114,x=0.586,y=0.708,zoneID=15969}},ends={{npcID=236114,x=0.642,y=0.162,zoneID=1519},{npcID=236114,x=0.542,y=0.566,zoneID=1637},{npcID=236114,x=0.496,y=0.316,zoneID=14771},{npcID=236114,x=0.586,y=0.708,zoneID=15969}},coords={x=0.642,y=0.162,source="quest_giver",zoneID=1519},questType="standard"},
[85900] = {id=85900,name="Breakneck Bolt",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=15347,mapID=2346,questType="standard"},
[85901] = {id=85901,name="Breakneck Bolt - Reverse",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=15347,mapID=2346,questType="standard"},
[85902] = {id=85902,name="Junkyard Jaunt",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=15347,mapID=2346,questType="standard"},
[85903] = {id=85903,name="Junkyard Jaunt - Reverse",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=15347,mapID=2346,questType="standard"},
[85904] = {id=85904,name="Casino Cruise",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=15347,mapID=2346,questType="standard"},
[85905] = {id=85905,name="Casino Cruise - Reverse",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=15347,mapID=2346,questType="standard"},
[85906] = {id=85906,name="Sandy Scuttle",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=15347,mapID=2346,questType="standard"},
[85907] = {id=85907,name="Sandy Scuttle - Reverse",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=15347,mapID=2346,questType="standard"},
[85941] = {id=85941,name="Attitude Adjustment",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="I'm not a violent gal by nature, but there are a lot of Darkfuse out there. They're already hassling the locals and they won't like you guys asking questions. You wanna keep your friends safe? You wanna put the locals in better spirits? It'd probably be best if there were a whole lot less Darkfuse. If you catch my meaning.",starts={{npcID=229246,x=0.452,y=0.422,zoneID=15347}},ends={{npcID=229246,x=0.452,y=0.422,zoneID=15347}},coords={x=0.452,y=0.422,source="quest_giver",zoneID=15347},questType="standard"},
[85947] = {id=85947,name="An Original Journey Through Time",level=0,requiredLevel=0,faction="both",expansion=10,zoneID=1637,description="Old warriors keep spinning tales about how things were so much tougher around Azeroth back in their day. I bet they would say you're not tough enough to last 10 minutes in their world. Think you're tough enough to find out? How 'bout you show me.",starts={{npcID=223884,x=0.628,y=0.502,zoneID=440},{npcID=234555,x=0.56,y=0.19,zoneID=1519},{npcID=234555,x=0.528,y=0.83,zoneID=1637}},ends={{npcID=223884,x=0.628,y=0.502,zoneID=440},{npcID=234555,x=0.56,y=0.19,zoneID=1519},{npcID=234555,x=0.528,y=0.83,zoneID=1637}},coords={x=0.628,y=0.502,source="quest_giver",zoneID=440},questType="standard"},
[85949] = {id=85949,name="A Frozen Journey Through Time",level=0,requiredLevel=0,faction="both",expansion=10,zoneID=4395,mapID=125,description="The chill star shines upon the land with its cold light as even the spirits retreat to the shadows. This star is unlike any other in the skies, sapping warmth and life. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.",questType="standard"},
[85953] = {id=85953,name="The Drag",level=50,requiredLevel=50,faction="none",expansion=10,zoneID=15946,questType="standard"},
[85961] = {id=85961,name="Moving the Pawns",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="There is a small island to the northwest of here, called Overlook Zo'Shuul. My scouts have been searching for a way into Manaforge Omega, where we must stop the return of the All-Devouring. If we are fortunate, the scouts have already found a safe pathway inside.",starts={{npcID=230700,x=0.342,y=0.108,zoneID=15781}},ends={{npcID=230806,x=0.482,y=0.366,zoneID=15336}},coords={x=0.342,y=0.108,source="quest_giver",zoneID=15781},questType="standard"},
[86151] = {id=86151,name="Faceless Mask of the Burned Bridge",level=80,requiredLevel=80,faction="both",expansion=10,description="The displaced warrior is always on uneasy footing, especially one who is removed from her home world. The void makes this unsteadiness a reality where one step can lead into the abyss or drain you to your core.",questType="standard"},
[86152] = {id=86152,name="Faceless Mask of the Daredevil",level=80,requiredLevel=80,faction="both",expansion=10,description="The hunter never sought to lead yet sought a challenge in life at every turn. He directed his allies with a deft hand and never shied from diving in to the melee himself. The prowess he showed made him as well as my other minions much more deadly. Return this mask to the altar of the Daredevil to challenge your own resolve in battle as your foes attacks cut even more deep.",questType="standard"},
[86153] = {id=86153,name="Faceless Mask of the Dark Imagination",level=80,requiredLevel=80,faction="both",expansion=10,description="These magi, twisting their magic to manipulate and conquer the world. Imagining greater power, they tread along the lines of the voids' domain. In these pursuits, these magi came to the realization that in the depths of one's imagination lie truly dark and terrible things.",questType="standard"},
[86154] = {id=86154,name="Faceless Mask of the Pained",level=80,requiredLevel=80,faction="both",expansion=10,description="Trading in secrets, trading in lies, operating on the fringes are all the Spymaster knows. His lost passions, lost loves are all gone, crushed under his own duty and loyalty to the crown. Nothing is left, nothing but the pain. Pain is an apt tutor and tool and one in which the void knows intimately. Return my mask if you dare to feel the many forms pain can take.",questType="standard"},
[86155] = {id=86155,name="Faceless Mask of the Long Night",level=80,requiredLevel=80,faction="both",expansion=10,description="The endurance needed to make it this far is extraordinary and the feat of a long experienced adventurer. Yet, the longest night is nigh and with it our ultimate conquest. Those that fight the coming of eternal twilight know only futility, for in the Longest Night they will be on the edge of sanity forever.",questType="standard"},
[86156] = {id=86156,name="Getting Involved",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=10416,description="You. Do that again. Could be good stuff we ain't seen yet. Get those caves open an' see what's in there!",starts={{npcID=227817,x=0.694,y=0.436,zoneID=10416}},ends={{npcID=227817,x=0.694,y=0.436,zoneID=10416}},coords={x=0.694,y=0.436,source="quest_giver",zoneID=10416},questType="standard"},
[86174] = {id=86174,name="Special Assignment: Storm's a Brewin",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=10416,mapID=2369,questType="standard"},
[86182] = {id=86182,name="Ghost Buster",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="I have been working on the Oasis console and I believe I am ready for the next step. It will involve destruction, so naturally I thought of you. I need you to use a phase conduit to shift into the Untethered Space of K'aresh and retrieve the essence of the ghostly slatebacks. I will explain more when you return.",starts={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[86183] = {id=86183,name="The Power of Gods",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Today, we create life. Assuming my calculations are correct--which they are--we can use the essence you gathered along with the data we have collected to create new slatebacks.",starts={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[86184] = {id=86184,name="Diminishing Returns",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="The machine has its uses, but the slatebacks must start breeding so they can sustain themselves. Thus far, they have shown no inclination to do so. Take this device and use it to collect the slatebacks for testing. Om'talad will review the data.",starts={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=230736,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[86185] = {id=86185,name="Running Free",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Been talkin' to Ve'nari and Om'talad--trying to help the slatebacks get together. Apparently slatebacks used to display virility by engaging in races. Challenge the slateback alpha to a race. At worst, you'll both get some exercise. At best, it will increase the likelihood of a successful pairing.",starts={{npcID=235353,x=0.758,y=0.34,zoneID=15336}},ends={{npcID=235353,x=0.758,y=0.34,zoneID=15336}},coords={x=0.758,y=0.34,source="quest_giver",zoneID=15336},questType="standard"},
[86186] = {id=86186,name="The Super Sniffer",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14752,description="It appears the slatebacks are not secreting the correct pheromones, resulting in them not breeding. We believe this is a side effect of the stasis. The technology was never tested for such an extreme length of time. Until now. Hemet tells me there are creatures called niffen in Azeroth that have expertise in this research. Bring me one from Azj-Kahet. You can use my portal to quickly get there.",starts={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=234272,x=0.776,y=0.618,zoneID=14752}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[86187] = {id=86187,name="The Smallest Possible Effort",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14752,description="You're a shrewd negotiator, . That's good fun! I'll start packing. You go get some bug bits for me, okay?",starts={{npcID=234272,x=0.776,y=0.618,zoneID=14752}},ends={{npcID=234272,x=0.776,y=0.618,zoneID=14752}},coords={x=0.776,y=0.618,source="quest_giver",zoneID=14752},questType="standard"},
[86188] = {id=86188,name="More-shrooms",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14752,description="Poor Gharrli needs to be set up while I'm away. The mushrooms you get will help with that. Get eight of them for now. We'll worry about the last one later!",starts={{npcID=234272,x=0.776,y=0.618,zoneID=14752}},ends={{npcID=234272,x=0.776,y=0.618,zoneID=14752}},coords={x=0.776,y=0.618,source="quest_giver",zoneID=14752},questType="standard"},
[86189] = {id=86189,name="Fungal Invasion",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14752,description="I'm sending you somewhere a lil scary, but I'm sure you can handle anything that comes your way! Mind clearing up some of the creatures so it'll be easier for Gharrli to gets the ingredients in the future?",starts={{npcID=234272,x=0.776,y=0.618,zoneID=14752}},ends={{npcID=234272,x=0.776,y=0.618,zoneID=14752}},coords={x=0.776,y=0.618,source="quest_giver",zoneID=14752},questType="standard"},
[86190] = {id=86190,name="One Mushroom to Rule Them All",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14752,description="We've been working on a new scent to delight the locals, but we have one more ingredient we need. It's a rare mushroom from Pillar-nest Vosh. Get that, and Gharrli can finish the fragrance while I'm away!",starts={{npcID=234272,x=0.776,y=0.618,zoneID=14752}},ends={{npcID=234272,x=0.776,y=0.618,zoneID=14752}},coords={x=0.776,y=0.618,source="quest_giver",zoneID=14752},questType="standard"},
[86191] = {id=86191,name="Smell Ya Later",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Well. That's everything, I think. I'm ready for adventure!",starts={{npcID=234272,x=0.776,y=0.618,zoneID=14752}},ends={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},coords={x=0.776,y=0.618,source="quest_giver",zoneID=14752},questType="standard"},
[86192] = {id=86192,name="On a Bed of Bones They Lie",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="I was talking to Om'talad over there. Apparently, slatebacks used to gather bones for birthing nests, which is kinda funny on account of them being herbivores! Normally they get bones from dead animals, but we don't have any in the eco-domes. Can you gather some bones from creatures outside the Oasis for me? They'd appreciate it, and so would I!",starts={{npcID=234316,x=0.76,y=0.344,zoneID=15336}},ends={{npcID=230736,x=0.758,y=0.342,zoneID=15336}},coords={x=0.76,y=0.344,source="quest_giver",zoneID=15336},questType="standard"},
[86193] = {id=86193,name="Life for Life",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="We're too late! The ritual is self-sustaining. It'll draw in more power until it overloads the machine. Tazavesh, the eco-domes--nothing will be safe if the failure cascades. If we remove the infusers, the energy should dissipate before it can cause any harm. It's too powerful though. It will tear you apart if you try to get close, and I'm not strong enough to do it alone... Unbind me. I'll wrap you in my energy. That should be enough to let you get close to the machine.",starts={{npcID=233500,x=0.57,y=0.572,zoneID=15336}},ends={{npcID=233503,x=0.596,y=0.606,zoneID=15336}},coords={x=0.57,y=0.572,source="quest_giver",zoneID=15336},questType="standard"},
[86194] = {id=86194,name="The Scent of Love",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="I was out and about checking on these slatebacks of yours, and your broker friends are wrong! The slatebacks are giving off the smell of love, but it's just not strong enough to overpower all this dry air on K'aresh. Not yet anyway! I whipped up a batch of pheromones that should fix them right up! Take this sprayer and douse the slatebacks. That'll get things started!",starts={{npcID=234316,x=0.76,y=0.344,zoneID=15336}},ends={{npcID=234316,x=0.76,y=0.344,zoneID=15336}},coords={x=0.76,y=0.344,source="quest_giver",zoneID=15336},questType="standard"},
[86195] = {id=86195,name="Slateback Soccer",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14752,description="Oh my. I never thought I would see the day. A newly born slateback! I have been running standard non-invasive medical tests. However, I also need a test of its coordination. I have been noticing it chasing this ball around. Perhaps you could throw it and observe the results?",starts={{npcID=230736,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=230736,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[86196] = {id=86196,name="Give Me Fuel",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Thank you for coming, . There are many dangers we face when attempting to terraform K'aresh , not the least of which is attracting creatures that see the domes as convenient energy sources. Eco-Dome: Springhost is plagued with them. I have a plan to remedy this, but I could use your help preparing.",starts={{npcID=234216,x=0.498,y=0.574,zoneID=15336}},ends={{npcID=234216,x=0.498,y=0.574,zoneID=15336}},coords={x=0.498,y=0.574,source="quest_giver",zoneID=15336},questType="standard"},
[86200] = {id=86200,name="Give Me Fire",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Now we need to process this firebud pollen into fuel. And with this fuel, the downfall of these pests will be assured.",starts={{npcID=234216,x=0.498,y=0.574,zoneID=15336}},ends={{npcID=234216,x=0.498,y=0.574,zoneID=15336}},coords={x=0.498,y=0.574,source="quest_giver",zoneID=15336},questType="standard"},
[86201] = {id=86201,name="Watch Me Make These Bugs Expire",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Now that we've processed this firebud pollen, we can bring some flame to bear against our pests in Eco-Dome: Springhost.",starts={{npcID=234216,x=0.498,y=0.574,zoneID=15336}},ends={{npcID=234216,x=0.498,y=0.574,zoneID=15336}},coords={x=0.498,y=0.574,source="quest_giver",zoneID=15336},questType="standard"},
[86203] = {id=86203,name="Operation: Floodgate",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15452,description="My sources report that Darkfuse forces have infiltrated the Waterworks down in the Ringing Deeps. They have seized the power generators there and are rerouting the electricity somewhere else. We do not know their directive, but I am not keen to find out. Dismantle their operation and I will see that you are adequately rewarded.",starts={{npcID=226623,x=0.466,y=0.482,zoneID=14771}},ends={{npcID=226623,x=0.466,y=0.482,zoneID=14771}},coords={x=0.466,y=0.482,source="quest_giver",zoneID=14771},questType="dungeon"},
[86204] = {id=86204,name="Liberation of Undermine: The House Loses",level=75,requiredLevel=75,faction="both",expansion=10,zoneID=15347,description="Gallywix has been a stain on Undermine since he forgot where he came from. Gallywix's always been steppin' on the little guy--greed and always looking for the \"next best thing\" is just makin' him step even harder. Seeking power just for its own sake? Forget that! The power lies with the people. Let's bring Gallywix some swift justice, .",starts={{npcID=233482,x=0.434,y=0.51,zoneID=15347}},ends={{npcID=238006,x=0.274,y=0.71,zoneID=15347}},coords={x=0.434,y=0.51,source="quest_giver",zoneID=15347},questType="raid"},
[86261] = {id=86261,name="Homeward Bound to Safer Shores",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=10416,starts={{npcID=234357,x=0.682,y=0.448,zoneID=10416}},ends={{npcID=234357,x=0.682,y=0.448,zoneID=10416}},coords={x=0.682,y=0.448,source="quest_giver",zoneID=10416},questType="standard"},
[86271] = {id=86271,name="Sanity's Rest",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,description="Looks like another one down the hatch, huh? I'm tellin' ya, these Black Blood dig sites are chewin' up workers faster than I can hire 'em! Every day, one of my guys goes down with the shakes, sproutin' nonsense about seein' tentacles in the dirt... Take 'em to see my guy, Stitchoaf , in the cave over there. He's brewin' up some kinda \"cure.\" See if he can't help this poor guy out.",starts={{npcID=233420,x=0.684,y=0.964,zoneID=14795}},ends={{npcID=234293,x=0.674,y=0.968,zoneID=14795}},coords={x=0.684,y=0.964,source="quest_giver",zoneID=14795},questType="standard"},
[86272] = {id=86272,name="Counteracting the Black Blood",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,description="Black Blood? Nasty stuff. Glad I got this mask here. Nobody should be workin' in that mess. It gets inside ya, messes with ya head. Some folks get dizzy, seein' things that ain't there. Some even sproutin' strange scales. Makes me itch thinkin' about it. An' there ain't no cure. Best we can do is ease the pain an' maybe help the symptoms a bit. I got a \"cure\" brewin'. It's just soup, but they don't know that. It's almost \"done,\" but it could use some flavor.",starts={{npcID=234293,x=0.674,y=0.968,zoneID=14795}},ends={{npcID=234293,x=0.674,y=0.968,zoneID=14795}},coords={x=0.674,y=0.968,source="quest_giver",zoneID=14795},questType="standard"},
[86273] = {id=86273,name="Visit to the Shop",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,description="That's all we can do for now. But if you really wanna help us fix all this, you ought to talk to our local engineer--uh, Tricksy... or maybe Trixxy. She's got her workshop set up further down in the cave, and Benny's got her tinkerin' away day and night on some kind of... \"permanent solution.\" Odd, but she's sharp as a blade. If anyone's got a chance at makin' people safe down here, it's her.",starts={{npcID=234293,x=0.674,y=0.968,zoneID=14795}},ends={{npcID=234294,x=0.672,y=0.98,zoneID=14795}},coords={x=0.674,y=0.968,source="quest_giver",zoneID=14795},questType="standard"},
[86274] = {id=86274,name="Automation Solution",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,description="As you have probably figured out, Black Blood exposure is bad for your health. And that's a problem for our operation. We can't keep replacin' our workers. It's expensive, and it ain't ethical. So! What's the solution? Replacin' our workers with my fully-automated bots. These beauties don't get affected by Black Blood exposure. They just dig and haul--precision, efficiency, an' no more sick workers! I just need more scrap to patch 'em up. You in?",starts={{npcID=234294,x=0.672,y=0.98,zoneID=14795}},ends={{npcID=234294,x=0.672,y=0.98,zoneID=14795}},coords={x=0.672,y=0.98,source="quest_giver",zoneID=14795},questType="standard"},
[86275] = {id=86275,name="Bug Exterminator Needed",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,description="Well, if ya really wanna help... We're safe in this cave from the Black Blood--or we were until it was crawlin' with nasty bloodfeasters . The ugly little creeps always had a taste for blood--but now they're gonzo for Black Blood! I got a hunch they're spreadin' Black Blood poisonin' when they bite us. I can't work like this. Each time I see one in a scrap pile, I wanna scream. They're gross, an' I don't wanna get bit an' start seein' things. Stomp 'em flat so we can keep safe an' keep workin'!",starts={{npcID=234294,x=0.672,y=0.98,zoneID=14795}},ends={{npcID=234294,x=0.672,y=0.98,zoneID=14795}},coords={x=0.672,y=0.98,source="quest_giver",zoneID=14795},questType="standard"},
[86276] = {id=86276,name="Out in the Fields",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,description="If Trixxie has those bots ready, then all we gotta do is mark where they needa work. Head out, fire a flare, and deploy those tin cans--an' see if they actually, yanno, work. Watch for glitchy servos, smokin' coolant vents... You know the drill. If they start doin' their work? Great. If not, well... I might be callin' some workers back in to clean up.",starts={{npcID=233420,x=0.684,y=0.964,zoneID=14795}},ends={{npcID=233420,x=0.684,y=0.964,zoneID=14795}},coords={x=0.684,y=0.964,source="quest_giver",zoneID=14795},questType="standard"},
[86277] = {id=86277,name="\"Worm\" Food No More",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,description="We've got the bots workin' the fields, but there are still flesh-an'-blood workers out there. They need to be able to get back here safely, an' they can't do that with a giant, slobberin' \"worm\" doggin' their steps 'cause it's got a taste for goblin meat. So, here's the job: I don't want that thing scared off, I want it gone. Go out there, track down that overgrown \"earthworm\", and make sure it dies. Don't hold back--I want guts everywhere. Payback for all the goblins it's had for lunch.",starts={{npcID=233420,x=0.684,y=0.964,zoneID=14795}},ends={{npcID=233420,x=0.684,y=0.964,zoneID=14795}},coords={x=0.684,y=0.964,source="quest_giver",zoneID=14795},questType="standard"},
[86297] = {id=86297,name="Morale Reflects Leadership",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Undermine swallows everything that's good. Now it got Laslo. We need to find who's in charge now and figure out how to keep 'em safe. I think I know where to start askin'.",starts={{npcID=229223,x=0.454,y=0.42,zoneID=15347}},ends={{npcID=229223,x=0.454,y=0.42,zoneID=15347}},coords={x=0.454,y=0.42,source="quest_giver",zoneID=15347},questType="standard"},
[86327] = {id=86327,name="The Tempest Fields",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15336,description="Those Wastelanders have that broker's ribbon. We must get it back or you will never be able to reach Dimensius. They are deliciously bloodthirsty. I think we should lure them to our cause. We need an army for the coming battle, and they have the numbers for that. The void glass lies between their camp and us. That might provide a means to manipulate--speak with the Wastelanders.",starts={{npcID=230602,x=0.684,y=0.52,zoneID=15336}},ends={{npcID=233878,x=0.64,y=0.47,zoneID=15336}},coords={x=0.684,y=0.52,source="quest_giver",zoneID=15336},questType="standard"},
[86332] = {id=86332,name="Distribution of Power",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="My people need energy to live. We can harvest it from the pylons that were set out to collect it or hunt the energy scavengers that have siphoned off what is ours. Let's gather today's meager bounty of energy and then distribute it to my people. If we are to go to war together, it will help us both to know the character of your allies.",starts={{npcID=234190,x=0.61,y=0.4,zoneID=15336}},ends={{npcID=230292,x=0.63,y=0.39,zoneID=15336}},coords={x=0.61,y=0.4,source="quest_giver",zoneID=15336},questType="standard"},
[86339] = {id=86339,name="Oasis Overdrive",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=15792,questType="standard"},
[86340] = {id=86340,name="Oasis Overdrive - Advanced",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=15792,questType="standard"},
[86341] = {id=86341,name="Oasis Overdrive - Reverse",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=15792,questType="standard"},
[86342] = {id=86342,name="Soaring over K'aresh",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="We've been taking the k'arrocs out for flights outside of the Oasis. Perhaps you might be interested in riding one?",starts={{npcID=230736,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=230736,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[86348] = {id=86348,name="Fox Bane",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="You have done well with the slatebacks. Will you do as well with the thorntails? If we are to improve their numbers, we will need some of their astral essence to produce new ones. Procure it for me.",starts={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[86349] = {id=86349,name="Lapbug Essence Hunter",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Thorntails are known to hunt smaller creatures. If we are to increase their numbers, we should also increase the numbers of the lapbug population to compensate. Gather some of their astral essence. You can use a phase conduit to get into Untethered Space.",starts={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[86350] = {id=86350,name="Eau de Foxy",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="It's my favorite ! I've been sniffing around the Oasis and I've whipped up a batch of pheromones for those thorntails out there. Can you give them a good dose for me? Let Om'talad know when you're done--he was lookin' to do some testing too!",starts={{npcID=234316,x=0.76,y=0.344,zoneID=15336}},ends={{npcID=230736,x=0.758,y=0.342,zoneID=15336}},coords={x=0.76,y=0.344,source="quest_giver",zoneID=15336},questType="standard"},
[86351] = {id=86351,name="Strike a Pose",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="We are running low on food for the thorntails. It is odd. They should be hunting for a larger portion of their food. Can you take some pictures of them for documentation purposes? Perhaps it will shed some light on the issue.",starts={{npcID=230736,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=230736,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[86352] = {id=86352,name="Hunting for a Good Author",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=13646,description="I am growing concerned that we may be in danger of overbalancing the ecosystem. We require a consultant. Have you read \"The Green Hills of Stranglethorn?\" I enjoyed it a great deal. The author appears to have turned from hunter to conservationist. Do not ask how I acquired this information. However, these are precisely the two skills I need. Retrieve him. Last I heard, he was in the Azure Span on the Dragon Isles. Use the portal to travel there.",starts={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=234745,x=0.188,y=0.398,zoneID=13646}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[86353] = {id=86353,name="Protecting the Young",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=13646,description="These gnolls have kidnapped children from Iskaara. I was going to sneak in and rescue them, but I could use some help. Let's split up. Two sets of eyes are better than one. If you spot any kids, tell 'em to gather at this spot. Tell them Hemet sent you. They know me.",starts={{npcID=234745,x=0.188,y=0.398,zoneID=13646}},ends={{npcID=234745,x=0.188,y=0.398,zoneID=13646}},coords={x=0.188,y=0.398,source="quest_giver",zoneID=13646},questType="standard"},
[86355] = {id=86355,name="Using the Whole Animal",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=13646,description="K'aresh, eh? Sounds a bit like Netherstorm. I've been staying with the tuskarr for a while an' learning what I can from 'em. I was supposed to gather meat for the evening meal. If you can do that, I can start packing.",starts={{npcID=235290,x=0.136,y=0.49,zoneID=13646}},ends={{npcID=235290,x=0.136,y=0.49,zoneID=13646}},coords={x=0.136,y=0.49,source="quest_giver",zoneID=13646},questType="standard"},
[86356] = {id=86356,name="Sustainable Harvesting",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=13646,description="I'd like to repay the tuskarr's kindness for hosting me. They have some repairs that need doing. Can ye gather some wood for them? They can handle the repairs themselves--they just need a bit of help gatherin' the materials.",starts={{npcID=235290,x=0.136,y=0.49,zoneID=13646}},ends={{npcID=235290,x=0.136,y=0.49,zoneID=13646}},coords={x=0.136,y=0.49,source="quest_giver",zoneID=13646},questType="standard"},
[86357] = {id=86357,name="Time for Noms",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=13646,description="The local ottuks have a symbiotic relationship with the tuskarr, and it's feeding time. Can ye put out some of the meat ye gathered for them?",starts={{npcID=235290,x=0.136,y=0.49,zoneID=13646}},ends={{npcID=235290,x=0.136,y=0.49,zoneID=13646}},coords={x=0.136,y=0.49,source="quest_giver",zoneID=13646},questType="standard"},
[86358] = {id=86358,name="Any Old Excuse",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=13646,description="This'll be the hardest task for ye yet. The ottuk pups have to get acclimatized to touch. I... I need ye to go pet them. Hard work, but it has to be done.",starts={{npcID=235290,x=0.136,y=0.49,zoneID=13646}},ends={{npcID=235290,x=0.136,y=0.49,zoneID=13646}},coords={x=0.136,y=0.49,source="quest_giver",zoneID=13646},questType="standard"},
[86359] = {id=86359,name="Return to K'aresh",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Right then. I'm ready to go. How do we get there?",starts={{npcID=235290,x=0.136,y=0.49,zoneID=13646}},ends={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},coords={x=0.136,y=0.49,source="quest_giver",zoneID=13646},questType="standard"},
[86360] = {id=86360,name="Fantastic Ms. Fox",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="The thorntails aren't hunting like they're supposed tae? Ve'nari said that lapbugs aren't their normal prey. We'll need to teach the matriarch how to hunt them ourselves!",starts={{npcID=235353,x=0.758,y=0.34,zoneID=15336}},ends={{npcID=235353,x=0.758,y=0.34,zoneID=15336}},coords={x=0.758,y=0.34,source="quest_giver",zoneID=15336},questType="standard"},
[86361] = {id=86361,name="Are You Kitting Me?",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="We need to ensure that the thorntail kits' reflexes are sharp so they are effective hunters when they grow up. Please take this ball and have a kit chase it. For scientific purposes, of course.",starts={{npcID=230736,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=230736,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[86362] = {id=86362,name="What Does the Fox Dream?",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="I'd like to get some medical data on how the thorntails are doing. Please gather some blood samples for me. Use these to tranquilize the creatures. There should be more than enough blood for sampling on the darts when you retrieve them.",starts={{npcID=230736,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=230736,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[86392] = {id=86392,name="Foxy Footwork",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Your efforts in teaching the matriarch to hunt have been too effective, it seems. Several broker guards have been attacked recently. Since you caused this issue, I need you to solve it. Best the thorntail matriarch in a fight. The rest of the thorntails will back down once their leader is humbled.",starts={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[86408] = {id=86408,name="My Hole in the Wall",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Never thought when I was lookin' for security I'd get some kinda bona fide hero. I can see why rumors about you spread so quickly. You like helpin' people, don'tcha? Look I don't wanna get all sappy or nothin'. It's just... What you did for everyone... Mama Keara shakes her head and regains her composure.> Anyways. A deal's a deal. Sign your name on the apartment log over there and you'll be an official Barrelbottom resident. I'd say you've definitely earned it.",starts={{npcID=228857,x=0.396,y=0.684,zoneID=15347}},coords={x=0.396,y=0.684,source="quest_giver",zoneID=15347},questType="standard"},
[86417] = {id=86417,name="Ready Check",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="We've done what we can here, . Now we just have to hope it'll be enough. Maybe Gazlowe's got a plan. Maybe now we're ready to face down Gallywix. Let's formulate our next steps. I enjoy a bit of formulation from time to time.",starts={{npcID=225876,x=0.564,y=0.678,zoneID=15347}},ends={{npcID=230268,x=0.564,y=0.674,zoneID=15347}},coords={x=0.564,y=0.678,source="quest_giver",zoneID=15347},questType="standard"},
[86447] = {id=86447,name="Devourer Attack: Eco-dome: Primus",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15336,mapID=2371,questType="standard"},
[86448] = {id=86448,name="Piecing Things Together",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=15329,mapID=2393,questType="standard"},
[86456] = {id=86456,name="An Elegy for a Silent World",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Ve'nari would know more about it?>",ends={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},questType="standard"},
[86457] = {id=86457,name="A Lullaby of Hope",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description=", do you know what this is? If I am right, this crystal is the essence of my world, K'aresh . I've spent much of my capital preserving some bit of K'aresh through the eco-dome project. But this... I do not wish to assume anything before verifying if it is true. Place down the shard, and let's see what we can find.",starts={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[86458] = {id=86458,name="A Song for Our Future",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=16104,description="There is a site, Eco-Dome: Al'dani, which I have kept hidden. It is built on the remains of one of our most sacred places with a powerful connection to K'aresh. It is the site of our greatest triumph of the project. This is the place where we can take the Worldsoul's essence so it can survive. This is also the eco-dome where Soul-Scribe and her Wastelanders are attacking. Clear the way for me one last time, . For K'aresh to survive, we need both the dome and Soul-Scribe intact.",starts={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=235155,zoneID=16104}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="dungeon"},
[86461] = {id=86461,name="Ancient Curiosity: Combat",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=15329,mapID=2393,questType="standard"},
[86462] = {id=86462,name="Ancient Curiosity: Utility",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=15329,mapID=2393,questType="standard"},
[86464] = {id=86464,name="Devourer Attack: The Atrium",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15336,mapID=2371,questType="standard"},
[86465] = {id=86465,name="Devourer Attack: Tazavesh",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15781,mapID=2472,questType="standard"},
[86469] = {id=86469,name="A Stromgarde Tour",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=16432,mapID=2451,questType="standard"},
[86470] = {id=86470,name="Fearin's Version",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15716,mapID=14,description="I need someone to deliver these requests to people around the city. We've been shorthanded and I haven't gotten around to distributing this bunch. As my newest deputy, this responsibility is now yours! Most of these are simple and straightforward. Requests for supplies and such for the Stromic army. Joseph is another matter. He's been inciting the populace with inflammatory rhetoric. He needs to stop or we will have to arrest him. We can't afford another riot breaking out right now.",questType="standard"},
[86476] = {id=86476,name="Worldsoul Memory: Early Cartel Wars",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=14717,mapID=2248,questType="standard"},
[86477] = {id=86477,name="Worldsoul Memory: Kaja'mite Contact",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=14717,mapID=2248,questType="standard"},
[86479] = {id=86479,name="LFGDungeons - 11.0 The War Within - Raid Finder - 1st",level=30,requiredLevel=30,faction="none",expansion=10,questType="standard"},
[86481] = {id=86481,name="Short-Supply Reward",level=30,requiredLevel=30,faction="none",expansion=10,questType="standard"},
[86482] = {id=86482,name="A Lifeline",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=10416,starts={{npcID=235216,x=0.708,y=0.484,zoneID=10416}},ends={{npcID=235216,x=0.708,y=0.484,zoneID=10416}},coords={x=0.708,y=0.484,source="quest_giver",zoneID=10416},questType="standard"},
[86483] = {id=86483,name="Snap To It",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=10416,description="meaty rations it has stolen from nearby invading forces. The snapdragon looks at you expectantly. Perhaps you can bring it more meaty rations by slaying the invading forces on the island.>",starts={{npcID=235237,x=0.708,y=0.486,zoneID=10416}},ends={{npcID=235237,x=0.708,y=0.486,zoneID=10416}},coords={x=0.708,y=0.486,source="quest_giver",zoneID=10416},questType="standard"},
[86484] = {id=86484,name="Temper Like A Tempest",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=10416,starts={{npcID=235243,x=0.708,y=0.486,zoneID=10416}},ends={{npcID=235243,x=0.708,y=0.486,zoneID=10416}},coords={x=0.708,y=0.486,source="quest_giver",zoneID=10416},questType="standard"},
[86485] = {id=86485,name="A Loyal Friend",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=10416,starts={{npcID=235250,x=0.708,y=0.486,zoneID=10416}},ends={{npcID=235250,x=0.708,y=0.486,zoneID=10416}},coords={x=0.708,y=0.486,source="quest_giver",zoneID=10416},questType="standard"},
[86486] = {id=86486,name="Hungry, Hungry Snapdragon",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=10416,starts={{npcID=235237,x=0.708,y=0.486,zoneID=10416},{npcID=235243,x=0.708,y=0.486,zoneID=10416},{npcID=235250,x=0.708,y=0.486,zoneID=10416}},ends={{npcID=235237,x=0.708,y=0.486,zoneID=10416},{npcID=235243,x=0.708,y=0.486,zoneID=10416},{npcID=235250,x=0.708,y=0.486,zoneID=10416}},coords={x=0.708,y=0.486,source="quest_giver",zoneID=10416},questType="standard"},
[86491] = {id=86491,name="Dastardly Duos! It's on!",level=0,requiredLevel=0,faction="both",expansion=10,zoneID=14717,description="Hello, fight fans. The world's meanest villains are teamed up and back for revenge! They have returned, this time as Dastardly Duos! Meet me in Dornogal, at the foot of Contender's Gate and sign up to face the Dastardly Duos. Beat down these bosses one more time. Relive the dream! - Vinnie Sweets",ends={{npcID=234296,x=0.528,y=0.516,zoneID=14717}},questType="standard"},
[86493] = {id=86493,name="LFGDungeons - Timewalking \"Heroic\" Random - 1st",level=0,requiredLevel=0,faction="none",expansion=10,questType="standard"},
[86495] = {id=86495,name="The Reshii Ribbon",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="During the Devouring War, I witnessed the horrific results of the All-Devouring's presence. A mortal being cannot approach him at the manaforge. He is the entropy of the end, and you are just flesh. Xal'atath knows rituals from across the Great Dark Beyond. With the power of the Reshii Ribbons, she was able to transform the K'areshi so they could withstand Dimensius. Alleria will not like this plan. You must convince her!",starts={{npcID=234106,x=0.482,y=0.366,zoneID=15336}},ends={{npcID=233946,x=0.482,y=0.366,zoneID=15336}},coords={x=0.482,y=0.366,source="quest_giver",zoneID=15336},questType="standard"},
[86496] = {id=86496,name="An Ordered Design",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=10416,description="Bargus holds up a tiny splinter of golden crystal.> Much like the radiant remnants found by the Arathi within Hallowfall, the Siren Crystal appears to be effecting the surrounding geological matrix of the island. Unlike our goblin compatriots, I don't recommend harvesting the larger shards we've seen around the isle, lest we disturb the fragile caverns beneath us or offend the Arathi. But these tiny splinters are worth investigating. Bring me a sizable portion. For... experimental purposes.",starts={{npcID=230242,x=0.676,y=0.42,zoneID=10416}},ends={{npcID=230242,x=0.676,y=0.42,zoneID=10416}},coords={x=0.676,y=0.42,source="quest_giver",zoneID=10416},questType="standard"},
[86503] = {id=86503,name="Who are the Dastardly Duos?",level=0,requiredLevel=0,faction="both",expansion=10,zoneID=14717,description="Great question! Here's how to find out: Talk to Xyggie Marou and sign up to fight the Dastardly Duos . And because you're new to this, let me give you a list of \"Dastardly\" tasks to do while you're in there! Good luck! Maybe I'll see you on the other side.",starts={{npcID=234296,x=0.528,y=0.516,zoneID=14717}},ends={{npcID=234296,x=0.528,y=0.516,zoneID=14717}},coords={x=0.528,y=0.516,source="quest_giver",zoneID=14717},questType="standard"},
[86535] = {id=86535,name="Test Run",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,description="Hey, you lookin' to make a few coins? We made a deal with the earthen to build a teleporter up in Dornogal. We get all the tourism traffic we want, and they get their pick of the finest cracked, chipped, or otherwise unsellable gemstones Undermine 's jewelers can offer. I just got this end of things workin', but I haven't tested it out yet. You wanna try? If you come out the other side, my coworker Kenzi will compensate ya. We'll say this constitutes a verbal waiver, yeah?",starts={{npcID=235402,x=0.276,y=0.542,zoneID=15347}},ends={{npcID=235403,x=0.524,y=0.508,zoneID=14771}},coords={x=0.276,y=0.542,source="quest_giver",zoneID=15347},questType="standard"},
[86555] = {id=86555,name="Undermine Benefactor",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=15347,mapID=2346,starts={{npcID=231409,x=0.436,y=0.508,mapID=2346}},ends={{npcID=231409,x=0.436,y=0.508,mapID=2346}},coords={x=0.436,y=0.508,source="quest_giver",mapID=2346},questType="standard"},
[86556] = {id=86556,name="A Shattered Journey Through Time",level=0,requiredLevel=0,faction="both",expansion=10,zoneID=1637,description="The Destroyer's star shines upon the land with its piercing light as even the spirits retreat to the shadows. This star is unlike any other in the skies, laying bare the weaknesses of even the boldest heroes. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.",starts={{npcID=101759,x=0.76,y=0.174,zoneID=1519},{npcID=101759,x=0.52,y=0.416,zoneID=1637}},ends={{npcID=101759,x=0.76,y=0.174,zoneID=1519},{npcID=101759,x=0.52,y=0.416,zoneID=1637}},coords={x=0.76,y=0.174,source="quest_giver",zoneID=1519},questType="standard"},
[86563] = {id=86563,name="A Savage Journey Through Time",level=0,requiredLevel=0,faction="both",expansion=10,zoneID=7333,description="The brutal star shines upon the land, threatening to trample underfoot all who stand in its path. This star is many things: primal, fierce, and noble. While its influence holds, new paths may open up to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.",starts={{npcID=151955,x=0.37,y=0.724,zoneID=7332},{npcID=151987,x=0.428,y=0.544,zoneID=7333}},ends={{npcID=151955,x=0.37,y=0.724,zoneID=7332},{npcID=151987,x=0.428,y=0.544,zoneID=7333}},coords={x=0.37,y=0.724,source="quest_giver",zoneID=7332},questType="standard"},
[86564] = {id=86564,name="A Fel Journey Through Time",level=0,requiredLevel=0,faction="both",expansion=10,zoneID=7502,mapID=627,description="A corrupting star shines upon the land, threatening all with burning oblivion. The star betrays those who seek the light, its red glow obscuring rather than revealing. While its influence holds, new paths may open up to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.",questType="standard"},
[86575] = {id=86575,name="Rocket Roll",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,description="That scrap was just what I needed. An' now without those bloodfeasters givin' me the heebie jeebies, I can get these bots officially rolled out. While I finish up here, why don't you go tell Benny the good news? I'm sure he'll wanna deploy 'em right away!",starts={{npcID=234294,x=0.672,y=0.98,zoneID=14795}},ends={{npcID=233420,x=0.684,y=0.964,zoneID=14795}},coords={x=0.672,y=0.98,source="quest_giver",zoneID=14795},questType="standard"},
[86587] = {id=86587,name="To Maldraxxus",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=11462,description="Rays once soared through the skies of K'aresh. While their void-touched descendants are in the skies outside the Oasis, we have no surviving specimens that have not been void-touched. However, I know of a location where we can procure a similar creature that should inhabit the same part of the ecosystem: Maldraxxus in the Shadowlands. Take my portal, and find the creatures for me.",starts={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=235860,x=0.69,y=0.484,zoneID=11462}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[86588] = {id=86588,name="Ritualistic Murder",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=11462,description="The local ritualists are causing problems for the necrorays. Specifically, plague problems. If you kill them, it should lessen the issues for the necrorays.",starts={{npcID=235860,x=0.69,y=0.484,zoneID=11462}},ends={{npcID=235860,x=0.69,y=0.484,zoneID=11462}},coords={x=0.69,y=0.484,source="quest_giver",zoneID=11462},questType="standard"},
[86589] = {id=86589,name="A Plague a Day Keeps the Doctor Away",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=11462,description="The ritualists have been testing a new plague out on our poor necrorays. This is abominable... That's my job! Bring me some samples of deceased rays and I should be able to concoct a cure for the ones that haven't perished.",starts={{npcID=235860,x=0.69,y=0.484,zoneID=11462}},ends={{npcID=235860,x=0.69,y=0.484,zoneID=11462}},coords={x=0.69,y=0.484,source="quest_giver",zoneID=11462},questType="standard"},
[86590] = {id=86590,name="I Don't Even Work Here",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=11462,description="It's good you are here, apprentice! I came to gather the essences from the local rancor. They are wonderful for adding just that little extra spice to a plague. But now that you are here, I can have you gather them instead! What an excellent learning opportunity for you!",starts={{npcID=235860,x=0.69,y=0.484,zoneID=11462}},ends={{npcID=235860,x=0.69,y=0.484,zoneID=11462}},coords={x=0.69,y=0.484,source="quest_giver",zoneID=11462},questType="standard"},
[86591] = {id=86591,name="A Poor Imitation",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=11462,description="This is Vorax's work. He was once my apprentice, just like you! He's trying to replicate my work? Flattering, but sloppy. I'll work on a solution for you, apprentice, while you work on a solution for him.",starts={{npcID=235860,x=0.69,y=0.484,zoneID=11462}},ends={{npcID=235860,x=0.69,y=0.484,zoneID=11462}},coords={x=0.69,y=0.484,source="quest_giver",zoneID=11462},questType="standard"},
[86592] = {id=86592,name="Get Your Jabs",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=11462,description="If these rays are to travel, we should inoculate them first. What a good opportunity for you to learn about administering anti-plague, apprentice! It's not something that happens here very often.",starts={{npcID=235860,x=0.69,y=0.484,zoneID=11462}},ends={{npcID=235860,x=0.69,y=0.484,zoneID=11462}},coords={x=0.69,y=0.484,source="quest_giver",zoneID=11462},questType="standard"},
[86593] = {id=86593,name="To the Oasis",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="I suppose you will be heading back now? It has been a true joy to work with you, apprentice. I hope we will see each other soon. I'll have some new experiments for you to help me out with. Please do take care of the necrorays! I hope they enjoy their new home.",starts={{npcID=235860,x=0.69,y=0.484,zoneID=11462}},ends={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},coords={x=0.69,y=0.484,source="quest_giver",zoneID=11462},questType="standard"},
[86594] = {id=86594,name="A Cultured Palette",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="We're trying to figure out what these rays eat. I've gathered some options. Can ye put them out? I'll watch for responses.",starts={{npcID=236846,x=0.484,y=0.61,zoneID=15336}},ends={{npcID=236846,x=0.484,y=0.61,zoneID=15336}},coords={x=0.484,y=0.61,source="quest_giver",zoneID=15336},questType="standard"},
[86595] = {id=86595,name="Custodial Duties",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Seems like these rays slough off some gunk as they move. It's congealin' and makin' a mess! Ve'nari sent over this vacuum device to help out. Can you clean things up while yer out and about?",starts={{npcID=236846,x=0.484,y=0.61,zoneID=15336}},ends={{npcID=236846,x=0.484,y=0.61,zoneID=15336}},coords={x=0.484,y=0.61,source="quest_giver",zoneID=15336},questType="standard"},
[86601] = {id=86601,name="Triple Twenty",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Tag the necrorays with these darts. It'll monitor their location and health. It also injects a pain killer so the necrorays don't even notice it. These brokers have some incredible inventions!",starts={{npcID=236890,x=0.49,y=0.57,zoneID=15336}},ends={{npcID=236890,x=0.49,y=0.57,zoneID=15336}},coords={x=0.49,y=0.57,source="quest_giver",zoneID=15336},questType="standard"},
[86602] = {id=86602,name="Medical Checkup",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="You said your friend de-plagued those necrorays, but we need to see if the other animals are picking up anything else from them. Can ye go and collect some samples so we can check for issues?",starts={{npcID=236890,x=0.49,y=0.57,zoneID=15336}},ends={{npcID=236890,x=0.49,y=0.57,zoneID=15336}},coords={x=0.49,y=0.57,source="quest_giver",zoneID=15336},questType="standard"},
[86603] = {id=86603,name="Ray-ket Ball",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="It seems one of the necrorays you brought back was pregnant, so I have been dealing with a newborn all day. Thank you. Perhaps you would not mind testing out its reflexes for me?",starts={{npcID=230736,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=230736,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[86604] = {id=86604,name="Dubious Intent",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="The ooze that Hemet had you collect may be of use to us. Go and collect the ooze directly from the necrorays. You can use this tranquilizer dart to bring them within range for collection.",starts={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[86605] = {id=86605,name="Booster Shots",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="After some analysis of the samples you brought back, it appears the necrorays are suffering from a vitamin deficiency. Ve'nari contacted Marileth, who prepared something... and then re-prepared it after she requested he remove the plague from it. Please gather the necrorays so we can test the initial batches.",starts={{npcID=230736,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=230736,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[86606] = {id=86606,name="The Golden Ooze",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Our custodians have yet to do their daily cleanup of the necrorays' discharge. I have many buyers in Tazavesh lined up for this material. They need it urgently, so its collection falls to you. Take the vacuum device. Compensation will be provided.",starts={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[86607] = {id=86607,name="The Freedom of Ray-cing",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Those necrorays responded really well to those treatments you gave 'em! So well in fact that one of 'em is needin' to burn off some energy. Would ye be able to wear it out?",starts={{npcID=235353,x=0.758,y=0.34,zoneID=15336}},ends={{npcID=235353,x=0.758,y=0.34,zoneID=15336}},coords={x=0.758,y=0.34,source="quest_giver",zoneID=15336},questType="standard"},
[86618] = {id=86618,name="License Not Required",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Alright. Before you go out and run somebody over let's make sure you know how to do it properly. We'll introduce you to the car, the D.R.I.V.E. service we offer, and how to drive it in style.",starts={{npcID=227210,x=0.374,y=0.488,zoneID=15347}},ends={{npcID=227210,x=0.374,y=0.488,zoneID=15347}},coords={x=0.374,y=0.488,source="quest_giver",zoneID=15347},questType="standard"},
[86619] = {id=86619,name="Theater Troupe",level=80,requiredLevel=80,faction="none",expansion=10,questType="standard"},
[86697] = {id=86697,name="The Cleanup Crew",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14795,description="Even if we got bots out there an' not workers, there are still gonna be monsters out there gettin' in their hair, er, wirin'. Get out there an' thin out the wildlife. That'll keep our bots from gettin' damaged and voidin' whatever warranty they got left. The longer they can stay out there, the longer we can stay right here!",starts={{npcID=233420,x=0.684,y=0.964,zoneID=14795}},ends={{npcID=233420,x=0.684,y=0.964,zoneID=14795}},coords={x=0.684,y=0.964,source="quest_giver",zoneID=14795},questType="standard"},
[86698] = {id=86698,name="Work It",level=0,requiredLevel=0,faction="both",expansion=10,zoneID=14771,description="The Trial of Style gives us the opportunity to look good. . The camera makes sure we keep looking good. So focus on me and my camera, follow my directions and I'll make sure you look fantastic!",starts={{npcID=236334,x=0.458,y=0.546,zoneID=14771}},ends={{npcID=236334,x=0.458,y=0.546,zoneID=14771}},coords={x=0.458,y=0.546,source="quest_giver",zoneID=14771},questType="standard"},
[86699] = {id=86699,name="Work It",level=0,requiredLevel=0,faction="both",expansion=10,zoneID=14717,description="The Trial of Style gives us the opportunity to look good, . The camera makes sure we keep looking good. So focus on me and my camera, follow my directions and I'll make sure you look fantastic!",starts={{npcID=236356,x=0.564,y=0.514,zoneID=14717}},ends={{npcID=236356,x=0.564,y=0.514,zoneID=14717}},coords={x=0.564,y=0.514,source="quest_giver",zoneID=14717},questType="standard"},
