[86706] = {id=86706,name="Seeking Knowledge of the Past",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,description="Greetings, . I must seek your aid. Soridormi and our kin have journeyed to Khaz Algar to help in this fight against the Void's new master. We think that we can provide insight and valuable information about past attacks by the Void. Seek her out near the southern edge of the Coreway.",starts={{npcID=238129,x=0.424,y=0.284,zoneID=14771}},ends={{npcID=236382,x=0.346,y=0.688,zoneID=14771}},coords={x=0.424,y=0.284,source="quest_giver",zoneID=14771},questType="standard"},
[86731] = {id=86731,name="An Original Path Through Time",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,description="Ever since your city fell out of the sky, I have learned more of this world's history and the challenges that heroes like yourself have faced. Learning from the past is how we ensure our future. Walk through time to the humble beginnings, defeat those threats once more, and bring those lessons forward.",starts={{npcID=226919,x=0.464,y=0.492,zoneID=14771}},ends={{npcID=226919,x=0.464,y=0.492,zoneID=14771}},coords={x=0.464,y=0.492,source="quest_giver",zoneID=14771},questType="standard"},
[86775] = {id=86775,name="Urge to Surge",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Occasionally we get more jobs than we can handle. You know what that means-- big money. Help out during some Surge Pricing and we'll see to it that you're thanked for your help.",starts={{npcID=231409,x=0.436,y=0.508,zoneID=15347}},ends={{npcID=231409,x=0.436,y=0.508,zoneID=15347}},coords={x=0.436,y=0.508,source="quest_giver",zoneID=15347},questType="standard"},
[86782] = {id=86782,name="Atrium Hospital",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="The necrorays have been installed in the Atrium, and Hemet is seeing to them. He has requested your presence.",starts={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=236846,x=0.484,y=0.61,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[86783] = {id=86783,name="Rays of Sunshine",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Right then. Let's get these rays into Eco-Dome: Primus to the north!",starts={{npcID=236846,x=0.484,y=0.61,zoneID=15336}},ends={{npcID=236890,x=0.49,y=0.57,zoneID=15336}},coords={x=0.484,y=0.61,source="quest_giver",zoneID=15336},questType="standard"},
[86786] = {id=86786,name="The Void Hunter",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=16505,description="The Void espouses all truths, . And in none of them do I defeat Ramon'ta without some help. And here you are. My quarry is a cosmic worm known as Ramon'ta the Insatiable . It started out small enough, but with each void entity it feasts upon, it grows, and its power grows along with it. If we can defeat it, I can claim its power. Will you help me?",starts={{npcID=240842,x=0.594,y=0.242,zoneID=15336},{npcID=240842,x=0.62,y=0.52,zoneID=16505}},ends={{npcID=236907,x=0.6,y=0.296,zoneID=15336}},coords={x=0.594,y=0.242,source="quest_giver",zoneID=15336},questType="standard"},
[86801] = {id=86801,name="Faceless Mask of Multitudes",level=80,requiredLevel=80,faction="both",expansion=10,description="By our multitudes will the world drown and feed the hunger of our gods. Only by bathing in the blood of our foes may one rise to the exaltation of our masters and unleash their never ending multitudes for themself.",questType="standard"},
[86820] = {id=86820,name="Manaforge Omega: Dimensius Looms",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="This is it, $p. We must defeat this Void Lord... no matter what it takes.",starts={{npcID=231522,x=0.428,y=0.214,zoneID=15336}},coords={x=0.428,y=0.214,source="quest_giver",zoneID=15336},questType="raid"},
[86835] = {id=86835,name="Regroup!",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15781,description="We've stabilized most of the city and saved as many as we could, but our job isn't over. Locus-Walker must still be out there looking for the enemy commander. We've already searched over most of the city, so he must be in the one place we've not yet looked. Come, . Meet me at Myza's Oasis.",starts={{npcID=234483,x=0.375,y=0.399,zoneID=15781}},ends={{npcID=234620,x=0.376,y=0.744,zoneID=15781}},coords={x=0.375,y=0.399,source="quest_giver",zoneID=15781},questType="standard"},
[86853] = {id=86853,name="Sparks of War: Undermine",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,description="Investigate the Undermine! Reports are coming in about a growing conflict in the area, go and check it out.",starts={{npcID=219260,x=0.588,y=0.752,zoneID=14771}},ends={{npcID=219260,x=0.588,y=0.752,zoneID=14771}},coords={x=0.588,y=0.752,source="quest_giver",zoneID=14771},questType="standard"},
[86905] = {id=86905,name="No More Sick Days",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=15524,mapID=2351,description="When we started clearin' out this forest we expected some trouble from the local wildlife but we never expected to be set upon by diseased animals! My work crew keeps gettin' sick and takin' time off to recover. Obviously this is messin' with our bottom line, so perhaps you could clear out some of the creatures so we can start work again? When you're done see my assistant for payment.",questType="standard"},
[86915] = {id=86915,name="Side with a Cartel",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15347,mapID=2346,questType="standard"},
[86917] = {id=86917,name="Ship Right",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15347,mapID=2346,questType="standard"},
[86918] = {id=86918,name="Reclaimed Scrap",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15347,mapID=2346,questType="standard"},
[86919] = {id=86919,name="Side Gig",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15347,mapID=2346,questType="standard"},
[86920] = {id=86920,name="War Mode Violence",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15347,mapID=2346,questType="standard"},
[86921] = {id=86921,name="This is a repro test",level=0,requiredLevel=0,faction="none",expansion=10,questType="standard"},
[86923] = {id=86923,name="Go Fish",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15347,mapID=2346,questType="standard"},
[86924] = {id=86924,name="Gotta Catch at Least a Few",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15347,mapID=2346,questType="standard"},
[86934] = {id=86934,name="Trash to Profit",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Ey! I heard you've been cleanin' up some of the trash around Undermine . Good on ya. Any interest in takin' that more literally? It's a dirty job, but lots of gold to be made if you're good at it. If that sounds up your alley, go talk to the boss man Carlo back at Undermine Sanitation. Tell him I sent ya so I get my recruitment bonus!",starts={{npcID=237649,x=0.428,y=0.502,zoneID=15347}},ends={{npcID=237659,x=0.266,y=0.374,zoneID=15347}},coords={x=0.428,y=0.502,source="quest_giver",zoneID=15347},questType="standard"},
[86935] = {id=86935,name="On-the-Job Training",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="If you're lookin' for work, S.C.R.A.P. is always hirin'. That's short for \"Salvage, Cleanup, and Recl-Amation Patrol.\" We go around Undermine shovelin' up trash and pickin' out the good bits. Valuables get brought back here, cleaned up, and resold to whoever's buyin'. Find somethin' useful and my man Angelo will trade you for it. Go check out what he's got in stock, then find me out in the field and I'll show you the ropes. But I mean, it's trash shovelin', not rocket surgery.",starts={{npcID=237659,x=0.266,y=0.374,zoneID=15347}},ends={{npcID=237659,x=0.266,y=0.374,zoneID=15347}},coords={x=0.266,y=0.374,source="quest_giver",zoneID=15347},questType="standard"},
[86936] = {id=86936,name="Warped Wood",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=15524,mapID=2351,description="Our shredders were cuttin' down trees in this area to make room for new homes when they suddenly uprooted and started causin' all kinds of havoc! As if all these diseased animals weren't bad enough, those trees seem hell bent on preventing us from completing this job. If you could clear out a few it would really help speed up our construction efforts.",questType="standard"},
[86937] = {id=86937,name="Healthy Home Certified",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=15524,mapID=2351,description="We think we've found the source for all this disease nonsense and wouldn't ya believe it -- a blasted satyr. I hate these guys, always showin' up in places I want to harvest for precious resources. Do us a favor and get rid of him? As always, see my assistant for payment.",questType="standard"},
[86946] = {id=86946,name="Unwrapped and Unraveled",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Seeing you two on the battlefield was beautiful. It really is wonderful watching you work. If only your so-called friends had trusted you with the truth of their actions so long ago. Locus-Walker hasn't tried to deceive you with his actions in the present, though his actions in the past that led us to this point... he has been less than forthcoming about. In all good conscience, I cannot continue hiding the truth from you or Alleria.",starts={{npcID=237705,x=0.542,y=0.454,zoneID=15336}},ends={{npcID=242538,x=0.47,y=0.544,zoneID=15336}},coords={x=0.542,y=0.454,source="quest_giver",zoneID=15336},questType="standard"},
[86960] = {id=86960,name="The Key to Good Health",level=70,requiredLevel=70,faction="none",expansion=10,description="I'm supposed to be the assigned health advisor for this job but somehow I'm the one who ended up getting sick! I have antidotes in this chest but I lost the key and I suspect one of the local wildlife ate it in the aftermath of being attacked. Be a pal and see if you can find it?",questType="standard"},
[86961] = {id=86961,name="Diversified Investments",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="who took down Gallywix.\" It takes you a frustrating amount of time to rip open the multiple layers of duct tape sealing the envelope shut.> Hey bud, You've been gettin' a reputation for yourself. Not afraid to roll up your sleeves and get down to business. Certain people really value that kind of thing. Let's talk shop. Meet me in my warehouse and maybe we can agree on a business partnership.",starts={{npcID=509486,x=0.433,y=0.515,zoneID=15347}},ends={{npcID=231396,x=0.306,y=0.388,zoneID=15347}},coords={x=0.433,y=0.515,source="quest_giver",zoneID=15347},questType="standard"},
[86962] = {id=86962,name="Blood in the Wound",level=70,requiredLevel=70,faction="none",expansion=10,questType="standard"},
[86994] = {id=86994,name="LFGDungeons - 11.1 The War Within - Raid Finder - 1st",level=80,requiredLevel=80,faction="none",expansion=10,questType="standard"},
[87000] = {id=87000,name="No Wood Left Behind",level=70,requiredLevel=70,faction="none",expansion=10,zoneID=15524,mapID=2351,description="When we were attacked by the local fauna we had to leave behind much of the wood we already harvested. While we are waitin' for you to take care of our little animal problem, we could be turnin' those logs into planks to get a head start on our buildin' efforts. If you can bring me back any I'd sure appreciate it pal.",questType="standard"},
[87008] = {id=87008,name="Ad-Hoc Wedding Planner",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Eeey, now that was a wedding worth talkin' about! You did okay. Everything went right and the only hitch was the one my little girl got. So we're good. I know the bride an' groom wanna say their thanks so go chat with them.",starts={{npcID=226518,x=0.254,y=0.418,zoneID=15347}},ends={{npcID=226518,x=0.254,y=0.418,zoneID=15347}},coords={x=0.254,y=0.418,source="quest_giver",zoneID=15347},questType="standard"},
[87010] = {id=87010,name="Calculation Container",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="A Calculation Container is no easy feat to construct. I have not made one recently, as thieves have stolen the data rods I need to complete the task. If you can recover the rods, I could create one. Be warned! The rods are quite heavy and will take some effort to return them. I have been known to drop them quite easily.",starts={{npcID=238057,x=0.48,y=0.574,zoneID=15336}},ends={{npcID=238057,x=0.48,y=0.574,zoneID=15336}},coords={x=0.48,y=0.574,source="quest_giver",zoneID=15336},questType="standard"},
[87284] = {id=87284,name="A Radiant Echo",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=14771,mapID=2339,questType="standard"},
[87285] = {id=87285,name="Marking Matrix",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="A Marking Matrix must be attuned to the frequency of the void energies wielded by the Shadowguard. You must obtain samples of that energy. My containment Trap is designed to capture Shadowguard and allow you to extract the void markings tied to their corrupted energies. With those markings I can create a matrix to help attune your creation to work on void powered constructs.",starts={{npcID=238057,x=0.48,y=0.574,zoneID=15336}},ends={{npcID=238057,x=0.48,y=0.574,zoneID=15336}},coords={x=0.48,y=0.574,source="quest_giver",zoneID=15336},questType="standard"},
[87289] = {id=87289,name="Barreling Down",level=10,requiredLevel=10,faction="alliance",expansion=10,zoneID=1537,description="If it's ale ye be looking for, we've plenty to sample! Or at least we would if the dracthyr folk would hurry up and bring the rest of the barrels down here. Some o' the dracthyr folk have come to celebrate here with us and decided to help transport the ale. Rolling barrels? That's no way to treat a good brew! Mind lending a hand to bring those barrels over to Kharanos? And try not to break 'em!",starts={{npcID=237987,x=0.538,y=0.39,zoneID=1}},ends={{npcID=237987,x=0.538,y=0.39,zoneID=1}},coords={x=0.538,y=0.39,source="quest_giver",zoneID=1},questType="standard"},
[87290] = {id=87290,name="The Oasis",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Hello again, . Ve'nari asked me to find you. She asked that you meet her in the Oasis. I shall join you shortly. I have some errands to run here first.",starts={{npcID=238212,x=0.396,y=0.244,zoneID=15781}},ends={{npcID=238209,x=0.758,y=0.342,zoneID=15336}},coords={x=0.396,y=0.244,source="quest_giver",zoneID=15781},questType="standard"},
[87291] = {id=87291,name="Salad Bar",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Hemet, Om'talad, and I have been working together to see what we can do to help the lapbugs. It seems their original food source didn't make it through the collapse of K'aresh! Do you think you might be able to gather some prickleblooms and lustrous conkers, and put together a little platter for them?",starts={{npcID=232385,x=0.758,y=0.338,zoneID=15336}},ends={{npcID=232385,x=0.758,y=0.338,zoneID=15336}},coords={x=0.758,y=0.338,source="quest_giver",zoneID=15336},questType="standard"},
[87292] = {id=87292,name="Rooting for Trouble",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Our bees have been marvelous at cultivating the local flora. Some of the plants have seen almost explosive growth. However, the lapbugs have become entangled in their roots. I've been untangling them all morning. Would you lend a hand?",starts={{npcID=232385,x=0.758,y=0.338,zoneID=15336}},ends={{npcID=232385,x=0.758,y=0.338,zoneID=15336}},coords={x=0.758,y=0.338,source="quest_giver",zoneID=15336},questType="standard"},
[87293] = {id=87293,name="Shameless Hawking",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15781,description="Lapbugs were once a highly sought after pet here on K'aresh. I suspect we could use them to attract interested parties in Tazavesh, increasing both support and donations for the Oasis. I would like you to test this theory.",starts={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[87294] = {id=87294,name="A Truth Universally Acknowledged",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="I have an idea, . Everyone seems to love the lapbugs, so I have enlarged them, given them hats, and placed them in picturesque locations. Take this camera and take some photos with the lapbugs. If I am correct, this will go a long way toward increasing support for our efforts.",starts={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[87297] = {id=87297,name="Cashing the Check",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="We got one more thing to set straight. Come on. Grimla's waitin' for us back in the hotel lobby.",starts={{npcID=234801,x=0.392,y=0.234,zoneID=15347}},ends={{npcID=238002,x=0.434,y=0.512,zoneID=15347}},coords={x=0.392,y=0.234,source="quest_giver",zoneID=15347},questType="standard"},
[87298] = {id=87298,name="Void Fused Resin",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Void-Fused Resin isn't my usual craft, but there is a way I could make it for you. Void energies continue to seep through the cracks in our shields contaminating the plants in the domes. If we eliminate the contaminated plants, they may provide the ingredients needed to create the resin. Destroy Void-Tainted Growths and bring me any Void Granules you find.",starts={{npcID=238069,x=0.494,y=0.544,zoneID=15336}},ends={{npcID=238069,x=0.494,y=0.544,zoneID=15336}},coords={x=0.494,y=0.544,source="quest_giver",zoneID=15336},questType="standard"},
[87299] = {id=87299,name="How Old Are These Things?",level=80,requiredLevel=80,faction="alliance",expansion=10,zoneID=15716,mapID=14,description="Marran tried to declare herself the new ruler of Stromgarde. While some in the army are complicit in her coup, there are still a lot of us who are loyal to Lord Danath Trollbane. But when we broke ranks, Marran was ready for us. She has an army of soldiers I've never seen before. They call themselves the Red Dawn, but I think they're just the bandits wearing uniforms they took from our supplies! Help us take out her goons and collect any evidence that shows what they really are!",questType="standard"},
[87301] = {id=87301,name="Untethered Battery",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Untethered batteries are difficult to create, as they require elusive energies that leak from void storage cells into Untethered Space. However, I know of an individual capable of harvesting this energy. If they can extract and store the energy and return it to me, we will have the necessary components to construct a battery. Speak to Myi Koo and collect the energy, we can then create a battery.",starts={{npcID=238057,x=0.48,y=0.574,zoneID=15336}},ends={{npcID=238057,x=0.48,y=0.574,zoneID=15336}},coords={x=0.48,y=0.574,source="quest_giver",zoneID=15336},questType="standard"},
[87302] = {id=87302,name="Rare Rivals",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15347,mapID=2346,questType="standard"},
[87303] = {id=87303,name="Clean the Sidestreets",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15347,mapID=2346,questType="standard"},
[87304] = {id=87304,name="Time to Vacate",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15347,mapID=2346,questType="standard"},
[87305] = {id=87305,name="Desire to D.R.I.V.E.",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15347,mapID=2346,questType="standard"},
[87306] = {id=87306,name="Kaja Cruising",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15347,mapID=2346,questType="standard"},
[87307] = {id=87307,name="Garbage Day",level=80,requiredLevel=80,faction="none",expansion=10,zoneID=15347,mapID=2346,questType="standard"},
[87321] = {id=87321,name="Things Left Undone",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Hey pal, I can't thank you enough for what you've done for me... and for Undermine . I know you've been busy since Renzik and Gazlowe brought you here, and you keep doing what we've asked of you. But there's one more thing that needs doing. Meet up with Gazlowe at the hotel. I'm sure he'd appreciate you being there to help.",starts={{npcID=238006,x=0.274,y=0.71,zoneID=15347}},ends={{npcID=232822,x=0.424,y=0.514,zoneID=15347}},coords={x=0.274,y=0.71,source="quest_giver",zoneID=15347},questType="standard"},
[87324] = {id=87324,name="Pile of Voidbane Gems",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Voidbane Gems are dangerous business! The Shadowguard hide the gems in Untethered Space. You need to go in and find them. Be warned though, others may be looking for those gems as well! I marked the location of the stashes for you, but there's other gems laying around too. Grab what you can, and you'll have yourself a nice big pile of gems when you're done.",starts={{npcID=238181,x=0.538,y=0.268,zoneID=15336}},ends={{npcID=238181,x=0.538,y=0.268,zoneID=15336}},coords={x=0.538,y=0.268,source="quest_giver",zoneID=15336},questType="standard"},
[87328] = {id=87328,name="Truly Horrific to Behold",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,description=", we have much to discuss. The new threat of the Void is one that puts us all at risk. But this is not our first time. There are clues in our past encounters. So is the case for the Black Blood. In the past, N'Zoth used it to induce visions. Perhaps we can figure out how to counter its effects by returning to these moments. Come, help me set up the portal.",starts={{npcID=236382,x=0.346,y=0.688,zoneID=14771}},ends={{npcID=236382,x=0.346,y=0.688,zoneID=14771}},coords={x=0.346,y=0.688,source="quest_giver",zoneID=14771},questType="standard"},
[87329] = {id=87329,name="Into the Darkest Memories",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,description="Are you prepared? The path through the timeways has been opened to where we last entered the visions. Expect your sanity to be tested. You probably will not last long on this first attempt. The portal is ready for you, . Journey forth.",starts={{npcID=236382,x=0.346,y=0.688,zoneID=14771}},ends={{npcID=236382,x=0.346,y=0.688,zoneID=14771}},coords={x=0.346,y=0.688,source="quest_giver",zoneID=14771},questType="standard"},
[87332] = {id=87332,name="A Collection of Variables",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,description="My assistant Augermu has been monitoring you and the timeways while you were in the past. He has a way for you to replicate gaining some of the boons adventurers used the first time they faced these visions. Give him some of the displaced corrupted mementos you gleaned from your experience for further analysis.",starts={{npcID=236382,x=0.346,y=0.688,zoneID=14771}},ends={{npcID=238136,x=0.35,y=0.686,zoneID=14771}},coords={x=0.346,y=0.688,source="quest_giver",zoneID=14771},questType="standard"},
[87335] = {id=87335,name="Echoing Lessons",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,description="We can use your displaced corrupted mementos to create Echoes of N'Zoth. I don't want to bore you with the details unless you want to hear. No? Oh well. Augermu appears slightly disappointed.> The more echoes you have, the closer we can get you to a version of yourself that's more prepared for the visions. So, let's get started.",starts={{npcID=238136,x=0.35,y=0.686,zoneID=14771}},ends={{npcID=238136,x=0.35,y=0.686,zoneID=14771}},coords={x=0.35,y=0.686,source="quest_giver",zoneID=14771},questType="standard"},
[87336] = {id=87336,name="Remembering Again and Again",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,description="Now that we have the hourglass calibrated to you, you can re-enter Horrific Visions whenever you like. No need for keys when traveling back in time! That said, we do face one limitation. The hourglass is still fragile, and I must harden it week to week to support additional Echoes of N'Zoth. Who knew that memories of an Old God were so dangerous...? Well, you should report back to Soridormi and get back to it!",starts={{npcID=238136,x=0.35,y=0.686,zoneID=14771}},ends={{npcID=236382,x=0.346,y=0.688,zoneID=14771}},coords={x=0.35,y=0.686,source="quest_giver",zoneID=14771},questType="standard"},
[87337] = {id=87337,name="Custodian Duties",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Ve'nari is very busy. While both her and Om'talad are away, I will give you your orders. We have many creatures here in the Oasis. They make messes. Go clean them up.",starts={{npcID=238209,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[87338] = {id=87338,name="Day One Orientation",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="We've taken some of the native species we saved out of stasis. We will need to recreate their habitats. There are two primary species here, as well as this console to monitor species in the Oasis. I recommend acquainting yourself with these creatures before we begin.",starts={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[87339] = {id=87339,name="Ongoing Activities",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="While you will be on assignments that befit your skill set, there are also additional tasks that need to be done in the Oasis on a regular basis. While these are typically done by the custodians, if you are in the area I would not say no to your assistance with them. Now, and in the future.",starts={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[87340] = {id=87340,name="Junk Mail",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="One final item before we begin--a special task suited to your unique capabilities. No, not killing. Flying. The Oasis requires donations. Donations come from advertising. Take these stacks of fliers and distribute them around Tazavesh.",starts={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[87341] = {id=87341,name="Barreling Down",level=10,requiredLevel=10,faction="horde",expansion=10,zoneID=14,description="If it's ale you're looking for, we've got plenty to sample! Or at least we would if the Dracthyr folk would hurry up and bring the rest of the barrels down here. Some of the Dracthyr have come to celebrate here with us and decided to help transport the ale. Rolling barrels? That's no way to treat a good brew! Mind lending a hand to bring those barrels over to Razor Hill? And try not to break them.",starts={{npcID=238221,x=0.424,y=0.18,zoneID=14}},ends={{npcID=238221,x=0.424,y=0.18,zoneID=14}},coords={x=0.424,y=0.18,source="quest_giver",zoneID=14},questType="standard"},
[87347] = {id=87347,name="Bubbling Brews",level=10,requiredLevel=10,faction="alliance",expansion=10,zoneID=1,description="Drat! I might've made a mistake asking the dracthyr to help with these deliveries. They've been rolling barrels of brews and crashing 'em all over the place! Well, we shouldn't let the brew go to waste if we can help it! Take a barrel an' take to the skies! Try to collect and save as much of the brew as you can by collecting the bubbles.",starts={{npcID=237987,x=0.538,y=0.39,zoneID=1}},ends={{npcID=237987,x=0.538,y=0.39,zoneID=1}},coords={x=0.538,y=0.39,source="quest_giver",zoneID=1},questType="standard"},
[87349] = {id=87349,name="Bubbling Brews",level=10,requiredLevel=10,faction="horde",expansion=10,zoneID=14,description="I might've made a mistake asking the dracthyr to help with these deliveries. They've been rolling barrels of brews and crashing them all over the place! Well, we shouldn't let the brew go to waste if we can help it! Take a barrel and take to the skies! Try to collect and save as much of the brew as you can by collecting the bubbles.",starts={{npcID=238221,x=0.424,y=0.18,zoneID=14}},ends={{npcID=238221,x=0.424,y=0.18,zoneID=14}},coords={x=0.424,y=0.18,source="quest_giver",zoneID=14},questType="standard"},
[87358] = {id=87358,name="Umbral Facade",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="The trick to creating a perfect Facade is to scan live Shadowguard with a nifty little device I will provide you. This device will allow you copy the very unique essence that is the core of their being, and store it for our use. You can locate shadowguard in both regular and untethered space. Regardless of how you find them, they won't take kindly to your presence, and they certainly won't want to be scanned.",starts={{npcID=238181,x=0.538,y=0.268,zoneID=15336}},ends={{npcID=238181,x=0.538,y=0.268,zoneID=15336}},coords={x=0.538,y=0.268,source="quest_giver",zoneID=15336},questType="standard"},
[87363] = {id=87363,name="Tazavesh Facade",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15781,description="To create the perfect Tazavesh facade , you must scan live Shadowguard around Tazavesh with a device I will provide you. This device will mark the targets, allowing you to copy the unique essence that is the core of their being and store it for our use. This is dangerous business, as you will have to approach them directly and see if they're willing to be scanned!",starts={{npcID=238387,x=0.468,y=0.574,zoneID=15781}},ends={{npcID=238387,x=0.468,y=0.574,zoneID=15781}},coords={x=0.468,y=0.574,source="quest_giver",zoneID=15781},questType="standard"},
[87374] = {id=87374,name="C.H.E.T.T.ing In",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,mapID=2346,description="Undermine with directions to The Incontinental's second floor.>",questType="standard"},
[87376] = {id=87376,name="Ethereal Seal",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15781,description="An Ethereal Seal grants unrestricted access and control over Ethereal assets without raising suspicion. Acquiring an authentic seal can be quite difficult. It is far easier to forge one using discarded cyphers instead. If you're not afraid to get your hands dirty, you can find discarded writs in the trash piles outside of town. Bring those to me, and I can create a seal for you.",starts={{npcID=238486,x=0.466,y=0.504,zoneID=15781}},ends={{npcID=238486,x=0.466,y=0.504,zoneID=15781}},coords={x=0.466,y=0.504,source="quest_giver",zoneID=15781},questType="standard"},
[87380] = {id=87380,name="Zo'kita Fruit",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15781,description="You can have the fruit, but only if you do me a favor first. Something is watching us. You can't see it, but the smell of the fruit draws it to us. Hidden monsters lurking just beyond our sight. Gain access to the Untethered Space, hunt these creatures down, and bring me their hides. I want proof that these creatures actually exist!",starts={{npcID=238474,x=0.524,y=0.576,zoneID=15781}},ends={{npcID=238474,x=0.524,y=0.576,zoneID=15781}},coords={x=0.524,y=0.576,source="quest_giver",zoneID=15781},questType="standard"},
[87404] = {id=87404,name="Energy Encapsulation",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="You need an Energy Encapsulation ? You must be planning to activate a portal or teleporter with it! I can construct what you require with ease, provided you supply the necessary energy. Visit the Harvesters nearby. They let us collect what we need, as long as we help keep the wyrms off the harvesters.",starts={{npcID=238057,x=0.48,y=0.574,zoneID=15336}},ends={{npcID=238057,x=0.48,y=0.574,zoneID=15336}},coords={x=0.48,y=0.574,source="quest_giver",zoneID=15336},questType="standard"},
[87405] = {id=87405,name="Warrant: Grubber",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,mapID=2371,description="A massive worm has been spotted lurking in the Scrapdrift Sands east of town. The locals have nicknamed it Grubber. Tragically, we lost deputy Zo'wie when he went out to investigate. The creature pulled him under the sand. Devise a method to lure the worm into revealing itself, so it may be eliminated once and for all.",questType="standard"},
[87406] = {id=87406,name="Inoperative Mega-Mecha Gorilla",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,ends={{npcID=236411,x=0.354,y=0.412,zoneID=15347}},questType="standard"},
[87408] = {id=87408,name="Being Spiritual",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="We have perfected creating existing creatures, but I would like to go one step further. I would like to try this process with a creature that did not survive the Devouring. This world once had a creature called a k'arroc. Locate its essence and gather it for me.",starts={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[87409] = {id=87409,name="From Death, Life",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="We have only to let the machine do its work now. I will let you do the honors. If it fails, I will place the blame on you... ... I jest, my friend. Mostly.",starts={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[87410] = {id=87410,name="Percussive Negotiation",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="The k'arrocs are big and they're going to need tae stretch their wings sooner or later. Let's plan for it, eh? The Shadowguard have all sorts of void shielding going on. I bet you could get parts from them using your usual method of negotiatin' with enemies. Take the parts to Ve'nari when you're done.",starts={{npcID=235353,x=0.758,y=0.34,zoneID=15336}},ends={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.34,source="quest_giver",zoneID=15336},questType="standard"},
[87411] = {id=87411,name="Making Stuff to Look Tough",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="I suppose we can construct the void shield Hemet imagined, but these parts are not ideal. Meet me outside the Oasis to the east and we shall see if we can craft a workable solution.",starts={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[87412] = {id=87412,name="K'arrocing Photos",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="We must keep our documentation updated. That means I require your services once more. Take this camera and gather more photos of the k'arrocs. You'll find them on the rocks around the area.",starts={{npcID=230736,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=230736,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[87413] = {id=87413,name="Bird Bath",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="--just the person I needed! The k'arrocs are gettin' so dirty that it's covering up their natural smell. There's not enough water here for them to bathe! Take this anima vacuum . It'll take that dirt straight off 'em, but you're gonna have to stick to the ones on the ground. Try looking on top of the rocks to the north!",starts={{npcID=234316,x=0.76,y=0.344,zoneID=15336}},ends={{npcID=234316,x=0.76,y=0.344,zoneID=15336}},coords={x=0.76,y=0.344,source="quest_giver",zoneID=15336},questType="standard"},
[87414] = {id=87414,name="Medical Maneuvers",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="It would be good to get a solid medical checkup on the k'arrocs. Would you shrink them down and bring them to me?",starts={{npcID=230736,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=230736,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[87415] = {id=87415,name="The Skies of K'aresh",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="The shielding device you helped with has been tested. It is ready for its first flight, if you will forgive the turn of phrase. Speak with Om'torid . They have a course picked out for you and the k'arroc to soar along.",starts={{npcID=230736,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[87417] = {id=87417,name="Worldsoul: Dungeons",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,description="The enemies of Khaz Algar rise up, unified in the suffering they inflict on those who do not believe in their causes. Show these people the light, . If they cannot see the error of their ways, please show them a merciful conclusion to their beliefs.",ends={{npcID=223875,x=0.46,y=0.494,zoneID=14771}},questType="standard"},
[87419] = {id=87419,name="Worldsoul: Delves",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,description="These lands house many deep crevices, leaving shadows where our enemies believe they are safe. Explore these hidden places and leave our enemies no sanctuary.",ends={{npcID=223875,x=0.46,y=0.494,zoneID=14771}},questType="standard"},
[87420] = {id=87420,name="Basket of Zo'kita Fruit",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15781,description="You need more Zo'kita Fruit than I'd ever dare to keep around here! Just one Zo'kita fruit is enough to drive my brother out of the market, and you're asking for a whole basket? Bold move, my friend! Visit Eco-dome: Primus, I secretly grow them there, hidden out of sight. Use my picking gear to locate them and take as many as you need.",starts={{npcID=238474,x=0.524,y=0.576,zoneID=15781}},ends={{npcID=238474,x=0.524,y=0.576,zoneID=15781}},coords={x=0.524,y=0.576,source="quest_giver",zoneID=15781},questType="standard"},
[87422] = {id=87422,name="Worldsoul: Undermine World Quests",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,description="Undermine may be a place I do not understand, but they too are in need of aid. Our conflicts inflame their situation, it would do good to help them move forward. Go there and help them. See what you can do to bring these... cartels closer together, and to us.",ends={{npcID=223875,x=0.46,y=0.494,zoneID=14771}},questType="standard"},
[87423] = {id=87423,name="Worldsoul: Undermine Explorer",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,description="Undermine is held together by an intricate design of innovation, hard work, allegiance, and it seems like the sheer will of the goblins. Rather than cower in their sunless cave, the goblins have built a city that thrives on motion and activity. We can learn much from that. After not seeing new faces for years, they bring a new light to our lands. Go help them in whatever ways seem fitting.",ends={{npcID=223875,x=0.46,y=0.494,zoneID=14771}},questType="standard"},
[87424] = {id=87424,name="Worldsoul: World Bosses",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14771,description="Hallowfall is not the only land beset by enemies. Great monsters threaten our allies. Wherever the shadows of our war have fallen, savage beasts and cunning fiends rise up. They murder Arathi, earthen, and the others who stand with us. Innocent farmers to great warriors. I know the Sacred Flame burns in you. You are our best hope to hunt these great evils.",ends={{npcID=223875,x=0.46,y=0.494,zoneID=14771}},questType="standard"},
[87425] = {id=87425,name="Large Sticky Voidmass",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Ah, yes, I've seen what you are describing! The sap from the corrupted plants is tainted with void energy. Collect several samples of the sap as you can, and I will combine it to make a Large Sticky Mass.",starts={{npcID=238069,x=0.494,y=0.544,zoneID=15336}},ends={{npcID=238069,x=0.494,y=0.544,zoneID=15336}},coords={x=0.494,y=0.544,source="quest_giver",zoneID=15336},questType="standard"},
[87426] = {id=87426,name="Flavorful Scraps",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15781,description="Plenty of profit to be made scavenging these sands, but watch out for the monster. It's hungry, I've seen it drag scavengers under the sands! You can trick it, I fed it once. Tossed it some scraps. You need the tastiest garbage to lure it out. Collect what you can and I will help sort it to find the most flavorful scraps .",starts={{npcID=238591,x=0.686,y=0.424,zoneID=15781}},ends={{npcID=238591,x=0.686,y=0.424,zoneID=15781}},coords={x=0.686,y=0.424,source="quest_giver",zoneID=15781},questType="standard"},
[87475] = {id=87475,name="Sureki Incursion: Hold the Wall",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14838,description="Flames! Those chitinous vermin are relentless! We've received reports from Auralia Steelstrike that a small force of nerubians are harassing the outer perimeter of the city. Regroup with our allies on the outskirts of Mereldar and join the fight!",starts={{npcID=234774,x=0.282,y=0.562,zoneID=14838}},ends={{npcID=234774,x=0.282,y=0.562,zoneID=14838},{npcID=241344,x=0.406,y=0.578,zoneID=14838}},coords={x=0.282,y=0.562,source="quest_giver",zoneID=14838},questType="standard"},
[87477] = {id=87477,name="Sureki Incursion: Southern Swarm",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14752,description="The Sureki aren't known to give up their assaults so easily. Reports from our southern holdings have warned of a swarm stirring along the mountain range. I don't know whether they plan to hit Tenir's Ascent or Beledar's Bounty, but we cannot wait for them to make the first move. Join our allies and intercept the swarm!",starts={{npcID=234774,x=0.282,y=0.562,zoneID=14838}},ends={{npcID=234774,x=0.282,y=0.562,zoneID=14838},{npcID=241340,x=0.52,y=0.664,zoneID=14838}},coords={x=0.282,y=0.562,source="quest_giver",zoneID=14838},questType="standard"},
[87480] = {id=87480,name="Sureki Incursion: The Eastern Assault",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14838,description="There's no time to rest, ! Our earthen allies in eastern Hallowfall have spotted a Sureki battalion preparing to attack Dunelle's Kindness--they must be targeting the Dawntower! Flame's Radiance reinforcements are securing the town and Lothar's Landing as we speak. Head east and lend what aid you can!",starts={{npcID=234774,x=0.282,y=0.562,zoneID=14838}},ends={{npcID=234774,x=0.282,y=0.562,zoneID=14838},{npcID=241093,x=0.764,y=0.458,zoneID=14838}},coords={x=0.282,y=0.562,source="quest_giver",zoneID=14838},questType="standard"},
[87496] = {id=87496,name="Benefit Packages",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Times are rough, so the cartels have been tryin' out this new business strategy called \"employee retention.\" Never heard of it before, but it sounds fancy. Anyway, I'm pretty sure it means givin' employees the privilege of buyin' stuff from the company stores after you work for 'em long enough. Go check out what the cartels got for sale. See if anything catches your eye before you start workin'.",starts={{npcID=231049,x=0.428,y=0.52,zoneID=15347}},ends={{npcID=231049,x=0.428,y=0.52,zoneID=15347}},coords={x=0.428,y=0.52,source="quest_giver",zoneID=15347},questType="standard"},
[87547] = {id=87547,name="What's Your Specialty?",level=7,requiredLevel=7,faction="alliance",expansion=10,zoneID=13644,description="The Dragon Isles is a dangerous and uncharted place. We'll need to get you prepared. You're strong enough now that you should choose a combat specialization. This will unlock a new array of abilities for you to face the dangers within the Dragon Isles. Go ahead and choose your combat specialization.",starts={{npcID=238913,x=0.82,y=0.314,zoneID=13644}},ends={{npcID=238913,x=0.82,y=0.314,zoneID=13644}},coords={x=0.82,y=0.314,source="quest_giver",zoneID=13644},questType="standard"},
[87548] = {id=87548,name="A Dozen Veilshards",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15781,description="Yes I know of Veilshards, a highly prized treasure, often the target of thieves! But rest assured, the upstanding citizen Om'sto , would not be involved in such crimes. To find Veilshards you need only look to the rats of this city, they are the craftiest of thieves! Follow a Thieving Scurrier to its nest, and you're bound to uncover a gem among it's stolen hoard. Bring back what you find, and we'll bundle them into a neat dozen for you.",starts={{npcID=238486,x=0.466,y=0.504,zoneID=15781}},ends={{npcID=238486,x=0.466,y=0.504,zoneID=15781}},coords={x=0.466,y=0.504,source="quest_giver",zoneID=15781},questType="standard"},
[87551] = {id=87551,name="Week 3: Spread the Word",level=0,requiredLevel=0,faction="both",expansion=10,zoneID=14717,description="Hey, you wanna help out the organization? you know, spread the word? Next time you're in a match, throw your Dastardly Banner down in the arena. Show support! But be careful -- your opponents might take offense and come straight after you...",starts={{npcID=234296,x=0.528,y=0.516,zoneID=14717}},ends={{npcID=234296,x=0.528,y=0.516,zoneID=14717}},coords={x=0.528,y=0.516,source="quest_giver",zoneID=14717},questType="standard"},
[87552] = {id=87552,name="Week 4: They've Heard of You",level=0,requiredLevel=0,faction="both",expansion=10,zoneID=14717,description="You're making a name for yourself, . You keep the victories coming and I'll keep the tickets selling.",starts={{npcID=234296,x=0.528,y=0.516,zoneID=14717}},ends={{npcID=234296,x=0.528,y=0.516,zoneID=14717}},coords={x=0.528,y=0.516,source="quest_giver",zoneID=14717},questType="standard"},
[87553] = {id=87553,name="Week 5: Another Amazing Week!",level=0,requiredLevel=0,faction="both",expansion=10,zoneID=14717,description="What? Oh, hey . Here to fill more seats-- I mean... here for another match? Great!",starts={{npcID=234296,x=0.528,y=0.516,zoneID=14717}},ends={{npcID=234296,x=0.528,y=0.516,zoneID=14717}},coords={x=0.528,y=0.516,source="quest_giver",zoneID=14717},questType="standard"},
[87554] = {id=87554,name="Week 6: It's the Finale!",level=0,requiredLevel=0,faction="both",expansion=10,zoneID=14717,description="This is it, the end of the event. Let's go out with a roar! Put on one last good show and we can count our money together!",starts={{npcID=234296,x=0.528,y=0.516,zoneID=14717}},ends={{npcID=234296,x=0.528,y=0.516,zoneID=14717}},coords={x=0.528,y=0.516,source="quest_giver",zoneID=14717},questType="standard"},
[87555] = {id=87555,name="Home Is Where the Hearth Is",level=7,requiredLevel=7,faction="alliance",expansion=10,zoneID=13644,description="Before you head off, you'll want to get yourself a Hearthstone . This little stone will return you to the inn where you last bound it to. It's not much of an \"inn\", but the explorer's have a tent set up. Test out that new mount of yours and ride over to Happy Hal. He'll get you sorted out with a Hearthstone .",starts={{npcID=238913,x=0.82,y=0.314,zoneID=13644}},ends={{npcID=238913,x=0.82,y=0.314,zoneID=13644}},coords={x=0.82,y=0.314,source="quest_giver",zoneID=13644},questType="standard"},
[87562] = {id=87562,name="Aiding the Dragon Isles",level=7,requiredLevel=7,faction="alliance",expansion=10,zoneID=13644,description="It's time for us to part ways. I have pressing business further within the Dragon Isles in a place called the Azure Span. Toddy Whiskers of the Dragonscale Expedition could use your help. Safe travels, . I look forward to our next meeting!",starts={{npcID=238913,x=0.82,y=0.314,zoneID=13644}},ends={{npcID=189022,x=0.82,y=0.318,zoneID=13644}},coords={x=0.82,y=0.314,source="quest_giver",zoneID=13644},questType="standard"},
[87581] = {id=87581,name="No More Walkin' Here",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="We gotta do something about how long it's taking to get you around. Luckily, I know just the gal. Go meet Nanny Talullah at Shipping and Handling and see if she'll lend you some wheels.",starts={{npcID=238946,x=0.432,y=0.594,zoneID=15347}},ends={{npcID=227210,x=0.374,y=0.488,zoneID=15347}},coords={x=0.432,y=0.594,source="quest_giver",zoneID=15347},questType="standard"},
[87597] = {id=87597,name="A Bag of Veilshards",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15781,description="I myself could sell you Veilshards, but my own supply has been stolen. The vermin of this city will not hesitate to steal them when my back is turned. Follow any Thieving Scurrier to its nest, and you are sure to locate some stolen shards. To assist you, I will provide a device capable of tracking the thieving vermin. Recover enough Veilshards to satisfy both our needs.",starts={{npcID=238486,x=0.466,y=0.504,zoneID=15781}},ends={{npcID=238486,x=0.466,y=0.504,zoneID=15781}},coords={x=0.466,y=0.504,source="quest_giver",zoneID=15781},questType="standard"},
[88652] = {id=88652,name="Faceless Mask of the Nemesis",level=80,requiredLevel=80,faction="both",expansion=10,description="There are those enemies that you will battle or come into conflict over and over. Thought defeated they return from the shadows to attack you again and again. This is is the heart of a true nemesis. And, these are the enemies that will live on forever no matter what you do.",questType="standard"},
[88655] = {id=88655,name="Outbound for Outland",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=3518,description="Snakes! Why'd it have to be snakes? Ve'nari says they used to have snake-like things on K'aresh before the Devouring. None of 'em survived. They still got worms, but that's nae what we're after. I know just the place--my ol' stomping grounds in Nagrand on Outland. Let's use this infernal contraption of a portal to get there.",starts={{npcID=235353,x=0.758,y=0.34,zoneID=15336}},ends={{npcID=18180,x=0.714,y=0.408,zoneID=3518}},coords={x=0.758,y=0.34,source="quest_giver",zoneID=15336},questType="standard"},
[88656] = {id=88656,name="Comfort Stones",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=3518,description="Right then. We're gonna need tae collect things tae make the snakes comfortable on K'aresh. Let's get 'em some bedding. Some of the most important things are rocks! Snakes can sun themselves atop a rock or hide under it. Those nearby earth elementals were always a pain in our side. See if you can get some rocks from 'em.",starts={{npcID=18180,x=0.714,y=0.408,zoneID=3518}},ends={{npcID=18180,x=0.714,y=0.408,zoneID=3518}},coords={x=0.714,y=0.408,source="quest_giver",zoneID=3518},questType="standard"},
[88657] = {id=88657,name="Zangarmoss",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=3521,description="Next up, we'll be needin' some moss for their beds. Sorry to say, but we need to go into the slimy marsh for 'em. The naga control that place. It grows on their mushroom trees. They're also fond o' munching on it or something foul. Fastest way to Zangarmarsh is through the pass to the north. If it were me, I'd look around the Darkcrest Shore.",starts={{npcID=18180,x=0.714,y=0.408,zoneID=3518}},ends={{npcID=18180,x=0.714,y=0.408,zoneID=3518}},coords={x=0.714,y=0.408,source="quest_giver",zoneID=3518},questType="standard"},
[88658] = {id=88658,name="Sneks and Things",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=3518,description="O' course, we also need some snakes. That's the whole point o' why we came out here in the first place. You can find the small ones we want down in the Telaari Basin to the south. Just rustle their dens an' they'll come slitherin' out. That's where the plants they like grow. Speaking of which, make sure to get some o' them fragrant plants while you're at it. Ye might not know this, but snakes have a keen sense o' smell.",starts={{npcID=18180,x=0.714,y=0.408,zoneID=3518}},ends={{npcID=18180,x=0.714,y=0.408,zoneID=3518}},coords={x=0.714,y=0.408,source="quest_giver",zoneID=3518},questType="standard"},
[88659] = {id=88659,name="More Cozy Beds",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=3521,description="We need all sorts o' replacements for things--stones and moss for the beds, and more o' them stinky flowers. Remember, ye can get the stone from the earth elementals in Nagrand. The flowers are down in the Telaari Basin there in Nagrand as well. An' the moss is over at the Darkcrest Shore in Zangarmarsh. It'll be a good excuse for me tae go see the gang again. Meet ye on the other side o' the portal.",starts={{npcID=235353,x=0.758,y=0.34,zoneID=15336}},ends={{npcID=235353,x=0.758,y=0.34,zoneID=15336}},coords={x=0.758,y=0.34,source="quest_giver",zoneID=15336},questType="standard"},
[88660] = {id=88660,name="Snakes on a Plane",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=3518,description="Last, but certainly not least, we need to get those two snakes off o' me plane! I dunno how long snakes normally live, but it seems like those two have been there forever. And they always look at me funny if I come near. Maybe you could go get 'em?",starts={{npcID=18180,x=0.714,y=0.408,zoneID=3518}},ends={{npcID=18180,x=0.714,y=0.408,zoneID=3518}},coords={x=0.714,y=0.408,source="quest_giver",zoneID=3518},questType="standard"},
[88661] = {id=88661,name="To the Atrium",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="We got what we're after. Time to head back. Before we can introduce the snakes to the ecology in the Oasis, we need to test 'em out. There are a few o' these place they call eco-domes where that's done on K'aresh. Ve'nari's portal will take us to one called the Atrium. I wish I could fly me plane there instead.",starts={{npcID=18180,x=0.714,y=0.408,zoneID=3518}},ends={{npcID=236846,x=0.484,y=0.61,zoneID=15336}},coords={x=0.714,y=0.408,source="quest_giver",zoneID=3518},questType="standard"},
[88662] = {id=88662,name="What's in a Name?",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Though they clearly don't like me, I think the two snakes from me crashed plane have taken a liking to you. Ye want to name 'em?",starts={{npcID=236846,x=0.484,y=0.61,zoneID=15336}},ends={{npcID=236846,x=0.484,y=0.61,zoneID=15336}},coords={x=0.484,y=0.61,source="quest_giver",zoneID=15336},questType="standard"},
[88663] = {id=88663,name="Scales and Measures",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Now to get some vital statistics. Ve'nari and her people have all sorts o' contraptions for doing things around here. This li'l robot is gonna use the thing the snakes are on to take some measurements. Just speak with it when you're ready. I can get readings for the rest o' the snakes while you're off doing other things.",starts={{npcID=236846,x=0.484,y=0.61,zoneID=15336}},ends={{npcID=236846,x=0.484,y=0.61,zoneID=15336}},coords={x=0.484,y=0.61,source="quest_giver",zoneID=15336},questType="standard"},
[88664] = {id=88664,name="Nagrandification",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Remember all those stinky plants ye gathered up in Nagrand? Would ye mind replanting 'em? We don't have to plant 'em all right now. Just enough to test and ensure they'll take to the soil of K'aresh. We'll be needin' a lot more plants than this eventually.",starts={{npcID=236846,x=0.484,y=0.61,zoneID=15336}},ends={{npcID=236846,x=0.484,y=0.61,zoneID=15336}},coords={x=0.484,y=0.61,source="quest_giver",zoneID=15336},questType="standard"},
[88665] = {id=88665,name="Follow Your Tongue",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Now it's time to move north into Eco-Dome: Primus. That's a mouthful. Take one o' the remaining stinky flowers an' lead the snakes there.",starts={{npcID=236846,x=0.484,y=0.61,zoneID=15336}},ends={{npcID=236890,x=0.49,y=0.57,zoneID=15336}},coords={x=0.484,y=0.61,source="quest_giver",zoneID=15336},questType="standard"},
[88666] = {id=88666,name="Mossy Beds",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="I've put together the rocks an' the moss that ye collected in Nagrand. Now it's time to see if the snakes like 'em. I spread 'em out around the eco-dome so you could test 'em out for differences. While you're doing that, I'll make preparations for getting 'em all to the Oasis.",starts={{npcID=236890,x=0.49,y=0.57,zoneID=15336}},ends={{npcID=236890,x=0.49,y=0.57,zoneID=15336}},coords={x=0.49,y=0.57,source="quest_giver",zoneID=15336},questType="standard"},
[88667] = {id=88667,name="Water Snakes",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Oh no! Some o' the snakes are having trouble adapting. They aren't drinkin' as much as they should an' are dehydrated. Quick, . Take this waterin' can and give 'em a good dousing.",starts={{npcID=236890,x=0.49,y=0.57,zoneID=15336}},ends={{npcID=236890,x=0.49,y=0.57,zoneID=15336}},coords={x=0.49,y=0.57,source="quest_giver",zoneID=15336},questType="standard"},
[88668] = {id=88668,name="Ophidian Portation",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Our tests are successful! Time to move to the Oasis. Ve'nari gave me these \"portation\" devices to quickly get the snakes o'er there. Why don't you take care o' Ember and Indigo, and I'll take care o' the rest? They've been giving me the side-eye ever since I moved 'em here.",starts={{npcID=236890,x=0.49,y=0.57,zoneID=15336}},ends={{npcID=235353,x=0.758,y=0.34,zoneID=15336}},coords={x=0.49,y=0.57,source="quest_giver",zoneID=15336},questType="standard"},
[88669] = {id=88669,name="Nesting Time",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="We need to set up a nice home for these two, especially since Ember's expectin'. I took a look around an' spotted a shady place under a tree not far from here. There's all sorts o' things to make 'em comfortable an' safe. Use Ve'nari's portation tags again to summon in everything ye need.",starts={{npcID=235353,x=0.758,y=0.34,zoneID=15336}},ends={{npcID=235353,x=0.758,y=0.34,zoneID=15336}},coords={x=0.758,y=0.34,source="quest_giver",zoneID=15336},questType="standard"},
[88670] = {id=88670,name="Soothing Serpents",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Most o' the snakes did not like Ve'nari's teleport. Others were cloned by Om'talad, an' they don't like that either. They're clearly agitated an' I'm afraid they're gonna hurt themselves. I've got this flute. Don't ask. I can't even play the darned thing. Would ye take it out there an' soothe the snakes with some calming melodies?",starts={{npcID=235353,x=0.758,y=0.34,zoneID=15336}},ends={{npcID=235353,x=0.758,y=0.34,zoneID=15336}},coords={x=0.758,y=0.34,source="quest_giver",zoneID=15336},questType="standard"},
[88671] = {id=88671,name="Eggstra Eggs",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="I've been talkin' with the others about food for the snakes, an' we think we have a solution. The k'arrocs have been prospering a wee bit too much for the ecology o' the Oasis. If ye get some o' their eggs, that should be enough for now so we can feed the snakes.",starts={{npcID=235353,x=0.758,y=0.34,zoneID=15336}},ends={{npcID=235353,x=0.758,y=0.34,zoneID=15336}},coords={x=0.758,y=0.34,source="quest_giver",zoneID=15336},questType="standard"},
[88672] = {id=88672,name="Snakelets!",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Speaking o' eggs--I checked, an' Ember has laid her clutch. It's almost time to hatch us some babies! Meet me back at the nest an' we can welcome our first snakelets to K'aresh.",starts={{npcID=235353,x=0.758,y=0.34,zoneID=15336}},ends={{npcID=235353,x=0.758,y=0.34,zoneID=15336}},coords={x=0.758,y=0.34,source="quest_giver",zoneID=15336},questType="standard"},
[88711] = {id=88711,name="Radiant Incursion: Toxins and Pheromones",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14752,description="Our allies in Azj-Kahet have identified a strategic location to strike at the Sureki. According to reports, our enemies are gathering toxins to fuel their war machines. Let's take this opportunity to cut off their supplies, and perhaps better our own understanding of their alchemy.",starts={{npcID=234774,x=0.282,y=0.562,zoneID=14838}},ends={{npcID=234774,x=0.282,y=0.562,zoneID=14838},{npcID=242591,x=0.66,y=0.596,zoneID=14752}},coords={x=0.282,y=0.562,source="quest_giver",zoneID=14838},questType="standard"},
[88754] = {id=88754,name="Short-Supply",level=10,requiredLevel=10,faction="none",expansion=10,questType="standard"},
[88803] = {id=88803,name="Timely Assistance",level=50,requiredLevel=50,faction="both",expansion=10,description="Hello, Champion. I have found a way that I may further assist you in the visions. Should you require it, you can call upon my assistance using this hourglass. I will form a construct that will assist you in the vision.",questType="standard"},
[88805] = {id=88805,name="A Scarred Path Through Time",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,description="Old enemies return and battle scars open once more. Defeat these foes and return with tales of glory.",starts={{npcID=226919,x=0.464,y=0.492,zoneID=14771}},ends={{npcID=226919,x=0.464,y=0.492,zoneID=14771}},coords={x=0.464,y=0.492,source="quest_giver",zoneID=14771},questType="standard"},
[88808] = {id=88808,name="A Scarred Journey Through Time",level=0,requiredLevel=0,faction="both",expansion=10,zoneID=8670,description="Azeroth calls out in need, champion. She bleeds still from wounds of war. Go forth among Zandalar and Kul Tiras to reveal those who would prolong her suffering. Vanquish foes in her name and defend Azeroth.",starts={{npcID=239840,x=0.708,y=0.17,zoneID=8568},{npcID=239840,x=0.46,y=0.948,zoneID=8670}},ends={{npcID=239840,x=0.708,y=0.17,zoneID=8568},{npcID=239840,x=0.46,y=0.948,zoneID=8670}},coords={x=0.708,y=0.17,source="quest_giver",zoneID=8568},questType="standard"},
[88870] = {id=88870,name="Honored with the Bilgewater Cartel",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="You done good for the Bilgewater so far. Keep up the good work. Talk to Rocco Razzboom , he'll take care of ya.",starts={{npcID=231406,x=0.39,y=0.22,zoneID=15347}},ends={{npcID=231406,x=0.39,y=0.22,zoneID=15347}},coords={x=0.39,y=0.22,source="quest_giver",zoneID=15347},questType="standard"},
