[88872] = {id=88872,name="Exalted with the Bilgewater Cartel",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="You done good for the Bilgewater. We appreciate it. Talk to Rocco Razzboom , he'll take care of ya.",ends={{npcID=231406,x=0.39,y=0.22,zoneID=15347}},questType="standard"},
[88873] = {id=88873,name="Honored with the Steamwheedle Cartel",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="The Steamwheedle Cartel wants to thank you for your assistance. Observe all safety protocols and see Lab Assistant Laszly for a reward.",starts={{npcID=231408,x=0.272,y=0.724,zoneID=15347}},ends={{npcID=231408,x=0.272,y=0.724,zoneID=15347}},coords={x=0.272,y=0.724,source="quest_giver",zoneID=15347},questType="standard"},
