[88876] = {id=88876,name="Honored with the Blackwater Cartel",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="The Blackwater Cartel is sailing smooth with your help. Boatswain Hardee has readied yer cut o' the plunder... that is to say, a respectable reward for your work.",starts={{npcID=231405,x=0.632,y=0.168,zoneID=15347}},ends={{npcID=231405,x=0.632,y=0.168,zoneID=15347}},coords={x=0.632,y=0.168,source="quest_giver",zoneID=15347},questType="standard"},
