[88879] = {id=88879,name="Honored with Venture Co.",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Venture Co. is ready to pay dividends for your assistance. Speak to Shredz the Scrapper for your reward.",starts={{npcID=231407,x=0.532,y=0.726,zoneID=15347}},ends={{npcID=231407,x=0.532,y=0.726,zoneID=15347}},coords={x=0.532,y=0.726,source="quest_giver",zoneID=15347},questType="standard"},
