[88881] = {id=88881,name="Exalted with Venture Co.",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Venture Co. is ready to pay dividends for your assistance. Speak to Shredz the Scrapper for your reward.",ends={{npcID=231407,x=0.532,y=0.726,zoneID=15347}},questType="standard"},
[88901] = {id=88901,name="Dastardly Duos Reward",level=80,requiredLevel=80,faction="none",expansion=10,questType="standard"},
[88903] = {id=88903,name="Faceless Mask of Vengeance",level=80,requiredLevel=80,faction="both",expansion=10,description="Blood begets blood, and the weight of the fallen lingers in the air like a whispered curse. Those who stand witness to your wrath feel it creeping into their bones, driving them to strike harder, desperation masquerading as courage. Vengeance does not end violence. It only feeds the storm.",questType="standard"},
[88916] = {id=88916,name="Radiant Incursion: Sureki's End",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14752,description="Credible intel has revealed the Sureki are regrouping for another assault. Now we take the fight to them! The Flame's Radiance have rallied at Faerin's Advance, and prepare to strike at the Sureki forces amassing in northern Azj-Kahet . Be warned, soldier. The Sureki in \"Arathi's End\" are greater in number and power. Should you require aid, our Sacredites in the field should be equipped with potions to assist you.",starts={{npcID=234774,x=0.282,y=0.562,zoneID=14838}},ends={{npcID=234774,x=0.282,y=0.562,zoneID=14838},{npcID=241100,x=0.606,y=0.186,zoneID=14752}},coords={x=0.282,y=0.562,source="quest_giver",zoneID=14838},questType="standard"},
[88945] = {id=88945,name="Radiant Incursion: Rak-Zakaz",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14752,description="The nerubian allies you and Lady Faerin made in Azj-Kahet have proven resourceful... for now. According to their intel, Sureki sympathizers have begun to rally at Rak-Zakaz and aid their fallen queen's loyalists in their renewed assaults. Regroup with our forces at Faerin's Advance and cut off their reinforcements!",starts={{npcID=234774,x=0.282,y=0.562,zoneID=14838}},ends={{npcID=234774,x=0.282,y=0.562,zoneID=14838},{npcID=241100,x=0.606,y=0.186,zoneID=14752}},coords={x=0.282,y=0.562,source="quest_giver",zoneID=14838},questType="standard"},
[88947] = {id=88947,name="Undermined Delves",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=14771,description="There's more tae do in delves, ! Meet me in Dornogal. There's loads to discuss!",ends={{npcID=206017,x=0.476,y=0.444,zoneID=14771}},questType="standard"},
[88970] = {id=88970,name="LFGDungeons - 11.2 The War Within - Raid Finder - 1st",level=80,requiredLevel=80,faction="none",expansion=10,questType="standard"},
[88974] = {id=88974,name="Eco-Stability",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Speakin' o' eggs, I checked an' Ember has laid her clutch. It's almost time ta hatch some babies! Meet me back at tha nest an' we can welcome our first snakelets ta K'aresh.",ends={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},questType="standard"},
[88975] = {id=88975,name="Spooked Slitherin' Snakes",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Somethin' has the snakes agitated again. Spooked even. How would ye feel about taking me flute back out there and calming 'em down?",starts={{npcID=235353,x=0.758,y=0.34,zoneID=15336}},ends={{npcID=235353,x=0.758,y=0.34,zoneID=15336}},coords={x=0.758,y=0.34,source="quest_giver",zoneID=15336},questType="standard"},
[88976] = {id=88976,name="The Hope of K'aresh",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="It is finished. By all measurements, the eco-system in the Oasis is fully stable. While there will always be things we can help with, it would survive if we left it alone. Take some time and speak with everyone. Congratulate them. Good work should be properly acknowledged. Speak with me when you are done.",starts={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[88980] = {id=88980,name="Who You Gonna Call?",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="We could do with more slateback essence . I imagine that the opportunity to keep the sand of K'aresh safe would be right up your alley, yes? Just bring me back what you find after you are done.",starts={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[88981] = {id=88981,name="Nesting Upkeep",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="It's time to refresh Ember, Indigo, an' the snakelet's nest. Gotta keep our K'areshi snakes comfy. Don't worry 'bout carrying anything down there. Just like last time, we'll use one o' Ve'nari's portation tags for that.",starts={{npcID=235353,x=0.758,y=0.34,zoneID=15336}},ends={{npcID=235353,x=0.758,y=0.34,zoneID=15336}},coords={x=0.758,y=0.34,source="quest_giver",zoneID=15336},questType="standard"},
[89016] = {id=89016,name="Members Only",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=15522,starts={{npcID=235617,zoneID=15522}},ends={{npcID=235617,zoneID=15522}},questType="standard"},
