[89029] = {id=89029,name="Chip Service",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=15522,starts={{npcID=235617,zoneID=15522}},ends={{npcID=235617,zoneID=15522}},questType="standard"},
[89056] = {id=89056,name="Ray-ket Ball, Redux",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Time again to test the reflexes of our newborn. Perhaps you could play more ray-ket ball?",starts={{npcID=230736,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=230736,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[89057] = {id=89057,name="Pee-Yew de Foxy",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="! Are you ready for a repeat adventure in olfactory excellence? I've whipped up another concoction for the thorntails. This one's definitely an improvement over the last batch. Would you be the best and go give it a try?",starts={{npcID=234316,x=0.76,y=0.344,zoneID=15336}},ends={{npcID=234316,x=0.76,y=0.344,zoneID=15336}},coords={x=0.76,y=0.344,source="quest_giver",zoneID=15336},questType="standard"},
[89061] = {id=89061,name="Making a Deposit",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Ve'nari may find this useful for powering the eco-domes.>",ends={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},questType="standard"},
[89062] = {id=89062,name="Making a Deposit",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Ve'nari may find this useful for powering the eco-domes.>",ends={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},questType="standard"},
[89063] = {id=89063,name="Making a Deposit",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Ve'nari may find this useful for powering the eco-domes.>",ends={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},questType="standard"},
[89065] = {id=89065,name="Ray-cing for the Future",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Looks like we've got another feisty necroray on our hands! Want to tire it out?",starts={{npcID=235353,x=0.758,y=0.34,zoneID=15336}},ends={{npcID=235353,x=0.758,y=0.34,zoneID=15336}},coords={x=0.758,y=0.34,source="quest_giver",zoneID=15336},questType="standard"},
[89192] = {id=89192,name="A Hard Day's Work",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="We are running low on void shields . Your assistance is required to make a new one. Meet me outside the dome to the east. We shall craft it together.",starts={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[89194] = {id=89194,name="Shake your Bee-hind",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="--just the I wanted to see! I need you to go dance for m--I mean, bees. I shall just watch you leave now.",starts={{npcID=232385,x=0.758,y=0.338,zoneID=15336}},ends={{npcID=232385,x=0.758,y=0.338,zoneID=15336}},coords={x=0.758,y=0.338,source="quest_giver",zoneID=15336},questType="standard"},
[89195] = {id=89195,name="Funny Buzzness",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="I seem to bee running low on bee puns at the moment, but I do need more bees from Stormsong Valley. Would you bee a dear and collect them for me?",starts={{npcID=232385,x=0.758,y=0.338,zoneID=15336}},ends={{npcID=232385,x=0.758,y=0.338,zoneID=15336}},coords={x=0.758,y=0.338,source="quest_giver",zoneID=15336},questType="standard"},
[89197] = {id=89197,name="Ray Ranching",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Ah, there you are. I need to perform medical checkups on the necrorays, and I could use some assistance in capturing them. Perhaps you could help?",starts={{npcID=230736,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=230736,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[89198] = {id=89198,name="Dry Cleaning",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Aw heck! The k'arrocs are acting all feisty again. Mind giving them a good clean so their natural aroma can rise to the top?",starts={{npcID=234316,x=0.76,y=0.344,zoneID=15336}},ends={{npcID=234316,x=0.76,y=0.344,zoneID=15336}},coords={x=0.76,y=0.344,source="quest_giver",zoneID=15336},questType="standard"},
[89209] = {id=89209,name="Bu-zzz",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="These bees are absolute workhorses--workbees? They are worker bees so I suppose... ah, apologies for my distraction. Several of the bees have tired themselves out. Can you return them to the hive?",starts={{npcID=232385,x=0.758,y=0.338,zoneID=15336}},ends={{npcID=232385,x=0.758,y=0.338,zoneID=15336}},coords={x=0.758,y=0.338,source="quest_giver",zoneID=15336},questType="standard"},
[89210] = {id=89210,name="Photography is the Bee's Knees",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="All right, . Take this camera and this film. You've done this before. It's time for documentation! I know you are practically buzzing to get out there, but it's time to bee focused.",starts={{npcID=232385,x=0.758,y=0.338,zoneID=15336}},ends={{npcID=232385,x=0.758,y=0.338,zoneID=15336}},coords={x=0.758,y=0.338,source="quest_giver",zoneID=15336},questType="standard"},
[89212] = {id=89212,name="Royal Photographer",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Om'talad is intently taking several photos of himself.> Ah! ! We need to update our documentation of the thorntails. This camera I was... testing appears to be functioning correctly. Please go update our documentation.",starts={{npcID=230736,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=230736,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[89213] = {id=89213,name="Flights of Fancy",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="We are in need of new photos of the k'arrocs for our records. Please take some for us while you are out in the eco-dome.",starts={{npcID=230736,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=230736,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[89221] = {id=89221,name="Leafing Things on the Ground",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="I woke up today and thought to myself, \"That platter of food put out for the lapbugs was excellent. I suspect the lapbugs would like it if did that again.\" Why don't you make that happen, hmm?",starts={{npcID=232385,x=0.758,y=0.338,zoneID=15336}},ends={{npcID=232385,x=0.758,y=0.338,zoneID=15336}},coords={x=0.758,y=0.338,source="quest_giver",zoneID=15336},questType="standard"},
[89222] = {id=89222,name="Remnant of Azeroth",level=1,requiredLevel=1,faction="alliance",expansion=10,zoneID=9527,description="Upon first glance it appears to be a crystallized shard of Azeroth's life blood. Peering into the shard reveals visions of war across familiar fronts, countless lives locked in battle. The sounds of thunderous storms and crashing waves begin to overwhelm you, before coming to an eerie halt. Kul Tiras calls out to you.",ends={{npcID=239840,x=0.708,y=0.17,zoneID=8568},{npcID=239840,x=0.46,y=0.948,zoneID=8670}},questType="standard"},
[89223] = {id=89223,name="Remnant of Azeroth",level=1,requiredLevel=1,faction="horde",expansion=10,zoneID=9527,description="Upon first glance it appears to be a crystallized shard of Azeroth's life blood. Peering into the shard reveals visions of war across familiar fronts, countless lives locked in battle. The sounds of thunderous storms and crashing waves begin to overwhelm you, before coming to an eerie halt. Zandalar calls out to you.",ends={{npcID=239840,x=0.708,y=0.17,zoneID=8568},{npcID=239840,x=0.46,y=0.948,zoneID=8670}},questType="standard"},
[89238] = {id=89238,name="Follow-up Appointment",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="There is much medical data to be gleaned in the evaluation of the k'arrocs. Please take the condenser disc to shrink them and then pick the little ones up for easy transport.",starts={{npcID=230736,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=230736,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[89240] = {id=89240,name="Dream-Dream-Dream-Dream-Dreameringeding!",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="We need to check how the thorntails are progressing. Would you be so kind as to gather more blood samples? As before, use the darts to put them to sleep and then retrieve the dart with the blood on it.",starts={{npcID=230736,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=230736,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[89242] = {id=89242,name="I Want a Golden Ooze!",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="It seems our custodians have been lax in their duties once again. Take the vacuum device. Clean up the lumps. I will cut you a percentage of the returns.",starts={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[89250] = {id=89250,name="Burning Rubber",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15347,description="Mobber will certainly know how to tune your ride with the new part.>",ends={{npcID=227216,x=0.376,y=0.47,zoneID=15347}},questType="standard"},
[89251] = {id=89251,name="Running Hot!",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=15522,starts={{npcID=235616,zoneID=15522}},ends={{npcID=235616,zoneID=15522}},questType="standard"},
[89252] = {id=89252,name="Need a Jump?",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=15522,starts={{npcID=235617,zoneID=15522}},ends={{npcID=235617,zoneID=15522}},questType="standard"},
[89254] = {id=89254,name="Shutterbug",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="The pictures with the lapbugs were a smash hit. We need more of them for marketing. Sorry, . In this case, the lapbugs with hats are more in-demand than you. Do not be sad though. At least you're getting paid while also getting your face out there, yes? Now, get clicking.",starts={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[89263] = {id=89263,name="Your Cut of the Spoils",level=11,requiredLevel=11,faction="both",expansion=10,zoneID=14771,description="You $p? Got something for you.",ends={{npcID=219760,x=0.466,y=0.454,zoneID=13862},{npcID=219760,x=0.57,y=0.614,zoneID=14771}},questType="standard"},
[89295] = {id=89295,name="The Flame Burns Eternal",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14838,description="These Sureki sure are a persistent bunch! We need to match their persistence with our blades. Can we count on your continued support in the battles ahead?",starts={{npcID=234774,x=0.282,y=0.562,zoneID=14838}},ends={{npcID=234774,x=0.282,y=0.562,zoneID=14838}},coords={x=0.282,y=0.562,source="quest_giver",zoneID=14838},questType="standard"},
[89297] = {id=89297,name="Not as Cute When They Are Bigger and Angrier",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="It seems there are some who are looking to adopt lapbugs. Adoptions mean more revenue. Ultimately, this benefits the Oasis. Please acquire more essence for me.",starts={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},ends={{npcID=231820,x=0.758,y=0.342,zoneID=15336}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=15336},questType="standard"},
[89317] = {id=89317,name="Children's Week in Dornogal",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14771,description="Oh, hello! You must be . I can't thank you enough for stopping by to help with these little ones. Since we earthen don't have children of our own, I thought it would be fun to help some of our allies out for the week, but it turns out children are quite... energetic. I also don't have a good grasp of what children find \"fun\" yet. If you could take the kobold youngling with you that would be helpful. They seem to have somewhere they want to visit. Take this whistle to call them to you.",starts={{npcID=240696,x=0.554,y=0.272,zoneID=14771}},ends={{npcID=241593,x=0.554,y=0.27,zoneID=14771}},coords={x=0.554,y=0.272,source="quest_giver",zoneID=14771},questType="standard"},
[89318] = {id=89318,name="Bold for a Kobold",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14838,description="Big-Tall! Nice Talk-Rock tell Skibbles that she get to do whatever she want today! Well, me have big dream. One so big, me get in trouble for it. A lot. Me want to be brave candle knight, like shiny humans with floaty boats! A-and me hear there is crystal that's brighter than any candle! Would...would you take Skibbles to see candle knights with big kitties?",starts={{npcID=241593,x=0.554,y=0.27,zoneID=14771}},ends={{npcID=241631,x=0.42,y=0.552,zoneID=14838}},coords={x=0.554,y=0.27,source="quest_giver",zoneID=14771},questType="standard"},
[89319] = {id=89319,name="The Wondrous Weave",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14752,description="H-hello! I'm Destien. Earthen Matron Ullna told me about you, and said you are an adventurer! You must have seen all kinds of spooky and awesome things, right? T-there is one thing I would like to do, but I'm worried it will scare people. I've heard there are good nerubians and that you've met them! I've always wanted to talk to one but they scare me. Would you come with me to meet them?",starts={{npcID=241604,x=0.554,y=0.27,zoneID=14771}},ends={{npcID=241649,x=0.556,y=0.436,zoneID=14752}},coords={x=0.554,y=0.27,source="quest_giver",zoneID=14771},questType="standard"},
[89320] = {id=89320,name="The Eager Engineer",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=15347,starts={{npcID=241603,x=0.556,y=0.436,zoneID=14752},{npcID=241603,x=0.554,y=0.272,zoneID=14771}},ends={{npcID=242338,x=0.348,y=0.406,zoneID=15347}},coords={x=0.556,y=0.436,source="quest_giver",zoneID=14752},questType="standard"},
[89321] = {id=89321,name="Recreation for Rooks",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14771,description="Hey! You're , ain't ya? My name's Kitzy! Man am I sure glad to see you. Look, I really wanna go back up to the surface to the stone city. The air is so clean and the sun is so bright! I also saw a giant blue bird fly overhead, except it had lots of legs! Ullna said it was called a...ruk? Rock? Somethin' like that. Anyway, I wanna see one! I ain't never seen anything so pretty before. Do you think I can pet one? Do you think I could RIDE one?",starts={{npcID=241605,x=0.556,y=0.436,zoneID=14752},{npcID=241605,x=0.554,y=0.272,zoneID=14771},{npcID=241732,x=0.554,y=0.272,zoneID=14771}},ends={{npcID=241732,x=0.554,y=0.272,zoneID=14771}},coords={x=0.556,y=0.436,source="quest_giver",zoneID=14752},questType="standard"},
[89322] = {id=89322,name="A Brighter Tomorrow",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=14771,description=", look at this! All of these people are here to discuss the children's futures. They expressed a desire to speak with you as well.",starts={{npcID=241732,x=0.554,y=0.272,zoneID=14771}},ends={{npcID=241732,x=0.554,y=0.272,zoneID=14771}},coords={x=0.554,y=0.272,source="quest_giver",zoneID=14771},questType="standard"},
[89323] = {id=89323,name="Wasted Lands",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Illidan taught us that if we are to fight threats that acknowledge no limits, we must be willing to do the same. With his rage he tamed the power of the fel, and so will I, with the void. A fragment from this world, touched by the All-Devouring, is held deep in the heart of North Sufaad. With the void essence Leona collected, and this fragment as a vessel, I will yoke the power of the void to my will. Combining the strength of the illidari and the secrets of the ren'dorei will make me unstoppable.",starts={{npcID=236907,x=0.6,y=0.296,zoneID=15336}},ends={{npcID=242179,x=0.79,y=0.534,zoneID=15336}},coords={x=0.6,y=0.296,source="quest_giver",zoneID=15336},questType="standard"},
[89324] = {id=89324,name="A Piece of Something Greater",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Seek out the Relictors. They comb through these wastes like carrion feeders, sifting through proof of their people's weakness in a misguided attempt to find strength. The only object of real value is here in front of us, and they keep it contained out of fear. I will not make that mistake. Go, find these Relictors, unburden them of their keys, and return.",starts={{npcID=242179,x=0.79,y=0.534,zoneID=15336}},ends={{npcID=242179,x=0.79,y=0.534,zoneID=15336}},coords={x=0.79,y=0.534,source="quest_giver",zoneID=15336},questType="standard"},
[89325] = {id=89325,name="The Void Confluence",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=16505,description="At last, . With the promise of this fragment's power, and my mastery over the illidari ways, I will be ready to fight the shadowguard and any other threats the void throws at us. Leona spoke of a cave near Shan'dorah where the void energies suffusing K'aresh converge. Meet us there, and play a part in my ascension.",starts={{npcID=242179,x=0.79,y=0.534,zoneID=15336}},ends={{npcID=240842,x=0.594,y=0.242,zoneID=15336},{npcID=240842,x=0.62,y=0.52,zoneID=16505}},coords={x=0.79,y=0.534,source="quest_giver",zoneID=15336},questType="standard"},
[89326] = {id=89326,name="Distilled Darkness",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=16505,description="Adarus is preparing his mind and body for the ritual. Our task is to place the fragment at two points within this cavern, which will both align the crystal to the void energy in the area and attract any void entities that reside nearby. Defeat those entities and their essence will be absorbed into the fragment, empowering it further.",starts={{npcID=240842,x=0.594,y=0.242,zoneID=15336},{npcID=240842,x=0.62,y=0.52,zoneID=16505}},ends={{npcID=240842,x=0.594,y=0.242,zoneID=15336},{npcID=240842,x=0.62,y=0.52,zoneID=16505}},coords={x=0.594,y=0.242,source="quest_giver",zoneID=15336},questType="standard"},
[89327] = {id=89327,name="Chaos",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=16505,description="This is it, . Place the K'areshi fragment above Adarus, and I will channel the void lure containing Ramon'ta's void essence into the shard. Adarus is powerful and determined, but we're attempting something both experimental and dangerous. I'll ask you to be vigilant.",starts={{npcID=240842,x=0.594,y=0.242,zoneID=15336},{npcID=240842,x=0.62,y=0.52,zoneID=16505}},ends={{npcID=240842,x=0.594,y=0.242,zoneID=15336},{npcID=240842,x=0.62,y=0.52,zoneID=16505}},coords={x=0.594,y=0.242,source="quest_giver",zoneID=15336},questType="standard"},
[89331] = {id=89331,name="Flame Fortification",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14838,description="Sureki forces are gathering all over Hallowfall and Azj-Kahet--but we're certain they're just distractions. We think the main attack will come from the west. When the time comes we'll need all the help we can get to push them back and defend Mereldar. Can Flame's Radiance count on your support?",starts={{npcID=234774,x=0.282,y=0.562,zoneID=14838}},ends={{npcID=234774,x=0.282,y=0.562,zoneID=14838}},coords={x=0.282,y=0.562,source="quest_giver",zoneID=14838},questType="standard"},
[89332] = {id=89332,name="Boot Camp",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14838,description="The Sureki gather across Hallowfall and Azj-Kahet while we prepare for their attack on Mereldar. They want to split our forces, but we cannot ignore their activities elsewhere. The Flame's Radiance forces are defending against their incursions in Hallowfall while we run incursions of our own into Azj-Kahet. Rendezvous with the Flame's Radiance in the field and assist their efforts.",starts={{npcID=234774,x=0.282,y=0.562,zoneID=14838}},ends={{npcID=234774,x=0.282,y=0.562,zoneID=14838}},coords={x=0.282,y=0.562,source="quest_giver",zoneID=14838},questType="standard"},
[89343] = {id=89343,name="The Untethered Void",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="The Reshii Wraps that the Harbinger gave you allow you to briefly transform into energy and fall into Untethered Space. This is a nightmare for all ethereals--a natural result of losing our wraps and radiating away our energy. We can control the process by properly attuning with the Phase Conduit, letting us visit this sub-realm and return intact. That is the theory. We have tested it with K'areshi Phase Divers, but not with one of your kind. Are you willing to risk the journey to Untethered Space?",starts={{npcID=241624,x=0.504,y=0.362,zoneID=15336}},ends={{npcID=241624,x=0.504,y=0.362,zoneID=15336}},coords={x=0.504,y=0.362,source="quest_giver",zoneID=15336},questType="standard"},
[89344] = {id=89344,name="What Doesn't See You",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Untethered Space is an arcane phenomenon twisted by creatures of the Void that feed on its energy. Should we ethereals damage our wraps or the brokers their suits, our energy cannot remain intact for long. Then, we fall into this layer of reality, possibly never to return. The upside of this nightmare is that all the energy that falls out of phase is valuable. Use the Phase Conduit to enter Untethered Space, and fight the observers that scavenge phase energy there.",starts={{npcID=241624,x=0.504,y=0.362,zoneID=15336}},ends={{npcID=241624,x=0.504,y=0.362,zoneID=15336}},coords={x=0.504,y=0.362,source="quest_giver",zoneID=15336},questType="standard"},
[89345] = {id=89345,name="The Untethered Horror",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="Void predators that have recently invaded Untethered Space are a mere annoyance compared to the ancient creatures that traveled here long ago. These primal predators feed on the energies of the remnants of old K'aresh , as well as the unfortunate K'areshi who have fallen into this state of being. There is one such creature we call Netherdeath that haunts this rock. We have only been able to drive it away. Perhaps you have the skill to end its reign of terror?",starts={{npcID=241624,x=0.504,y=0.362,zoneID=15336}},ends={{npcID=241624,x=0.504,y=0.362,zoneID=15336}},coords={x=0.504,y=0.362,source="quest_giver",zoneID=15336},questType="standard"},
[89346] = {id=89346,name="Your Cut of the Spoils",level=0,requiredLevel=0,faction="none",expansion=10,description="You $p? Got something for you.",questType="standard"},
[89348] = {id=89348,name="Let There Bee Love",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="All right. I'll get these bees over to the Oasis and meet you there.",starts={{npcID=231919,x=0.724,y=0.698,zoneID=9042},{npcID=231919,x=0.484,y=0.612,zoneID=15336}},ends={{npcID=232385,x=0.758,y=0.338,zoneID=15336}},coords={x=0.724,y=0.698,source="quest_giver",zoneID=9042},questType="standard"},
[89349] = {id=89349,name="Flame's Radiance Stipend",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14838,mapID=2215,starts={{npcID=240852,x=0.282,y=0.562,mapID=2215}},ends={{npcID=240852,x=0.282,y=0.562,mapID=2215}},coords={x=0.282,y=0.562,source="quest_giver",mapID=2215},questType="standard"},
[89351] = {id=89351,name="Liberation of Undermine: Splitting Pairs",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15522,description="If you're gonna take out the Big G, you're gonna have to bust a few heads - on the very same Ogre, as a matter of fact. Mug'Zee's army of goons litter the Gallagio's shadiest back rooms. If you can secure the Tower of Spades, I'll drop you and your friends off there any time you like.",starts={{npcID=235619,zoneID=15522}},ends={{npcID=235619,zoneID=15522}},questType="raid"},
[89352] = {id=89352,name="Liberation of Undermine: Splitting Pairs",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15522,description="If you're gonna take out the Big G, you're gonna have to bust a few heads - on the very same Ogre, as a matter of fact. Mug'Zee's army of goons litter the Gallagio's shadiest back rooms. If you can secure the Tower of Spades, I'll drop you and your friends off there any time you like.",starts={{npcID=235619,zoneID=15522}},ends={{npcID=235619,zoneID=15522}},questType="raid"},
[89353] = {id=89353,name="Liberation of Undermine: Splitting Pairs",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15522,description="If you're gonna take out the Big G, you're gonna have to bust a few heads - on the very same Ogre, as a matter of fact. Mug'Zee's army of goons litter the Gallagio's shadiest back rooms. If you can secure the Tower of Spades, I'll drop you and your friends off there any time you like.",starts={{npcID=235619,zoneID=15522}},ends={{npcID=235619,zoneID=15522}},questType="raid"},
[89380] = {id=89380,name="Another World",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15336,description="I represent a group within the Trust tasked with a dangerous but vital job--Phase Diving. I was at Overlook Zo'Shuul when the Harbinger transformed you into energy. It is similar to that, but more profitable. The Trust embarks on Phase Dives to help replenish our energy reserves. On K'aresh , energy is power--and now we must compete with the Shadowguard. We desperately need the help of someone like you. Meet me at Overlook Zo'Shuul if you are interested. We will, of course, compensate you.",starts={{npcID=241601,x=0.748,y=0.31,zoneID=15336}},ends={{npcID=241624,x=0.504,y=0.362,zoneID=15336}},coords={x=0.748,y=0.31,source="quest_giver",zoneID=15336},questType="standard"},
[89390] = {id=89390,name="Flame's Radiance Stipend",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=14838,mapID=2215,starts={{npcID=240852,x=0.282,y=0.562,mapID=2215}},ends={{npcID=240852,x=0.282,y=0.562,mapID=2215}},coords={x=0.282,y=0.562,source="quest_giver",mapID=2215},questType="standard"},
