[93055] = {id=93055,name="Extracurriculars",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=7502,description="$p, how fares your journey through this timeline? Should you wish to explore history further, Khadgar and Eternus may be able to show you more quests that the champions of Azeroth previously experienced.",questType="standard"},
[93056] = {id=93056,name="A Lesson in Alacrity",level=10,requiredLevel=10,faction="both",expansion=10,zoneID=7502,description="You are exceeding expectations, $p. Even still, let us not tarry. I will teach you what I know so that we may expedite your journey. However, all good things come with time. You are not yet ready for my strongest blessings.",questType="standard"},
[93057] = {id=93057,name="A House For You",level=0,requiredLevel=0,faction="none",expansion=10,description="Greetings, ! Have you ever wanted to own a home? Have a place to call your own? Now you can! Join us in Founder's Point, the new Housing Neighborhood. Get your very own slice of Azeroth!",questType="standard"},
