[93140] = {id=93140,name="Decor Treasure Hunt",level=0,requiredLevel=0,faction="both",expansion=10,zoneID=15524,description="Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle: Where kodos take rest. Past gate marked with bone and fire. Dig near the hay bale. Good luck!",starts={{npcID=253596,x=0.536,y=0.574,zoneID=15524}},ends={{npcID=587681,x=0.452,y=0.563,zoneID=15524}},coords={x=0.536,y=0.574,source="quest_giver",zoneID=15524},questType="standard"},
[93141] = {id=93141,name="Decor Treasure Hunt",level=0,requiredLevel=0,faction="both",expansion=10,zoneID=15524,description="Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle: Just like Thunder Bluff. Tower watches three swaying paths. Look to the platform. Good luck!",starts={{npcID=253596,x=0.536,y=0.574,zoneID=15524}},ends={{npcID=587681,x=0.452,y=0.563,zoneID=15524}},coords={x=0.536,y=0.574,source="quest_giver",zoneID=15524},questType="standard"},
[93142] = {id=93142,name="Decor Treasure Hunt",level=0,requiredLevel=0,faction="both",expansion=10,zoneID=15524,description="Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle: Near where farmers toil. Beast of burden raises young. Seek the broadest shade. Good luck!",starts={{npcID=253596,x=0.536,y=0.574,zoneID=15524}},ends={{npcID=587681,x=0.452,y=0.563,zoneID=15524}},coords={x=0.536,y=0.574,source="quest_giver",zoneID=15524},questType="standard"},
[93143] = {id=93143,name="Decor Treasure Hunt",level=0,requiredLevel=0,faction="both",expansion=10,zoneID=15524,description="Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle: Overlooking fields. Bushels brim with bloom and seed. Check for stock in back. Good luck!",starts={{npcID=253596,x=0.536,y=0.574,zoneID=15524}},ends={{npcID=587681,x=0.452,y=0.563,zoneID=15524}},coords={x=0.536,y=0.574,source="quest_giver",zoneID=15524},questType="standard"},
[93147] = {id=93147,name="Decor Treasure Hunt",level=0,requiredLevel=0,faction="both",expansion=10,zoneID=15524,description="Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle: Highest wyvern perch. Circling above the sea. Look to the center. Good luck!",starts={{npcID=253596,x=0.536,y=0.574,zoneID=15524}},ends={{npcID=587681,x=0.452,y=0.563,zoneID=15524}},coords={x=0.536,y=0.574,source="quest_giver",zoneID=15524},questType="standard"},
[93148] = {id=93148,name="Decor Treasure Hunt",level=0,requiredLevel=0,faction="both",expansion=10,zoneID=15524,description="Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle: Across gentle falls. Ocean breeze meets the bounty. East end of the bridge. Good luck!",starts={{npcID=253596,x=0.536,y=0.574,zoneID=15524}},ends={{npcID=587681,x=0.452,y=0.563,zoneID=15524}},coords={x=0.536,y=0.574,source="quest_giver",zoneID=15524},questType="standard"},
[93149] = {id=93149,name="Decor Treasure Hunt",level=0,requiredLevel=0,faction="both",expansion=10,zoneID=15524,description="Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle: Smugglers scheme above. Tortollans tend bar below. Search through the seaweed. Good luck!",starts={{npcID=253596,x=0.536,y=0.574,zoneID=15524}},ends={{npcID=587681,x=0.452,y=0.563,zoneID=15524}},coords={x=0.536,y=0.574,source="quest_giver",zoneID=15524},questType="standard"},
[93150] = {id=93150,name="Decor Treasure Hunt",level=0,requiredLevel=0,faction="both",expansion=10,zoneID=15524,description="Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle: A secret beast den. Hidden behind narrow falls. Search the oasis. Good luck!",starts={{npcID=253596,x=0.536,y=0.574,zoneID=15524}},ends={{npcID=587681,x=0.452,y=0.563,zoneID=15524}},coords={x=0.536,y=0.574,source="quest_giver",zoneID=15524},questType="standard"},
[93151] = {id=93151,name="Decor Treasure Hunt",level=0,requiredLevel=0,faction="both",expansion=10,zoneID=15524,description="Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle: The fire never ends. Gather for sorrow or mirth. Search behind the fuel. Good luck!",starts={{npcID=253596,x=0.536,y=0.574,zoneID=15524}},ends={{npcID=587681,x=0.452,y=0.563,zoneID=15524}},coords={x=0.536,y=0.574,source="quest_giver",zoneID=15524},questType="standard"},
[93152] = {id=93152,name="Decor Treasure Hunt",level=0,requiredLevel=0,faction="both",expansion=10,zoneID=15524,description="Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle: Life stirs from dry soil. Camp where fishers may take rest. Fire warms the treasure. Good luck!",starts={{npcID=253596,x=0.536,y=0.574,zoneID=15524}},ends={{npcID=587681,x=0.452,y=0.563,zoneID=15524}},coords={x=0.536,y=0.574,source="quest_giver",zoneID=15524},questType="standard"},
[93382] = {id=93382,name="Pardon the Interruption",level=10,requiredLevel=10,faction="alliance",expansion=10,zoneID=16432,description="! Glad to see you. The defenders in the fortress could use your help. One of the gnomes built a robot to try to help defend the keep. However, it goes haywire every time it turns on. She needs the help of someone who can properly disrupt the robot's attacks so it can be repaired. Do you have a moment to help?",starts={{npcID=249423,x=0.194,y=0.574,zoneID=16432}},ends={{npcID=249456,x=0.208,y=0.598,zoneID=16432}},coords={x=0.194,y=0.574,source="quest_giver",zoneID=16432},questType="standard"},
