[93879] = {id=93879,name="Conditional Objectives - Conditional After Sequence",level=10,requiredLevel=10,faction="none",expansion=10,zoneID=7637,mapID=680,description="! Glad to see you. The defenders in the fortress could use your help. One of the gnomes built a robot to try to help defend the keep. However, it goes haywire every time it turns on. She needs the help of someone who can properly disrupt the robot's attacks so it can be repaired. Do you have a moment to help?",questType="standard"},
[93979] = {id=93979,name="Lingering Memories",level=80,requiredLevel=80,faction="both",expansion=10,zoneID=15781,description="Dimensius threatens us once more. There is no one who knows his methods better than his former Harbinger, Xal'atath . I would not say we can trust her, but we can work with her. She fears the All-Devouring's wrath after her betrayal. We can't afford to turn away any potential ally. Think how many we will save from the Void Lord's hunger. Get your bearings in this city the four of us saved together. I will convince Alleria.",starts={{npcID=231128,x=0.378,y=0.744,zoneID=15781}},ends={{npcID=230700,x=0.342,y=0.108,zoneID=15781}},coords={x=0.378,y=0.744,source="quest_giver",zoneID=15781},questType="standard"},
[94363] = {id=94363,name="The Gloves Are Off",level=80,requiredLevel=80,faction="alliance",expansion=10,zoneID=2257,mapID=500,description="If you've found yourself an invite you'll be wanting to put it to good use, no? Use your Blood-Soaked Invitation first then talk to a Bouncer in the Brawlpub and get to brawling!",questType="standard"},
[94372] = {id=94372,name="The Gloves Are Off",level=80,requiredLevel=80,faction="horde",expansion=10,zoneID=6298,description="If you've found yourself an invite you'll be wanting to put it to good use, no? Use your Blood-Soaked Invitation first then talk to a Grunt in the Brawl'gar Arena and get to brawling!",starts={{npcID=252933,x=0.734,y=0.316,zoneID=1637}},coords={x=0.734,y=0.316,source="quest_giver",zoneID=1637},questType="standard"},
[94415] = {id=94415,name="Plumbing the Void",level=70,requiredLevel=70,faction="both",expansion=10,zoneID=15781,mapID=2472,starts={{npcID=235252,x=0.406,y=0.292,mapID=2472}},ends={{npcID=235252,x=0.406,y=0.292,mapID=2472}},coords={x=0.406,y=0.292,source="quest_giver",mapID=2472},questType="standard"},
